# Single-cell Colab script: Download Twitter (X) user photo media without the official API
# - Authenticates using your auth_token and ct0 cookies from your logged-in browser
# - Dynamically discovers the current web bearer token from Twitter's client JS (no hard-coded bearer)
# - Resolves the user ID, paginates the media timeline, extracts photo URLs, and downloads originals
# - Includes robust status checks, error handling, and automatic directory creation
#
# IMPORTANT:
# - Only download content you have rights to. Respect Twitter's Terms of Service and rate limits.
# - auth_token and ct0 are sensitive. Do not share them. They expire and may require refreshing in your browser.
# - This uses Twitter's web endpoints (like the site does), not the official API. Endpoints/structures can change at any time.

import os
import re
import json
import time
import random
import errno
import shutil
import string
import subprocess
from pathlib import Path
from typing import Dict, Any, List, Optional, Tuple

# Ensure dependencies (requests is preinstalled on Colab, tqdm typically is too; install if missing)
try:
    import requests
except Exception as e:
    raise RuntimeError("requests is required in Colab") from e

try:
    from tqdm.auto import tqdm
except Exception:
    subprocess.check_call(["python3", "-m", "pip", "install", "-q", "tqdm"])  # silent install
    from tqdm.auto import tqdm

# ====================== USER CONFIG ======================
USERNAME   = "twitter"   # e.g., "jack" (without @)
AUTH_TOKEN = "PASTE_YOUR_auth_token_COOKIE_HERE"
CT0        = "PASTE_YOUR_ct0_COOKIE_HERE"

# Where to save (change to your Drive path if you mount Drive)
OUTPUT_DIR = "/content/twitter_images"

# Crawl limits and pacing
MAX_PAGES       = 80        # safety cap on paginated requests
MAX_IMAGES      = None      # e.g., 500 to stop after 500 photos; None for no specific cap
REQ_TIMEOUT     = 30        # seconds
SLEEP_RANGE_REQ = (1.0, 2.0)  # between timeline requests
SLEEP_RANGE_DL  = (0.0, 0.25) # between image downloads
# =========================================================

# -------------------- Utility helpers --------------------
UA = (
    "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 "
    "(KHTML, like Gecko) Chrome/115.0.0.0 Safari/537.36"
)

def ensure_dir(path: str) -> None:
    Path(path).mkdir(parents=True, exist_ok=True)

def jitter(a: float, b: float) -> float:
    return random.uniform(a, b)

class TwitterAuthError(RuntimeError):
    pass

class TwitterRequestError(RuntimeError):
    pass

def make_session(auth_token: str, ct0: str) -> requests.Session:
    if not auth_token or not ct0:
        raise TwitterAuthError("Both AUTH_TOKEN and CT0 must be provided (cookies from your logged-in browser).")

    s = requests.Session()
    s.headers.update({
        "User-Agent": UA,
        "Accept": "*/*",
        "Accept-Language": "en-US,en;q=0.9",
        "Referer": "https://twitter.com/",
        "Origin": "https://twitter.com",
        "Connection": "keep-alive",
    })
    # Attach cookies to the session for twitter.com
    s.cookies.set("auth_token", auth_token, domain=".twitter.com")
    s.cookies.set("ct0", ct0, domain=".twitter.com")
    # CSRF header must match ct0 cookie
    s.headers["x-csrf-token"] = ct0
    s.headers["x-twitter-active-user"] = "yes"
    s.headers["x-twitter-client-language"] = "en"
    # x-twitter-auth-type is commonly set by the web app when logged-in
    s.headers["x-twitter-auth-type"] = "OAuth2Session"
    return s

def _extract_js_urls_from_html(html: str) -> List[str]:
    # Find Twitter client JS bundles hosted on abs.twimg.com
    # Match both client-web and client-web-legacy variants
    pattern = re.compile(r'src="(https://abs\\.twimg\\.com/responsive-web/(?:client-web(?:-legacy)?)/[^"]+?\\.js)"')
    return list(dict.fromkeys(m.group(1) for m in pattern.finditer(html)))

def fetch_web_bearer_token(session: requests.Session) -> str:
    # Load a main page to discover client JS bundles
    r = session.get("https://twitter.com/home", timeout=REQ_TIMEOUT, allow_redirects=True)
    if r.status_code != 200:
        # Try fallback to root
        r = session.get("https://twitter.com/", timeout=REQ_TIMEOUT, allow_redirects=True)
    if r.status_code != 200:
        raise TwitterRequestError(f"Failed to load Twitter HTML for bearer discovery (status {r.status_code}).")

    js_urls = _extract_js_urls_from_html(r.text)
    if not js_urls:
        # Some pages lazy-load; try a locale variant
        r2 = session.get("https://twitter.com/?lang=en", timeout=REQ_TIMEOUT)
        if r2.status_code == 200:
            js_urls = _extract_js_urls_from_html(r2.text)
    if not js_urls:
        raise TwitterRequestError("Could not find Twitter client JS URLs to extract bearer token.")

    # Scan JS files for a Bearer token string
    bearer_re = re.compile(r"Bearer\s+([A-Za-z0-9%-]{20,})")
    for url in js_urls[:6]:  # check a handful for speed
        js = session.get(url, timeout=REQ_TIMEOUT)
        if js.status_code != 200:
            continue
        m = bearer_re.search(js.text)
        if m:
            token = m.group(1)
            # If percent-encoded, unquote once
            try:
                from urllib.parse import unquote
                token = unquote(token)
            except Exception:
                pass
            return token
    raise TwitterRequestError("Failed to extract web bearer token from client JS. The site structure may have changed.")

def resolve_user_id(session: requests.Session, username: str) -> str:
    # First try a lightweight, public syndication endpoint (often works without auth)
    try:
        url = f"https://cdn.syndication.twimg.com/widgets/followbutton/info.json?screen_names={username}"
        r = session.get(url, timeout=REQ_TIMEOUT)
        if r.status_code == 200:
            data = r.json()
            if isinstance(data, list) and data:
                uid = str(data[0].get("id_str") or data[0].get("id") or "").strip()
                if uid.isdigit():
                    return uid
    except Exception:
        pass

    # Fallback: use GraphQL UserByScreenName with discovered bearer
    # Find a query hash for UserByScreenName in client JS bundles
    r = session.get("https://twitter.com/home", timeout=REQ_TIMEOUT)
    if r.status_code != 200:
        r = session.get("https://twitter.com/", timeout=REQ_TIMEOUT)
    if r.status_code != 200:
        raise TwitterRequestError(f"Failed to load Twitter HTML for query discovery (status {r.status_code}).")

    js_urls = _extract_js_urls_from_html(r.text)
    qhash = None
    qre = re.compile(r"/i/api/graphql/([A-Za-z0-9_-]{40,})/UserByScreenName")
    for url in js_urls[:8]:
        js = session.get(url, timeout=REQ_TIMEOUT)
        if js.status_code != 200:
            continue
        m = qre.search(js.text)
        if m:
            qhash = m.group(1)
            break
    if not qhash:
        raise TwitterRequestError("Could not locate GraphQL query hash for UserByScreenName in client JS.")

    variables = {
        "screen_name": username,
        "withSafetyModeUserFields": True,
        "withHighlightedLabel": True,
    }
    params = {"variables": json.dumps(variables, separators=(",", ":"))}
    url = f"https://twitter.com/i/api/graphql/{qhash}/UserByScreenName"
    r = session.get(url, params=params, timeout=REQ_TIMEOUT)
    if r.status_code != 200:
        raise TwitterRequestError(f"UserByScreenName failed with status {r.status_code}: {r.text[:200]}")
    data = r.json()
    uid = (
        data.get("data", {})
            .get("user", {})
            .get("result", {})
            .get("rest_id")
        or data.get("data", {})
            .get("user", {})
            .get("rest_id")
    )
    if not uid or not str(uid).isdigit():
        raise TwitterRequestError("Could not resolve user ID from UserByScreenName response.")
    return str(uid)

def extract_photos_from_entries(entries: List[Dict[str, Any]]) -> List[Dict[str, str]]:
    photos: List[Dict[str, str]] = []
    for e in entries:
        content = e.get("content") or {}
        item = None
        # Different shapes: itemContent nested under TimelineTimelineItem
        if content.get("entryType") == "TimelineTimelineItem" or "itemContent" in content:
            item = content.get("itemContent") or content
        elif isinstance(content, dict) and "content" in content:
            item = content.get("content")
        if not isinstance(item, dict):
            continue
        tweet_res = item.get("tweetResult") or item.get("tweet_results") or {}
        result = tweet_res.get("result") or {}
        # Some layers wrap under 'tweet'
        if "tweet" in result and isinstance(result["tweet"], dict):
            result = result["tweet"]
        legacy = result.get("legacy") or {}
        if not legacy:
            # Sometimes nested one more level
            core = result.get("core") or {}
            if isinstance(core, dict):
                legacy = core.get("legacy") or legacy
        if not isinstance(legacy, dict):
            continue
        tweet_id = legacy.get("id_str") or legacy.get("id")
        ent = legacy.get("extended_entities") or {}
        media = ent.get("media") or []
        for idx, m in enumerate(media):
            if m.get("type") == "photo":
                url = m.get("media_url_https") or m.get("media_url")
                if not url:
                    continue
                # Ensure original size
                if "name=" not in url:
                    url_orig = url + ("?name=orig" if "?" not in url else "&name=orig")
                else:
                    url_orig = re.sub(r"name=\w+", "name=orig", url)
                photos.append({
                    "tweet_id": str(tweet_id) if tweet_id else "",
                    "media_url": url,
                    "download_url": url_orig,
                })
    return photos

def parse_timeline_response(js: Dict[str, Any]) -> Tuple[List[Dict[str, Any]], Optional[str]]:
    # Collect entries from instructions and find Bottom cursor
    entries: List[Dict[str, Any]] = []
    next_cursor: Optional[str] = None
    tl = js.get("timeline") or {}
    instructions = tl.get("instructions") or []

    for inst in instructions:
        if "addEntries" in inst:
            entries.extend(inst["addEntries"].get("entries", []))
        if "replaceEntry" in inst:
            entry = inst.get("replaceEntry", {}).get("entry")
            if entry:
                entries.append(entry)

    # Find Bottom cursor among entries
    for e in entries:
        content = e.get("content") or {}
        # Direct cursor
        if content.get("entryType") == "TimelineTimelineCursor" and content.get("cursorType") == "Bottom":
            next_cursor = content.get("value")
            if next_cursor:
                break
        # Operation-wrapped cursor
        op = content.get("operation") if isinstance(content, dict) else None
        if isinstance(op, dict):
            cur = op.get("cursor")
            if isinstance(cur, dict) and cur.get("cursorType") == "Bottom":
                next_cursor = cur.get("value")
                if next_cursor:
                    break
    return entries, next_cursor

def download_file(session: requests.Session, url: str, dest_path: str) -> None:
    # Stream download with status checks; try alt ':orig' if needed
    r = session.get(url, stream=True, timeout=REQ_TIMEOUT)
    if r.status_code != 200:
        # Fallback to :orig style if query param form fails
        base = url.split("?", 1)[0]
        alt = base + ":orig"
        r = session.get(alt, stream=True, timeout=REQ_TIMEOUT)
        if r.status_code != 200:
            raise TwitterRequestError(f"Failed to download image: {url} (status {r.status_code})")
    with open(dest_path, "wb") as f:
        for chunk in r.iter_content(chunk_size=1 << 14):  # 16 KiB
            if chunk:
                f.write(chunk)

# -------------------- Main workflow --------------------
# Validate input
if not USERNAME or USERNAME.strip() == "" or USERNAME.startswith("@"):
    raise ValueError("USERNAME must be a non-empty handle without '@'.")
if not AUTH_TOKEN or not CT0:
    raise ValueError("Please set AUTH_TOKEN and CT0 from your browser cookies.")

# Prepare output
user_dir = os.path.join(OUTPUT_DIR, USERNAME)
ensure_dir(user_dir)
archive_path = os.path.join(user_dir, "downloaded_urls.txt")
manifest_path = os.path.join(user_dir, "manifest.jsonl")

# Load download archive to avoid duplicates across runs
downloaded: set = set()
if os.path.exists(archive_path):
    with open(archive_path, "r", encoding="utf-8") as f:
        for line in f:
            u = line.strip()
            if u:
                downloaded.add(u)

session = make_session(AUTH_TOKEN, CT0)

# Discover current bearer token dynamically
bearer = fetch_web_bearer_token(session)
session.headers["Authorization"] = f"Bearer {bearer}"

# Resolve user ID from username
user_id = resolve_user_id(session, USERNAME)
print(f"Resolved @{USERNAME} -> user_id={user_id}")

# Paginate media timeline and collect photo URLs
base_url = f"https://twitter.com/i/api/2/timeline/media/{user_id}.json"
collected: List[Dict[str, str]] = []
page = 0
cursor: Optional[str] = None
seen_cursors: set = set()

try:
    while True:
        if MAX_PAGES is not None and page >= MAX_PAGES:
            break
        if cursor and cursor in seen_cursors:
            break
        params = {"count": 40}
        if cursor:
            params["cursor"] = cursor
        r = session.get(base_url, params=params, timeout=REQ_TIMEOUT)
        if r.status_code != 200:
            raise TwitterRequestError(f"Timeline request failed (status {r.status_code}): {r.text[:200]}")
        js = r.json()
        entries, next_cursor = parse_timeline_response(js)
        photos = extract_photos_from_entries(entries)
        # Deduplicate by URL within this run
        for p in photos:
            if MAX_IMAGES is not None and len(collected) >= MAX_IMAGES:
                break
            if p["download_url"] not in {x["download_url"] for x in collected}:
                collected.append(p)
        page += 1
        print(f"Page {page}: found {len(photos)} photos, total collected {len(collected)}")
        if MAX_IMAGES is not None and len(collected) >= MAX_IMAGES:
            break
        if not next_cursor or next_cursor == cursor:
            break
        seen_cursors.add(cursor) if cursor else None
        cursor = next_cursor
        time.sleep(jitter(*SLEEP_RANGE_REQ))
except Exception as e:
    raise

if not collected:
    print("No photos found in the user's media timeline or account is inaccessible.")
else:
    print(f"Preparing to download {len(collected)} photos...")

# Download photos
saved = 0
with open(archive_path, "a", encoding="utf-8") as arch, open(manifest_path, "a", encoding="utf-8") as man:
    for i, item in enumerate(tqdm(collected, desc="Downloading", unit="img")):
        url = item["download_url"]
        if url in downloaded:
            continue
        # Build a filename: tweetId_mediaIndex.ext
        base = item.get("media_url", url).split("?")[0]
        name = os.path.basename(base)
        # Prepend tweet ID if available
        prefix = (item.get("tweet_id") or "")
        fname = f"{prefix + '_' if prefix else ''}{name}"
        dest = os.path.join(user_dir, fname)
        try:
            download_file(session, url, dest)
            downloaded.add(url)
            arch.write(url + "\n")
            arch.flush()
            man.write(json.dumps({
                "tweet_id": item.get("tweet_id"),
                "media_url": item.get("media_url"),
                "download_url": url,
                "file": dest,
            }, ensure_ascii=False) + "\n")
            man.flush()
            saved += 1
        except Exception as e:
            print(f"[WARN] Failed to download {url}: {e}")
        time.sleep(jitter(*SLEEP_RANGE_DL))

print(f"Done. Saved {saved} images to: {user_dir}")
print(f"Archive: {archive_path}")
print(f"Manifest: {manifest_path}")
