#define _XOPEN_SOURCE 500
#include <ftw.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

/*
Program: ncpmvdir
Synopsis:
  ncpmvdir [source_dir] [destination_dir] [options] <extension list>

- source_dir and destination_dir can be absolute or relative, but must belong to the HOME directory hierarchy.
- If destination_dir is not present, it will be created.
- options:
  -cp  Copy the directory tree rooted at source_dir into destination_dir (do not delete source)
  -mv  Move the directory tree rooted at source_dir into destination_dir (delete source tree entirely after copy)
- extension list: up to 6 file extensions (e.g., c pdf txt). If provided, files with these extensions are excluded from being copied/moved.
- The original directory hierarchy is preserved under destination_dir.

Requirement: Uses nftw() to traverse the file tree.

Sample runs:
  $ ncpmvdir ./folder1 ./folder2/folder3 -cp txt pdf
    Copies ./folder1 into ./folder2/folder3 (preserving hierarchy), skipping .txt and .pdf files.

  $ ncpmvdir ~/folder1 ~/folder3 -mv
    Moves the entire directory tree from ~/folder1 to ~/folder3 (preserving hierarchy) and deletes the original ~/folder1.
*/

static const char *g_src_root = NULL;
static const char *g_dst_root = NULL;
static char *g_exts[6];
static int g_ext_count = 0;
static int g_do_move = 0; /* 0 = copy, 1 = move */

static int mkdirs_p(const char *path, mode_t mode);
static int ensure_parent_dir(const char *path, mode_t mode);
static int copy_file(const char *src, const char *dst, mode_t mode);
static int traverse_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf);
static int rm_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf);
static int is_within_prefix(const char *path, const char *prefix);
static int is_excluded(const char *path);
static void usage(const char *prog);

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s <source_dir> <destination_dir> <-cp|-mv> [ext1 ext2 ... up to 6]\n"
        "Example 1: %s ./folder1 ./folder2/folder3 -cp txt pdf\n"
        "Example 2: %s ~/folder1 ~/folder3 -mv\n",
        prog, prog, prog);
}

static int is_within_prefix(const char *path, const char *prefix) {
    size_t lp = strlen(prefix);
    if (strncmp(path, prefix, lp) != 0) return 0;
    /* Allow exact match or prefix followed by '/' */
    if (path[lp] == '\0') return 1;
    if (path[lp] == '/') return 1;
    return 0;
}

static int mkdirs_p(const char *path, mode_t mode) {
    if (!path || !*path) return -1;
    char tmp[PATH_MAX];
    size_t len = strnlen(path, sizeof(tmp) - 1);
    if (len >= sizeof(tmp)) {
        errno = ENAMETOOLONG;
        return -1;
    }
    memcpy(tmp, path, len);
    tmp[len] = '\0';

    /* Skip leading '/' */
    char *p = tmp;
    if (*p == '/') p++;

    for (; *p; ++p) {
        if (*p == '/') {
            *p = '\0';
            if (strlen(tmp) > 0) {
                if (mkdir(tmp, mode) == -1 && errno != EEXIST) {
                    *p = '/';
                    return -1;
                }
            }
            *p = '/';
        }
    }
    if (mkdir(tmp, mode) == -1 && errno != EEXIST) {
        return -1;
    }
    return 0;
}

static int ensure_parent_dir(const char *path, mode_t mode) {
    char buf[PATH_MAX];
    size_t len = strnlen(path, sizeof(buf) - 1);
    if (len >= sizeof(buf)) {
        errno = ENAMETOOLONG;
        return -1;
    }
    memcpy(buf, path, len);
    buf[len] = '\0';

    char *slash = strrchr(buf, '/');
    if (!slash) return 0; /* current dir */
    if (slash == buf) {
        /* Parent is root */
        return 0;
    }
    *slash = '\0';
    return mkdirs_p(buf, mode);
}

static int copy_file(const char *src, const char *dst, mode_t mode) {
    int sfd = open(src, O_RDONLY);
    if (sfd < 0) {
        fprintf(stderr, "Error: open source '%s' failed: %s\n", src, strerror(errno));
        return -1;
    }
    int dfd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode);
    if (dfd < 0) {
        fprintf(stderr, "Error: open dest '%s' failed: %s\n", dst, strerror(errno));
        close(sfd);
        return -1;
    }

    char buf[1 << 16];
    ssize_t r;
    int ret = 0;
    while ((r = read(sfd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dfd, buf + off, (size_t)(r - off));
            if (w < 0) {
                fprintf(stderr, "Error: write to '%s' failed: %s\n", dst, strerror(errno));
                ret = -1;
                break;
            }
            off += w;
        }
        if (ret < 0) break;
    }
    if (r < 0) {
        fprintf(stderr, "Error: read from '%s' failed: %s\n", src, strerror(errno));
        ret = -1;
    }

    /* Ensure mode (permissions) */
    if (fchmod(dfd, mode) != 0) {
        /* Not fatal */
    }

    close(dfd);
    close(sfd);
    return ret;
}

static int is_excluded(const char *path) {
    if (g_ext_count <= 0) return 0;
    const char *base = strrchr(path, '/');
    if (!base) base = path; else base++;
    const char *dot = strrchr(base, '.');
    if (!dot || dot[1] == '\0') return 0;
    const char *ext = dot + 1;
    for (int i = 0; i < g_ext_count; ++i) {
        if (g_exts[i] && strcasecmp(ext, g_exts[i]) == 0) return 1;
    }
    return 0;
}

static int traverse_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    size_t src_len = strlen(g_src_root);
    const char *rel = fpath;
    if (strncmp(fpath, g_src_root, src_len) == 0) {
        rel = fpath + src_len;
        if (*rel == '/') rel++;
        if (*rel == '\0') rel = NULL; /* root itself */
    }

    char dst_path[PATH_MAX];
    if (!rel) {
        /* root maps to destination root */
        snprintf(dst_path, sizeof(dst_path), "%s", g_dst_root);
    } else {
        snprintf(dst_path, sizeof(dst_path), "%s/%s", g_dst_root, rel);
    }

    switch (typeflag) {
        case FTW_D: {
            /* Create corresponding directory */
            if (mkdir(dst_path, 0777) != 0) {
                if (errno != EEXIST) {
                    fprintf(stderr, "Error: mkdir '%s' failed: %s\n", dst_path, strerror(errno));
                    return -1;
                }
            }
            /* Try to mirror src dir permissions */
            struct stat st;
            if (stat(fpath, &st) == 0) {
                chmod(dst_path, st.st_mode & 0777);
            }
            return 0;
        }
        case FTW_F: {
            if (is_excluded(fpath)) {
                return 0; /* skip copy */
            }
            struct stat st;
            if (stat(fpath, &st) != 0) {
                fprintf(stderr, "Warning: stat '%s' failed: %s\n", fpath, strerror(errno));
                return 0;
            }
            if (ensure_parent_dir(dst_path, 0777) != 0) {
                fprintf(stderr, "Error: ensure parent dir for '%s' failed: %s\n", dst_path, strerror(errno));
                return -1;
            }
            if (copy_file(fpath, dst_path, st.st_mode & 0777) != 0) {
                return -1;
            }
            return 0;
        }
        case FTW_SL:
        case FTW_SLN:
        case FTW_DNR:
        case FTW_NS:
        default:
            /* Skip special/unreadable entries */
            return 0;
    }
}

static int rm_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    if (remove(fpath) != 0) {
        fprintf(stderr, "Error: remove '%s' failed: %s\n", fpath, strerror(errno));
        return -1;
    }
    return 0;
}

static char *sanitize_ext(const char *e) {
    while (*e == '.') e++; /* strip leading dots */
    size_t n = strlen(e);
    if (n == 0) return NULL;
    char *out = malloc(n + 1);
    if (!out) return NULL;
    for (size_t i = 0; i < n; ++i) out[i] = (char)tolower((unsigned char)e[i]);
    out[n] = '\0';
    return out;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *src_arg = argv[1];
    const char *dst_arg = argv[2];
    const char *opt_arg = argv[3];

    if (strcmp(opt_arg, "-cp") == 0) {
        g_do_move = 0;
    } else if (strcmp(opt_arg, "-mv") == 0) {
        g_do_move = 1;
    } else {
        fprintf(stderr, "Error: option must be -cp or -mv\n");
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    int extra = argc - 4;
    if (extra > 6) {
        fprintf(stderr, "Error: up to 6 extensions allowed, got %d\n", extra);
        return EXIT_FAILURE;
    }
    for (int i = 0; i < extra; ++i) {
        g_exts[g_ext_count] = sanitize_ext(argv[4 + i]);
        if (!g_exts[g_ext_count]) {
            fprintf(stderr, "Error: invalid extension '%s'\n", argv[4 + i]);
            return EXIT_FAILURE;
        }
        g_ext_count++;
    }

    char home[PATH_MAX];
    const char *home_env = getenv("HOME");
    if (!home_env || !realpath(home_env, home)) {
        fprintf(stderr, "Error: cannot resolve HOME directory\n");
        return EXIT_FAILURE;
    }

    char src_real[PATH_MAX];
    if (!realpath(src_arg, src_real)) {
        fprintf(stderr, "Error: source directory '%s' does not exist or cannot be resolved: %s\n", src_arg, strerror(errno));
        return EXIT_FAILURE;
    }
    struct stat sst;
    if (stat(src_real, &sst) != 0 || !S_ISDIR(sst.st_mode)) {
        fprintf(stderr, "Error: source '%s' is not a directory\n", src_real);
        return EXIT_FAILURE;
    }

    if (!is_within_prefix(src_real, home)) {
        fprintf(stderr, "Error: source directory '%s' is not within HOME hierarchy '%s'\n", src_real, home);
        return EXIT_FAILURE;
    }

    char dst_real[PATH_MAX];
    struct stat dstst;
    if (stat(dst_arg, &dstst) == 0) {
        /* Exists */
        if (!realpath(dst_arg, dst_real)) {
            fprintf(stderr, "Error: cannot resolve destination '%s': %s\n", dst_arg, strerror(errno));
            return EXIT_FAILURE;
        }
        if (!S_ISDIR(dstst.st_mode)) {
            fprintf(stderr, "Error: destination '%s' exists and is not a directory\n", dst_real);
            return EXIT_FAILURE;
        }
        if (!is_within_prefix(dst_real, home)) {
            fprintf(stderr, "Error: destination '%s' is not within HOME hierarchy '%s'\n", dst_real, home);
            return EXIT_FAILURE;
        }
    } else {
        /* Does not exist: build absolute candidate and ensure within HOME, then create */
        char abs_candidate[PATH_MAX];
        if (dst_arg[0] == '/') {
            if (snprintf(abs_candidate, sizeof(abs_candidate), "%s", dst_arg) >= (int)sizeof(abs_candidate)) {
                fprintf(stderr, "Error: destination path too long\n");
                return EXIT_FAILURE;
            }
        } else {
            char cwd[PATH_MAX];
            if (!getcwd(cwd, sizeof(cwd))) {
                fprintf(stderr, "Error: cannot get current directory: %s\n", strerror(errno));
                return EXIT_FAILURE;
            }
            if (snprintf(abs_candidate, sizeof(abs_candidate), "%s/%s", cwd, dst_arg) >= (int)sizeof(abs_candidate)) {
                fprintf(stderr, "Error: destination path too long\n");
                return EXIT_FAILURE;
            }
        }
        if (!is_within_prefix(abs_candidate, home)) {
            fprintf(stderr, "Error: destination '%s' is not within HOME hierarchy '%s'\n", abs_candidate, home);
            return EXIT_FAILURE;
        }
        if (mkdirs_p(abs_candidate, 0777) != 0) {
            fprintf(stderr, "Error: could not create destination directory '%s': %s\n", abs_candidate, strerror(errno));
            return EXIT_FAILURE;
        }
        /* Canonicalize */
        if (!realpath(abs_candidate, dst_real)) {
            fprintf(stderr, "Error: cannot resolve newly created destination '%s': %s\n", abs_candidate, strerror(errno));
            return EXIT_FAILURE;
        }
        if (!is_within_prefix(dst_real, home)) {
            fprintf(stderr, "Error: destination '%s' is not within HOME hierarchy '%s' after resolution\n", dst_real, home);
            return EXIT_FAILURE;
        }
    }

    /* Prevent pathological cases: destination inside source or source inside destination */
    if (is_within_prefix(dst_real, src_real)) {
        fprintf(stderr, "Error: destination '%s' is inside source '%s' (not allowed)\n", dst_real, src_real);
        return EXIT_FAILURE;
    }
    if (is_within_prefix(src_real, dst_real)) {
        fprintf(stderr, "Error: source '%s' is inside destination '%s' (not allowed)\n", src_real, dst_real);
        return EXIT_FAILURE;
    }

    g_src_root = src_real;
    g_dst_root = dst_real;

    /* Ensure destination root exists */
    if (mkdir(g_dst_root, 0777) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error: cannot create destination root '%s': %s\n", g_dst_root, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Traverse and copy */
    if (nftw(g_src_root, traverse_cb, 16, FTW_PHYS | FTW_ACTIONRETVAL) != 0) {
        fprintf(stderr, "Error: traversal/copy failed\n");
        return EXIT_FAILURE;
    }

    if (g_do_move) {
        /* Delete source tree entirely */
        if (nftw(g_src_root, rm_cb, 16, FTW_PHYS | FTW_DEPTH | FTW_MOUNT) != 0) {
            fprintf(stderr, "Error: failed to delete source tree '%s' after move\n", g_src_root);
            return EXIT_FAILURE;
        }
    }

    /* Success */
    return EXIT_SUCCESS;
}

#define _XOPEN_SOURCE 700
#include <ftw.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <errno.h>
#include <limits.h>

typedef struct {
    char src_root[PATH_MAX];
    char dst_root[PATH_MAX];
    size_t src_len;
    int do_move; // 0 = copy, 1 = move
    int ext_count;
    char exts[6][32]; // up to 6 extensions, lowercased, without leading dot
} Ctx;

static Ctx g_ctx;

static void to_lower_str(char *s) {
    for (; *s; ++s) {
        if (*s >= 'A' && *s <= 'Z') *s = (char)(*s - 'A' + 'a');
    }
}

static void strip_trailing_slash(char *p) {
    size_t n = strlen(p);
    while (n > 1 && p[n-1] == '/') {
        p[n-1] = '\0';
        n--;
    }
}

static int join_paths(char *out, size_t outsz, const char *a, const char *b) {
    if (!a || !*a) return snprintf(out, outsz, "%s", b ? b : "") >= (int)outsz ? -1 : 0;
    if (!b || !*b) return snprintf(out, outsz, "%s", a) >= (int)outsz ? -1 : 0;
    size_t alen = strlen(a);
    int need_slash = (alen > 0 && a[alen-1] != '/');
    if (need_slash)
        return snprintf(out, outsz, "%s/%s", a, b) >= (int)outsz ? -1 : 0;
    else
        return snprintf(out, outsz, "%s%s", a, b) >= (int)outsz ? -1 : 0;
}

static int path_starts_with(const char *path, const char *prefix) {
    size_t lp = strlen(prefix);
    if (strncmp(path, prefix, lp) != 0) return 0;
    if (path[lp] == '\0') return 1;
    if (path[lp] == '/') return 1;
    return 0;
}

static int compute_abs_path(const char *in, char *out, size_t outsz) {
    if (!in || !*in) return -1;
    if (in[0] == '/') {
        return (snprintf(out, outsz, "%s", in) >= (int)outsz) ? -1 : 0;
    } else {
        char cwd[PATH_MAX];
        if (!getcwd(cwd, sizeof(cwd))) return -1;
        if (join_paths(out, outsz, cwd, in) != 0) return -1;
        return 0;
    }
}

static int recursive_mkdir(const char *path, mode_t mode) {
    char tmp[PATH_MAX];
    if (snprintf(tmp, sizeof(tmp), "%s", path) >= (int)sizeof(tmp)) return -1;
    strip_trailing_slash(tmp);
    size_t len = strlen(tmp);
    for (size_t i = 1; i < len; ++i) {
        if (tmp[i] == '/') {
            tmp[i] = '\0';
            if (mkdir(tmp, mode) != 0 && errno != EEXIST) return -1;
            tmp[i] = '/';
        }
    }
    if (mkdir(tmp, mode) != 0 && errno != EEXIST) return -1;
    return 0;
}

static int has_excluded_ext(const char *filename) {
    if (g_ctx.ext_count <= 0) return 0; // nothing to exclude
    // Extract basename
    const char *base = strrchr(filename, '/');
    base = base ? base + 1 : filename;
    const char *dot = strrchr(base, '.');
    if (!dot || dot == base) return 0; // no extension
    char ext[64];
    if (snprintf(ext, sizeof(ext), "%s", dot + 1) >= (int)sizeof(ext)) return 0;
    to_lower_str(ext);
    for (int i = 0; i < g_ctx.ext_count; ++i) {
        if (strcmp(ext, g_ctx.exts[i]) == 0) return 1;
    }
    return 0;
}

static int copy_file(const char *src, const char *dst, mode_t mode) {
    int in = open(src, O_RDONLY);
    if (in < 0) return -1;
    int out = open(dst, O_WRONLY | O_CREAT | O_TRUNC, mode & 0777);
    if (out < 0) { close(in); return -1; }
    char buf[1 << 16];
    ssize_t r;
    while ((r = read(in, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out, buf + off, (size_t)(r - off));
            if (w < 0) { close(in); close(out); return -1; }
            off += w;
        }
    }
    if (r < 0) { close(in); close(out); return -1; }
    if (close(in) < 0) { close(out); return -1; }
    if (close(out) < 0) return -1;
    return 0;
}

static int copy_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    // Compute relative path from src_root
    const char *rel = NULL;
    size_t slen = g_ctx.src_len;
    if (strncmp(fpath, g_ctx.src_root, slen) == 0) {
        if (fpath[slen] == '\0') rel = ""; // root itself
        else if (fpath[slen] == '/') rel = fpath + slen + 1;
    }
    if (!rel) rel = fpath; // fallback (shouldn't happen)

    char dst_path[PATH_MAX];
    if (rel[0] == '\0') {
        // root maps to destination root
        if (snprintf(dst_path, sizeof(dst_path), "%s", g_ctx.dst_root) >= (int)sizeof(dst_path)) {
            fprintf(stderr, "Path too long: %s\n", g_ctx.dst_root);
            return -1;
        }
    } else {
        if (join_paths(dst_path, sizeof(dst_path), g_ctx.dst_root, rel) != 0) {
            fprintf(stderr, "Path too long: %s/%s\n", g_ctx.dst_root, rel);
            return -1;
        }
    }

    switch (typeflag) {
        case FTW_D: {
            // Ensure directory exists; set permissions similar to source
            if (recursive_mkdir(dst_path, 0755) != 0 && errno != EEXIST) {
                fprintf(stderr, "Failed to create directory: %s (%s)\n", dst_path, strerror(errno));
                return -1;
            }
            // Adjust mode to match source dir perms
            chmod(dst_path, sb->st_mode & 0777);
            break;
        }
        case FTW_F: {
            if (has_excluded_ext(fpath)) {
                // skip copying excluded file types
                return 0;
            }
            // Ensure parent directory exists (should already exist via FTW_D)
            if (copy_file(fpath, dst_path, sb->st_mode) != 0) {
                fprintf(stderr, "Failed to copy file: %s -> %s (%s)\n", fpath, dst_path, strerror(errno));
                return -1;
            }
            break;
        }
        case FTW_SL:
            // Skip symlinks (not specified to preserve). Could add handling if required.
            break;
        default:
            // Skip other types (devices, sockets, etc.)
            break;
    }
    return 0;
}

static int rm_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    int rc = 0;
    switch (typeflag) {
        case FTW_DP: // directory after contents
        case FTW_D:
            rc = rmdir(fpath);
            if (rc != 0) {
                fprintf(stderr, "Failed to remove dir: %s (%s)\n", fpath, strerror(errno));
            }
            break;
        default:
            rc = unlink(fpath);
            if (rc != 0) {
                fprintf(stderr, "Failed to remove file: %s (%s)\n", fpath, strerror(errno));
            }
            break;
    }
    return rc;
}

static void print_usage(const char *prog) {
    fprintf(stderr, "Usage: %s <source_dir> <destination_dir> <-cp|-mv> [ext1 [ext2 ... ext6]]\n", prog);
}

int main(int argc, char *argv[]) {
    if (argc < 4) { print_usage(argv[0]); return EXIT_FAILURE; }

    const char *src_in = argv[1];
    const char *dst_in = argv[2];
    const char *opt = argv[3];

    if (strcmp(opt, "-cp") != 0 && strcmp(opt, "-mv") != 0) {
        fprintf(stderr, "Error: option must be -cp or -mv.\n");
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }
    g_ctx.do_move = (strcmp(opt, "-mv") == 0);

    g_ctx.ext_count = 0;
    for (int i = 4; i < argc && g_ctx.ext_count < 6; ++i) {
        if (argv[i][0] == '\0') continue;
        size_t len = strlen(argv[i]);
        if (len >= sizeof(g_ctx.exts[0])) {
            fprintf(stderr, "Warning: extension '%s' too long, skipping.\n", argv[i]);
            continue;
        }
        snprintf(g_ctx.exts[g_ctx.ext_count], sizeof(g_ctx.exts[0]), "%s", argv[i]);
        to_lower_str(g_ctx.exts[g_ctx.ext_count]);
        g_ctx.ext_count++;
    }
    if (argc > 4 + g_ctx.ext_count) {
        fprintf(stderr, "Warning: more than 6 extensions provided, extra ones ignored.\n");
    }

    const char *home = getenv("HOME");
    if (!home || home[0] != '/') {
        fprintf(stderr, "Error: HOME environment variable not set to an absolute path.\n");
        return EXIT_FAILURE;
    }

    char src_abs[PATH_MAX];
    if (!realpath(src_in, src_abs)) {
        fprintf(stderr, "Error: source directory '%s' does not exist or cannot be resolved.\n", src_in);
        return EXIT_FAILURE;
    }
    struct stat st;
    if (stat(src_abs, &st) != 0 || !S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: source '%s' is not a directory.\n", src_abs);
        return EXIT_FAILURE;
    }

    if (!path_starts_with(src_abs, home)) {
        fprintf(stderr, "Error: source directory '%s' is not within the home directory hierarchy.\n", src_abs);
        return EXIT_FAILURE;
    }

    char dst_abs[PATH_MAX];
    int dst_exists = 0;
    if (realpath(dst_in, dst_abs)) {
        dst_exists = 1;
        if (stat(dst_abs, &st) != 0) {
            fprintf(stderr, "Error: destination path '%s' cannot be stat'ed.\n", dst_abs);
            return EXIT_FAILURE;
        }
        if (!S_ISDIR(st.st_mode)) {
            fprintf(stderr, "Error: destination '%s' exists but is not a directory.\n", dst_abs);
            return EXIT_FAILURE;
        }
    } else {
        // Destination does not exist: compute absolute path for membership check and creation
        if (compute_abs_path(dst_in, dst_abs, sizeof(dst_abs)) != 0) {
            fprintf(stderr, "Error: cannot resolve destination path '%s'.\n", dst_in);
            return EXIT_FAILURE;
        }
    }

    // Ensure destination is within HOME
    if (!path_starts_with(dst_abs, home)) {
        fprintf(stderr, "Error: destination directory '%s' is not within the home directory hierarchy.\n", dst_abs);
        return EXIT_FAILURE;
    }

    // Normalize stored roots
    snprintf(g_ctx.src_root, sizeof(g_ctx.src_root), "%s", src_abs);
    strip_trailing_slash(g_ctx.src_root);
    g_ctx.src_len = strlen(g_ctx.src_root);

    snprintf(g_ctx.dst_root, sizeof(g_ctx.dst_root), "%s", dst_abs);
    strip_trailing_slash(g_ctx.dst_root);

    // Prevent dangerous overlaps (destination inside source or equal)
    if (path_starts_with(g_ctx.dst_root, g_ctx.src_root)) {
        fprintf(stderr, "Error: destination '%s' must not be the same as or inside the source '%s'.\n", g_ctx.dst_root, g_ctx.src_root);
        return EXIT_FAILURE;
    }

    // Create destination directory if not exists
    if (!dst_exists) {
        if (recursive_mkdir(g_ctx.dst_root, 0755) != 0) {
            fprintf(stderr, "Error: failed to create destination directory '%s' (%s).\n", g_ctx.dst_root, strerror(errno));
            return EXIT_FAILURE;
        }
    }

    // Traverse and copy
    int rc = nftw(g_ctx.src_root, copy_cb, 32, FTW_PHYS);
    if (rc != 0) {
        fprintf(stderr, "Error: traversal/copy failed (rc=%d).\n", rc);
        return EXIT_FAILURE;
    }

    // If move, delete the original source subtree entirely
    if (g_ctx.do_move) {
        int drc = nftw(g_ctx.src_root, rm_cb, 32, FTW_DEPTH | FTW_PHYS);
        if (drc != 0) {
            fprintf(stderr, "Error: failed to delete source tree '%s' (rc=%d).\n", g_ctx.src_root, drc);
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

Sample runs:
- ncpmvdir ./folder1 ./folder2/folder3 -cp txt pdf
  Copies the directory tree rooted at ./folder1 into ./folder2/folder3, preserving the original hierarchy, excluding files with .txt and .pdf extensions. Creates ./folder2/folder3 if it does not exist.
- ncpmvdir ~/folder1 ~/folder3 -mv
  Moves the entire directory tree rooted at ~/folder1 into ~/folder3, preserving the hierarchy. Deletes the original ~/folder1 tree after moving. Creates ~/folder3 if it does not exist.

/*
 * ncpmvdir: copy or move a directory tree using nftw(), excluding specified extensions.
 * Synopsis: ncpmvdir source_dir destination_dir -cp|-mv [ext1 ext2 ... ext6]
 *
 * Requirements satisfied:
 * - Uses nftw() to traverse the tree.
 * - Supports -cp (copy) and -mv (move) options.
 * - Creates destination_dir if it does not exist (recursively), preserving hierarchy.
 * - Excludes up to 6 file extensions from copy/move.
 * - Validates that source and destination belong to HOME hierarchy.
 * - On -mv, deletes the original source subtree entirely after a successful copy.
 * - Handles errors and prints appropriate messages.
 */

#define _XOPEN_SOURCE 700
#include <ftw.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <ctype.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

static char src_root[PATH_MAX];
static char dst_root[PATH_MAX];
static size_t src_root_len = 0;
static int do_move = 0; /* 0=copy, 1=move */
static char home_dir[PATH_MAX];

#define MAX_EXT 6
#define EXT_LEN 64
static char exts[MAX_EXT][EXT_LEN];
static int ext_count = 0;

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s source_dir destination_dir -cp|-mv [ext1 ext2 ... ext6]\n", prog);
}

static void strip_trailing_slashes(char *p) {
    size_t n = strlen(p);
    while (n > 1 && p[n-1] == '/') { p[n-1] = '\0'; n--; }
}

static void to_lower_str(char *s) {
    for (; *s; ++s) *s = (char)tolower((unsigned char)*s);
}

static int path_is_within(const char *path, const char *dir) {
    size_t n = strlen(dir);
    if (strncmp(path, dir, n) != 0) return 0;
    if (path[n] == '\0') return 1;
    if (path[n] == '/') return 1;
    return 0;
}

/* Normalize an absolute path syntactically (resolve '.' and '..' without following symlinks). */
static int normalize_abs_path(const char *input_abs, char out[PATH_MAX]) {
    if (!input_abs || input_abs[0] != '/') return -1;
    char tmp[PATH_MAX];
    if (strlen(input_abs) >= sizeof(tmp)) return -1;
    strcpy(tmp, input_abs);

    char result[PATH_MAX];
    size_t rlen = 0;
    result[rlen++] = '/';
    result[rlen] = '\0';

    char token[NAME_MAX + 1];
    size_t i = 1; /* skip leading '/' */
    while (tmp[i] != '\0') {
        /* extract next segment */
        size_t tlen = 0;
        while (tmp[i] != '\0' && tmp[i] != '/') {
            if (tlen < NAME_MAX) token[tlen++] = tmp[i];
            i++;
        }
        token[tlen] = '\0';
        while (tmp[i] == '/') i++; /* skip repeated '/' */

        if (tlen == 0 || (tlen == 1 && token[0] == '.')) {
            continue;
        } else if (tlen == 2 && token[0] == '.' && token[1] == '.') {
            /* pop one segment from result if possible */
            if (rlen > 1) {
                /* remove trailing slash if any */
                if (result[rlen-1] == '/' && rlen > 1) rlen--;
                /* find previous '/' */
                while (rlen > 1 && result[rlen-1] != '/') rlen--;
                /* now keep the trailing slash */
            }
            result[rlen] = '\0';
        } else {
            if (rlen > 1 && result[rlen-1] != '/') {
                if (rlen + 1 >= sizeof(result)) return -1;
                result[rlen++] = '/';
            }
            size_t need = strlen(token);
            if (rlen + need >= sizeof(result)) return -1;
            memcpy(result + rlen, token, need);
            rlen += need;
            result[rlen] = '\0';
        }
    }
    if (rlen > 1 && result[rlen-1] == '/') {
        result[rlen-1] = '\0';
    }
    strncpy(out, result, PATH_MAX);
    out[PATH_MAX-1] = '\0';
    return 0;
}

/* Build absolute normalized path from possibly relative input. */
static int make_absolute_normalized(const char *in, char out[PATH_MAX]) {
    char base[PATH_MAX];
    if (!in || !out) return -1;
    if (in[0] == '/') {
        return normalize_abs_path(in, out);
    }
    if (!getcwd(base, sizeof(base))) return -1;
    char absbuf[PATH_MAX];
    if (snprintf(absbuf, sizeof(absbuf), "%s/%s", base, in) >= (int)sizeof(absbuf)) return -1;
    return normalize_abs_path(absbuf, out);
}

static int mkdir_p_mode(const char *path, mode_t mode) {
    char buf[PATH_MAX];
    if (!path || strlen(path) >= sizeof(buf)) return -1;
    strcpy(buf, path);

    if (buf[0] != '/') return -1; /* expect absolute */

    size_t len = strlen(buf);
    if (len == 0) return -1;

    for (size_t i = 1; i < len; ++i) {
        if (buf[i] == '/') {
            buf[i] = '\0';
            if (strlen(buf) > 0) {
                if (mkdir(buf, 0775) == -1 && errno != EEXIST) {
                    buf[i] = '/';
                    return -1;
                }
            }
            buf[i] = '/';
        }
    }
    if (mkdir(buf, mode) == -1) {
        if (errno == EEXIST) {
            /* adjust mode */
            chmod(buf, mode);
            return 0;
        }
        return -1;
    }
    return 0;
}

static int ensure_parent_dir(const char *path) {
    char tmp[PATH_MAX];
    if (strlen(path) >= sizeof(tmp)) return -1;
    strcpy(tmp, path);
    /* remove last component */
    char *slash = strrchr(tmp, '/');
    if (!slash) return -1;
    if (slash == tmp) {
        /* parent is root */
        tmp[1] = '\0';
    } else {
        *slash = '\0';
    }
    struct stat st;
    if (stat(tmp, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        errno = ENOTDIR;
        return -1;
    }
    return mkdir_p_mode(tmp, 0775);
}

static int copy_file_mode(const char *src, const char *dst, mode_t mode) {
    int sfd = open(src, O_RDONLY);
    if (sfd < 0) return -1;
    if (ensure_parent_dir(dst) != 0) { close(sfd); return -1; }
    int dfd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (dfd < 0) { close(sfd); return -1; }
    char buf[131072];
    ssize_t r;
    while ((r = read(sfd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dfd, buf + off, (size_t)(r - off));
            if (w < 0) { close(sfd); close(dfd); return -1; }
            off += w;
        }
    }
    if (r < 0) { close(sfd); close(dfd); return -1; }
    fchmod(dfd, mode & 07777);
    close(sfd);
    if (close(dfd) != 0) return -1;
    return 0;
}

static int has_excluded_ext(const char *path) {
    if (ext_count <= 0) return 0;
    const char *base = strrchr(path, '/');
    base = base ? base + 1 : path;
    const char *dot = strrchr(base, '.');
    if (!dot || dot == base) return 0;
    char extbuf[EXT_LEN];
    if (strlen(dot) >= sizeof(extbuf)) return 0; /* ignore if ext too long */
    strcpy(extbuf, dot);
    to_lower_str(extbuf);
    for (int i = 0; i < ext_count; ++i) {
        if (strcmp(extbuf, exts[i]) == 0) return 1;
    }
    return 0;
}

static int copy_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)ftwbuf;
    char dpath[PATH_MAX];
    const char *rel = fpath + src_root_len;
    if (*rel == '\0') {
        /* root */
        snprintf(dpath, sizeof(dpath), "%s", dst_root);
    } else if (*rel == '/') {
        snprintf(dpath, sizeof(dpath), "%s%s", dst_root, rel);
    } else {
        snprintf(dpath, sizeof(dpath), "%s/%s", dst_root, rel);
    }

    switch (typeflag) {
        case FTW_D: {
            /* create directory */
            if (mkdir_p_mode(dpath, sb->st_mode & 07777) != 0) {
                fprintf(stderr, "Error: cannot create directory '%s': %s\n", dpath, strerror(errno));
                /* continue traversal */
            } else {
                chmod(dpath, sb->st_mode & 07777);
            }
            break;
        }
        case FTW_F: {
            if (has_excluded_ext(fpath)) {
                /* skip copying this file */
                break;
            }
            if (copy_file_mode(fpath, dpath, sb->st_mode) != 0) {
                fprintf(stderr, "Error: failed to copy '%s' -> '%s': %s\n", fpath, dpath, strerror(errno));
            }
            break;
        }
        default:
            /* skip other types (symlinks, devices, etc.) */
            break;
    }
    return 0;
}

static int rm_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
    (void)sb; (void)ftwbuf;
    int rc = 0;
    if (typeflag == FTW_DP || typeflag == FTW_D) {
        rc = rmdir(fpath);
    } else {
        rc = unlink(fpath);
        if (rc != 0 && (typeflag == FTW_SL || typeflag == FTW_SLN)) {
            /* try lstat'd symlink removal */
            rc = unlink(fpath);
        }
        if (rc != 0 && typeflag == FTW_F) {
            rc = unlink(fpath);
        }
    }
    if (rc != 0) {
        fprintf(stderr, "Warning: failed to remove '%s': %s\n", fpath, strerror(errno));
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    const char *src_in = argv[1];
    const char *dst_in = argv[2];
    const char *opt = argv[3];

    if (strcmp(opt, "-cp") == 0) do_move = 0;
    else if (strcmp(opt, "-mv") == 0) do_move = 1;
    else {
        fprintf(stderr, "Error: option must be -cp or -mv\n");
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    /* parse extensions */
    ext_count = 0;
    for (int i = 4; i < argc; ++i) {
        if (ext_count >= MAX_EXT) {
            fprintf(stderr, "Error: too many extensions (max %d)\n", MAX_EXT);
            return EXIT_FAILURE;
        }
        char buf[EXT_LEN];
        if (strlen(argv[i]) >= sizeof(buf)) {
            fprintf(stderr, "Error: extension too long: %s\n", argv[i]);
            return EXIT_FAILURE;
        }
        if (argv[i][0] == '.') snprintf(buf, sizeof(buf), "%s", argv[i]);
        else snprintf(buf, sizeof(buf), ".%s", argv[i]);
        to_lower_str(buf);
        strncpy(exts[ext_count], buf, EXT_LEN);
        exts[ext_count][EXT_LEN-1] = '\0';
        ext_count++;
    }

    /* get HOME */
    const char *home = getenv("HOME");
    if (!home || !realpath(home, home_dir)) {
        fprintf(stderr, "Error: cannot determine HOME directory\n");
        return EXIT_FAILURE;
    }

    /* Resolve source absolute normalized path and verify it exists */
    char src_abs[PATH_MAX];
    if (!realpath(src_in, src_abs)) {
        fprintf(stderr, "Error: source directory does not exist or cannot be resolved: %s\n", src_in);
        return EXIT_FAILURE;
    }
    /* verify it's a directory */
    struct stat stsrc;
    if (stat(src_abs, &stsrc) != 0 || !S_ISDIR(stsrc.st_mode)) {
        fprintf(stderr, "Error: source is not a directory: %s\n", src_in);
        return EXIT_FAILURE;
    }

    /* Destination absolute normalized even if it doesn't exist */
    char dst_abs[PATH_MAX];
    if (make_absolute_normalized(dst_in, dst_abs) != 0) {
        fprintf(stderr, "Error: cannot resolve destination path: %s\n", dst_in);
        return EXIT_FAILURE;
    }

    /* Strip trailing slashes for consistent prefix checks */
    strip_trailing_slashes(src_abs);
    strip_trailing_slashes(dst_abs);
    strip_trailing_slashes(home_dir);

    /* Check both within HOME hierarchy */
    if (!path_is_within(src_abs, home_dir)) {
        fprintf(stderr, "Error: source directory must belong to the home directory hierarchy.\n");
        return EXIT_FAILURE;
    }
    if (!path_is_within(dst_abs, home_dir)) {
        fprintf(stderr, "Error: destination directory must belong to the home directory hierarchy.\n");
        return EXIT_FAILURE;
    }

    /* Prevent copying into itself or nested relations */
    if (strcmp(src_abs, dst_abs) == 0 || path_is_within(dst_abs, src_abs) || path_is_within(src_abs, dst_abs)) {
        fprintf(stderr, "Error: source and destination must be distinct and not nested within each other.\n");
        return EXIT_FAILURE;
    }

    /* Create destination root directory if needed */
    struct stat stdst;
    if (stat(dst_abs, &stdst) != 0) {
        if (errno == ENOENT) {
            if (mkdir_p_mode(dst_abs, 0775) != 0) {
                fprintf(stderr, "Error: cannot create destination directory '%s': %s\n", dst_abs, strerror(errno));
                return EXIT_FAILURE;
            }
        } else {
            fprintf(stderr, "Error: cannot stat destination '%s': %s\n", dst_abs, strerror(errno));
            return EXIT_FAILURE;
        }
    } else if (!S_ISDIR(stdst.st_mode)) {
        fprintf(stderr, "Error: destination path exists and is not a directory.\n");
        return EXIT_FAILURE;
    }

    /* Set globals for callbacks */
    strncpy(src_root, src_abs, sizeof(src_root)); src_root[sizeof(src_root)-1] = '\0';
    strncpy(dst_root, dst_abs, sizeof(dst_root)); dst_root[sizeof(dst_root)-1] = '\0';
    src_root_len = strlen(src_root);

    /* Ensure destination root has at least 0755 */
    chmod(dst_root, 0775);

    /* Traverse and copy */
    int rc = nftw(src_root, copy_cb, 20, FTW_PHYS);
    if (rc != 0) {
        /* nftw returns nonzero if callback returns nonzero; we always return 0, so rc!=0 means internal nftw error */
        fprintf(stderr, "Error: nftw traversal failed during copy.\n");
        return EXIT_FAILURE;
    }

    if (do_move) {
        /* Delete original subtree entirely */
        int rc2 = nftw(src_root, rm_cb, 20, FTW_PHYS | FTW_DEPTH);
        if (rc2 != 0) {
            fprintf(stderr, "Error: failed to delete source subtree after move.\n");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}


Sample runs:
- ncpmvdir ./folder1 ./folder2/folder3 -cp txt pdf
  Copies the directory tree rooted at ./folder1 into ./folder2/folder3 (creating it if needed), excluding .txt and .pdf files, preserving hierarchy.
- ncpmvdir ~/folder1 ~/folder3 -mv
  Moves the entire directory tree rooted at ~/folder1 into ~/folder3, preserving hierarchy and deleting the original source subtree entirely.

Below is a complete MATLAB/YALMIP script that formulates the H2 state-feedback problem using the Schur complement with the substitution Y = KX, solves it, and adds step response plots comparing the H2 controller with an LQR controller for both the plant output y and the control input u.

% H2 state-feedback via LMIs (Schur complement) with step comparisons vs LQR
clc
clear
close all

% Load data and identify model (requires System Identification Toolbox)
load('data3.mat');                      % expects variable data3
G3  = bj(data3, [5 5 5 5 1]);           % Box-Jenkins identification (SISO)
G3c = d2c(G3);                          % Discrete -> continuous
sysc = ss(G3c);                         % Convert to state-space
[A,B,C,D] = ssdata(sysc);
n = size(A,1);
m = size(B,2);
p = size(C,1);

% Generalized plant for H2:
% xdot = A x + B (w + u),   u = -K x
% z    = [y1; y2] = [C x; -K x] = C1 x + D12 u
C1  = [C; zeros(m,n)];
D12 = [zeros(p,m); eye(m)];

% YALMIP decision variables
X = sdpvar(n,n,'symmetric');            % X > 0
Y = sdpvar(m,n,'full');                 % Y = K X
Z = sdpvar(p+m,p+m,'symmetric');        % For H2 objective via Schur complement

% LMIs:
% 1) Closed-loop Lyapunov with disturbance at B (B_w = B):
%    A X + X A' - (B Y + Y' B') + B B' < 0
eps_stab = 1e-9;
LMI_cl = A*X + X*A' - (B*Y + Y'*B') + (B*B') <= -eps_stab*eye(n);

% 2) H2 objective (z = C1 x + D12 u, u = -K x, Y = KX) via Schur complement:
%    [ Z,  (C1 X - D12 Y)
%      *,               X ] >= 0
LMI_h2 = [ Z,              (C1*X - D12*Y) ; 
           (C1*X - D12*Y)',             X ] >= 0;

% Positive definiteness
LMI_pos = X >= 1e-6*eye(n);

Constraints = [LMI_cl, LMI_h2, LMI_pos];

% Objective: minimize trace(Z) = ||T_{w->z}||_2^2
Objective = trace(Z);

% Select solver (MOSEK preferred; fallback to SeDuMi)
if exist('mosekopt','file') == 3 || exist('mosekopt','file') == 2
    solver = 'mosek';
else
    solver = 'sedumi';
end
ops = sdpsettings('solver',solver,'verbose',1);

% Solve the SDP
sol = optimize(Constraints, Objective, ops);
if sol.problem ~= 0
    error('SDP failed: %s', sol.info);
end

% Recover controller K and H2 norm
Xv = value(X);
Yv = value(Y);
Kv = Yv / Xv;                           % K = Y * X^{-1}
H2sq  = value(trace(Z));                 % squared H2 norm from w to z
H2norm = sqrt(max(H2sq,0));

fprintf('Controller synthesis successful.\n');
fprintf('||T_{w->z}||_2 = %.6f\n', H2norm);

% Closed-loop systems (from disturbance w to outputs)
Acl = A - B*Kv;
Bcl = B;                                 % disturbance w enters via B
Cy  = C;                                 % output y
Dyw = zeros(p, m);

% Output y to w (H2 and LQR)
sys_y_H2  = ss(Acl, Bcl, Cy,  Dyw);

% Control input u = -K x (as an output) to w
Cu  = -Kv;                               % maps x to u
Duw = zeros(m, m);
sys_u_H2  = ss(Acl, Bcl, Cu,  Duw);

% LQR comparison
Q = eye(n);
R = 1;
K_lqr = lqr(A,B,Q,R);
Acl_lqr = A - B*K_lqr;
sys_y_LQR = ss(Acl_lqr, Bcl, Cy,    Dyw);
sys_u_LQR = ss(Acl_lqr, Bcl, -K_lqr, Duw);

% Step response comparisons (disturbance step at w)
tFinal = 5;   % seconds (adjust as needed)

figure;
step(sys_y_H2, sys_y_LQR, tFinal);
legend('H2','LQR','Location','best');
title('Output y: step in disturbance w');
grid on;

figure;
step(sys_u_H2, sys_u_LQR, tFinal);
legend('H2','LQR','Location','best');
title('Control input u: step in disturbance w');
grid on;

% Optional: closed-loop poles
fprintf('Closed-loop poles (H2):\n');
disp(eig(Acl));
fprintf('Closed-loop poles (LQR):\n');
disp(eig(Acl_lqr));

indicator("Structural Pivots Method (SPM) v5", overlay=true, max_labels_count=500)

// ==========================
// State for Anchor/Reference
// ==========================
var int   anchorIdx   = na
var float anchorHigh  = na
var float anchorLow   = na
var float anchorClose = na

// Initialize anchor on the first bar
if barstate.isfirst
    anchorIdx   := bar_index
    anchorHigh  := high
    anchorLow   := low
    anchorClose := close

// =====================================
// Counters for non-consecutive Bar1/Bar2
// =====================================
var int lowerCount = 0   // For SPH confirmation: bars with low < anchorLow AND close < anchorClose
var int higherCount = 0  // For SPL confirmation: bars with high > anchorHigh AND close > anchorClose
var int lowerLastCountedIdx = na
var int higherLastCountedIdx = na
var int bar1Lower = na
var int bar2Lower = na
var int bar1Higher = na
var int bar2Higher = na

// ==============================
// Small Pivot candidates & state
// ==============================
// lastSmallType:  1 = SPH, -1 = SPL, 0 = none yet
var int   lastSmallType  = 0
var int   lastSPHIdx     = na
var float lastSPHPrice   = na
var bool  lastSPHTemp    = false
var int   lastSPLIdx     = na
var float lastSPLPrice   = na
var bool  lastSPLTemp    = false

// Running candidates (high/low between alternating pivots)
var float swingHighCand = na
var int   swingHighIdx  = na
var float swingLowCand  = na
var int   swingLowIdx   = na

// Initialize candidates on first bar
if barstate.isfirst
    swingHighCand := high
    swingHighIdx  := bar_index
    swingLowCand  := low
    swingLowIdx   := bar_index

// Determine which small pivot we are currently expecting (alternation)
// 1 => expecting SPH, -1 => expecting SPL, 0 => first pivot (either side)
expectedSmall = lastSmallType == 1 ? -1 : lastSmallType == -1 ? 1 : 0

// Update candidates continuously according to what we're expecting
if expectedSmall == 1 or expectedSmall == 0
    if na(swingHighCand) or high > swingHighCand
        swingHighCand := high
        swingHighIdx  := bar_index

if expectedSmall == -1 or expectedSmall == 0
    if na(swingLowCand) or low < swingLowCand
        swingLowCand := low
        swingLowIdx  := bar_index

// ================================
// Count non-consecutive Bar1/Bar2
// ================================
condLower = (low < anchorLow) and (close < anchorClose)
condHigher = (high > anchorHigh) and (close > anchorClose)

if (expectedSmall == 1 or expectedSmall == 0) and condLower and lowerLastCountedIdx != bar_index
    lowerCount += 1
    lowerLastCountedIdx := bar_index
    if lowerCount == 1
        bar1Lower := bar_index
    if lowerCount == 2
        bar2Lower := bar_index

if (expectedSmall == -1 or expectedSmall == 0) and condHigher and higherLastCountedIdx != bar_index
    higherCount += 1
    higherLastCountedIdx := bar_index
    if higherCount == 1
        bar1Higher := bar_index
    if higherCount == 2
        bar2Higher := bar_index

// ==================================
// Small Pivot marking (with altern.)
// ==================================
var label lbl = na
newSPH = false
newSPL = false

// Helper to set anchor to a given bar index (bar2 of the last pivot)
f_set_anchor_for_idx(idx) =>
    int barsAgo = bar_index - idx
    [high[barsAgo], low[barsAgo], close[barsAgo]]

// Mark SPH when two lower bars vs anchor are formed (non-consecutive allowed)
if (lastSmallType == -1 or lastSmallType == 0) and lowerCount >= 2 and not na(swingHighCand)
    // SPH is highest point between SPLs (tracked as swingHighCand/Idx)
    lastSmallType := 1
    lastSPHPrice  := swingHighCand
    lastSPHIdx    := swingHighIdx
    lastSPHTemp   := true
    newSPH        := true

    // Previous SPL (if any) becomes permanent now
    if not na(lastSPLIdx)
        lastSPLTemp := false
        // Optional label to denote permanence
        lbl := label.new(lastSPLIdx, lastSPLPrice, "SPL (perm)", style=label.style_label_up, color=color.new(color.lime, 0), textcolor=color.white)

    // Label for new SPH (temp)
    lbl := label.new(lastSPHIdx, lastSPHPrice, "SPH (temp)", style=label.style_label_down, color=color.new(color.red, 0), textcolor=color.white)

    // Anchor becomes Bar2 of this SPH detection (bar with second lower low/close)
    if not na(bar2Lower)
        [ah, al, ac] = f_set_anchor_for_idx(bar2Lower)
        anchorHigh  := ah
        anchorLow   := al
        anchorClose := ac
        anchorIdx   := bar2Lower

    // Reset counters; switch to searching SPL
    lowerCount := 0
    bar1Lower  := na
    bar2Lower  := na
    higherCount := 0
    bar1Higher  := na
    bar2Higher  := na

    // Reset and start tracking next swing low candidate
    swingLowCand := low
    swingLowIdx  := bar_index

// Mark SPL when two higher bars vs anchor are formed (non-consecutive allowed)
if (lastSmallType == 1 or lastSmallType == 0) and higherCount >= 2 and not na(swingLowCand)
    // SPL is lowest point between SPHs (tracked as swingLowCand/Idx)
    lastSmallType := -1
    lastSPLPrice  := swingLowCand
    lastSPLIdx    := swingLowIdx
    lastSPLTemp   := true
    newSPL        := true

    // Previous SPH (if any) becomes permanent now
    if not na(lastSPHIdx)
        lastSPHTemp := false
        // Optional label to denote permanence
        lbl := label.new(lastSPHIdx, lastSPHPrice, "SPH (perm)", style=label.style_label_down, color=color.new(color.maroon, 0), textcolor=color.white)

    // Label for new SPL (temp)
    lbl := label.new(lastSPLIdx, lastSPLPrice, "SPL (temp)", style=label.style_label_up, color=color.new(color.green, 0), textcolor=color.white)

    // Anchor becomes Bar2 of this SPL detection (bar with second higher high/close)
    if not na(bar2Higher)
        [ah2, al2, ac2] = f_set_anchor_for_idx(bar2Higher)
        anchorHigh  := ah2
        anchorLow   := al2
        anchorClose := ac2
        anchorIdx   := bar2Higher

    // Reset counters; switch to searching SPH
    higherCount := 0
    bar1Higher  := na
    bar2Higher  := na
    lowerCount := 0
    bar1Lower  := na
    bar2Lower  := na

    // Reset and start tracking next swing high candidate
    swingHighCand := high
    swingHighIdx  := bar_index

// ==================================
// Large Pivots (LPH/LPL) logic
// ==================================
// We maintain rolling best SPH since last LPL and best SPL since last LPH
var float maxSPHSinceLastLPLPrice = na
var int   maxSPHSinceLastLPLIdx   = na
var float minSPLSinceLastLPHPrice = na
