// Mark LPL when breaking the most recent SPH; choose lowest SPL since last LPH
if breakSPH and (lastLPType != -1) and not na(minSPLSinceLastLPHPrice)
    prevLPLPrice := lastLPLPrice
    lastLPLPrice := minSPLSinceLastLPHPrice
