    // Draw LPL label at chosen SPL
    lbl := label.new(lastLPLIdx, lastLPLPrice, "LPL", style=label.style_label_up, color=color.new(color.teal, 0), textcolor=color.white)
    // Reset SPH-max aggregator for the next LPH cycle
    maxSPHSinceLastLPLPrice := na
