// ======================
// Buy/Sell signal logic
// ======================
buySignal  = not na(prevLPHPrice) and not na(prevLPLPrice) and not na(lastLPHPrice) and not na(lastLPLPrice) and (lastLPHPrice > prevLPHPrice) and (lastLPLPrice > prevLPLPrice)
sellSignal = not na(prevLPHPrice) and not na(prevLPLPrice) and not na(lastLPHPrice) and not na(lastLPLPrice) and (lastLPHPrice < prevLPHPrice) and (lastLPLPrice < prevLPLPrice)

plotshape(buySignal,  title="Buy", style=shape.triangleup,   location=location.belowbar, color=color.new(color.lime, 0), size=size.tiny, text="Buy")
plotshape(sellSignal, title="Sell", style=shape.triangledown, location=location.abovebar, color=color.new(color.red, 0),  size=size.tiny, text="Sell")

// ==========================
// Visual aids (optional)
// ==========================
plotchar(not na(lastSPHIdx) and bar_index == lastSPHIdx, title="SPH idx marker", char='^', location=location.abovebar, color=color.new(color.red, 70), size=size.tiny)
plotchar(not na(lastSPLIdx) and bar_index == lastSPLIdx, title="SPL idx marker", char='v', location=location.belowbar, color=color.new(color.green, 70), size=size.tiny)

// End of SPM v5 implementation

