    cand_max_idx  := bar_index
if na(cand_min_low) or low < cand_min_low
    cand_min_low := low
    cand_min_idx := bar_index

//==============================
// Count non-consecutive Bar1 & Bar2 relative to anchor (do not reset until pivot marks)
//==============================
