// Helper to finalize a small pivot and set next anchor = Bar2
//==============================
mark_small_pivot(_type, _price, _idx) =>
    // _type: 1=SPH, -1=SPL
    // Mark previous temp small pivot as permanent (on alternating)
    if not na(lastTempSmallLabel)
        label.set_textcolor(lastTempSmallLabel, color.white)
        label.set_style(lastTempSmallLabel, label.style_label_left)
        label.set_color(lastTempSmallLabel, _type == 1 ? color.new(color.red, 0) : color.new(color.blue, 0))
