        label.set_text(lastTempSmallLabel, str.replace_all(t, "(temp)", "(perm)"))
    // Create new temp small pivot label
    label newLbl = na
    if _type == 1
        array.push(sphPrices, _price)
        array.push(sphIdx, _idx)
        newLbl := label.new(_idx, _price, text="SPH (temp)", style=label.style_label_down, color=color.new(color.orange, 0), textcolor=color.black)
    else
        array.push(splPrices, _price)
        array.push(splIdx, _idx)
        newLbl := label.new(_idx, _price, text="SPL (temp)", style=label.style_label_up, color=color.new(color.aqua, 0), textcolor=color.black)
    lastTempSmallLabel := newLbl
    // Set last small type and Bar2 anchor = current bar
    last_small_type := _type
    last_small_bar2_idx := bar_index
