            System.out.println("VERIFICATION PASSED: Computed table matches the expected results.");
        } else {
            System.err.println("VERIFICATION FAILED: Differences found. Shutting down now.");
            System.exit(1);
        }
    }

    // Compute normalized LAT: for each a,b: (# of x with <a,x> == <b,S(x)>) - 4
    private static int[][] normalizedLat(int[] sbox) {
        int n = sbox.length;          // 8 inputs
        int half = n / 2;             // 4
        int[][] table = new int[n][n];

        for (int a = 0; a < n; a++) {
            for (int b = 0; b < n; b++) {
                int countZero = 0;
                for (int x = 0; x < n; x++) {
                    int u = parity(a & x);         // <a, x>
                    int v = parity(b & sbox[x]);   // <b, S(x)>
                    if ((u ^ v) == 0) {
                        countZero++;
                    }
                }
                table[a][b] = countZero - half;    // normalize to {-4,-2,0,2,4}
            }
        }
        return table;
    }

    // Parity of bits (mod 2): returns 0 if even, 1 if odd
    private static int parity(int x) {
        return Integer.bitCount(x) & 1;
    }

    // Print rows as comma-separated values to match the expected format
    private static void printTable(int[][] table) {
        for (int i = 0; i < table.length; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < table[i].length; j++) {
                if (j > 0) sb.append(", ");
                sb.append(table[i][j]);
            }
            System.out.println(sb.toString());
        }
    }

    // Verify computed table equals expected; print first mismatch for rapid diagnosis
    private static boolean verifyTable(int[][] actual, int[][] expected) {
        if (actual.length != expected.length) {
            System.err.println("Row count mismatch: actual=" + actual.length + ", expected=" + expected.length);
            return false;
        }
        for (int i = 0; i < actual.length; i++) {
            if (actual[i].length != expected[i].length) {
                System.err.println("Column count mismatch at row " + i + ": actual=" + actual[i].length + ", expected=" + expected[i].length);
                return false;
            }
            for (int j = 0; j < actual[i].length; j++) {
                if (actual[i][j] != expected[i][j]) {
                    System.err.println("Mismatch at (row=" + i + ", col=" + j + "): actual=" + actual[i][j] + ", expected=" + expected[i][j]);
                    return false;
                }
            }
        }
        return true;
    }
}

Notes
- This directly fixes the original bug (integer products and XORs on bits) by using dot products mod 2 via parity of bitwise ANDs, which is the correct LAT definition.
- The program prints the normalized table and immediately verifies it against the provided expected matrix, addressing the urgency with clear PASS/FAIL feedback and fast shutdown on failure.

