// In a thread-safe design, exposing data should not allow external mutation
// of the internal state. Here we model that by making the external mutation
// operation a no-op on the internal state (it works on a copy only).
class DataStoreSpec {
    private var data = mutableMapOf<String, String>()

    fun refresh() {
