@StressCTest(
    sequentialSpecification = DataStoreSpec::class
)
class DataStoreLinCheckTest {
    private val sut = DataStore()

    // Writer operation: sets the map to a singleton {"r" -> "r"}
    @Operation
    fun refresh() {
        sut.refreshData("r")
    }

    // Leaked mutation: because getData() exposes the actual mutable map,
    // a client can mutate the internal state without synchronization.
    // This is exactly what we simulate here.
    @Operation
    fun leakPut() {
        sut.getData()["m"] = "m"
    }

    // Reader operation: observe current size
    @Operation
    fun size(): Int = sut.getData().size

    @Test
    fun run() {
        LinChecker.check(DataStoreLinCheckTest::class.java)
    }
}

How this test proves thread-unsafety:
- What is specified as correct: The sequential specification (DataStoreSpec) models a safe design where callers cannot mutate the internal state via getData. The leakPut operation is therefore a no-op in the spec; the state should remain a singleton map after refresh().
- What the implementation does: The actual code returns the internal mutable map reference (getData), allowing external code to mutate the internal state. In leakPut we exploit this by writing a new entry directly into that map.
