# components/DocEditor.tsx
# -------------------------------------------------------------
doc_editor_tsx = r'''
"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import {
  doc,
  getDoc,
  onSnapshot,
  setDoc,
  updateDoc,
  deleteDoc,
  serverTimestamp,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";
import { useRouter } from "next/navigation";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

function normalizeSpacing(text: string) {
  // collapse 3+ blank lines down to 2; ensure trailing single newline
  let out = text.replace(/\n{3,}/g, "\n\n");
  if (!out.endsWith("\n")) out += "\n";
  return out;
}

function enforceSingleH1(title: string, content: string) {
  // Remove any leading H1 and replace with a single H1 from title
  const lines = content.split(/\r?\n/);
  let startIdx = 0;
  if (lines[0]?.startsWith("# ")) {
    startIdx = 1;
    // skip any immediate blank line after H1
    if (lines[1] === "") startIdx = 2;
  }
  const rest = lines.slice(startIdx).join("\n").replace(/^#\s+.*$/gm, (m, offset) => (offset === 0 ? "" : m));
  const header = `# ${title || "Untitled"}`;
  const combined = `${header}\n\n${rest}`.replace(/^\n+/, "");
  return normalizeSpacing(combined);
}

export default function DocEditor({ slug }: { slug: string }) {
  const [loaded, setLoaded] = React.useState(false);
  const [title, setTitle] = React.useState("");
  const [tagsText, setTagsText] = React.useState("");
  const [content, setContent] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [renaming, setRenaming] = React.useState(false);
  const [newSlug, setNewSlug] = React.useState(slug);
  const router = useRouter();

  // Load and live-subscribe
  React.useEffect(() => {
    const dref = doc(db, "docs", slug);
    const unsub = onSnapshot(dref, (snap) => {
      if (!snap.exists()) {
        setLoaded(true);
        return;
      }
      const data = snap.data() as DocData;
      setTitle(data.title || slug);
      setTagsText((data.tags || []).join(", "));
      setContent(data.content || "");
      setLoaded(true);
    });
    return () => unsub();
  }, [slug]);

  const outline = React.useMemo(() => {
    const items: { level: number; text: string; id: string }[] = [];
    const re = /^(#{1,6})\s+(.+)$/gm;
    let m: RegExpExecArray | null;
    while ((m = re.exec(content))) {
      const level = m[1].length;
      const text = m[2].replace(/[#`*_~]/g, "").trim();
      const id = text.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)+/g, "");
      items.push({ level, text, id });
    }
    return items;
  }, [content]);

  async function save(formatFirst = false) {
    setSaving(true);
    try {
      const dref = doc(db, "docs", slug);
      let nextContent = content;
      if (formatFirst) {
        nextContent = enforceSingleH1(title, nextContent);
      }
      await updateDoc(dref, {
        title: title || slug,
        content: normalizeSpacing(nextContent),
        tags: tagsText
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean),
        updatedAt: serverTimestamp(),
      }).catch(async (e) => {
        // If doc doesn't exist yet, create it
        const snap = await getDoc(dref);
        if (!snap.exists()) {
          await setDoc(dref, {
            title: title || slug,
            content: normalizeSpacing(nextContent),
            tags: tagsText
              .split(",")
              .map((s) => s.trim())
              .filter(Boolean),
            createdAt: serverTimestamp(),
            updatedAt: serverTimestamp(),
          });
        } else {
          throw e;
        }
      });
    } finally {
      setSaving(false);
    }
  }

  async function onUploadImage(file: File): Promise<string> {
    const path = `docs/${slug}/images/${Date.now()}_${file.name}`;
    const sref = ref(storage, path);
    await uploadBytes(sref, file);
    return await getDownloadURL(sref);
  }

  async function onDelete() {
    if (!confirm("Delete this document? This cannot be undone.")) return;
    await deleteDoc(doc(db, "docs", slug));
    router.push("/docs");
  }

  async function onRename() {
    const target = slugify(newSlug);
    if (!target || target === slug) return;
    setRenaming(true);
    try {
      const oldRef = doc(db, "docs", slug);
      const oldSnap = await getDoc(oldRef);
      if (!oldSnap.exists()) return;
      const data = oldSnap.data() as DocData;
      const newRef = doc(db, "docs", target);
      await setDoc(newRef, {
        ...data,
        title: title || target,
        updatedAt: serverTimestamp(),
        createdAt: data.createdAt || serverTimestamp(),
      });
      await deleteDoc(oldRef);
      router.replace(`/docs/${target}`);
    } finally {
      setRenaming(false);
    }
  }

  if (!loaded) {
    return <div className="p-4">Loading...</div>;
  }

  return (
    <div className="grid grid-cols-1 gap-6 md:grid-cols-[1fr_280px]">
      <div className="space-y-4">
        <div className="rounded-md border bg-card p-3">
          <div className="flex flex-col gap-2 md:flex-row md:items-center md:gap-3">
            <input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Document title"
              className="w-full rounded-md border px-3 py-2"
            />
            <input
              value={tagsText}
              onChange={(e) => setTagsText(e.target.value)}
              placeholder="tags: comma, separated"
              className="w-full rounded-md border px-3 py-2 md:max-w-sm"
            />
            <button
              onClick={() => save(true)}
              disabled={saving}
              className="rounded-md bg-primary px-4 py-2 text-white disabled:opacity-50"
            >
              {saving ? "Saving..." : "Format & Save"}
            </button>
            <button
              onClick={onDelete}
              className="rounded-md border border-destructive px-4 py-2 text-destructive"
            >
              Delete
            </button>
          </div>
        </div>

        <MarkdownRXEditor value={content} onChange={setContent} onUploadImage={onUploadImage} />
      </div>

      <aside className="space-y-4">
        <div className="rounded-md border bg-card p-3">
          <h3 className="mb-2 text-sm font-medium">Outline</h3>
          <ul className="space-y-1 text-sm">
            {outline.length === 0 && (
              <li className="text-muted-foreground">No headings yet.</li>
            )}
            {outline.map((h, i) => (
              <li key={i} style={{ paddingLeft: (h.level - 1) * 8 }}>
                <span className="text-muted-foreground">{Array(h.level).fill("#").join("")}</span> {h.text}
              </li>
            ))}
          </ul>
        </div>

        <div className="rounded-md border bg-card p-3">
          <h3 className="mb-2 text-sm font-medium">Rename</h3>
          <div className="flex gap-2">
            <input
              value={newSlug}
              onChange={(e) => setNewSlug(e.target.value)}
              className="w-full rounded-md border px-3 py-2"
            />
            <button
              onClick={onRename}
              disabled={renaming}
              className="rounded-md border px-3 py-2 disabled:opacity-50"
            >
              {renaming ? "Renaming..." : "Apply"}
            </button>
          </div>
          <p className="mt-1 text-xs text-muted-foreground">New path: /docs/{slugify(newSlug) || ""}</p>
        </div>

        <div className="rounded-md border bg-card p-3">
          <h3 className="mb-2 text-sm font-medium">Preview</h3>
          <div className="prose max-w-none">
            <MarkdownRXPreview value={content} />
          </div>
        </div>
      </aside>
    </div>
  );
}
'''
