Notes
- The /docs page uses React hooks, so it begins with "use client". The [slug] page is a server component that renders the client Editor; no hooks there, so no directive needed. All hook-using components (MarkdownRX.tsx and DocEditor.tsx) include "use client" at the top.
- The DocEditor’s Format & Save button enforces: a single H1 from the title, normalized blank lines, and a trailing newline. This helps keep documentation formatting consistent.
- The Outline panel is computed from markdown headings and encourages a structured document. You can link headings by adding ids in MarkdownRX if desired.
- For better readability, install and enable @tailwindcss/typography and wrap previews in className="prose max-w-none" (already applied).
- Image uploads are stored under docs/{slug}/images/. Renaming a doc does not move images; you can optionally implement a Storage copy/move if needed.

Here is a complete JavaScript (Canvas) solution that renders a center line at 1px across 100% width inside a 32px-tall area, with a dot that scans left-to-right and periodically "pulses" by stretching vertically using a triangular envelope (up then down over ~1s). No waveform is drawn on the line; only the dot changes height. JavaScript is used (instead of CSS-only) to support precise timing, random pulse positions per sweep, and responsive width.

<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <title>ECG-like Pulse Dot</title>
    <style>
      /* Container: 100% width, fixed 32px height */
      .ecg {
        width: 100%;
        height: 32px;
        position: relative;
        background: #000; /* optional: dark background for contrast */
      }
      .ecg canvas {
        width: 100%;
        height: 100%;
        display: block;
      }
    </style>
  </head>
  <body>
    <div id="ecg" class="ecg"></div>

    <script>
      (function () {
        const container = document.getElementById('ecg');
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        container.appendChild(canvas);

        let width = 0, height = 0, centerY = 0;

        // Visual parameters
        const lineColor = '#e00000';    // center line color
        const dotColor  = '#0070ff';    // moving dot color
        const dotWidth  = 4;            // horizontal width of the dot (px)
        const normalH   = 6;            // normal dot height (px)
        const maxH      = 28;           // max pulse height (px), within 32px container

        // Motion/pulse parameters
        let speed = 240;                // horizontal speed in px/s
        const pulseDuration = 1000;     // one pulse takes ~1 second

        // State
        let dotX = -dotWidth / 2;       // start slightly off-screen
        let pulseActive = false;
        let pulseStart = 0;
        let pulseTriggerX = 0;          // where in this sweep the pulse starts

        // High-DPI aware resize
        function resize() {
          const dpr = window.devicePixelRatio || 1;
          const w = container.clientWidth;
          const h = container.clientHeight; // will be 32px

          // set backing store size
          canvas.width = Math.max(1, Math.floor(w * dpr));
          canvas.height = Math.max(1, Math.floor(h * dpr));
          // CSS size
          canvas.style.width = w + 'px';
          canvas.style.height = h + 'px';
          // draw in CSS pixels
          ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

          width = w;
          height = h;
          centerY = height / 2;
        }

        function schedulePulse() {
          // Choose a random trigger within the sweep (avoid edges)
          pulseTriggerX = Math.random() * (width * 0.7) + width * 0.15;
          // If the dot already passed this spot in the current sweep, push to next sweep
          if (dotX > pulseTriggerX) pulseTriggerX += width;
        }

        function roundedRect(x, y, w, h, r) {
          const rr = Math.min(r, w / 2, h / 2);
          ctx.beginPath();
          ctx.moveTo(x + rr, y);
          ctx.lineTo(x + w - rr, y);
          ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
          ctx.lineTo(x + w, y + h - rr);
          ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
          ctx.lineTo(x + rr, y + h);
          ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
          ctx.lineTo(x, y + rr);
          ctx.quadraticCurveTo(x, y, x + rr, y);
          ctx.closePath();
          ctx.fill();
        }

        let last = performance.now();
        function frame(now) {
          const dt = (now - last) / 1000;
          last = now;

          // Move dot
          dotX += speed * dt;
          if (dotX - dotWidth / 2 > width) {
            // Wrap to left for a new sweep
            dotX = -dotWidth / 2;
            pulseActive = false;
            schedulePulse();
          }

          // Start pulse when crossing triggerX
          if (!pulseActive && dotX >= pulseTriggerX) {
            pulseActive = true;
            pulseStart = now;
          }

          // Determine current dot height via triangular envelope
          let dotH = normalH;
          if (pulseActive) {
            const t = (now - pulseStart) / pulseDuration; // 0..1
            if (t >= 1) {
              pulseActive = false; // end pulse, no line waveform drawn
              dotH = normalH;
            } else {
              const tri = t < 0.5 ? (t * 2) : (1 - t) * 2; // up then down, linear
              dotH = normalH + tri * (maxH - normalH);
            }
          }

          // Render
          ctx.clearRect(0, 0, width, height);

          // Center line (1px)
          ctx.strokeStyle = lineColor;
          ctx.lineWidth = 1;
          ctx.beginPath();
          // Draw at half-pixel to keep it crisp
          const y = Math.round(centerY) + 0.5;
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
          ctx.stroke();

          // Dot: vertical rounded rect centered on the line
          ctx.fillStyle = dotColor;
          const x = dotX - dotWidth / 2;
          const top = centerY - dotH / 2;
          roundedRect(x, top, dotWidth, dotH, dotWidth / 2);

          requestAnimationFrame(frame);
        }

        window.addEventListener('resize', function () {
          // Preserve relative position on resize
          const ratio = width > 0 ? dotX / width : 0;
          resize();
          dotX = ratio * width;
          schedulePulse();
        });

        resize();
        schedulePulse();
        requestAnimationFrame(frame);
      })();
    </script>
  </body>
</html>

Notes:
- The container strictly enforces 32px height and 100% width; the center line spans the full width.
- The dot moves left-to-right every sweep and pulses once per sweep at a random horizontal position using a triangular envelope (grow then shrink over ~1s).
- No triangular waveform is drawn on the line; only the dot’s height changes, matching the described behavior.
- Using JavaScript (requestAnimationFrame + Canvas) provides precise control over timing, randomization, and responsiveness that is cumbersome or impractical with CSS-only keyframes.
- You can tweak speed, colors, dotWidth, normalH, maxH, and pulseDuration to match your desired look.

Below is a complete, self-contained HTML + JavaScript example that renders a cardio-monitor-style pulsing animation in a 32px-tall, 100%-wide strip. It draws a thin baseline through the center, animates a moving dot from left to right, and periodically grows a vertical spike whose height follows a triangular envelope (grow to peak, then shrink) over about one second. No continuous triangular waveform line is drawn—only the baseline plus the dot/spike.

<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Cardio Pulse (32px height, 100% width)</title>
  <style>
    /* 32px tall, full-width container */
    .ecg {
      width: 100%;
      height: 32px;          /* exact requested height */
      background: #000;      /* monitor-like background */
      position: relative;
      overflow: hidden;
      user-select: none;
    }
    /* Canvas fills the container */
    #ecg {
      width: 100%;
      height: 100%;
      display: block;
    }
  </style>
</head>
<body>
  <div class="ecg">
    <canvas id="ecg"></canvas>
  </div>

  <script>
    (function () {
      const canvas = document.getElementById('ecg');
      const ctx = canvas.getContext('2d');

      let dpr = 1;
      let width = 0;
      let height = 0;

      // Animation state
      let last = performance.now();
      let x = -4;                  // dot starts just off-screen to the left
      let speedPxPerSec = 200;     // dot speed (will be scaled on resize)

      // Pulse state: randomized intervals, 1s triangular envelope
      const pulseDuration = 1000;  // ms
      let pulsing = false;
      let pulseStart = 0;
      let nextPulseAt = performance.now() + 600; // first pulse after ~0.6–1.8s

      function scheduleNextPulse(now) {
        // Next pulse after a random delay (0.6–1.8s) following current or next start
        const delay = 600 + Math.random() * 1200; // ms
        nextPulseAt = now + delay;
      }

      function resize() {
        const rect = canvas.getBoundingClientRect();
        dpr = window.devicePixelRatio || 1;
        canvas.width = Math.round(rect.width * dpr);
        canvas.height = Math.round(rect.height * dpr);
        width = rect.width;
        height = rect.height;
        // Draw using CSS pixel units for crisp 1px strokes
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

        // Make the sweep cross the strip in ~2 seconds regardless of width
        speedPxPerSec = width / 2.0;
      }

      function triangle01(t) {
        // t in [0,1] -> rises to 1 at 0.5, falls to 0 at 1
        return 1 - Math.abs(2 * t - 1);
      }

      function draw() {
        const now = performance.now();
        const dt = Math.min(50, now - last) / 1000; // s, clamp for tab-throttle safety
        last = now;

        // Update dot position (wrap around)
        x += speedPxPerSec * dt;
        if (x > width + 4) x = -4;

        // Pulse timing
        if (!pulsing && now >= nextPulseAt) {
          pulsing = true;
          pulseStart = now;
          // Schedule the next pulse to happen after this one completes
          scheduleNextPulse(now + pulseDuration);
        }
        if (pulsing && (now - pulseStart) >= pulseDuration) {
          pulsing = false;
        }

        // Clear frame
        ctx.clearRect(0, 0, width, height);

        // Baseline (1px) across the center
        const midY = Math.floor(height / 2) + 0.5; // half-pixel for crisp 1px line
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0, 255, 90, 0.9)';
        ctx.beginPath();
        ctx.moveTo(0, midY);
        ctx.lineTo(width, midY);
        ctx.stroke();

        // Glow settings for dot/spike
        ctx.save();
        ctx.shadowColor = 'rgba(0, 255, 120, 0.9)';
        ctx.shadowBlur = 8;

        // Optional vertical spike during pulse; height follows a triangular envelope
        if (pulsing) {
          const t = Math.min(1, (now - pulseStart) / pulseDuration);
          const env = triangle01(t); // 0 -> 1 -> 0 over 1s
          const maxHalf = Math.max(0, (height * 0.5) - 1); // leave 1px margin
          const halfH = env * maxHalf;

          ctx.lineWidth = 2;
          ctx.strokeStyle = '#00ff66';
          ctx.beginPath();
          ctx.moveTo(x, midY - halfH);
          ctx.lineTo(x, midY + halfH);
          ctx.stroke();
        }

        // Moving dot at the center line
        ctx.fillStyle = '#00ff66';
        ctx.beginPath();
        ctx.arc(x, height / 2, 2.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        requestAnimationFrame(draw);
      }

      window.addEventListener('resize', resize);
      resize();
      requestAnimationFrame(draw);
    })();
  </script>
</body>
</html>

Why JavaScript is preferred over CSS here:
- Precise control of timing and randomness: The animation needs the point to pulse at specific or random positions and to hold the pulse for about a second using a triangular envelope. JavaScript can schedule and shape these events programmatically; CSS keyframes are fixed and awkward for randomized, stateful timing without generating dynamic styles.
- Independent elements without distortion: You want a thin baseline line that never thickens while the point grows/shrinks. With CSS transforms (e.g., scaleY), you tend to distort the same element or require complex layering and synchronization. Canvas lets you draw the baseline and the dot/spike independently with pixel-level control.
- Pixel-accurate rendering across devices: Using the device pixel ratio, JavaScript adjusts the canvas so the 1px baseline remains crisp at any DPI, which is harder to guarantee with pure CSS animations.
- Single-pass rendering of custom shapes: The vertical spike whose height follows a triangular envelope is trivial to compute per frame in JS; in CSS you would approximate with multiple keyframes or complex clip-path/filters and still lack the dynamic timing control you asked for.

