// Generic repository (templates) for owning objects
template <typename T>
class Repository {
private:
    std::vector<std::unique_ptr<T>> items_;
public:
    Repository() = default;

    void add(std::unique_ptr<T> item) { items_.push_back(std::move(item)); }

    // Perfect-forwarded emplace for derived types
    template <typename U = T, typename... Args>
    U& emplace(Args&&... args) {
        static_assert(std::is_base_of_v<T, U>, "U must derive from T");
        auto ptr = std::make_unique<U>(std::forward<Args>(args)...);
        U& ref = *ptr;
        items_.push_back(std::move(ptr));
        return ref;
    }

    std::size_t size() const { return items_.size(); }

    const T& operator[](std::size_t i) const { return *items_.at(i); }
    T& operator[](std::size_t i) { return *items_.at(i); }

    const std::vector<std::unique_ptr<T>>& items() const { return items_; }

    // Create a non-owning view of raw pointers for algorithms
    std::vector<const T*> view() const {
        std::vector<const T*> v;
        v.reserve(items_.size());
        for (const auto& p : items_) v.push_back(p.get());
        return v;
    }
};

// Analysis helpers (templates and specialized logic)

// Generic averageOf over a repository given a value extractor
template <typename T, typename ValueFn>
std::optional<double> averageOf(const Repository<T>& repo, ValueFn valueFn) {
    double sum = 0.0;
    std::size_t n = 0;
    for (const auto& p : repo.items()) {
        sum += static_cast<double>(valueFn(*p));
        ++n;
    }
    if (n == 0) return std::nullopt;
    return sum / static_cast<double>(n);
}

// Generic countIf over a repository
template <typename T, typename Pred>
std::size_t countIf(const Repository<T>& repo, Pred pred) {
    std::size_t cnt = 0;
    for (const auto& p : repo.items()) if (pred(*p)) ++cnt;
    return cnt;
}

struct ExhibitAnalytics {
    static std::unordered_map<std::string, std::size_t> typeCounts(const Repository<Exhibit>& repo) {
        std::unordered_map<std::string, std::size_t> counts;
        for (const auto& p : repo.items()) ++counts[p->type()];
        return counts;
    }

    static std::map<int, int> ratingHistogram(const Repository<Exhibit>& repo) {
        std::map<int, int> hist;
        for (int r = 1; r <= 5; ++r) hist[r] = 0;
        for (const auto& p : repo.items()) {
            for (int r : p->ratings()) ++hist[r];
        }
        return hist;
    }

    static std::optional<double> averageRating(const Repository<Exhibit>& repo) {
        double sum = 0.0; std::size_t n = 0;
        for (const auto& p : repo.items()) {
            if (auto ar = p->averageRating()) { sum += *ar; ++n; }
        }
        if (n == 0) return std::nullopt;
        return sum / static_cast<double>(n);
    }

    static std::unordered_map<std::string, double> averageRatingByType(const Repository<Exhibit>& repo) {
        struct Agg { double sum{0}; std::size_t n{0}; };
        std::unordered_map<std::string, Agg> acc;
        for (const auto& p : repo.items()) {
            if (auto ar = p->averageRating()) {
                auto& a = acc[p->type()];
                a.sum += *ar; a.n += 1;
            }
        }
        std::unordered_map<std::string, double> result;
        for (auto& kv : acc) {
            result[kv.first] = kv.second.n ? kv.second.sum / static_cast<double>(kv.second.n) : 0.0;
        }
        return result;
    }

    static std::vector<const Exhibit*> topNByAverageRating(const Repository<Exhibit>& repo, std::size_t n) {
        std::vector<const Exhibit*> v = repo.view();
        std::stable_sort(v.begin(), v.end(), [](const Exhibit* a, const Exhibit* b){
            double arA = a->averageRating().value_or(0.0);
            double arB = b->averageRating().value_or(0.0);
            if (arA != arB) return arA > arB; // descending
            return *a < *b; // tie-breaker
        });
        if (v.size() > n) v.resize(n);
        return v;
    }
};

// Museum aggregates exhibits and provides operations
class Museum {
private:
    std::string name_;
    Repository<Exhibit> exhibits_;
public:
    explicit Museum(std::string name) : name_(std::move(name)) {}

    const std::string& name() const { return name_; }
    void rename(const std::string& n) { name_ = n; }

    // Overloaded add: by unique_ptr (ownership)
    Exhibit& add(std::unique_ptr<Exhibit> e) {
        Exhibit& ref = *e;
        exhibits_.add(std::move(e));
        return ref;
    }
    // Overloaded add: by reference (clone)
    void add(const Exhibit& e) { exhibits_.add(e.clone()); }

    const Repository<Exhibit>& exhibits() const { return exhibits_; }
    Repository<Exhibit>& exhibits() { return exhibits_; }

    void displayAll() const {
        for (const auto& p : exhibits_.items()) p->display();
    }

    std::vector<const Exhibit*> sortedByNameYear() const {
        auto view = exhibits_.view();
        std::sort(view.begin(), view.end(), [](const Exhibit* a, const Exhibit* b){ return *a < *b; });
        return view;
    }

    Museum operator+(const Museum& other) const {
        Museum combined(name_ + " + " + other.name_);
        for (const auto& p : exhibits_.items()) combined.add(p->clone());
        for (const auto& p : other.exhibits_.items()) combined.add(p->clone());
        return combined;
    }

    friend std::ostream& operator<<(std::ostream& os, const Museum& m) {
        os << "Museum: " << m.name_ << " (" << m.exhibits_.size() << " exhibits)";
        return os;
    }
};

