// ---------- Text processing utilities (data analysis helpers) ----------
static std::string toLower(const std::string& s) {
    std::string t; t.reserve(s.size());
    for (unsigned char c : s) t.push_back(static_cast<char>(std::tolower(c)));
    return t;
}

static std::vector<std::string> tokenize(const std::string& text) {
    std::string t = toLower(text);
    std::vector<std::string> tokens;
    std::string cur;
    for (unsigned char c : t) {
        if (std::isalpha(c)) cur.push_back(static_cast<char>(c));
        else if (!cur.empty()) { tokens.push_back(cur); cur.clear(); }
    }
    if (!cur.empty()) tokens.push_back(cur);
    return tokens;
}

