// ---------- Templates: Generic repository and analyzer ----------

template <typename T>
class Repository {
private:
    std::vector<T> items_;
public:
    void add(const T& item) { items_.push_back(item); }
    void add(T&& item) { items_.push_back(std::move(item)); } // method overloading

    template <typename It>
    void extend(It first, It last) { items_.insert(items_.end(), first, last); }

    template <typename Pred>
    std::vector<T> where(Pred p) const {
        std::vector<T> out;
        for (const auto& x : items_) if (p(x)) out.push_back(x);
        return out;
    }

    template <typename Key>
    std::vector<Key> map(std::function<Key(const T&)> f) const {
        std::vector<Key> out; out.reserve(items_.size());
        for (const auto& x : items_) out.push_back(f(x));
        return out;
    }

    template <typename Key>
    void sort_by(std::function<Key(const T&)> key, bool reverse=false) {
        std::sort(items_.begin(), items_.end(), [&](const T& a, const T& b){
            return reverse ? key(a) > key(b) : key(a) < key(b);
        });
    }

    const std::vector<T>& items() const { return items_; }
          std::vector<T>& items()       { return items_; }
};

// Summarize numeric values extracted from a range of T

template <typename Range, typename ValueFn>
std::optional<std::map<std::string, double>> summarize_numeric(const Range& rng, ValueFn value) {
    std::vector<double> vals; vals.reserve(rng.size());
    for (const auto& it : rng) vals.push_back(static_cast<double>(value(it)));
    if (vals.empty()) return std::nullopt;
    const double n = static_cast<double>(vals.size());
    const double s = std::accumulate(vals.begin(), vals.end(), 0.0);
    const double mn = *std::min_element(vals.begin(), vals.end());
    const double mx = *std::max_element(vals.begin(), vals.end());
    const double mean = s / n;
    double var = 0.0; for (double x : vals) var += (x - mean) * (x - mean);
    var /= n; const double stddev = std::sqrt(var);
    return std::map<std::string, double>{{"count", n},{"min", mn},{"max", mx},{"mean", mean},{"std", stddev}};
}

// Generic histogram over a range using a key function

template <typename Range, typename KeyFn>
auto histogram(const Range& rng, KeyFn key) {
    using Item = typename Range::value_type;
    using K = decltype(key(std::declval<Item>()));
    std::unordered_map<K, std::size_t> h;
    for (const auto& it : rng) ++h[key(it)];
    return h;
}

template <typename T>
class Analyzer {
private:
    std::vector<T> items_;
public:
    explicit Analyzer(std::vector<T> items) : items_(std::move(items)) {}

    template <typename ScoreFn>
    std::vector<T> top_n(ScoreFn score, std::size_t n) const {
        std::vector<T> copy = items_;
        std::sort(copy.begin(), copy.end(), [&](const T& a, const T& b){ return score(a) > score(b); });
        if (copy.size() > n) copy.resize(n);
        return copy;
    }

    template <typename TextFn>
    std::unordered_map<std::string, std::size_t> token_frequencies(TextFn text) const {
        std::unordered_map<std::string, std::size_t> freq;
        for (const auto& it : items_) {
            for (const auto& tok : tokenize(text(it))) ++freq[tok];
        }
        return freq;
    }

    template <typename ValueFn>
    auto summary(ValueFn value) const {
        return summarize_numeric(items_, value);
    }
};

