Below is a detailed, end-to-end C# example that post-processes an Advance Steel single-part view on a drawing and places Cartesian (ordinate) dimensions for each hole center relative to the plate’s lower-left corner (0,0) in that view. The code uses the AutoCAD .NET API to create OrdinateDimension entities on the drawing, and it is structured so you can run it inside an Advance Steel DWG after detailing. Inline comments also reference relevant Autodesk Advance Steel .NET API classes/methods you can use if you prefer to locate views and/or compute model-to-view transforms with the Advance Steel API rather than picking the view manually.

Key notes
- Approach: Post-detailing. We work directly in the drawing by traversing the selected Advance Steel view block, finding the plate outline and hole centers, and then creating X and Y ordinate dimensions in paper space, all measured from the plate’s lower-left corner in that view.
- Dimensions: These are vanilla AutoCAD OrdinateDimension entities. They are not DSM-driven dimensions. Common best practice is to delete and recreate them on drawing updates.
- Advance Steel API: While the code below selects the view block interactively for simplicity, inline comments point to Advance Steel API classes you can use to programmatically find the drawing, view, and projection if you want a fully automated pipeline.

// Build requirements
// - Target: .NET Framework matching your AutoCAD/Advance Steel host (e.g., 4.8)
// - References (copy from your AutoCAD/Advance Steel installation):
//   AcCoreMgd.dll, AcDbMgd.dll, AcMgd.dll
// - Compile as a class library and NETLOAD into Advance Steel (or load via a plugin framework)

using System;
using System.Collections.Generic;
using System.Linq;
using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.EditorInput;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.Runtime;

// Optional: If you plan to also use Advance Steel API in code (see comments below),
// add references to the Advance Steel managed assemblies and uncomment these:
// using Autodesk.AdvanceSteel.DocumentManagement;   // e.g., DocumentManager.GetCurrentDocument()
// using Autodesk.AdvanceSteel.Drawing;              // e.g., drawing docs, views
// using Autodesk.AdvanceSteel.CADAccess;            // e.g., AS transactions, DB access

public class PlateHoleCartesianDims
{
  // RegApp used to tag dimensions created by this command (for cleanup on rerun)
  private const string RegAppName = "AS_CARTESIAN_HOLE_DIMS";

  [CommandMethod("AS_DIM_PLATE_HOLES_CARTESIAN")]
  public static void AddCartesianHoleDims()
  {
    var doc = Application.DocumentManager.MdiActiveDocument;
    var db = doc.Database;
    var ed = doc.Editor;

    // 1) Let the user pick the Advance Steel single-part view block in paper space
    //    You can replace this with Advance Steel API code to auto-find the view (see notes below).
    var peo = new PromptEntityOptions("\nSelect Advance Steel single-part view block (paper space):");
    peo.SetRejectMessage("\nMust be a BlockReference.");
    peo.AddAllowedClass(typeof(BlockReference), false);
    var per = ed.GetEntity(peo);
    if (per.Status != PromptStatus.OK)
      return;

    using (var tr = db.TransactionManager.StartTransaction())
    {
      var br = (BlockReference)tr.GetObject(per.ObjectId, OpenMode.ForRead);

      // Ensure RegApp exists (for tagging/cleanup)
      EnsureRegApp(tr, db, RegAppName);

      // Current paper space BTR (dims will be created here)
      var spaceBtr = (BlockTableRecord)tr.GetObject(db.CurrentSpaceId, OpenMode.ForWrite);

      // 2) Recursively gather geometry inside the selected view block
      var viewBtr = (BlockTableRecord)tr.GetObject(br.BlockTableRecord, OpenMode.ForRead);
      var rootXf = br.BlockTransform; // view space -> paper space

      var polys = new List<Tuple<Polyline, Matrix3d>>();
      var circles = new List<Tuple<Circle, Matrix3d>>();
      CollectGeometryRecursive(tr, viewBtr, rootXf, polys, circles);

      if (polys.Count == 0)
      {
        ed.WriteMessage("\nNo polylines found in the selected view block.");
        tr.Commit();
        return;
      }

      // 3) Identify the plate outline as the largest closed polyline by area
      var plate = polys
        .Where(t => t.Item1.Closed && SafeHasArea(t.Item1))
        .OrderByDescending(t => Math.Abs(t.Item1.Area))
        .FirstOrDefault();

      if (plate == null)
      {
        ed.WriteMessage("\nCould not find a closed polyline with area to use as plate outline.");
        tr.Commit();
        return;
      }

      // Transform outline into paper space for robust computations
      var outlinePs = (Polyline)plate.Item1.Clone();
      outlinePs.TransformBy(plate.Item2);

      // 4) Compute origin at plate's lower-left corner (paper space)
      var ext = outlinePs.GeometricExtents;
      var origin = new Point3d(ext.MinPoint.X, ext.MinPoint.Y, 0.0);

      // 5) Collect hole centers from circles that lie inside the outline
      var outlineVerts = GetPolylineVertices2d(outlinePs);
      var holeCenters = new List<Point3d>();

      foreach (var tup in circles)
      {
        var c = (Circle)tup.Item1.Clone();
        c.TransformBy(tup.Item2); // to paper space
        var ctr = new Point2d(c.Center.X, c.Center.Y);
        if (PointInPolygon(ctr, outlineVerts))
          holeCenters.Add(new Point3d(ctr.X, ctr.Y, 0.0));
      }

      if (holeCenters.Count == 0)
      {
        ed.WriteMessage("\nNo hole circles found inside the plate outline.");
        tr.Commit();
        return;
      }

      // 6) Optional: remove previously created dimensions (tagged by our RegApp)
      RemoveTaggedDims(tr, spaceBtr, RegAppName);

      // 7) Create ordinate dimensions (X and Y) for each hole center
      // Determine a reasonable offset for leaders based on plate size
      double width = ext.MaxPoint.X - ext.MinPoint.X;
      double height = ext.MaxPoint.Y - ext.MinPoint.Y;
      double size = Math.Max(width, height);
      double xBase = Math.Max(10.0, 0.06 * size);
      double yBase = Math.Max(10.0, 0.06 * size);
      double xStep = Math.Max(6.0, 0.04 * size);
      double yStep = Math.Max(6.0, 0.04 * size);

      // Use current dimstyle
      ObjectId dimStyleId = db.Dimstyle;

      int xi = 0, yi = 0;
      foreach (var p in holeCenters.OrderBy(h => h.X).ThenBy(h => h.Y))
      {
        // X-ordinate (horizontal) dimension: UsingXAxis = true
        var xLeader = new Point3d(p.X, origin.Y - (xBase + xi * xStep), 0.0);
        var xDim = new OrdinateDimension(
          true,            // use X axis
          p,               // defining point (hole center)
          origin,          // common origin
          xLeader,         // leader end point
          "<>",           // dimension text; "<>" lets AutoCAD format the value
          dimStyleId
        );
        TagWithRegApp(xDim, RegAppName);
        spaceBtr.AppendEntity(xDim);
        tr.AddNewlyCreatedDBObject(xDim, true);
        xi++;

        // Y-ordinate (vertical) dimension: UsingXAxis = false
        var yLeader = new Point3d(origin.X - (yBase + yi * yStep), p.Y, 0.0);
        var yDim = new OrdinateDimension(
          false,           // use Y axis
          p,
          origin,
          yLeader,
          "<>",
          dimStyleId
        );
        TagWithRegApp(yDim, RegAppName);
        spaceBtr.AppendEntity(yDim);
        tr.AddNewlyCreatedDBObject(yDim, true);
        yi++;
      }

      ed.WriteMessage($"\nCreated {holeCenters.Count * 2} ordinate dimensions from origin {origin}.");
      tr.Commit();
    }
  }

  // Recursively traverses block content to gather closed polylines and circles, carrying world transform
  private static void CollectGeometryRecursive(
    Transaction tr,
    BlockTableRecord btr,
    Matrix3d parentXf,
    List<Tuple<Polyline, Matrix3d>> polys,
    List<Tuple<Circle, Matrix3d>> circles)
  {
    foreach (ObjectId id in btr)
    {
      var dbObj = tr.GetObject(id, OpenMode.ForRead);
      if (dbObj is BlockReference childBr)
      {
        var childBtr = (BlockTableRecord)tr.GetObject(childBr.BlockTableRecord, OpenMode.ForRead);
        var xf = parentXf * childBr.BlockTransform;
        CollectGeometryRecursive(tr, childBtr, xf, polys, circles);
      }
      else if (dbObj is Polyline pl)
      {
        polys.Add(Tuple.Create(pl, parentXf));
      }
      else if (dbObj is Circle c)
      {
        circles.Add(Tuple.Create(c, parentXf));
      }
    }
  }

  // True if Polyline.Area can be read safely (some degenerate polylines may throw)
  private static bool SafeHasArea(Polyline pl)
  {
    try { var _ = pl.Area; return true; } catch { return false; }
  }

  private static List<Point2d> GetPolylineVertices2d(Polyline pl)
  {
    var pts = new List<Point2d>(pl.NumberOfVertices);
    for (int i = 0; i < pl.NumberOfVertices; i++)
      pts.Add(pl.GetPoint2dAt(i));
    return pts;
  }

  // Ray-casting point-in-polygon
  private static bool PointInPolygon(Point2d p, List<Point2d> poly)
  {
    bool inside = false;
    int n = poly.Count;
    for (int i = 0, j = n - 1; i < n; j = i++)
    {
      var pi = poly[i];
      var pj = poly[j];
      bool intersect = ((pi.Y > p.Y) != (pj.Y > p.Y)) &&
                       (p.X < (pj.X - pi.X) * (p.Y - pi.Y) / (pj.Y - pi.Y + 1e-12) + pi.X);
      if (intersect) inside = !inside;
    }
    return inside;
  }

  private static void EnsureRegApp(Transaction tr, Database db, string name)
  {
    var rat = (RegAppTable)tr.GetObject(db.RegAppTableId, OpenMode.ForRead);
    if (!rat.Has(name))
    {
      rat.UpgradeOpen();
      var rec = new RegAppTableRecord { Name = name };
      rat.Add(rec);
      tr.AddNewlyCreatedDBObject(rec, true);
    }
  }

  private static void TagWithRegApp(Entity ent, string regAppName)
  {
    var rb = new ResultBuffer(
      new TypedValue((int)DxfCode.ExtendedDataRegAppName, regAppName),
      new TypedValue((int)DxfCode.ExtendedDataAsciiString, "ORDINATE")
    );
    ent.XData = rb;
    rb.Dispose();
  }

  // Remove previously created dimensions tagged with our RegApp
  private static void RemoveTaggedDims(Transaction tr, BlockTableRecord spaceBtr, string regAppName)
  {
    var toErase = new List<Entity>();
    foreach (ObjectId id in spaceBtr)
    {
      if (!id.ObjectClass.DxfName.Equals("DIMENSION", StringComparison.OrdinalIgnoreCase))
        continue;
      var dim = tr.GetObject(id, OpenMode.ForRead) as Dimension;
      if (dim == null) continue;
      var xdata = dim.XData;
      if (xdata == null) continue;
      foreach (TypedValue tv in xdata)
      {
        if (tv.TypeCode == (int)DxfCode.ExtendedDataRegAppName && string.Equals((string)tv.Value, regAppName, StringComparison.Ordinal))
        {
          dim.UpgradeOpen();
          toErase.Add(dim);
          break;
        }
      }
    }
    foreach (var e in toErase)
      e.Erase();
  }
}

How this maps to your request (step-by-step)
1) Work in the drawing after detailing a single-part view for the plate.
2) Select the Advance Steel view block (paper space). In a fully automated workflow, you can locate it via the Advance Steel API.
3) Traverse the view block’s nested content, collecting closed polylines and circles in the view. The largest closed polyline is assumed to be the plate outline; circles inside it are treated as holes.
4) Compute the lower-left corner of the outline’s extents (paper space) and take it as the (0,0) Cartesian origin.
5) For each hole center, create two OrdinateDimension entities: X-ordinate (UsingXAxis = true) and Y-ordinate (UsingXAxis = false), both referenced to the same origin.
6) Optionally tag dimensions with a RegApp so you can safely delete/rebuild them on updates.

Relevant Autodesk APIs used
- AutoCAD .NET (for drawing manipulation):
  - Autodesk.AutoCAD.DatabaseServices.BlockReference.BlockTransform
  - Autodesk.AutoCAD.DatabaseServices.BlockTableRecord (enumeration of nested content)
  - Autodesk.AutoCAD.DatabaseServices.Polyline (Closed, Area, GeometricExtents)
  - Autodesk.AutoCAD.DatabaseServices.Circle (Center)
  - Autodesk.AutoCAD.DatabaseServices.OrdinateDimension (constructors, UsingXAxis)
  - Autodesk.AutoCAD.DatabaseServices.RegAppTable / RegAppTableRecord (for XData tagging)
  - Autodesk.AutoCAD.EditorInput.Editor.GetEntity (user selection of view block)

- Autodesk Advance Steel .NET (where you may integrate, depending on your workflow):
  - Autodesk.AdvanceSteel.DocumentManagement.DocumentManager.GetCurrentDocument() to access the current Advance Steel document/drawing.
  - Autodesk.AdvanceSteel.Drawing namespaces to enumerate drawing sheets and views programmatically instead of asking the user to pick a view block.
  - Autodesk.AdvanceSteel.CADAccess transaction helpers if you want to wrap DB edits in an Advance Steel transaction context.
  - When working model-driven, you can retrieve the model plate and its hole features via Autodesk.AdvanceSteel.Modelling classes, project their centers to the view plane using the view’s transform (in Autodesk.AdvanceSteel.Drawing), then place the same OrdinateDimension entities at the projected locations.

Tip: Bottom-left as 0,0 of the plate
- This sample uses the plate outline’s paper-space extents to compute the origin. If you prefer the true lower-left contour vertex, you can walk the outline polyline vertices and use the one with minimal X/Y.

Additional resources
- AutoCAD .NET API: OrdinateDimension class reference (ObjectARX/Managed .NET docs)
  https://help.autodesk.com/view/OARX/2024/ENU/?guid=GUID-BA68C140-8B22-4E01-8E7B-2B0E9B7E76F8
- Advance Steel API overview and samples (version-specific; pick your installed version):
  https://help.autodesk.com/view/ASTPRO/2024/ENU/
- Advance Steel Developer Forum (discussion/examples of drawing post-processing):
  https://forums.autodesk.com/t5/advance-steel-forum/bd-p/204

import sys
sys.setrecursionlimit(1_100_000)

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    t = next(it)
    out = []
    for _ in range(t):
        n = next(it)
        adj = [[] for _ in range(n + 1)]
        for i in range(1, n):
            u = next(it)
            v = next(it)
            adj[u].append((v, i))
            adj[v].append((u, i))
        if n % 3 != 0:
            out.append("-1")
            continue
        cuts = []
        def dfs(u, p):
            rem = 1
            for v, eid in adj[u]:
                if v == p:
                    continue
                child = dfs(v, u)
                if child == 0:
                    cuts.append(eid)
                else:
                    rem += child
            return rem % 3
        root_rem = dfs(1, 0)
        if root_rem != 0:
            out.append("-1")
        else:
            k = len(cuts)
            out.append(str(k))
            out.append(" ".join(map(str, cuts)) if k > 0 else "")
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

