<script>
(function () {
  const $ = (sel, root = document) => root.querySelector(sel);
  const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

  function showPanel(name) {
    const isLogin = name === 'login';
    $('#fp-tab-login').classList.toggle('active', isLogin);
    $('#fp-tab-login').setAttribute('aria-selected', String(isLogin));
    $('#fp-tab-register').classList.toggle('active', !isLogin);
    $('#fp-tab-register').setAttribute('aria-selected', String(!isLogin));

    $('#fp-panel-login').hidden = !isLogin;
    $('#fp-panel-register').hidden = isLogin;
  }

  function readUsers() {
    try { return JSON.parse(localStorage.getItem('tg_users') || '{}'); }
    catch { return {}; }
  }
  function writeUsers(users) {
    localStorage.setItem('tg_users', JSON.stringify(users));
  }

  function setAuthenticated(user) {
    sessionStorage.setItem('tg_current_user', JSON.stringify(user));
    document.body.classList.add('fp-authenticated');
    const overlay = $('#fp-overlay');
    if (overlay) overlay.setAttribute('aria-hidden', 'true');

    // Fire an app event your game can listen to
    document.dispatchEvent(new CustomEvent('frontpage:authenticated', { detail: { user } }));

    // Try to start the game if functions exist
    try {
      if (typeof window.startGame === 'function') window.startGame(user);
      else if (typeof window.initGame === 'function') window.initGame(user);
    } catch (e) { /* ignore */ }
  }

  function alreadyAuthenticated() {
    const raw = sessionStorage.getItem('tg_current_user');
    if (!raw) return false;
    try {
      const user = JSON.parse(raw);
      if (user && user.username) {
        document.body.classList.add('fp-authenticated');
        $('#fp-overlay')?.setAttribute('aria-hidden', 'true');
        return true;
      }
    } catch {}
    return false;
  }

  function attachEvents() {
    // Tabs
    $('#fp-tab-login')?.addEventListener('click', () => showPanel('login'));
    $('#fp-tab-register')?.addEventListener('click', () => showPanel('register'));
    $('#fp-to-register')?.addEventListener('click', () => showPanel('register'));
    $('#fp-to-login')?.addEventListener('click', () => showPanel('login'));

    // Register
    $('#fp-register-form')?.addEventListener('submit', (e) => {
      e.preventDefault();
      const username = $('#fp-reg-username').value.trim();
      const email = $('#fp-reg-email').value.trim();
      const password = $('#fp-reg-password').value;
      const confirm = $('#fp-reg-confirm').value;
      const err = $('#fp-register-error');
      err.textContent = '';

      if (!username || !password || !confirm) {
        err.textContent = 'Please fill in all required fields.';
        return;
      }
      if (password !== confirm) {
        err.textContent = 'Passwords do not match.';
        return;
      }

      const users = readUsers();
      if (users[username]) {
        err.textContent = 'Username already exists. Please choose another.';
        return;
      }

      users[username] = { username, email, password };
      writeUsers(users);
      showPanel('login');
      $('#fp-login-username').value = username;
      $('#fp-login-password').focus();
    });

    // Login
    $('#fp-login-form')?.addEventListener('submit', (e) => {
      e.preventDefault();
      const username = $('#fp-login-username').value.trim();
      const password = $('#fp-login-password').value;
      const err = $('#fp-login-error');
      err.textContent = '';

      if (!username || !password) {
        err.textContent = 'Please enter username and password.';
        return;
      }

      const users = readUsers();
      const u = users[username];
      if (!u || u.password !== password) {
        err.textContent = 'Invalid username or password.';
        return;
      }

      setAuthenticated({ username: u.username, email: u.email || '' });
    });
  }

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      if (!alreadyAuthenticated()) attachEvents();
    });
  } else {
    if (!alreadyAuthenticated()) attachEvents();
  }
})();
</script>

