  if(!clientId){ clientId = Date.now()+"-"+Math.random().toString(36).slice(2,8); sessionStorage.setItem('clientId', clientId); }

  // Pairing state
  let pairing = { roomId: null, isHost: false, peerName: null, roomCh: null, lobbyCh: null, matched: false };

  // Elements
  const pairingUI = $('#fp-pairing');
  const meSpan = $('#pair-me');
  const peerSpan = $('#pair-peer');
  const statusEl = $('#pair-status');
