  window.addEventListener('frontpage:authenticated', showPairingUI);
  // If already authenticated from earlier step reload, show directly
  if (sessionStorage.getItem('authName') || localStorage.getItem('authName')) {
    showPairingUI();
  }

  function setStatus(msg, isError=false){
    if(!statusEl) return;
    statusEl.textContent = msg || '';
    statusEl.classList.toggle('error', !!isError);
  }

  // Private Room: Host
  function createPrivateRoom(){
    if(pairing.matched) return;
    pairing.roomId = randID();
    pairing.isHost = true;
    pairing.peerName = null;
    roomInput && (roomInput.value = pairing.roomId);
    btnCopy && (btnCopy.disabled = false);
    setStatus('Room created. Share the Room ID with your friend. Waiting for opponent to join…');

    pairing.roomCh && pairing.roomCh.close();
    pairing.roomCh = new BroadcastChannel('tennis-room-'+pairing.roomId);
    pairing.roomCh.onmessage = (ev) => {
      const msg = ev.data || {};
      if(msg.type === 'join-request' && !pairing.matched){
        pairing.peerName = msg.name || 'Opponent';
        peerSpan && (peerSpan.textContent = pairing.peerName);
        // Accept join and finalize pairing
        pairing.roomCh.postMessage({ type: 'accept', hostName: userName(), roomId: pairing.roomId });
        finalizePairing();
      }
    };
  }

  // Private Room: Guest
  function joinPrivateRoom(){
    if(pairing.matched) return;
    const rid = (roomInput && roomInput.value || '').trim().toUpperCase();
    if(!rid || rid.length < 4){ setStatus('Please enter a valid Room ID.', true); return; }
    pairing.roomId = rid;
    pairing.isHost = false;

    pairing.roomCh && pairing.roomCh.close();
    pairing.roomCh = new BroadcastChannel('tennis-room-'+pairing.roomId);

    let accepted = false;
    const timeout = setTimeout(()=>{ if(!accepted) setStatus('No host responded. Check the Room ID or try again.', true); }, 6000);

    pairing.roomCh.onmessage = (ev) => {
      const msg = ev.data || {};
      if(msg.type === 'accept' && msg.roomId === pairing.roomId){
        accepted = true; clearTimeout(timeout);
        pairing.peerName = msg.hostName || 'Host';
        peerSpan && (peerSpan.textContent = pairing.peerName);
