        }
      }
      if(msg.type === 'rand-match' && (msg.host === clientId || msg.guest === clientId) && !done){
        pairing.roomId = msg.roomId;
        pairing.isHost = (msg.host === clientId);
        pairing.peerName = (pairing.isHost ? msg.guestName : msg.hostName) || 'Opponent';
        if(pairing.isHost){ openRoomAsHost(true); }
        else { openRoomAsGuest(true); }
        done = true;
      }
    };

    // Announce presence
    pairing.lobbyCh.postMessage(lookingMsg);

    function openRoomAsHost(autoFinalize){
      pairing.roomCh && pairing.roomCh.close();
      pairing.roomCh = new BroadcastChannel('tennis-room-'+pairing.roomId);
      pairing.roomCh.onmessage = (e)=>{
        const m=e.data||{};
        if(m.type==='join-request' && !pairing.matched){
          pairing.roomCh.postMessage({ type:'accept', hostName:userName(), roomId: pairing.roomId });
          if(autoFinalize) finalizePairing();
        }
      };
      peerSpan && (peerSpan.textContent = pairing.peerName);
      setStatus('Found opponent! Finalizing…');
    }
    function openRoomAsGuest(autoFinalize){
      pairing.roomCh && pairing.roomCh.close();
      pairing.roomCh = new BroadcastChannel('tennis-room-'+pairing.roomId);
      pairing.roomCh.onmessage = (e)=>{
        const m=e.data||{};
        if(m.type==='accept' && m.roomId===pairing.roomId && !pairing.matched){ if(autoFinalize) finalizePairing(); }
      };
      // Ask host
      pairing.roomCh.postMessage({ type:'join-request', name: userName() });
      peerSpan && (peerSpan.textContent = pairing.peerName);
      setStatus('Found opponent! Finalizing…');
    }
  }

  function finalizePairing(){
    pairing.matched = true;
    try { pairing.lobbyCh && pairing.lobbyCh.close(); } catch {}
    setStatus('Paired! Room '+pairing.roomId+' • Opponent: '+(pairing.peerName||'Opponent'));
    // Persist pairing data for the game
    sessionStorage.setItem('roomId', pairing.roomId);
    sessionStorage.setItem('playerIndex', pairing.isHost ? '1' : '2');
    sessionStorage.setItem('opponentName', pairing.peerName || 'Opponent');
    sessionStorage.setItem('gameStartAt', String(Date.now()));

    // Dispatch event and start the game
    window.dispatchEvent(new CustomEvent('frontpage:paired', { detail: {
      roomId: pairing.roomId,
      playerIndex: pairing.isHost ? 1 : 2,
      me: userName(),
      opponent: pairing.peerName || 'Opponent'
    }}));

    // Hide front overlay (if CSS uses body.fp-authenticated) and start game
    document.body.classList.add('fp-authenticated');
    const start = window.startGame || window.initGame || window.start || window.beginGame;
    if(typeof start === 'function') start();
  }

  // Copy Room ID button
  on(btnCopy, 'click', async ()=>{
    if(!pairing.roomId){ setStatus('Create a room first.', true); return; }
    try { await navigator.clipboard.writeText(pairing.roomId); setStatus('Room ID copied to clipboard.'); }
    catch { setStatus('Unable to copy. Copy manually: '+pairing.roomId, true); }
  });

  on(btnCreate, 'click', createPrivateRoom);
  on(btnJoin, 'click', joinPrivateRoom);
  on(btnRandom, 'click', randomMatch);

  // Game Over API – call window.showGameOver(stats) from your losing condition
  window.showGameOver = function(stats){
    try {
      // stats = { timeMs?, players:[{name, score, hp, returns, opponentHits|hitsOnOpponent, items}], ranking?: [names] }
      const startAt = Number(sessionStorage.getItem('gameStartAt')||0);
      const used = (stats && typeof stats.timeMs==='number') ? stats.timeMs : (startAt ? (Date.now()-startAt) : 0);
      goTime && (goTime.textContent = fmtTime(used));

      // Build rows sorted by ranking if provided or by score desc then hp desc
      const players = Array.isArray(stats?.players) ? stats.players.slice() : [];
      let order = players;
      if(Array.isArray(stats?.ranking) && stats.ranking.length){
        const idx = Object.fromEntries(stats.ranking.map((n,i)=>[n,i]));
        order.sort((a,b)=> (idx[a.name]??99) - (idx[b.name]??99));
      } else {
        order.sort((a,b)=> (b.score||0)-(a.score||0) || (b.hp||0)-(a.hp||0));
      }

      if(goTbody){
        goTbody.innerHTML = '';
        order.forEach((p, i)=>{
          const tr = document.createElement('tr');
          const rank = (i===0?1:i+1);
          tr.innerHTML = `
            <td class="${rank===1?'go-rank-1':''}">${rank}</td>
            <td>${esc(p.name||('Player '+(i+1)))}</td>
            <td>${num(p.score)}</td>
            <td>${num(p.hp)}</td>
            <td>${num(p.returns)}</td>
            <td>${num(p.opponentHits ?? p.hitsOnOpponent)}</td>
            <td>${num(p.items)}</td>
          `;
          goTbody.appendChild(tr);
        });
      }

      goOverlay && (goOverlay.hidden = false);
      goOverlay && goOverlay.setAttribute('aria-hidden', 'false');
    } catch(e) { console.error('showGameOver error', e); }
  };

  function fmtTime(ms){ if(!ms||ms<0) return '00:00'; const s=Math.floor(ms/1000); const m=Math.floor(s/60); const r=s%60; return String(m).padStart(2,'0')+':'+String(r).padStart(2,'0'); }
  function num(v){ return (v==null||isNaN(v))?0: +v; }
  function esc(s){ return String(s).replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c])); }

  on(goPlayAgain, 'click', ()=>{
    // Hide Game Over and restart
    if(goOverlay){ goOverlay.hidden = true; goOverlay.setAttribute('aria-hidden', 'true'); }
    sessionStorage.setItem('gameStartAt', String(Date.now()));
    const start = window.startGame || window.initGame || window.start || window.beginGame;
    if(typeof start === 'function') start();
    else location.reload();
  });

  on(goLogout, 'click', ()=>{
    // Clear session and return to front page overlay
    try { sessionStorage.clear(); } catch {}
    try { localStorage.removeItem('authName'); } catch {}
    document.body.classList.remove('fp-authenticated');
    // Reset pairing UI
    if(pairingUI){ pairingUI.hidden = false; }
    if(statusEl){ statusEl.textContent=''; statusEl.classList.remove('error'); }
    if(roomInput){ roomInput.value=''; }
    if(btnCopy){ btnCopy.disabled = true; }
    if(meSpan){ meSpan.textContent = userName(); }
    if(peerSpan){ peerSpan.textContent = '—'; }
    // Optionally reload to reset game state fully
    location.reload();
  });
})();
</script>
