<script>
(function(){
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => Array.from(root.querySelectorAll(sel));

  // Tabs toggle
  const tabLogin = $('#fp-tab-login');
  const tabRegister = $('#fp-tab-register');
  const formLogin = $('#fp-form-login');
  const formRegister = $('#fp-form-register');

  if (tabLogin && tabRegister) {
    tabLogin.addEventListener('click', () => {
      tabLogin.classList.add('active'); tabRegister.classList.remove('active');
      formLogin.style.display = ''; formRegister.style.display = 'none';
    });
    tabRegister.addEventListener('click', () => {
      tabRegister.classList.add('active'); tabLogin.classList.remove('active');
      formRegister.style.display = ''; formLogin.style.display = 'none';
    });
  }

  // Demo auth store
  const USERS_KEY = 'tg_users';
  function loadUsers(){ try { return JSON.parse(localStorage.getItem(USERS_KEY)) || {}; } catch { return {}; } }
  function saveUsers(u){ localStorage.setItem(USERS_KEY, JSON.stringify(u)); }

  function login(username){
    sessionStorage.setItem('tg_user', username);
    document.body.classList.add('fp-authenticated');
    window.tgStartTime = performance.now();
    const ev = new CustomEvent('frontpage:authenticated', { detail: { user: username } });
    window.dispatchEvent(ev);
    if (typeof window.startGame === 'function') window.startGame({ user: username });
    else if (typeof window.initGame === 'function') window.initGame({ user: username });
  }

  // Register handler
  if (formRegister) {
    formRegister.addEventListener('submit', (e) => {
      e.preventDefault();
      const u = $('#fp-reg-user').value.trim();
      const p = $('#fp-reg-pass').value;
      const users = loadUsers();
      if (!u || !p) { $('#fp-reg-error').textContent = 'Please fill all fields.'; return; }
      if (users[u]) { $('#fp-reg-error').textContent = 'Username already exists.'; return; }
      users[u] = { password: p };
      saveUsers(users);
      $('#fp-reg-error').textContent = '';
      // Auto-login after registration
      login(u);
    });
  }

  // Login handler
  if (formLogin) {
    formLogin.addEventListener('submit', (e) => {
      e.preventDefault();
      const u = $('#fp-login-user').value.trim();
      const p = $('#fp-login-pass').value;
      const users = loadUsers();
      if (!u || !p) { $('#fp-login-error').textContent = 'Please fill all fields.'; return; }
      if (!users[u] || users[u].password !== p) { $('#fp-login-error').textContent = 'Invalid username or password.'; return; }
      $('#fp-login-error').textContent = '';
      login(u);
    });
  }

  // Game Over logic
  function formatTime(ms){
    const sec = Math.max(0, Math.floor(ms/1000));
    const m = Math.floor(sec/60).toString().padStart(2,'0');
    const s = (sec%60).toString().padStart(2,'0');
    return `${m}:${s}`;
  }

