#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INFLL = (ll)4e18;

struct Edge {int to; int w;};

vector<ll> dijkstra(int n, int src, const vector<vector<Edge>>& adj){
    vector<ll> dist(n+1, INFLL);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d != dist[u]) continue;
        for(const auto &e: adj[u]){
            int v = e.to; ll nd = d + (ll)e.w;
            if(nd < dist[v]){
                dist[v] = nd;
                pq.push({nd, v});
            }
        }
    }
    return dist;
}

struct LiChaoDiscrete {
    struct Line { ll x, y; bool empty; }; // represents f(j) = A[j]*x - B[j]*y (or its negation if invert)
    int N;
    vector<Line> tr;
    const vector<ll> &A, &B; // queries sorted by ratio, but we evaluate by index directly
    bool invert; // false: val = A*x - B*y; true: val = B*y - A*x

    LiChaoDiscrete(int n, const vector<ll>& As, const vector<ll>& Bs, bool inv)
        : N(n), tr(4*n, Line{0,0,true}), A(As), B(Bs), invert(inv) {}

    inline ll eval(const Line &ln, int idx) const {
        if (ln.empty) return INFLL;
        __int128 ax = (__int128)A[idx] * ln.x;
        __int128 by = (__int128)B[idx] * ln.y;
        __int128 v = invert ? (by - ax) : (ax - by);
        if (v > (__int128)INFLL) return INFLL;
        if (v < -(__int128)INFLL) return -INFLL;
        return (ll)v;
    }

    void insert_at_node(int p, int l, int r, Line cur){
        int m = (l + r) >> 1;
        if (tr[p].empty) { tr[p] = cur; tr[p].empty = false; return; }
        bool left_better = eval(cur, l) < eval(tr[p], l);
        bool mid_better  = eval(cur, m) < eval(tr[p], m);
        if (mid_better) swap(tr[p], cur);
        if (l == r) return;
        if (left_better != mid_better) insert_at_node(p<<1, l, m, cur);
        else insert_at_node(p<<1|1, m+1, r, cur);
    }

    void add_segment(int p, int l, int r, int ql, int qr, const Line &ln){
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) { insert_at_node(p, l, r, ln); return; }
        int m = (l + r) >> 1;
        add_segment(p<<1, l, m, ql, qr, ln);
        add_segment(p<<1|1, m+1, r, ql, qr, ln);
    }

    inline void add_range(int l, int r, ll x, ll y){
        if (l > r || N == 0) return;
        Line ln{ x, y, false };
        add_segment(1, 0, N-1, l, r, ln);
    }

    ll query_point(int p, int l, int r, int idx) const {
        ll res = tr[p].empty ? INFLL : eval(tr[p], idx);
        if (l == r) return res;
        int m = (l + r) >> 1;
        if (idx <= m) return min(res, query_point(p<<1, l, m, idx));
        else return min(res, query_point(p<<1|1, m+1, r, idx));
    }

    inline ll query(int idx) const {
        if (N == 0) return INFLL;
        return query_point(1, 0, N-1, idx);
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if(!(cin >> n >> m >> k)) return 0;

    vector<vector<Edge>> adj(n+1);
    for(int i=0;i<m;++i){
        int u,v; int w; cin >> u >> v >> w;
        adj[u].push_back({v,w});
        adj[v].push_back({u,w});
    }

    vector<pair<ll,ll>> queries(k);
    for(int j=0;j<k;++j){
        ll a,b; cin >> a >> b;
        queries[j] = {a,b};
    }

    // Dijkstra from 1 and from n
    vector<ll> d1 = dijkstra(n, 1, adj);
    vector<ll> dn = dijkstra(n, n, adj);

    // Prepare queries sorted by ratio a/b without floating point
    struct Q { ll a,b; int idx; };
    vector<Q> qs(k);
    for(int i=0;i<k;++i){ qs[i] = Q{queries[i].first, queries[i].second, i}; }
    auto cmp = [](const Q& L, const Q& R){
        // L.a/L.b < R.a/R.b  <=>  L.a*R.b < R.a*L.b
        return (__int128)L.a * R.b < (__int128)R.a * L.b;
    };
    sort(qs.begin(), qs.end(), cmp);

    vector<ll> A(k), B(k);
    vector<int> pos2orig(k);
    for(int i=0;i<k;++i){ A[i]=qs[i].a; B[i]=qs[i].b; pos2orig[i]=qs[i].idx; }

    // Build two Li Chao discrete trees: one for positive values (A*x - B*y), one for negative (-A*x + B*y)
    LiChaoDiscrete posTree(k, A, B, false);
    LiChaoDiscrete negTree(k, A, B, true);

    // Insert each node's line into appropriate intervals
    for(int v=1; v<=n; ++v){
        ll x = d1[v];
        ll y = dn[v];
        if (x >= INFLL || y >= INFLL) continue; // unreachable from one side -> ignore
        if (k == 0) continue;
        if (x == 0){
            // L = -y <= 0 for all r -> goes entirely to negative tree
            negTree.add_range(0, k-1, x, y);
        } else {
            // find first index pos0 with A[pos]*x >= B[pos]*y  (i.e., r >= y/x)
            int l=0, r=k;
            while(l<r){
                int mid = (l+r)>>1;
                if((__int128)A[mid]*x < (__int128)B[mid]*y) l = mid + 1;
                else r = mid;
            }
            int pos0 = l; // negative on [0, pos0-1], positive on [pos0, k-1]
            if (pos0 > 0) negTree.add_range(0, pos0-1, x, y);
            if (pos0 < k) posTree.add_range(pos0, k-1, x, y);
        }
    }

    // Answer queries in sorted order, then map back to original order
    vector<ll> ans_sorted(k, INFLL);
    for(int i=0;i<k;++i){
        ll bestPos = posTree.query(i);
        ll bestNeg = negTree.query(i);
        ll best = min(bestPos, bestNeg);
        ans_sorted[i] = best;
    }

    vector<ll> ans(k);
    for(int i=0;i<k;++i){
        ans[pos2orig[i]] = ans_sorted[i];
    }

    for(int j=0;j<k;++j){
        cout << ans[j] << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (ll)4e18;

struct Edge { int v; ll w; };

vector<ll> dijkstra(int n, const vector<vector<Edge>>& adj, int src){
    vector<ll> dist(n+1, INF);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d != dist[u]) continue;
        for(const auto& e: adj[u]){
            int v = e.v; ll nd = d + e.w;
            if(nd < dist[v]){ dist[v] = nd; pq.push({nd, v}); }
        }
    }
    return dist;
}

struct Line {
    long double m, b; // f(x) = m*x + b
    int id;           // node id that generated this line
    Line(): m(0), b(numeric_limits<long double>::infinity()), id(-1) {}
    Line(long double _m, long double _b, int _id): m(_m), b(_b), id(_id) {}
    inline long double val(long double x) const { return m * x + b; }
};

struct LiChaoSeg {
    int N;
    vector<long double> xs; // discrete query x-coords (sorted, unique)
    vector<Line> st;

    LiChaoSeg() {}
    LiChaoSeg(const vector<long double>& _xs){ init(_xs); }

    void init(const vector<long double>& _xs){
        xs = _xs;
        N = (int)xs.size();
        st.assign(4*N, Line());
    }

    void insert_line_node(Line nw, int p, int l, int r){
        int mid = (l + r) >> 1;
        long double xl = xs[l], xm = xs[mid], xr = xs[r];
        bool leftBetter = nw.val(xl) < st[p].val(xl);
        bool midBetter  = nw.val(xm) < st[p].val(xm);
        bool rightBetter= nw.val(xr) < st[p].val(xr);

        if(st[p].id == -1){ st[p] = nw; return; }

        // Ensure st[p] is better at mid
        if(midBetter) swap(st[p], nw);

        if(l == r) return;

        // nw may still be better on one side; recurse there
        if(nw.val(xl) < st[p].val(xl)){
            insert_line_node(nw, p<<1, l, mid);
        } else if(nw.val(xr) < st[p].val(xr)){
            insert_line_node(nw, p<<1|1, mid+1, r);
        }
    }

    void insert_segment(Line nw, int p, int l, int r, int ql, int qr){
        if(qr < l || r < ql) return;
        if(ql <= l && r <= qr){
            insert_line_node(nw, p, l, r);
            return;
        }
        int mid = (l + r) >> 1;
        insert_segment(nw, p<<1, l, mid, ql, qr);
        insert_segment(nw, p<<1|1, mid+1, r, ql, qr);
    }

    // Insert line active on [ql, qr] indices
    void insert_segment(Line nw, int ql, int qr){
        if(ql > qr) return;
        insert_segment(nw, 1, 0, N-1, ql, qr);
    }

    pair<long double,int> query_idx(int idx){
        int p = 1, l = 0, r = N-1;
        long double x = xs[idx];
        long double best = numeric_limits<long double>::infinity();
        int bestId = -1;
        while(true){
            long double v = st[p].val(x);
            if(v < best){ best = v; bestId = st[p].id; }
            if(l == r) break;
            int mid = (l + r) >> 1;
            if(idx <= mid){ p = p<<1; r = mid; }
            else{ p = p<<1|1; l = mid+1; }
        }
        return {best, bestId};
    }
};

int main(){
