% Near-boundary: 3-point centered (O(h^2)) at i = 2 and i = N-1
d2y(2)     = ( y(3) - 2*y(2) + y(1) )/(h^2);
d2y(N-1)   = ( y(N) - 2*y(N-1) + y(N-2) )/(h^2);

% Interior: 5-point centered (O(h^4)) for i = 3..N-2
for i = 3:N-2
    d2y(i) = ( -y(i+2) + 16*y(i+1) - 30*y(i) + 16*y(i-1) - y(i-2) )/(12*h^2);
end

