Below is a complete, self-contained Tkinter application that implements the e-sports tournament scoring system with clear structure, robust validation, and inline comments for maintainability. Save as tournament_scoring.py and run with Python 3.8+.

import json
from dataclasses import dataclass, asdict, field
from typing import Dict, List, Optional, Tuple

import tkinter as tk
from tkinter import ttk, messagebox, filedialog


# -------------------------
# Data Model
# -------------------------

@dataclass
class Team:
    id: int
    name: str
    members: List[str] = field(default_factory=list)
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Individual:
    id: int
    name: str
    one_event_only: bool = False
    chosen_event_id: Optional[int] = None  # Applies if one_event_only is True


@dataclass
class Event:
    id: int
    name: str
    type: str  # "Team" or "Individual"
    genre: str = ""
    points_map: Optional[Dict[int, int]] = None  # Optional per-event override


class TournamentData:
    """
    Core model for the tournament. Handles validation, CRUD operations,
    results storage, points aggregation, and JSON (de)serialization.
    """

    def __init__(self):
        # Entities indexed by IDs
        self.teams: Dict[int, Team] = {}
        self.individuals: Dict[int, Individual] = {}
        self.events: Dict[int, Event] = {}
        # event_id -> ordered list of entrant IDs (team IDs for Team events, individual IDs for Individual events)
        self.results: Dict[int, List[int]] = {}
        # Global points table (default: F1 Top 10)
        self.points_map: Dict[int, int] = {1: 25, 2: 18, 3: 15, 4: 12, 5: 10, 6: 8, 7: 6, 8: 4, 9: 2, 10: 1}
        # ID counters
        self.team_counter = 1
        self.indiv_counter = 1
        self.event_counter = 1

    # ---- Constraints ----
    def max_teams(self) -> int:
        return 4

    def max_team_members(self) -> int:
        return 5

    def max_individuals(self) -> int:
        return 20

    def max_events_per_type(self) -> int:
        return 5  # 5 Team events and 5 Individual events

    # ---- Helpers ----
    @staticmethod
    def _clean_name(value: str) -> str:
        return (value or "").strip()

    def _validate_points_map(self, points: Dict[int, int]) -> None:
        if not isinstance(points, dict) or not points:
            raise ValueError("Points map must be a non-empty dictionary.")
        for k, v in points.items():
            if not isinstance(k, int) or k <= 0:
                raise ValueError("Rank keys must be positive integers.")
            if not isinstance(v, int) or v < 0:
                raise ValueError("Point values must be non-negative integers.")
        # Enforce non-increasing points as rank increases (optional but recommended)
        prev = None
        for r in sorted(points.keys()):
            if prev is not None and points[r] > points[prev]:
                raise ValueError("Points should not increase for lower ranks.")
            prev = r

    def get_points_for_event(self, event_id: int) -> Dict[int, int]:
        ev = self.events.get(event_id)
        return ev.points_map if (ev and ev.points_map) else self.points_map

    # ---- CRUD: Teams ----
    def add_team(self, name: str, members: List[str], one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(self.teams) >= self.max_teams():
            raise ValueError("Maximum number of teams reached (4).")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if any(t.name.lower() == name.lower() for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")
        tid = self.team_counter
        self.team_counter += 1
        self.teams[tid] = Team(id=tid, name=name, members=cleaned_members, one_event_only=one_event_only, chosen_event_id=chosen_event_id)
        return tid

    def edit_team(self, tid: int, name: str, members: List[str], one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Team name cannot be empty.")
        if len(members) > self.max_team_members():
            raise ValueError("A team can have at most 5 members.")
        cleaned_members = [self._clean_name(m) for m in members if self._clean_name(m)]
        if not cleaned_members:
            raise ValueError("A team must have at least one member.")
        if any(t.name.lower() == name.lower() and t.id != tid for t in self.teams.values()):
            raise ValueError("Team name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Team":
                raise ValueError("Chosen event must be a valid Team event.")
        team = self.teams[tid]
        team.name = name
        team.members = cleaned_members
        team.one_event_only = one_event_only
        team.chosen_event_id = chosen_event_id

    def remove_team(self, tid: int) -> None:
        if tid not in self.teams:
            raise ValueError("Team not found.")
        # Remove from team event results
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Team":
                self.results[ev_id] = [pid for pid in places if pid != tid]
        del self.teams[tid]

    # ---- CRUD: Individuals ----
    def add_individual(self, name: str, one_event_only: bool = False, chosen_event_id: Optional[int] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if len(self.individuals) >= self.max_individuals():
            raise ValueError("Maximum number of individuals reached (20).")
        if any(p.name.lower() == name.lower() for p in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")
        iid = self.indiv_counter
        self.indiv_counter += 1
        self.individuals[iid] = Individual(id=iid, name=name, one_event_only=one_event_only, chosen_event_id=chosen_event_id)
        return iid

    def edit_individual(self, iid: int, name: str, one_event_only: bool, chosen_event_id: Optional[int]) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Individual name cannot be empty.")
        if any(p.name.lower() == name.lower() and p.id != iid for p in self.individuals.values()):
            raise ValueError("Individual name must be unique.")
        if chosen_event_id is not None:
            ev = self.events.get(chosen_event_id)
            if ev is None or ev.type != "Individual":
                raise ValueError("Chosen event must be a valid Individual event.")
        person = self.individuals[iid]
        person.name = name
        person.one_event_only = one_event_only
        person.chosen_event_id = chosen_event_id

    def remove_individual(self, iid: int) -> None:
        if iid not in self.individuals:
            raise ValueError("Individual not found.")
        # Remove from individual event results
        for ev_id, places in list(self.results.items()):
            ev = self.events.get(ev_id)
            if ev and ev.type == "Individual":
                self.results[ev_id] = [pid for pid in places if pid != iid]
        del self.individuals[iid]

    # ---- CRUD: Events ----
    def add_event(self, name: str, etype: str, genre: str = "", points_map: Optional[Dict[int, int]] = None) -> int:
        name = self._clean_name(name)
        if not name:
            raise ValueError("Event name cannot be empty.")
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        if sum(1 for e in self.events.values() if e.type == etype) >= self.max_events_per_type():
            raise ValueError(f"Maximum number of {etype} events reached (5).")
        if any(e.name.lower() == name.lower() for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        if points_map:
            self._validate_points_map(points_map)
        eid = self.event_counter
        self.event_counter += 1
        self.events[eid] = Event(id=eid, name=name, type=etype, genre=self._clean_name(genre), points_map=points_map)
        return eid

    def edit_event(self, eid: int, name: str, etype: str, genre: str, points_map: Optional[Dict[int, int]]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        name = self._clean_name(name)
        if not name:
            raise ValueError("Event name cannot be empty.")
        if etype not in ("Team", "Individual"):
            raise ValueError("Event type must be 'Team' or 'Individual'.")
        if any(e.name.lower() == name.lower() and e.id != eid for e in self.events.values()):
            raise ValueError("Event name must be unique.")
        if points_map:
            self._validate_points_map(points_map)
        ev = self.events[eid]
        if ev.type != etype and eid in self.results:
            # Clear results if type changes to avoid cross-type mismatch
            self.results[eid] = []
        ev.name = name
        ev.type = etype
        ev.genre = self._clean_name(genre)
        ev.points_map = points_map

    def remove_event(self, eid: int) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        # Remove results
        self.results.pop(eid, None)
        # Clear chosen_event_id references
        for t in self.teams.values():
            if t.chosen_event_id == eid:
                t.chosen_event_id = None
        for i in self.individuals.values():
            if i.chosen_event_id == eid:
                i.chosen_event_id = None
        del self.events[eid]

    # ---- Results and scoring ----
    def set_results(self, eid: int, ordered_ids: List[int]) -> None:
        if eid not in self.events:
            raise ValueError("Event not found.")
        ev = self.events[eid]
        # Basic validations
        if len(ordered_ids) != len(set(ordered_ids)):
            raise ValueError("Duplicate entrants in results are not allowed.")
        # Verify entrants exist and match event type
        for pid in ordered_ids:
            if ev.type == "Team":
                if pid not in self.teams:
                    raise ValueError(f"Unknown team ID: {pid}")
            else:
                if pid not in self.individuals:
                    raise ValueError(f"Unknown individual ID: {pid}")
        # Enforce one-event-only rule
        for pid in ordered_ids:
            if ev.type == "Team":
                team = self.teams[pid]
                if team.one_event_only:
                    if team.chosen_event_id is None:
                        # Ensure they don't already appear in another team event
                        for other_eid, places in self.results.items():
                            other_ev = self.events.get(other_eid)
                            if other_ev and other_ev.type == "Team" and pid in places and other_eid != eid:
                                raise ValueError(f"Team '{team.name}' is one-event-only and already entered another event.")
                        team.chosen_event_id = eid
                    elif team.chosen_event_id != eid:
                        raise ValueError(f"Team '{team.name}' is restricted to its chosen event.")
            else:
                ind = self.individuals[pid]
                if ind.one_event_only:
                    if ind.chosen_event_id is None:
                        for other_eid, places in self.results.items():
                            other_ev = self.events.get(other_eid)
                            if other_ev and other_ev.type == "Individual" and pid in places and other_eid != eid:
                                raise ValueError(f"Individual '{ind.name}' is one-event-only and already entered another event.")
                        ind.chosen_event_id = eid
                    elif ind.chosen_event_id != eid:
                        raise ValueError(f"Individual '{ind.name}' is restricted to their chosen event.")
        # Save results
        self.results[eid] = list(ordered_ids)

    def aggregate_points(self) -> Tuple[Dict[int, int], Dict[int, int]]:
        """Return (team_points, individual_points) as dictionaries of totals."""
        team_points: Dict[int, int] = {tid: 0 for tid in self.teams}
        indiv_points: Dict[int, int] = {iid: 0 for iid in self.individuals}
        for eid, ordered in self.results.items():
            ev = self.events.get(eid)
            if not ev or not ordered:
                continue
            pmap = self.get_points_for_event(eid)
            for idx, pid in enumerate(ordered):
                rank = idx + 1
                pts = pmap.get(rank, 0)
                if ev.type == "Team" and pid in team_points:
                    team_points[pid] += pts
                elif ev.type == "Individual" and pid in indiv_points:
                    indiv_points[pid] += pts
        return team_points, indiv_points

    def events_entered_counts(self) -> Tuple[Dict[int, int], Dict[int, int]]:
        """Return (team_events_entered, individual_events_entered) counts."""
        team_counts: Dict[int, int] = {tid: 0 for tid in self.teams}
        indiv_counts: Dict[int, int] = {iid: 0 for iid in self.individuals}
        for eid, ordered in self.results.items():
            ev = self.events.get(eid)
            if not ev:
                continue
            if ev.type == "Team":
                for pid in set(ordered):
                    if pid in team_counts:
                        team_counts[pid] += 1
            else:
                for pid in set(ordered):
                    if pid in indiv_counts:
                        indiv_counts[pid] += 1
        return team_counts, indiv_counts

    # ---- JSON serialization ----
    def to_json(self) -> dict:
        return {
            "teams": [asdict(t) for t in self.teams.values()],
            "individuals": [asdict(i) for i in self.individuals.values()],
            "events": [
                {
                    **asdict(e),
                    "points_map": {str(k): v for k, v in (e.points_map or {}).items()}
                }
                for e in self.events.values()
            ],
            "results": {str(eid): places for eid, places in self.results.items()},
            "points_map": {str(k): v for k, v in self.points_map.items()},
        }

    def load_json(self, data: dict) -> None:
        # Validate base keys
        for key in ("teams", "individuals", "events", "results", "points_map"):
            if key not in data:
                raise ValueError(f"Missing key in file: {key}")
        # Load points map
        points_map = {int(k): int(v) for k, v in data.get("points_map", {}).items()}
        if points_map:
            self._validate_points_map(points_map)
            self.points_map = points_map
        # Load events
        self.events.clear()
        for e in data["events"]:
            eid = int(e["id"]) if "id" in e else None
            if eid is None:
                raise ValueError("Event missing id.")
            etype = e.get("type")
            name = self._clean_name(e.get("name"))
            genre = e.get("genre", "")
            pmap = e.get("points_map") or {}
            pmap_int = {int(k): int(v) for k, v in pmap.items()} if pmap else None
            if pmap_int:
                self._validate_points_map(pmap_int)
            self.events[eid] = Event(id=eid, name=name, type=etype, genre=genre, points_map=pmap_int)
        # Check events count constraints
        if sum(1 for ev in self.events.values() if ev.type == "Team") > self.max_events_per_type():
            raise ValueError("Too many Team events in file.")
        if sum(1 for ev in self.events.values() if ev.type == "Individual") > self.max_events_per_type():
            raise ValueError("Too many Individual events in file.")
        # Load teams
        self.teams.clear()
        for t in data["teams"]:
            tid = int(t["id"]) if "id" in t else None
            if tid is None:
                raise ValueError("Team missing id.")
            one_ev = bool(t.get("one_event_only", False))
            chosen = t.get("chosen_event_id")
            chosen = int(chosen) if chosen is not None else None
            if chosen is not None:
                ev = self.events.get(chosen)
                if ev is None or ev.type != "Team":
                    raise ValueError("Team chosen_event_id invalid or wrong type.")
            members = [self._clean_name(m) for m in t.get("members", []) if self._clean_name(m)]
            if len(members) == 0:
                raise ValueError("A team must have at least one member.")
            self.teams[tid] = Team(id=tid, name=self._clean_name(t.get("name")), members=members, one_event_only=one_ev, chosen_event_id=chosen)
        if len(self.teams) > self.max_teams():
            raise ValueError("Too many teams in file.")
        # Load individuals
        self.individuals.clear()
        for i in data["individuals"]:
            iid = int(i["id"]) if "id" in i else None
            if iid is None:
                raise ValueError("Individual missing id.")
            one_ev = bool(i.get("one_event_only", False))
            chosen = i.get("chosen_event_id")
            chosen = int(chosen) if chosen is not None else None
            if chosen is not None:
                ev = self.events.get(chosen)
                if ev is None or ev.type != "Individual":
                    raise ValueError("Individual chosen_event_id invalid or wrong type.")
            self.individuals[iid] = Individual(id=iid, name=self._clean_name(i.get("name")), one_event_only=one_ev, chosen_event_id=chosen)
        if len(self.individuals) > self.max_individuals():
            raise ValueError("Too many individuals in file.")
        # Load results
        self.results.clear()
        for k, places in data.get("results", {}).items():
            eid = int(k)
            if eid not in self.events:
                continue
            # Basic type checks
            if not isinstance(places, list):
                raise ValueError("Results for an event must be a list.")
            # Validate entries
            ev = self.events[eid]
            ids = [int(p) for p in places]
            if len(ids) != len(set(ids)):
                raise ValueError("Duplicate entrants in saved results.")
            for pid in ids:
                if ev.type == "Team":
                    if pid not in self.teams:
                        raise ValueError("Result references unknown team.")
                else:
                    if pid not in self.individuals:
                        raise ValueError("Result references unknown individual.")
            self.results[eid] = ids
        # Reset counters to avoid collisions on subsequent adds
        self.team_counter = (max(self.teams) + 1) if self.teams else 1
        self.indiv_counter = (max(self.individuals) + 1) if self.individuals else 1
        self.event_counter = (max(self.events) + 1) if self.events else 1


