        self.indiv_frame.columnconfigure(2, weight=1)

        ttk.Label(frm2, text="Name:").grid(row=0, column=0, sticky="w")
        self.indiv_name = ttk.Entry(frm2)
        self.indiv_name.grid(row=0, column=1, sticky="ew")

        self.indiv_one_ev = tk.BooleanVar(value=False)
        ttk.Checkbutton(frm2, text="One event only", variable=self.indiv_one_ev).grid(row=1, column=1, sticky="w")

        ttk.Label(frm2, text="Chosen event:").grid(row=2, column=0, sticky="w")
        self.indiv_chosen_event = ttk.Combobox(frm2, state="readonly")  # filled with Individual events
        self.indiv_chosen_event.grid(row=2, column=1, sticky="ew")
        self.indiv_chosen_event['values'] = ["(none)"]

        btnfrm2 = ttk.Frame(frm2)
        btnfrm2.grid(row=3, column=0, columnspan=2, pady=(8, 0))
