        ttk.Button(btnfrm2, text="Update", command=self._update_indiv).grid(row=0, column=1, padx=2)
        ttk.Button(btnfrm2, text="Remove", command=self._remove_indiv).grid(row=0, column=2, padx=2)
        ttk.Button(btnfrm2, text="Clear", command=self._clear_indiv_fields).grid(row=0, column=3, padx=2)

        for c in range(2):
            frm2.columnconfigure(c, weight=1)

    # ---- Data refreshers ----
    def refresh_all(self):
        self._refresh_team_list()
        self._refresh_indiv_list()
        self._refresh_event_comboboxes()

    def _refresh_team_list(self):
        self.team_list.delete(0, tk.END)
        for t in sorted(self.model.teams.values(), key=lambda x: x.name.lower()):
            self.team_list.insert(tk.END, f"[{t.id}] {t.name}")

    def _refresh_indiv_list(self):
        self.indiv_list.delete(0, tk.END)
        for p in sorted(self.model.individuals.values(), key=lambda x: x.name.lower()):
            self.indiv_list.insert(tk.END, f"[{p.id}] {p.name}")

    def _refresh_event_comboboxes(self):
        # Populate chosen event comboboxes based on type
        team_events = ["(none)"] + [f"{e.id}: {e.name}" for e in self.model.events.values() if e.type == "Team"]
        indiv_events = ["(none)"] + [f"{e.id}: {e.name}" for e in self.model.events.values() if e.type == "Individual"]
        self.team_chosen_event['values'] = team_events
        self.indiv_chosen_event['values'] = indiv_events

    # ---- Helpers ----
    def _selected_team_id(self) -> Optional[int]:
        sel = self.team_list.curselection()
        if not sel:
            return None
        label = self.team_list.get(sel[0])
        try:
            return int(label.split(']')[0][1:])
        except Exception:
            return None

    def _selected_indiv_id(self) -> Optional[int]:
        sel = self.indiv_list.curselection()
        if not sel:
            return None
        label = self.indiv_list.get(sel[0])
        try:
            return int(label.split(']')[0][1:])
        except Exception:
            return None

    def _parse_chosen_event(self, value: str) -> Optional[int]:
        if not value or value == "(none)":
            return None
        try:
            return int(value.split(':')[0])
        except Exception:
            return None

    # ---- Events: Teams ----
    def _on_team_select(self, _):
        tid = self._selected_team_id()
        if tid is None:
            return
        t = self.model.teams.get(tid)
        if not t:
            return
        self.team_name.delete(0, tk.END)
        self.team_name.insert(0, t.name)
        for i, e in enumerate(self.member_entries):
            e.delete(0, tk.END)
            if i < len(t.members):
                e.insert(0, t.members[i])
        self.team_one_ev.set(t.one_event_only)
        if t.chosen_event_id and t.chosen_event_id in self.model.events:
            ev = self.model.events[t.chosen_event_id]
            self.team_chosen_event.set(f"{ev.id}: {ev.name}")
        else:
            self.team_chosen_event.set("(none)")

    def _collect_team_members(self) -> List[str]:
        members = []
        for e in self.member_entries:
            val = e.get().strip()
            if val:
                members.append(val)
        return members

    def _add_team(self):
        try:
            name = self.team_name.get().strip()
            members = self._collect_team_members()
            one_ev = self.team_one_ev.get()
            chosen = self._parse_chosen_event(self.team_chosen_event.get())
            self.model.add_team(name, members, one_ev, chosen)
            self._clear_team_fields()
            self._refresh_team_list()
        except Exception as e:
            messagebox.showerror("Add Team", str(e))

    def _update_team(self):
        tid = self._selected_team_id()
        if tid is None:
            messagebox.showwarning("Update Team", "Select a team to update.")
            return
        try:
            name = self.team_name.get().strip()
            members = self._collect_team_members()
            one_ev = self.team_one_ev.get()
            chosen = self._parse_chosen_event(self.team_chosen_event.get())
            self.model.edit_team(tid, name, members, one_ev, chosen)
            self._refresh_team_list()
        except Exception as e:
            messagebox.showerror("Update Team", str(e))

    def _remove_team(self):
        tid = self._selected_team_id()
        if tid is None:
            messagebox.showwarning("Remove Team", "Select a team to remove.")
            return
        if messagebox.askyesno("Remove Team", "Are you sure you want to remove this team?"):
            try:
                self.model.remove_team(tid)
                self._refresh_team_list()
            except Exception as e:
                messagebox.showerror("Remove Team", str(e))

    def _clear_team_fields(self):
        self.team_name.delete(0, tk.END)
        for e in self.member_entries:
            e.delete(0, tk.END)
        self.team_one_ev.set(False)
        self.team_chosen_event.set("(none)")
        self.team_list.selection_clear(0, tk.END)

    # ---- Events: Individuals ----
    def _on_indiv_select(self, _):
        iid = self._selected_indiv_id()
        if iid is None:
            return
        p = self.model.individuals.get(iid)
        if not p:
            return
        self.indiv_name.delete(0, tk.END)
        self.indiv_name.insert(0, p.name)
        self.indiv_one_ev.set(p.one_event_only)
        if p.chosen_event_id and p.chosen_event_id in self.model.events:
            ev = self.model.events[p.chosen_event_id]
            self.indiv_chosen_event.set(f"{ev.id}: {ev.name}")
        else:
            self.indiv_chosen_event.set("(none)")

    def _add_indiv(self):
        try:
            name = self.indiv_name.get().strip()
            one_ev = self.indiv_one_ev.get()
            chosen = self._parse_chosen_event(self.indiv_chosen_event.get())
            self.model.add_individual(name, one_ev, chosen)
            self._clear_indiv_fields()
            self._refresh_indiv_list()
        except Exception as e:
            messagebox.showerror("Add Individual", str(e))

    def _update_indiv(self):
        iid = self._selected_indiv_id()
        if iid is None:
            messagebox.showwarning("Update Individual", "Select an individual to update.")
            return
        try:
            name = self.indiv_name.get().strip()
            one_ev = self.indiv_one_ev.get()
            chosen = self._parse_chosen_event(self.indiv_chosen_event.get())
            self.model.edit_individual(iid, name, one_ev, chosen)
            self._refresh_indiv_list()
        except Exception as e:
            messagebox.showerror("Update Individual", str(e))

    def _remove_indiv(self):
        iid = self._selected_indiv_id()
        if iid is None:
            messagebox.showwarning("Remove Individual", "Select an individual to remove.")
            return
        if messagebox.askyesno("Remove Individual", "Are you sure you want to remove this individual?"):
            try:
                self.model.remove_individual(iid)
                self._refresh_indiv_list()
            except Exception as e:
                messagebox.showerror("Remove Individual", str(e))

    def _clear_indiv_fields(self):
        self.indiv_name.delete(0, tk.END)
        self.indiv_one_ev.set(False)
        self.indiv_chosen_event.set("(none)")
        self.indiv_list.selection_clear(0, tk.END)


class EventsTab(ttk.Frame):
    """Manage Events, including optional per-event points overrides."""

    def __init__(self, master, model: TournamentData, refresh_participants_cb):
        super().__init__(master)
        self.model = model
        self.refresh_participants_cb = refresh_participants_cb
        self._build_ui()
        self.refresh_events()

    def _build_ui(self):
        self.event_list = tk.Listbox(self, height=14)
        self.event_list.grid(row=0, column=0, rowspan=8, sticky="nsew", padx=(8, 4), pady=8)
        self.event_list.bind("<<ListboxSelect>>", self._on_event_select)
        scroll = ttk.Scrollbar(self, orient=tk.VERTICAL, command=self.event_list.yview)
        self.event_list.configure(yscrollcommand=scroll.set)
        scroll.grid(row=0, column=1, rowspan=8, sticky="ns", pady=8)

        frm = ttk.Frame(self)
        frm.grid(row=0, column=2, sticky="nsew", padx=8, pady=8)
        self.columnconfigure(0, weight=1)
        self.columnconfigure(2, weight=1)

        ttk.Label(frm, text="Name:").grid(row=0, column=0, sticky="w")
        self.ev_name = ttk.Entry(frm)
        self.ev_name.grid(row=0, column=1, sticky="ew")

        ttk.Label(frm, text="Type:").grid(row=1, column=0, sticky="w")
        self.ev_type = ttk.Combobox(frm, state="readonly", values=["Team", "Individual"])
        self.ev_type.grid(row=1, column=1, sticky="ew")

        ttk.Label(frm, text="Genre:").grid(row=2, column=0, sticky="w")
        self.ev_genre = ttk.Entry(frm)
        self.ev_genre.grid(row=2, column=1, sticky="ew")

        ttk.Label(frm, text="Per-event points (e.g. 1:25,2:18):").grid(row=3, column=0, sticky="w")
        self.ev_points = ttk.Entry(frm)
        self.ev_points.grid(row=3, column=1, sticky="ew")

        btnfrm = ttk.Frame(frm)
        btnfrm.grid(row=4, column=0, columnspan=2, pady=(8, 0))
        ttk.Button(btnfrm, text="Add", command=self._add_event).grid(row=0, column=0, padx=2)
        ttk.Button(btnfrm, text="Update", command=self._update_event).grid(row=0, column=1, padx=2)
        ttk.Button(btnfrm, text="Remove", command=self._remove_event).grid(row=0, column=2, padx=2)
        ttk.Button(btnfrm, text="Clear", command=self._clear_event_fields).grid(row=0, column=3, padx=2)

        for c in range(2):
            frm.columnconfigure(c, weight=1)

    def refresh_events(self):
        self.event_list.delete(0, tk.END)
        for e in sorted(self.model.events.values(), key=lambda x: (x.type, x.name.lower())):
            self.event_list.insert(tk.END, f"[{e.id}] {e.type} - {e.name}")

    def _selected_event_id(self) -> Optional[int]:
        sel = self.event_list.curselection()
        if not sel:
            return None
        label = self.event_list.get(sel[0])
        try:
            return int(label.split(']')[0][1:])
        except Exception:
            return None

    def _parse_points_map(self, text: str) -> Optional[Dict[int, int]]:
        text = (text or "").strip()
        if not text:
            return None
        try:
            parts = [p.strip() for p in text.split(',') if p.strip()]
            mp: Dict[int, int] = {}
            for p in parts:
                k, v = p.split(':')
                mp[int(k.strip())] = int(v.strip())
            self.model._validate_points_map(mp)
            return mp
        except Exception as e:
            raise ValueError(f"Invalid points format: {e}")

    def _on_event_select(self, _):
        eid = self._selected_event_id()
        if eid is None:
            return
        ev = self.model.events.get(eid)
        if not ev:
            return
        self.ev_name.delete(0, tk.END)
        self.ev_name.insert(0, ev.name)
        self.ev_type.set(ev.type)
        self.ev_genre.delete(0, tk.END)
        self.ev_genre.insert(0, ev.genre or "")
        if ev.points_map:
            txt = ",".join([f"{k}:{v}" for k, v in sorted(ev.points_map.items())])
            self.ev_points.delete(0, tk.END)
            self.ev_points.insert(0, txt)
        else:
            self.ev_points.delete(0, tk.END)

    def _add_event(self):
        try:
            name = self.ev_name.get().strip()
            etype = self.ev_type.get().strip()
            genre = self.ev_genre.get().strip()
            pmap = self._parse_points_map(self.ev_points.get())
            self.model.add_event(name, etype, genre, pmap)
            self._clear_event_fields()
            self.refresh_events()
            self.refresh_participants_cb()
        except Exception as e:
            messagebox.showerror("Add Event", str(e))

    def _update_event(self):
        eid = self._selected_event_id()
        if eid is None:
            messagebox.showwarning("Update Event", "Select an event to update.")
            return
        try:
            name = self.ev_name.get().strip()
            etype = self.ev_type.get().strip()
            genre = self.ev_genre.get().strip()
            pmap = self._parse_points_map(self.ev_points.get())
            self.model.edit_event(eid, name, etype, genre, pmap)
            self.refresh_events()
            self.refresh_participants_cb()
        except Exception as e:
            messagebox.showerror("Update Event", str(e))

    def _remove_event(self):
        eid = self._selected_event_id()
        if eid is None:
            messagebox.showwarning("Remove Event", "Select an event to remove.")
            return
        if messagebox.askyesno("Remove Event", "Are you sure you want to remove this event?"):
            try:
                self.model.remove_event(eid)
                self.refresh_events()
                self.refresh_participants_cb()
            except Exception as e:
                messagebox.showerror("Remove Event", str(e))

    def _clear_event_fields(self):
        self.ev_name.delete(0, tk.END)
        self.ev_type.set("")
        self.ev_genre.delete(0, tk.END)
        self.ev_points.delete(0, tk.END)
        self.event_list.selection_clear(0, tk.END)


class ResultsTab(ttk.Frame):
    """Enter ranked results by ordering entrants for a selected event."""

    def __init__(self, master, model: TournamentData):
        super().__init__(master)
        self.model = model
        self._build_ui()
        self._refresh_events()

    def _build_ui(self):
        top = ttk.Frame(self)
        top.pack(fill=tk.X, padx=8, pady=8)
        ttk.Label(top, text="Event:").pack(side=tk.LEFT)
        self.event_combo = ttk.Combobox(top, state="readonly")
        self.event_combo.pack(side=tk.LEFT, padx=6)
        self.event_combo.bind("<<ComboboxSelected>>", lambda e: self._refresh_entrants())

        mid = ttk.Frame(self)
        mid.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        # Available entrants
        left = ttk.Labelframe(mid, text="Available entrants")
        left.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(0, 4))
        self.available_list = tk.Listbox(left, selectmode=tk.EXTENDED)
        self.available_list.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        # Controls
        ctrls = ttk.Frame(mid)
        ctrls.pack(side=tk.LEFT, fill=tk.Y)
        ttk.Button(ctrls, text=">>", command=self._add_selected).pack(pady=4)
        ttk.Button(ctrls, text="<<", command=self._remove_selected).pack(pady=4)
        ttk.Button(ctrls, text="Up", command=self._move_up).pack(pady=4)
        ttk.Button(ctrls, text="Down", command=self._move_down).pack(pady=4)

        # Ordered results
        right = ttk.Labelframe(mid, text="Ordered results (1st at top)")
        right.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(4, 0))
        self.results_list = tk.Listbox(right)
        self.results_list.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        bottom = ttk.Frame(self)
        bottom.pack(fill=tk.X, padx=8, pady=(0, 8))
        ttk.Button(bottom, text="Save Results", command=self._save_results).pack(side=tk.RIGHT)

    def _refresh_events(self):
        vals = [f"{e.id}: {e.name} ({e.type})" for e in self.model.events.values()]
        self.event_combo['values'] = vals
        if vals:
            self.event_combo.current(0)
        self._refresh_entrants()

    def _current_event_id(self) -> Optional[int]:
        val = self.event_combo.get()
        if not val:
            return None
        try:
            return int(val.split(':')[0])
        except Exception:
            return None

    def _refresh_entrants(self):
        self.available_list.delete(0, tk.END)
        self.results_list.delete(0, tk.END)
        eid = self._current_event_id()
        if eid is None:
            return
        ev = self.model.events.get(eid)
        if not ev:
            return
        # Fill available entrants based on event type
        if ev.type == "Team":
            data = sorted([(t.id, t.name) for t in self.model.teams.values()], key=lambda x: x[1].lower())
        else:
            data = sorted([(i.id, i.name) for i in self.model.individuals.values()], key=lambda x: x[1].lower())
        for pid, name in data:
            self.available_list.insert(tk.END, f"{pid}: {name}")
        # Load existing results if any
        if eid in self.model.results:
            for pid in self.model.results[eid]:
                name = self._name_for_pid(ev.type, pid)
                if name is not None:
                    self.results_list.insert(tk.END, f"{pid}: {name}")

    def _name_for_pid(self, etype: str, pid: int) -> Optional[str]:
        if etype == "Team":
            t = self.model.teams.get(pid)
            return t.name if t else None
        else:
            i = self.model.individuals.get(pid)
            return i.name if i else None

    def _add_selected(self):
        for idx in self.available_list.curselection():
            val = self.available_list.get(idx)
            if val not in self.results_list.get(0, tk.END):
                self.results_list.insert(tk.END, val)

    def _remove_selected(self):
        sel = list(self.results_list.curselection())
        sel.reverse()
        for i in sel:
            self.results_list.delete(i)

    def _move_up(self):
        sel = self.results_list.curselection()
        if not sel:
            return
        i = sel[0]
        if i <= 0:
            return
        val = self.results_list.get(i)
        self.results_list.delete(i)
        self.results_list.insert(i-1, val)
        self.results_list.selection_set(i-1)

    def _move_down(self):
        sel = self.results_list.curselection()
        if not sel:
            return
        i = sel[0]
        if i >= self.results_list.size()-1:
            return
        val = self.results_list.get(i)
        self.results_list.delete(i)
        self.results_list.insert(i+1, val)
        self.results_list.selection_set(i+1)

    def _save_results(self):
        eid = self._current_event_id()
        if eid is None:
            messagebox.showwarning("Save Results", "Select an event.")
            return
        try:
            ids: List[int] = []
            for i in range(self.results_list.size()):
                label = self.results_list.get(i)
                pid = int(label.split(':')[0])
                ids.append(pid)
            self.model.set_results(eid, ids)
            messagebox.showinfo("Save Results", "Results saved.")
        except Exception as e:
            messagebox.showerror("Save Results", str(e))


class LeaderboardsTab(ttk.Frame):
    """Display Team and Individual leaderboards."""

    def __init__(self, master, model: TournamentData):
        super().__init__(master)
        self.model = model
        self._build_ui()
        self.refresh()

    def _build_ui(self):
        paned = ttk.Panedwindow(self, orient=tk.HORIZONTAL)
        paned.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        self.team_frame = ttk.Labelframe(paned, text="Team Leaderboard")
        self.indiv_frame = ttk.Labelframe(paned, text="Individual Leaderboard")
        paned.add(self.team_frame, weight=1)
        paned.add(self.indiv_frame, weight=1)

        cols = ("rank", "name", "points", "events")
        self.team_tree = ttk.Treeview(self.team_frame, columns=cols, show="headings")
        for c, t in zip(cols, ("Rank", "Team", "Points", "Events")):
            self.team_tree.heading(c, text=t)
            self.team_tree.column(c, width=90, anchor=tk.CENTER if c != "name" else tk.W)
        self.team_tree.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        self.indiv_tree = ttk.Treeview(self.indiv_frame, columns=cols, show="headings")
        for c, t in zip(cols, ("Rank", "Competitor", "Points", "Events")):
            self.indiv_tree.heading(c, text=t)
            self.indiv_tree.column(c, width=90, anchor=tk.CENTER if c != "name" else tk.W)
        self.indiv_tree.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        ttk.Button(self, text="Refresh", command=self.refresh).pack(anchor=tk.E, padx=8, pady=(0, 8))

    def refresh(self):
        # Clear
        for tv in (self.team_tree, self.indiv_tree):
            for item in tv.get_children():
                tv.delete(item)
        team_pts, indiv_pts = self.model.aggregate_points()
        team_ev, indiv_ev = self.model.events_entered_counts()
        # Team leaderboard
        team_rows = []
        for tid, t in self.model.teams.items():
            team_rows.append((t.name, team_pts.get(tid, 0), team_ev.get(tid, 0), tid))
        team_rows.sort(key=lambda x: (-x[1], x[0].lower()))
        for idx, (name, pts, evs, tid) in enumerate(team_rows, start=1):
            self.team_tree.insert('', tk.END, values=(idx, name, pts, evs))
        # Individual leaderboard
        indiv_rows = []
        for iid, p in self.model.individuals.items():
            indiv_rows.append((p.name, indiv_pts.get(iid, 0), indiv_ev.get(iid, 0), iid))
        indiv_rows.sort(key=lambda x: (-x[1], x[0].lower()))
        for idx, (name, pts, evs, iid) in enumerate(indiv_rows, start=1):
            self.indiv_tree.insert('', tk.END, values=(idx, name, pts, evs))


class PointsTab(ttk.Frame):
    """Configure global points map using suggested schemes or custom map."""

    def __init__(self, master, model: TournamentData):
        super().__init__(master)
        self.model = model
        self.scheme = tk.StringVar(value="F1")
        self._build_ui()
        self._load_current_points()

    def _build_ui(self):
        frm = ttk.Frame(self)
        frm.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)

        ttk.Label(frm, text="Suggested schemes:").grid(row=0, column=0, sticky="w")
        schemes = [
            ("F1 Top-10", "F1"),
            ("Top-8 Balanced", "T8"),
            ("Winner-Takes-All (Top-5)", "WTA"),
            ("Linear Builder", "LIN"),
        ]
        rfrm = ttk.Frame(frm)
        rfrm.grid(row=1, column=0, columnspan=2, sticky="w")
        for i, (label, value) in enumerate(schemes):
            ttk.Radiobutton(rfrm, text=label, variable=self.scheme, value=value, command=self._apply_scheme_preview).grid(row=0, column=i, padx=4, pady=4)

        # Linear builder controls
        self.lin_n = tk.IntVar(value=10)
        self.lin_top = tk.IntVar(value=10)
        linfrm = ttk.Frame(frm)
        linfrm.grid(row=2, column=0, columnspan=2, sticky="w")
        ttk.Label(linfrm, text="Linear N:").grid(row=0, column=0, sticky="w")
        ttk.Spinbox(linfrm, from_=1, to=20, textvariable=self.lin_n, width=5, command=self._apply_scheme_preview).grid(row=0, column=1, padx=4)
        ttk.Label(linfrm, text="Top points:").grid(row=0, column=2, sticky="w")
        ttk.Spinbox(linfrm, from_=1, to=100, textvariable=self.lin_top, width=5, command=self._apply_scheme_preview).grid(row=0, column=3, padx=4)

        ttk.Label(frm, text="Custom points map (e.g. 1:25,2:18):").grid(row=3, column=0, sticky="w", pady=(8, 0))
        self.custom_entry = ttk.Entry(frm)
        self.custom_entry.grid(row=4, column=0, columnspan=2, sticky="ew")

        ttk.Label(frm, text="Preview:").grid(row=5, column=0, sticky="w", pady=(8, 0))
        self.preview = tk.Text(frm, height=4, width=50)
        self.preview.grid(row=6, column=0, columnspan=2, sticky="ew")
        self.preview.configure(state=tk.DISABLED)

        btnfrm = ttk.Frame(frm)
        btnfrm.grid(row=7, column=0, columnspan=2, pady=8, sticky="e")
        ttk.Button(btnfrm, text="Apply Global Points", command=self._apply_points).grid(row=0, column=0, padx=4)

        frm.columnconfigure(0, weight=1)
        frm.columnconfigure(1, weight=1)

    def _load_current_points(self):
        # Show current global points in preview
        self._set_preview(self.model.points_map)

    def _set_preview(self, mp: Dict[int, int]):
        txt = ", ".join([f"{k}:{v}" for k, v in sorted(mp.items())])
        self.preview.configure(state=tk.NORMAL)
        self.preview.delete("1.0", tk.END)
        self.preview.insert(tk.END, txt)
        self.preview.configure(state=tk.DISABLED)

    def _apply_scheme_preview(self):
        scheme = self.scheme.get()
        if scheme == "F1":
            mp = {1: 25, 2: 18, 3: 15, 4: 12, 5: 10, 6: 8, 7: 6, 8: 4, 9: 2, 10: 1}
        elif scheme == "T8":
            mp = {1: 10, 2: 8, 3: 6, 4: 5, 5: 4, 6: 3, 7: 2, 8: 1}
        elif scheme == "WTA":
            mp = {1: 10, 2: 0, 3: 0, 4: 0, 5: 0}
        else:  # Linear
            n = max(1, int(self.lin_n.get()))
            top = max(1, int(self.lin_top.get()))
            mp = {r: max(0, top - (r - 1)) for r in range(1, n + 1)}
        self._set_preview(mp)

    def _parse_custom(self) -> Optional[Dict[int, int]]:
        text = self.custom_entry.get().strip()
        if not text:
            return None
        parts = [p.strip() for p in text.split(',') if p.strip()]
        mp: Dict[int, int] = {}
        for p in parts:
            k, v = p.split(':')
            mp[int(k.strip())] = int(v.strip())
        return mp

    def _apply_points(self):
        try:
            custom = self._parse_custom()
            if custom is not None:
                self.model._validate_points_map(custom)
                self.model.points_map = custom
                self._set_preview(self.model.points_map)
                messagebox.showinfo("Points", "Applied custom global points.")
                return
            # Apply selected scheme
            scheme = self.scheme.get()
            if scheme == "F1":
                mp = {1: 25, 2: 18, 3: 15, 4: 12, 5: 10, 6: 8, 7: 6, 8: 4, 9: 2, 10: 1}
            elif scheme == "T8":
                mp = {1: 10, 2: 8, 3: 6, 4: 5, 5: 4, 6: 3, 7: 2, 8: 1}
            elif scheme == "WTA":
                mp = {1: 10, 2: 0, 3: 0, 4: 0, 5: 0}
            else:
                n = max(1, int(self.lin_n.get()))
                top = max(1, int(self.lin_top.get()))
                mp = {r: max(0, top - (r - 1)) for r in range(1, n + 1)}
            self.model._validate_points_map(mp)
            self.model.points_map = mp
            self._set_preview(self.model.points_map)
            messagebox.showinfo("Points", "Applied global points scheme.")
        except Exception as e:
            messagebox.showerror("Points", str(e))


class App(tk.Tk):
    """Main application window with tabs and file menu."""

    def __init__(self):
        super().__init__()
        self.title("E-Sports Tournament Scoring")
        self.geometry("1100x700")
        self.model = TournamentData()
        self.current_file: Optional[str] = None
        self._build_menu()
        self._build_tabs()

    # ---- Menu ----
    def _build_menu(self):
        menubar = tk.Menu(self)
        filemenu = tk.Menu(menubar, tearoff=0)
        filemenu.add_command(label="New", command=self._new_file)
        filemenu.add_command(label="Open...", command=self._open_file)
        filemenu.add_command(label="Save", command=self._save)
        filemenu.add_command(label="Save As...", command=self._save_as)
        filemenu.add_separator()
        filemenu.add_command(label="Exit", command=self.destroy)
        menubar.add_cascade(label="File", menu=filemenu)
        self.config(menu=menubar)

    # ---- Tabs ----
    def _build_tabs(self):
        self.nb = ttk.Notebook(self)
        self.nb.pack(fill=tk.BOTH, expand=True)

        self.participants_tab = ParticipantsTab(self.nb, self.model, refresh_events_cb=self._refresh_event_sources)
        self.events_tab = EventsTab(self.nb, self.model, refresh_participants_cb=self._refresh_event_sources)
        self.results_tab = ResultsTab(self.nb, self.model)
        self.leaderboards_tab = LeaderboardsTab(self.nb, self.model)
        self.points_tab = PointsTab(self.nb, self.model)

        self.nb.add(self.participants_tab, text="Participants")
        self.nb.add(self.events_tab, text="Events")
        self.nb.add(self.results_tab, text="Results")
        self.nb.add(self.leaderboards_tab, text="Leaderboards")
        self.nb.add(self.points_tab, text="Points")

    def _refresh_event_sources(self):
        # Called when events change to refresh participants' chosen-event combos and results selector
        self.participants_tab._refresh_event_comboboxes()
        self.events_tab.refresh_events()
        self.results_tab._refresh_events()
        self.leaderboards_tab.refresh()

    # ---- File ops ----
    def _new_file(self):
        if not messagebox.askyesno("New", "Clear all data and start a new tournament?"):
            return
        self.model = TournamentData()
        # Rebuild tabs to bind to new model or update their model refs
        self.participants_tab.model = self.model
        self.events_tab.model = self.model
        self.results_tab.model = self.model
        self.leaderboards_tab.model = self.model
        self.points_tab.model = self.model
        self._refresh_event_sources()
        self.participants_tab.refresh_all()
        self.current_file = None

    def _open_file(self):
        path = filedialog.askopenfilename(title="Open Tournament", filetypes=[("JSON Files", "*.json"), ("All Files", "*.*")])
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            self.model = TournamentData()
            self.model.load_json(data)
            # Rebind models
            self.participants_tab.model = self.model
            self.events_tab.model = self.model
            self.results_tab.model = self.model
            self.leaderboards_tab.model = self.model
            self.points_tab.model = self.model
            self._refresh_event_sources()
            self.participants_tab.refresh_all()
            self.current_file = path
        except Exception as e:
            messagebox.showerror("Open", f"Failed to open file:\n{e}")

    def _save(self):
        if not self.current_file:
            self._save_as()
            return
        try:
            data = self.model.to_json()
            with open(self.current_file, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2)
            messagebox.showinfo("Save", "Saved successfully.")
        except Exception as e:
            messagebox.showerror("Save", f"Failed to save:\n{e}")

    def _save_as(self):
        path = filedialog.asksaveasfilename(defaultextension=".json", filetypes=[("JSON Files", "*.json"), ("All Files", "*.*")])
        if not path:
            return
        self.current_file = path
        self._save()


