# PowerShell script to loop through specified folders and perform Git, code replacement, NuGet updates, and run tests
param(
  [string[]]$Folders = @('Ewl.Platform.Analytics')
)

$ErrorActionPreference = 'Stop'
$startDir = Get-Location

function Invoke-Checked {
  param(
    [Parameter(Mandatory)][string]$File,
    [string[]]$Args
  )
  & $File @Args
  if ($LASTEXITCODE -ne 0) { throw "Command failed: $File $($Args -join ' ')" }
}

function Replace-TimeZoneInFile {
  param(
    [Parameter(Mandatory)][string]$Path
  )
  $raw = [System.IO.File]::ReadAllText($Path)
  $nl = if ($raw.Contains("`r`n")) { "`r`n" } else { "`n" }

  $lines = New-Object 'System.Collections.Generic.List[string]'
  $lines.AddRange([System.IO.File]::ReadAllLines($Path))

  $modified = $false
  for ($i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]
    if ($line.Trim() -eq 'o.Select().Filter().OrderBy().Count().Expand().SetMaxTop(100);') {
      $indent = ([regex]::Match($line, '^\s*')).Value
      $next = if ($i + 1 -lt $lines.Count) { $lines[$i + 1].Trim() } else { '' }
      if ($next -ne 'o.TimeZone = TimeZoneInfo.Utc;') {
        $lines.Insert($i + 1, $indent + 'o.TimeZone = TimeZoneInfo.Utc;')
        $modified = $true
        $i++
      }
    }
  }

  if ($modified) {
    $text = [string]::Join($nl, $lines)
    [System.IO.File]::WriteAllText($Path, $text, (New-Object System.Text.UTF8Encoding($false)))
    Write-Host "[INFO] Updated $Path"
  } else {
    Write-Host "[INFO] No changes needed in $Path"
  }
}

try {
  foreach ($folder in $Folders) {
    $repoPath = Resolve-Path -LiteralPath $folder -ErrorAction SilentlyContinue
    if (-not $repoPath) {
      Write-Warning "Folder not found: $folder"
      continue
    }

    Push-Location $repoPath
    try {
      # Sync with origin/main
      Invoke-Checked git @('fetch','origin','--prune')
      Invoke-Checked git @('checkout','-B','main','origin/main')
      Invoke-Checked git @('reset','--hard','origin/main')

      # Feature branch handling
      $branchName = 'TK/14278_TM-13'
      & git rev-parse --verify ("refs/heads/" + $branchName) *> $null
      if ($LASTEXITCODE -eq 0) {
        Invoke-Checked git @('checkout', $branchName)
        Invoke-Checked git @('reset','--hard','origin/main')
      } else {
        Invoke-Checked git @('checkout','-b', $branchName, 'origin/main')
      }

      # Find and update MvcBuilderExtensions.cs files
      $files = Get-ChildItem -Recurse -File -Filter 'MvcBuilderExtensions.cs' |
        Where-Object { $_.FullName -notmatch '\\bin\\' -and $_.FullName -notmatch '\\obj\\' }
      foreach ($f in $files) {
        Replace-TimeZoneInFile -Path $f.FullName
      }

      # NuGet package updates
      $nuget = Get-Command nuget -ErrorAction SilentlyContinue
      if ($nuget) {
        # Main project under src/<folder>
        $mainProjDir = Join-Path (Get-Location) ("src\" + $folder)
        if (Test-Path $mainProjDir) {
          $mainProj = Get-ChildItem -Path $mainProjDir -Filter *.csproj | Select-Object -First 1
          if ($mainProj) {
            Invoke-Checked $nuget.Source @('update', $mainProj.FullName, '-Id','Ewl.Platform.Common.Api','-Version','1.0.0')
          } else {
            Write-Warning "No main project .csproj found in $mainProjDir"
          }
        } else {
          Write-Warning "Main project directory not found: $mainProjDir"
        }

        # Storage projects ending with .Storage
        $storageProjs = Get-ChildItem -Path (Join-Path (Get-Location) 'src') -Recurse -File -Filter *.csproj |
          Where-Object { $_.BaseName -like '*.Storage' }
        foreach ($sp in $storageProjs) {
          Invoke-Checked $nuget.Source @('update', $sp.FullName, '-Id','Ewl.Platform.Common.Storage','-Version','1.0.0')
        }
      } else {
        Write-Warning 'nuget.exe not found in PATH; skipping NuGet updates.'
      }

      # Run tests
      $sln = Get-ChildItem -Filter *.sln | Select-Object -First 1
      if ($sln) {
        Invoke-Checked dotnet @('test', $sln.FullName)
      } else {
        Invoke-Checked dotnet @('test')
      }
    } finally {
      Pop-Location
    }
  }
} finally {
  Set-Location $startDir
}

// ==UserScript==
// @name         DrTorkzadeh First-Tab Automator
// @namespace    http://tampermonkey.net/
// @version      1.0
// @description  Automate actions on drtorkzadeh.com with first-tab control, time window, text check, and second-tab handoff
// @match        http://www.drtorkzadeh.com/*
// @match        https://www.drtorkzadeh.com/*
// @run-at       document-idle
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_addValueChangeListener
// @grant        GM_deleteValue
// ==/UserScript==

(function() {
  'use strict';

  const TEXT_TO_FIND = 'رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است';
  const LEADER_KEY = 'drtz_leader_tab';
  const CMD_KEY = 'drtz_command';
  const instanceId = `${Date.now()}_${Math.random().toString(36).slice(2)}`;

  function isMainPage() {
    return location.hostname === 'www.drtorkzadeh.com' && (location.pathname === '/' || location.pathname === '');
  }

  if (!isMainPage()) {
    return; // Only operate on the main page
  }

  function inAllowedTimeWindow() {
    const d = new Date();
    const minutes = d.getHours() * 60 + d.getMinutes();
    const start = 22 * 60 + 30; // 22:30
    const end = 3 * 60 + 30;    // 03:30
    // Window crosses midnight: allowed if after 22:30 or before/equal 03:30
    return (minutes >= start) || (minutes <= end);
  }

  // Elect a single active tab ("first" tab = first to claim leadership)
  let isLeader = false;
  const existingLeader = GM_getValue(LEADER_KEY, null);
  if (!existingLeader) {
    GM_setValue(LEADER_KEY, instanceId);
    isLeader = true;
  } else {
    isLeader = (existingLeader === instanceId);
  }

  // Second-tab action listener: only non-leader tab will act on command
  let secondTabActed = false;
  GM_addValueChangeListener(CMD_KEY, (name, oldVal, newVal, remote) => {
    if (!remote || secondTabActed || !newVal) return;
    let cmd;
    try { cmd = JSON.parse(newVal); } catch (e) { return; }
    if (cmd.type !== 'clickSubmit') return;

    const currentLeader = GM_getValue(LEADER_KEY, null);
    if (currentLeader === instanceId) return; // Leader must not act here

    // Ensure we're still on main page
    if (!isMainPage()) return;

    // Click the specified element in the second tab, then stop
    const form = document.querySelector('form[action="http://www.drtorkzadeh.com/"]');
    let submitBtn = null;
    if (form) {
      submitBtn = form.querySelector('#submit');
    }
    if (!submitBtn) {
      submitBtn = document.querySelector('input#submit[type="submit"]');
    }
    if (submitBtn) {
      submitBtn.click();
    }
    secondTabActed = true;
    GM_deleteValue(CMD_KEY);
  });

  // Leader: time-gated loop to check text and reload; if text not found, hand off to second tab
  if (isLeader) {
    let commandSent = false;
    const loopIntervalMs = 5000; // check every 5s when inside window

    function leaderLoop() {
      if (!inAllowedTimeWindow()) {
        // Outside allowed time: wait and re-check
        setTimeout(leaderLoop, 60000); // re-check every 60s
        return;
      }

      const bodyText = (document.body && document.body.innerText) || '';
      const found = bodyText.includes(TEXT_TO_FIND);

      if (found) {
        // Found exact text: wait 5 seconds, then reload and continue
        setTimeout(() => { location.reload(); }, 5000);
        setTimeout(leaderLoop, loopIntervalMs + 5000);
      } else {
        // Not found: signal second tab to click and stop leader activity
        if (!commandSent) {
          commandSent = true;
          GM_setValue(CMD_KEY, JSON.stringify({ type: 'clickSubmit', from: instanceId, at: Date.now() }));
          // Stop the leader loop after handing off
          return;
        }
      }
    }

    // Start the leader loop
    leaderLoop();
  }
})();

// ==UserScript==
// @name         DrTorkzadeh Automator
// @namespace    http://tampermonkey.net/
// @version      1.0
// @description  Automate actions on drtorkzadeh.com as requested
// @match        http://www.drtorkzadeh.com/
// @match        https://www.drtorkzadeh.com/
// @run-at       document-idle
// @grant        GM_getValue
// @grant        GM_setValue
// ==/UserScript==

(function() {
  'use strict';

  // Exact text to look for
  const TARGET_TEXT = "رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است";

  // Ensure the script only runs in the first (primary) tab instance
  function isPrimaryTab() {
    const KEY = 'tm_primary_tab_id';
    const selfId = window.name || (Date.now() + '_' + Math.random());
    if (!window.name) window.name = selfId;
    const cur = GM_getValue(KEY, null);
    if (cur === null) {
      GM_setValue(KEY, selfId);
      return true;
    }
    return cur === selfId;
  }

  // Restrict operation to the main page of the site
  function isMainPage() {
    try {
      const u = new URL(window.location.href);
      const hostOk = (u.hostname === 'www.drtorkzadeh.com' || u.hostname === 'drtorkzadeh.com');
      const pathOk = (u.pathname === '/' || u.pathname === '');
      return hostOk && pathOk;
    } catch (e) {
      return false;
    }
  }

  // Time window 22:30 to 03:30 (spans midnight)
  function inAllowedWindow() {
    const now = new Date();
    const h = now.getHours();
    const m = now.getMinutes();
    const afterStart = (h > 22) || (h === 22 && m >= 30);
    const beforeEnd = (h < 3) || (h === 3 && m <= 30);
    return afterStart || beforeEnd;
  }

  function msUntilNextStart() {
    const now = new Date();
    if (inAllowedWindow()) return 0;
    const start = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 22, 30, 0, 0);
    if (now < start) return start.getTime() - now.getTime();
    const tomorrowStart = new Date(start.getTime() + 24 * 60 * 60 * 1000);
    return tomorrowStart.getTime() - now.getTime();
  }

  function waitUntilWindowStart(cb) {
    const ms = msUntilNextStart();
    setTimeout(cb, Math.max(1, ms));
  }

  // Attempt to switch to next tab via Ctrl+Tab (may not be honored by browsers)
  function tryCtrlTab() {
    try {
      const e = new KeyboardEvent('keydown', { key: 'Tab', code: 'Tab', ctrlKey: true, bubbles: true });
      document.body && document.body.dispatchEvent(e);
      return true;
    } catch (e) {
      return false;
    }
  }

  // Open/focus next tab and click the requested submit element, then stop
  function goToNextTabAndClick() {
    // First, attempt a Ctrl+Tab (best-effort)
    tryCtrlTab();

    // Fallback: open/focus a new tab for the same main page and click the element there
    const url = 'http://www.drtorkzadeh.com/';
    const w = window.open(url, '_blank');
    if (!w) {
      return; // Could not open a tab (popup blocker or policy)
    }
    w.focus();

    const tryClick = () => {
      try {
        const doc = w.document;
        const selectorHttp = 'form[action="http://www.drtorkzadeh.com/"] input[type="submit"]#submit';
        const selectorHttps = 'form[action="https://www.drtorkzadeh.com/"] input[type="submit"]#submit';
        let btn = doc.querySelector(selectorHttp) || doc.querySelector(selectorHttps) || doc.querySelector('#submit[type="submit"]');
        if (btn) {
          btn.click();
          return true;
        }
      } catch (e) {
        // DOM not ready yet
      }
      return false;
    };

    const start = Date.now();
    const maxWaitMs = 10000; // wait up to 10s for the button to appear
    const iv = setInterval(() => {
      if (tryClick() || (Date.now() - start > maxWaitMs)) {
        clearInterval(iv);
      }
    }, 300);
  }

  function loopUntilCondition() {
    let stopped = false;

    const tick = () => {
      if (stopped) return;

      if (!inAllowedWindow()) {
        waitUntilWindowStart(() => {
          if (!stopped) tick();
        });
        return;
      }

      const bodyText = document.body ? (document.body.innerText || document.body.textContent || '') : '';
      if (bodyText.includes(TARGET_TEXT)) {
        setTimeout(() => {
          if (!stopped) location.reload();
        }, 5000);
      } else {
        stopped = true; // Once we go to next tab and click, we stop this script
        goToNextTabAndClick();
      }
    };

    // Initial tick and repeated checks
    tick();
    const interval = setInterval(() => {
      if (!stopped) tick(); else clearInterval(interval);
    }, 3000);
  }

  function main() {
    if (!isPrimaryTab()) return;            // Only first tab
    if (!isMainPage()) return;              // Only main page

    if (inAllowedWindow()) {
      loopUntilCondition();
    } else {
      waitUntilWindowStart(loopUntilCondition);
    }
  }

  main();
})();

// ==UserScript==
// @name         DrTorkzadeh Automation
// @namespace    local.drtorkzadeh.automation
// @version      1.0
// @description  Automate actions on drtorkzadeh.com per requested steps
// @match        http://www.drtorkzadeh.com/
// @match        https://www.drtorkzadeh.com/
// @run-at       document-idle
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_addValueChangeListener
// @grant        GM_getTabs
// @grant        GM_saveTab

(function() {
  'use strict';

  const TARGET_TEXT = 'رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است';
  const START_HOUR = 22, START_MIN = 30; // 22:30
  const END_HOUR = 3, END_MIN = 30;      // 03:30

  // Identify this tab and enable cross-tab coordination
  const myToken = Math.random().toString(36).slice(2) + Date.now();
  GM_saveTab({ token: myToken, createdAt: Date.now() });

  let myTabId = null;
  let leaderTabId = null;
  let isLeader = false;

  // Time helpers (local time)
  function inAllowedWindow() {
    const d = new Date();
    const minutes = d.getHours() * 60 + d.getMinutes();
    const start = START_HOUR * 60 + START_MIN; // 1350
    const end = END_HOUR * 60 + END_MIN;       // 210
    return (minutes >= start) || (minutes <= end);
  }

  function msUntilNextWindowStart() {
    const now = new Date();
    const todayStart = new Date(now);
    todayStart.setHours(START_HOUR, START_MIN, 0, 0);
    if (now <= todayStart) return todayStart - now;
    const tomorrowStart = new Date(now);
    tomorrowStart.setDate(now.getDate() + 1);
    tomorrowStart.setHours(START_HOUR, START_MIN, 0, 0);
    return tomorrowStart - now;
  }

  function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

  async function waitUntilWindowOpens() {
    while (!inAllowedWindow()) {
      const ms = Math.max(1000, Math.min(30000, msUntilNextWindowStart()));
      await sleep(ms);
    }
  }

  async function electLeaderAndInit() {
    const tabs = await GM_getTabs();
    for (const [id, state] of Object.entries(tabs)) {
      if (state && state.token === myToken) {
        myTabId = id;
        break;
      }
    }

    let storedLeader = await GM_getValue('leaderTabId', null);
    if (!storedLeader || !(storedLeader in tabs)) {
      // Pick the earliest created tab as the leader
      let earliestId = null;
      let earliestAt = Infinity;
      for (const [id, state] of Object.entries(tabs)) {
        const ca = (state && state.createdAt) || Date.now();
        if (ca < earliestAt) { earliestAt = ca; earliestId = id; }
      }
      storedLeader = earliestId || myTabId;
      await GM_setValue('leaderTabId', storedLeader);
    }
    leaderTabId = storedLeader;
    isLeader = (myTabId === leaderTabId);

    // Non-leader tabs wait for a trigger to click the submit button
    GM_addValueChangeListener('triggerClick', (name, oldVal, newVal, remote) => {
      if (!remote || !newVal) return; // ignore local changes; only react to other tab
      if (newVal.targetTabId && newVal.targetTabId === myTabId) {
        clickSubmitAndStop();
      }
    });
  }

  function clickSubmitAndStop() {
    try {
      const exactSel = 'form[action="http://www.drtorkzadeh.com/"] input#submit[type="submit"]';
      let btn = document.querySelector(exactSel);
      if (!btn) {
        btn = document.querySelector('input#submit[type="submit"], #submit');
      }
      if (btn) {
        btn.click();
      }
    } catch (e) {
      // Silent fail per requirement to stop
    }
  }

  async function mainLoopLeader() {
    await waitUntilWindowOpens();

    let running = true;
    while (running) {
      // If window closed during loop, wait until it reopens
      if (!inAllowedWindow()) {
        await waitUntilWindowOpens();
      }

      const bodyText = (document.body && document.body.innerText) || '';
      if (bodyText.includes(TARGET_TEXT)) {
        await sleep(5000);
        location.reload();
        // allow page to settle before re-checking
        await sleep(1000);
        continue;
      }

      // Text not found: trigger click on the next (non-leader) tab and stop
      const tabs = await GM_getTabs();
      const otherIds = Object.keys(tabs).filter(id => id !== leaderTabId);
      if (otherIds.length > 0) {
        const secondTabId = otherIds[0];
        await GM_setValue('triggerClick', { targetTabId: secondTabId, at: Date.now() });
      }
      running = false; // stop after triggering
    }
  }

  (async function init() {
    // Ensure we are on the main page only (matches enforce this, but double-check path)
    const path = location.pathname || '/';
    if (path !== '/' && path !== '') return;

    await electLeaderAndInit();

    if (isLeader) {
      mainLoopLeader();
    } // Non-leader: remain idle until a trigger arrives
  })();
})();

