function umart_user_can_manage($user_id) {
    $cfg = umart_config();
    $user = get_user_by('id', $user_id);
    if (!$user) return false;
    foreach ($cfg['um']['access_roles'] as $role) {
        if (in_array($role, (array) $user->roles, true)) return true;
    }
    return user_can($user_id, 'edit_posts');
}

function umart_get_user_artiste_post($user_id, $include_trashed = false) {
    $args = array(
        'post_type'      => umart_config()['cpt'],
        'post_status'    => $include_trashed ? array('any','trash') : 'any',
        'author'         => $user_id,
        'posts_per_page' => 1,
        'orderby'        => 'ID',
        'order'          => 'DESC',
        'fields'         => 'all',
    );
    $q = new WP_Query($args);
    return $q->have_posts() ? $q->posts[0] : null;
}

function umart_validate_and_sanitize($data) {
    $cfg = umart_config();
    $errors = array();
    $clean  = array();

    foreach ($cfg['fields'] as $field) {
        $key = $field['key'];
        $raw = isset($data[$key]) ? $data[$key] : '';
        $raw = is_string($raw) ? wp_unslash($raw) : $raw;
        if (!empty($field['required']) && $raw === '') {
            $errors[$key] = 'required';
            continue;
        }
        if (!empty($field['sanitize_cb']) && is_callable($field['sanitize_cb'])) {
            $clean[$key] = call_user_func($field['sanitize_cb'], $raw);
        } else {
            $clean[$key] = $raw;
        }
    }
    return array($clean, $errors);
}

function umart_handle_media_upload(&$post_id) {
    $cfg = umart_config();
    $m   = $cfg['media']['featured_image'];
    if (empty($m['enabled'])) return;
    $name = $m['input'];
    if (!isset($_FILES[$name]) || empty($_FILES[$name]['name'])) return;

    $file = $_FILES[$name];
    if (!empty($file['error'])) return;

    $type = wp_check_filetype_and_ext($file['tmp_name'], $file['name']);
    if (empty($type['type']) || !in_array($type['type'], $m['allowed_mime_types'], true)) {
        return new WP_Error('file_type', umart_config()['messages']['file_type']);
    }
    $max = absint($m['max_mb']) * 1024 * 1024;
    if ($file['size'] > $max) {
        return new WP_Error('file_size', umart_config()['messages']['file_size']);
    }

    require_once ABSPATH . 'wp-admin/includes/file.php';
    require_once ABSPATH . 'wp-admin/includes/media.php';
    require_once ABSPATH . 'wp-admin/includes/image.php';

    $attach_id = media_handle_upload($name, $post_id);
    if (is_wp_error($attach_id)) {
        return new WP_Error('upload_err', umart_config()['messages']['upload_err']);
    }
    set_post_thumbnail($post_id, $attach_id);
    return true;
}

/**
 * Handle create/update/delete submission (owner only)
 */
function umart_handle_submission($user_id) {
    $cfg = umart_config();

    if ($_SERVER['REQUEST_METHOD'] !== 'POST') return;
    if (!isset($_POST[$cfg['security']['nonce_field']]) || !wp_verify_nonce($_POST[$cfg['security']['nonce_field']], $cfg['security']['nonce_action'])) return;

    if (!umart_user_can_manage($user_id)) {
        wp_die(esc_html($cfg['messages']['no_perm']));
    }

    $existing = umart_get_user_artiste_post($user_id, $cfg['one_per_user']['include_trashed']);

    if (isset($_POST['umart_delete']) && $existing) {
        if ($cfg['one_per_user']['delete_behavior'] === 'force') {
            wp_delete_post($existing->ID, true);
        } else {
            wp_trash_post($existing->ID);
        }
        wp_safe_redirect(add_query_arg('umart_msg', 'deleted'));
        exit;
    }

    list($clean, $errors) = umart_validate_and_sanitize($_POST);
    if (!empty($errors)) {
        add_filter('umart_flash_error', function() use ($cfg) { return $cfg['messages']['invalid']; });
        return;
    }

    $postarr = array(
        'post_type'   => $cfg['cpt'],
        'post_title'  => isset($clean['post_title']) ? $clean['post_title'] : '',
        'post_status' => $existing ? $cfg['status']['update'] : $cfg['status']['create'],
        'post_author' => $user_id,
    );

    if ($existing) {
        $postarr['ID'] = $existing->ID;
        $post_id = wp_update_post($postarr, true);
    } else {
        if ($cfg['one_per_user']['enforce'] && $cfg['one_per_user']['on_second_attempt'] === 'error' && $existing) {
            add_filter('umart_flash_error', function() use ($cfg) { return $cfg['messages']['one_only']; });
            return;
        }
        $post_id = wp_insert_post($postarr, true);
    }

    if (is_wp_error($post_id)) {
        add_filter('umart_flash_error', function() { return 'Unable to save post.'; });
        return;
    }

    // Save Meta Box fields
    foreach ($cfg['fields'] as $field) {
        if ($field['key'] === 'post_title') continue;
        if (isset($clean[$field['key']])) {
            update_post_meta($post_id, $field['key'], $clean[$field['key']]);
        }
    }

    // Handle featured image
    $media_result = umart_handle_media_upload($post_id);
    if (is_wp_error($media_result)) {
        add_filter('umart_flash_error', function() use ($media_result) { return $media_result->get_error_message(); });
    }

    $msg = $existing ? 'updated' : 'created';
    wp_safe_redirect(add_query_arg('umart_msg', $msg));
    exit;
}

