function umart_render_tab() {
    if (!function_exists('um_profile_id')) {
        echo '<p>Ultimate Member not detected.</p>';
        return;
    }

    $cfg = umart_config();
    $profile_user_id = (int) um_profile_id();
    $current_user_id = (int) get_current_user_id();
    $is_owner = ($current_user_id && $current_user_id === $profile_user_id);

    if ($is_owner) {
        umart_handle_submission($profile_user_id);
    }

    $post = umart_get_user_artiste_post($profile_user_id, $cfg['one_per_user']['include_trashed']);

    // Flash message
    if (!empty($_GET['umart_msg'])) {
        $msg_key = sanitize_key($_GET['umart_msg']);
        if (!empty($cfg['messages'][$msg_key])) {
            echo '<div class="um-message success">' . esc_html($cfg['messages'][$msg_key]) . '</div>';
        }
    }
    if (has_filter('umart_flash_error')) {
        $err = apply_filters('umart_flash_error', '');
        if ($err) echo '<div class="um-message error">' . esc_html($err) . '</div>';
        remove_all_filters('umart_flash_error');
    }

    if ($is_owner && umart_user_can_manage($profile_user_id)) {
        umart_render_edit_ui($post, $cfg);
    } else {
        umart_render_readonly_ui($post, $cfg);
    }
}

function umart_render_edit_ui($post, $cfg) {
    $editing = !empty($post) && $post instanceof WP_Post && $post->post_status !== 'trash';
    if (!$editing && $cfg['one_per_user']['enforce'] && umart_get_user_artiste_post(get_current_user_id(), true) && $cfg['one_per_user']['on_second_attempt'] === 'edit') {
        $editing = true; // force edit of existing if enforcing one per user
    }

    echo '<div class="um-artiste-wrap">';

    if (!$editing) {
        echo '<h3>' . esc_html($cfg['messages']['not_found']) . '</h3>';
    }

    echo '<form method="post" enctype="multipart/form-data">';
    wp_nonce_field($cfg['security']['nonce_action'], $cfg['security']['nonce_field']);

    $values = array(
        'post_title' => $editing ? $post->post_title : '',
    );
    foreach ($cfg['fields'] as $field) {
        if ($field['key'] === 'post_title') continue; // handled below for layout control
        $values[$field['key']] = $editing ? get_post_meta($post->ID, $field['key'], true) : '';
    }

    // Title
    echo '<p><label>' . esc_html__('Title', 'umart') . '<br />';
    echo '<input type="text" name="post_title" value="' . esc_attr($values['post_title']) . '" required />';
    echo '</label></p>';

    // Meta Box fields (manual form inputs mapping to saved post meta)
    foreach ($cfg['fields'] as $field) {
        if ($field['key'] === 'post_title') continue;
        $key   = esc_attr($field['key']);
        $label = esc_html($field['label']);
        $val   = isset($values[$field['key']]) ? $values[$field['key']] : '';
        $req   = !empty($field['required']) ? 'required' : '';

        echo '<p><label>' . $label . '<br />';
        switch ($field['type']) {
            case 'textarea':
                echo '<textarea name="' . $key . '" rows="5" ' . $req . '>' . esc_textarea($val) . '</textarea>';
                break;
            case 'url':
                echo '<input type="url" name="' . $key . '" value="' . esc_attr($val) . '" ' . $req . ' />';
                break;
            default:
                echo '<input type="text" name="' . $key . '" value="' . esc_attr($val) . '" ' . $req . ' />';
        }
        echo '</label></p>';
    }

    // Featured image upload
    if (!empty($cfg['media']['featured_image']['enabled'])) {
        echo '<p><label>' . esc_html__('Featured image', 'umart') . '<br />';
        echo '<input type="file" name="' . esc_attr($cfg['media']['featured_image']['input']) . '" accept="image/*" />';
        echo '</label></p>';
        if ($editing && has_post_thumbnail($post)) {
            echo get_the_post_thumbnail($post, 'thumbnail');
        }
    }

    echo '<p>';
    echo '<button type="submit" class="um-button">' . esc_html($editing ? $cfg['messages']['updated'] : $cfg['messages']['created']) . '</button>';
    if ($editing) {
        echo ' <button type="submit" name="umart_delete" value="1" class="um-button um-button-danger" onclick="return confirm(\'Delete this Artiste?\');">' . esc_html($cfg['messages']['deleted']) . '</button>';
    }
    echo '</p>';

    echo '</form>';
    echo '</div>';
}

function umart_render_readonly_ui($post, $cfg) {
    echo '<div class="um-artiste-view">';
    if (!$post || $post->post_status === 'trash') {
        echo '<p>' . esc_html($cfg['messages']['not_found']) . '</p>';
        echo '</div>';
        return;
    }

    echo '<h3>' . esc_html(get_the_title($post)) . '</h3>';
    if (has_post_thumbnail($post)) {
        echo get_the_post_thumbnail($post, 'medium');
    }

    echo '<ul class="um-artiste-fields">';
    foreach ($cfg['fields'] as $field) {
        if ($field['key'] === 'post_title') continue;
        $val = get_post_meta($post->ID, $field['key'], true);
        if ($val === '' || $val === null) continue;
        $label = esc_html($field['label']);
        if ($field['type'] === 'url') {
            $val = '<a href="' . esc_url($val) . '" target="_blank" rel="nofollow noopener">' . esc_html($val) . '</a>';
        } else {
            $val = esc_html($val);
        }
        echo '<li><strong>' . $label . ':</strong> ' . $val . '</li>';
    }
    echo '</ul>';

    echo '</div>';
}
