function run_panel_method()
% RUN_PANEL_METHOD
% Main script for 2-D constant-strength source panel method (external flow).
% - Reads boundary points from a user-specified text file: two columns [x y],
%   counterclockwise, including both surfaces (close to a closed loop).
% - Prompts for U_inf (m/s), alpha (deg), rho (kg/m^3)
% - Allows multiple panel counts (e.g., [40 80 160]) by subsampling input points
% - Builds geometry, solves source strengths with zero-normal-velocity BC
% - Computes tangential velocities, Cp, and integrated Cl via Kutta–Joukowski
% - Compares with references when applicable (circle, NACAxxxx thin airfoil theory)
% - Reports convergence metrics and saves Cp distributions to CSV files
% - Robust error handling: input file issues, orientation, duplicates, degeneracy
%
% No plots are produced by default. Outputs printed to console; Cp saved to CSV.

clc;

fprintf('2-D Constant-Strength Source Panel Method (External Flow)\n');
fprintf('=========================================================\n');

% --- Get inputs from user
filename = input('Enter path to boundary points file (two columns x y): ', 's');
if isempty(filename)
    error('No file specified.');
end
U_inf = getScalarInput('Enter free-stream speed U_inf (m/s): ', 0, Inf);
alpha_deg = getScalarInput('Enter angle of attack alpha (deg): ', -180, 180);
rho = getScalarInput('Enter fluid density rho (kg/m^3): ', 0, Inf);

panel_counts_str = input('Enter panel counts as MATLAB vector (e.g., [40 80 160]): ', 's');
if isempty(panel_counts_str)
    error('No panel counts specified.');
end
try
    panel_counts = eval(panel_counts_str); %#ok<EVLDIR>
catch
    error('Invalid panel counts input.');
end
if ~isvector(panel_counts) || any(~isfinite(panel_counts)) || any(panel_counts<=2)
    error('Panel counts must be a vector of integers > 2.');
end
panel_counts = unique(round(panel_counts(:)'));

% --- Read and sanitize points
[Xraw, Yraw, meta] = readPanelPoints(filename);

% Detect and correct non-CCW, remove duplicates, ensure closed loop
[Xccw, Yccw, infoGeom] = buildGeometry(Xraw, Yraw);

% --- Detect special shapes for reference comparisons
circRef = circleDetection(Xccw, Yccw);
nacaRef = nacaClReference(filename, Xccw, Yccw);

fprintf('\nGeometry info:\n');
fprintf(' - Points read (raw): %d\n', numel(Xraw));
fprintf(' - Points after cleaning: %d\n', numel(Xccw));
fprintf(' - Oriented CCW: %s\n', ternary(infoGeom.ccw, 'yes', 'fixed'));
fprintf(' - Removed duplicates: %d\n', infoGeom.removedDuplicates);
fprintf(' - Closed first-last coincidence: %s\n', ternary(infoGeom.closed, 'yes', 'fixed to closed'));
if circRef.isCircle
    fprintf(' - Detected circle: center=(%.6g, %.6g), R=%.6g, tol=%.2e\n', circRef.cx, circRef.cy, circRef.R, circRef.rmseR);
end
if nacaRef.isNACA
    fprintf(' - Detected NACA filename: %s, unit chord: %s\n', nacaRef.NACAname, ternary(nacaRef.unitChord, 'yes', 'no'));
end

% --- Flow params
alpha = deg2rad(alpha_deg);
Vinf = U_inf;
q_inf = 0.5*rho*Vinf^2;

% --- Loop over panel counts
results = struct([]);
prevCp = [];
prevNp = [];
fprintf('\nRunning panel method for panel counts: %s\n', mat2str(panel_counts));

for k = 1:numel(panel_counts)
    Np = panel_counts(k);

    % Subsample points to get target panel count
    [x, y] = subsampleClosedCurve(Xccw, Yccw, Np);

    % Build panels and geometry details
    geom = panelize(x, y); % contains x, y, xc, yc, S, beta, nx, ny, tx, ty, N

    % Influence matrix and RHS
    A = influenceMatrix(geom);
    RHS = -Vinf * (cos(alpha)*geom.nx + sin(alpha)*geom.ny); % zero-normal-velocity BC

    % Solve for source strengths sigma
    sigma = solveSourceStrengths(A, RHS);

    % Compute tangential velocities and Cp at control points
    [Vt, Cp] = velocitiesAndCp(geom, sigma, Vinf, alpha);

    % Compute circulation and lift coefficient via Kutta–Joukowski
    [Gamma, Lprime, Cl] = integrateForces(geom, Vt, rho, Vinf);

    % Save Cp distribution to CSV
    outCSV = sprintf('Cp_N%d.csv', Np);
    writeCpCSV(outCSV, geom, Cp, Vt);
    fprintf('Saved Cp and Vt to %s\n', outCSV);

    % Reference comparisons
    ref = struct('hasCpRef', false, 'hasClRef', false);
    if circRef.isCircle
        % Analytical potential flow around cylinder with circulation from alpha
        % Classical potential flow without circulation has Cl=0; with effective AoA to uniform flow,
        % tangential velocity at angle theta: Vtheta = 2*Vinf*sin(theta - alpha)
        % Cp(theta) = 1 - [Vtheta/Vinf]^2 = 1 - 4*sin^2(theta - alpha)
        % Cl (per span) from ideal cylinder with superposed circulation = 2*pi*rho*Vinf*Gamma? For cylinder,
        % thin-airfoil-like 2*pi*alpha does not strictly apply; we compare Cp only, and Cl should be ~0 if no vortex.
        [Cp_ref, theta_nodes] = cylinderCpReference(geom, circRef, Vinf, alpha);
        if ~isempty(Cp_ref)
            ref.hasCpRef = true;
            Cp_rmse = sqrt(mean((Cp - Cp_ref).^2));
            fprintf('Reference (circle) Cp RMSE (N=%d): %.4e\n', Np, Cp_rmse);
        end
        % Circulation-free cylinder should yield Cl ~ 0
        ref.hasClRef = true;
        Cl_ref = 0.0;
        Cl_err_pct = percentError(Cl, Cl_ref);
        fprintf('Reference (circle) Cl: computed=%.6g, ref=%.6g, error=%.3f%%\n', Cl, Cl_ref, Cl_err_pct);
    elseif nacaRef.isNACA && nacaRef.unitChord
        % Thin airfoil theory: Cl = 2*pi*alpha (rad)
        ref.hasClRef = true;
        Cl_ref = 2*pi*alpha;
        Cl_err_pct = percentError(Cl, Cl_ref);
        fprintf('Reference (NACA TAT) Cl: computed=%.6g, ref=%.6g, error=%.3f%%\n', Cl, Cl_ref, Cl_err_pct);
    end

    % Convergence vs previous
    conv = struct('dCl', NaN, 'Cp_rmse', NaN);
    if ~isempty(prevCp) && ~isempty(prevNp)
        % Compare by interpolating Cp along arc-length to common resolution
        conv.Cp_rmse = cpRMSEBetween(geom, Cp, prevGeom, prevCp);
        conv.dCl = abs(Cl - prevCl);
    end

    % Print summary for this N
    fprintf('N=%d: Cl=%.6g, Gamma=%.6g, L''=%.6g N/m\n', Np, Cl, Gamma, Lprime);
    if ~isnan(conv.dCl)
        fprintf('    Convergence vs N=%d: |ΔCl|=%.4e, Cp RMSE=%.4e\n', prevNp, conv.dCl, conv.Cp_rmse);
    end

    % Store results
    res = struct();
    res.N = Np;
    res.geom = geom;
    res.sigma = sigma;
    res.Vt = Vt;
    res.Cp = Cp;
    res.Gamma = Gamma;
    res.Cl = Cl;
    res.Lprime = Lprime;
    res.ref = ref;
    if exist('Cp_ref','var'); res.Cp_ref = Cp_ref; else; res.Cp_ref = []; end

    results = [results; res]; %#ok<AGROW>

    % Update previous for convergence metrics
    prevCp = Cp;
    prevGeom = geom;
    prevCl = Cl;
    prevNp = Np;

    clear Cp_ref theta_nodes
end

% Global convergence table
fprintf('\nConvergence summary:\n');
fprintf(' N        Cl           |ΔCl| vs prev    Cp RMSE vs prev\n');
fprintf('--------------------------------------------------------\n');
for k = 1:numel(results)
    if k==1
        fprintf('%-8d %-12.6g %-16s %-12s\n', results(k).N, results(k).Cl, '---', '---');
    else
        dCl = abs(results(k).Cl - results(k-1).Cl);
        rmseCp = cpRMSEBetween(results(k).geom, results(k).Cp, results(k-1).geom, results(k-1).Cp);
        fprintf('%-8d %-12.6g %-16.4e %-12.4e\n', results(k).N, results(k).Cl, dCl, rmseCp);
    end
end

fprintf('\nDone.\n');

end

