function val = getScalarInput(prompt, lb, ub)
while true
    s = input(prompt, 's');
    if isempty(s), error('Input cancelled.'); end
    v = str2double(s);
    if ~isfinite(v)
        fprintf('Invalid number. Try again.\n');
        continue;
    end
    if v<=lb || v>=ub
        % allow equality at 0 for density and speed? Use <= lb or < lb as needed
        if lb==0
            if v<lb || v>=ub
                fprintf('Value must satisfy %g <= value < %g.\n', lb, ub);
                continue;
            end
        else
            fprintf('Value must satisfy %g < value < %g.\n', lb, ub);
            continue;
        end
    end
    val = v;
    return;
end
end

function s = ternary(cond, a, b)
if cond, s = a; else, s = b; end
end

function writeCpCSV(fname, geom, Cp, Vt)
