function [X, Y, meta] = readPanelPoints(filename)
% READPANELPOINTS Read two-column x y points from text file.
% - Ignores empty lines and comments starting with % or #
% - Returns column vectors X, Y
% - Robust to extra whitespace, commas, tabs
% - Throws errors for ill-formed input

meta = struct();
if ~exist(filename, 'file')
    error('File not found: %s', filename);
end
fid = fopen(filename, 'r');
if fid<0, error('Could not open file: %s', filename); end

X = [];
Y = [];
ln = 0;
while true
    tline = fgetl(fid);
    if ~ischar(tline), break; end
    ln = ln + 1;
    s = strtrim(tline);
    if isempty(s), continue; end
    if startsWith(s, '%') || startsWith(s, '#'), continue; end
    % Replace commas with spaces
    s = strrep(s, ',', ' ');
    parts = strsplit(s);
    if numel(parts) < 2
        fclose(fid);
        error('Line %d: expected two columns.', ln);
    end
    xi = str2double(parts{1});
    yi = str2double(parts{2});
    if ~isfinite(xi) || ~isfinite(yi)
