function [Xccw, Yccw, info] = buildGeometry(X, Y)
% BUILDGEOMETRY
% - Removes duplicate consecutive points and exact duplicates
% - Closes the loop if first and last points are not equal
% - Ensures counterclockwise order; reverses if necessary
% - Checks for degenerate panels (zero length) and removes them

info = struct('removedDuplicates',0,'ccw',true,'closed',true);

% Remove NaNs
mask = isfinite(X) & isfinite(Y);
X = X(mask); Y = Y(mask);

% Remove duplicate consecutive points
d = hypot(diff(X), diff(Y));
keep = [true; d>0];
X = X(keep); Y = Y(keep);

% Remove global duplicates by unique on rows, preserving order
[~, ia] = unique([X Y], 'rows', 'stable');
if numel(ia) < numel(X)
    info.removedDuplicates = numel(X)-numel(ia);
    X = X(ia); Y = Y(ia);
end

% Ensure closed loop: if last differs from first, append first
if hypot(X(end)-X(1), Y(end)-Y(1)) > 1e-12
    X(end+1) = X(1);
    Y(end+1) = Y(1);
    info.closed = false;
end

% Compute signed area to determine orientation
area2 = 0.5*sum( X(1:end-1).*Y(2:end) - X(2:end).*Y(1:end-1) );
if area2 < 0
    % Clockwise; reverse to make CCW
    info.ccw = false;
    X = flipud(X);
    Y = flipud(Y);
end

% Remove degenerate panels (zero length)
d = hypot(diff(X), diff(Y));
deg = find(d < 1e-14);
if ~isempty(deg)
    mask = true(size(X));
    mask(deg+1) = false; % remove second point of degenerate panel
    X = X(mask); Y = Y(mask);
    % Ensure still closed
    if hypot(X(end)-X(1), Y(end)-Y(1)) > 1e-12
        X(end+1)=X(1); Y(end+1)=Y(1);
    end
end

% Final sanity
if numel(X) < 4
    error('Too few unique points after cleaning.');
end

Xccw = X(:);
Yccw = Y(:);

end


