function [xSub, ySub] = subsampleClosedCurve(X, Y, N)
% SUBSAMPLECLOSEDCURVE Subsample a closed polyline to N panels (N points including closure).
% Uses arc-length parametrization and uniform spacing by cumulative length.

% Ensure closed
if hypot(X(end)-X(1), Y(end)-Y(1)) > 1e-12
    X = [X; X(1)]; Y = [Y; Y(1)];
end
% Cumulative length along edges
dx = diff(X); dy = diff(Y);
segL = hypot(dx, dy);
s = [0; cumsum(segL)];
Ltot = s(end);
if Ltot <= 0
    error('Total length zero.');
end

% Target N panels => N points with closure (repeat first at end)
% We will generate N points with s from 0 to Ltot*(N-1)/N, then append s=0 as last point
% More simply: N points on [0, Ltot), then repeat first to close
sTarget = linspace(0, Ltot, N+1).';
sTarget = sTarget(1:end-1);

% Interpolate positions along the polyline (periodic)
xSub = interp1(s, X, mod(sTarget, Ltot), 'linear');
ySub = interp1(s, Y, mod(sTarget, Ltot), 'linear');

% Append first to close
xSub(end+1) = xSub(1);
ySub(end+1) = ySub(1);
end


