function geom = panelize(x, y)
% PANELIZE Build panel geometry from closed polygon points.
% Returns struct with:
%  x, y: nodal points (size N+1, closed)
%  xc, yc: control points (midpoints)
%  S: panel lengths
%  beta: panel angle wrt x-axis (atan2 of dy, dx)
%  nx, ny: outward normal unit vector (assuming CCW boundary)
%  tx, ty: unit tangents
%  N: number of panels

if hypot(x(end)-x(1), y(end)-y(1)) > 1e-10
    error('Input to panelize must be closed (last point = first).');
end

N = numel(x)-1;
dx = x(2:end) - x(1:end-1);
dy = y(2:end) - y(1:end-1);
S = hypot(dx, dy);
if any(S < 1e-14)
    error('Degenerate panel(s) found during panelize.');
end
tx = dx ./ S;
ty = dy ./ S;
% Outward normal for CCW polygon: rotate tangent by +90 deg => (-ty, tx) is inward for CCW?
% For a CCW boundary with exterior to the left, outward normal is (-ty, tx) pointing outside the body?
% Actually for CCW traversing boundary with body on left, outward is (ty, -tx). We want outward (away from body).
% For a CCW loop enclosing interior on left, outward normal is (tx, ty) rotated -90: (ty, -tx)
nx =  ty;
ny = -tx;

xc = 0.5*(x(1:end-1) + x(2:end));
yc = 0.5*(y(1:end-1) + y(2:end));
beta = atan2(dy, dx);

geom = struct('x',x(:),'y',y(:),'xc',xc(:),'yc',yc(:),'S',S(:), ...
    'beta',beta(:),'nx',nx(:),'ny',ny(:),'tx',tx(:),'ty',ty(:),'N',N);
end


