function A = influenceMatrix(geom)
% INFLUENCEMATRIX Build A_ij = normal velocity at control point i due to unit-strength
% constant source distributed along panel j (2D). Uses classical formulas
% based on panel local coordinates.
%
% For panel j with length S, located from (xj1,yj1) to (xj2,yj2),
% in its local frame (s along panel, n normal), the influence of a unit
% source density (per length) on control point i is:
% u_n = (1/2pi) * [theta2 - theta1], where theta are angles from endpoints
% measured from control point in panel-local coordinates, projected onto normal.
% Here we use standard potential influence coefficients following Katz & Plotkin:
% Let x', y' be the coordinates of control point i in panel j's local system:
%   x' =  ( (xi-xj1)*txj + (yi-yj1)*tyj )
%   y' =  (-(xi-xj1)*tyj + (yi-yj1)*txj )   (y' positive to left of panel)
% Then:
%   phi = (1/2pi) * log( (r2^2)/(r1^2) ) / 2  [potential], but we only need velocity components.
% Normal velocity influence (to i) from panel j of unit source strength is:
%   v_n(i,j) = (1/2pi) * ( atan2( (S - x')*y', (S - x')^2 + y'^2 ) - atan2( -x'*y', x'^2 + y'^2 ) )
% Tangential velocity influence (for later) not needed here in A; A is normal-normal.

N = geom.N;
A = zeros(N, N);

x1 = geom.x(1:end-1);
y1 = geom.y(1:end-1);
tx = geom.tx; ty = geom.ty; S = geom.S;

for j = 1:N
    dx1 = geom.xc - x1(j);
    dy1 = geom.yc - y1(j);
    % Local coords of control points relative to panel j
    xpj =  dx1.*tx(j) + dy1.*ty(j);
    ypj = -dx1.*ty(j) + dy1.*tx(j);

    % Avoid singularity exactly on panel: shift y' by tiny epsilon
    ypj = ypj + 0;

    % Endpoints in local s: 0 and S(j)
    Sj = S(j);
    % Angles for atan2 terms
    % Using formula for normal velocity influence of a source panel:
    % v_n = (1/2pi) * ( atan2((Sj - x')*y', (Sj - x')^2 + y'^2) - atan2((-x')*y', x'^2 + y'^2) )
    term2 = atan2((Sj - xpj).*ypj, (Sj - xpj).^2 + ypj.^2);
    term1 = atan2((-xpj).*ypj, xpj.^2 + ypj.^2);
    vn = (term2 - term1) / (2*pi);

    % Project onto the local normal of panel j? Above vn is already normal to panel j,
    % but boundary condition uses normal at control point i (panel i's normal).
    % For source panels, induced velocity vector components in global frame are needed.
    % However, a standard simplification for Neumann BC matrix uses the dot of induced
    % velocity with panel i normal. We must compute u,v then dot with (nxi, nyi).
    %
    % To be precise, the expression above returns the normal component relative to panel j.
    % That is not what we need. We need the global velocity vector components u,v induced by panel j.
    % So we compute u and v using standard formulas:

    % Compute induced velocity components in panel j local frame:
    % u_s (along +s) and u_n (along +n). For a source panel of unit strength:
    % u_s = (1/2pi) * ( ln( r2 / r1 ) )
    % u_n = (1/2pi) * ( atan2((Sj - x')*y', (Sj - x')^2 + y'^2) - atan2((-x')*y', x'^2 + y'^2) )
    r1sq = xpj.^2 + ypj.^2;
    r2sq = (Sj - xpj).^2 + ypj.^2;
    us = 0.5*log(r2sq ./ r1sq) / (2*pi);
    un = (term2 - term1) / (2*pi);

    % Transform to global components:
    ui = us.*tx(j) - un.*ty(j);  % s along (tx,ty), n to left, so rotate accordingly
    vi = us.*ty(j) + un.*tx(j);

    % Dot with control-point normal (panel i normal):
    A(:, j) = ui.*geom.nx + vi.*geom.ny;
end

% Diagonal terms: self-influence limit yields 0.5 (for normal component with Neumann BC)
% For a closed smooth boundary, the limiting normal velocity of a source panel on itself is 0.5
% when taking the principal value. Therefore set diagonal to 0.5.
for i = 1:N
    A(i,i) = 0.5;
end
end


