function [Vt, Cp] = velocitiesAndCp(geom, sigma, Vinf, alpha)
% VELOCITIESANDCP Compute tangential velocity and Cp at control points on surface.
% Superpose freestream velocity and induced velocity from all source panels.
% Then project onto local tangent to get Vt, and Cp = 1 - (Vt/Vinf)^2 (in incompressible, irrotational, inviscid flow).

N = geom.N;
x1 = geom.x(1:end-1);
y1 = geom.y(1:end-1);
tx = geom.tx; ty = geom.ty; S = geom.S;

% Induced velocities from source panels
u = zeros(N,1);
v = zeros(N,1);

for j = 1:N
    dx1 = geom.xc - x1(j);
    dy1 = geom.yc - y1(j);
    xpj =  dx1.*tx(j) + dy1.*ty(j);
    ypj = -dx1.*ty(j) + dy1.*tx(j);
    Sj = S(j);

    r1sq = xpj.^2 + ypj.^2;
    r2sq = (Sj - xpj).^2 + ypj.^2;

    % Avoid log(0) by small epsilon in self terms; handled by principal value below
    % Panel-induced velocity components in panel-local frame for unit strength:
    us = 0.5*log(r2sq ./ r1sq) / (2*pi);
    term2 = atan2((Sj - xpj).*ypj, (Sj - xpj).^2 + ypj.^2);
    term1 = atan2((-xpj).*ypj, xpj.^2 + ypj.^2);
    un = (term2 - term1) / (2*pi);

    % Transform to global
    ui = us.*tx(j) - un.*ty(j);
    vi = us.*ty(j) + un.*tx(j);

    u = u + sigma(j)*ui;
    v = v + sigma(j)*vi;
end

% Add freestream
u = u + Vinf*cos(alpha);
v = v + Vinf*sin(alpha);

% Tangential velocity
Vt = u.*geom.tx + v.*geom.ty;

% Pressure coefficient
Cp = 1 - (Vt./Vinf).^2;

end


