function [Gamma, Lprime, Cl] = integrateForces(geom, Vt, rho, Vinf)
% INTEGRATEFORCES Compute circulation and lift coefficient via Kutta–Joukowski.
% Circulation Gamma is integral of tangential velocity along the body, with sign
% following right-hand rule for outward normal. For CCW boundary and outward normal
% defined in panelize, the integral of Vt along the contour gives Gamma (positive CCW).
%
% Lift per unit span L' = rho * Vinf * Gamma
% Lift coefficient Cl = L' / (0.5 * rho * Vinf^2 * c), where c is reference chord.
% We take c = xmax - xmin of the input geometry.

Gamma = sum(Vt .* geom.S);
Lprime = rho * Vinf * Gamma;
c_ref = max(geom.x) - min(geom.x);
if c_ref <= 0
    c_ref = 1; % fallback
end
Cl = Lprime / (0.5 * rho * Vinf^2 * c_ref);

end


