function circ = circleDetection(X, Y)
% CIRCLEDETECTION Detect if points lie on a common circle within tolerance.
% Returns circ.isCircle, center (cx,cy), radius R, and rmse on radius.

% Fit circle by linear least squares (Kasa method)
x = X(:); y = Y(:);
% Remove final duplicate if closed
if hypot(x(end)-x(1), y(end)-y(1)) < 1e-12
    x = x(1:end-1); y = y(1:end-1);
end
A = [x y ones(size(x))];
b = -(x.^2 + y.^2);
sol = A \ b;
% Circle: x^2 + y^2 + Dx + Ey + F = 0 -> center (-D/2, -E/2), R^2 = (D^2+E^2)/4 - F
D = sol(1); E = sol(2); F = sol(3);
cx = -D/2; cy = -E/2;
R2 = (D^2 + E^2)/4 - F;
if R2 <= 0
    circ = struct('isCircle',false,'cx',NaN,'cy',NaN,'R',NaN,'rmseR',Inf);
    return;
end
R = sqrt(R2);
r = hypot(x - cx, y - cy);
rmse = sqrt(mean((r - R).^2));

% Tolerance relative to radius
tol = 1e-3 * max(1, R);
isCircle = rmse < tol;

circ = struct('isCircle',isCircle,'cx',cx,'cy',cy,'R',R,'rmseR',rmse);

end


