function rmse = cpRMSEBetween(geomA, CpA, geomB, CpB)
% CPRMSEBETWEEN Compute RMSE of Cp between two discretizations by arc-length mapping.
% Both are closed contours assumed to be similar shapes.

% Arc-length for each
sA = [0; cumsum(geomA.S)];
sA = sA / sA(end);
sB = [0; cumsum(geomB.S)];
sB = sB / sB(end);

% Use control points at mid-panels; define their cumulative positions
