function source_panel_2D_main
% SOURCE_PANEL_2D_MAIN
% Complete, runnable MATLAB implementation of a 2‑D source panel method for
% incompressible, irrotational, inviscid flow around a closed contour.
%
% Features:
% - Reads ordered boundary points (x y) from a user-specified text file.
% - Prompts user for U_inf (m/s), alpha (deg), rho (kg/m^3), and whether to
%   include a constant-strength vortex with Kutta condition.
% - Source-only panel method; optional single vortex to satisfy Kutta and predict lift.
% - Computes surface tangential velocity, Cp, writes Cp vs x to CSV, and plots Cp.
% - Computes lift coefficient Cl via Kutta–Joukowski and via surface pressure integration.
% - Built-in comparisons:
%   * Circle: compares Cp with/without circulation to analytic solution; reports max/mean error.
%   * NACA 4-digit: compares Cl with thin-airfoil theory (Cl = 2π·alpha in radians).
% - Convergence assessment by re-paneling internally N=[40 80 160]; reports Cp and Cl convergence.
% - Single script with local helper functions; closes non-closed contours with a warning.
%
% Usage: Run the script, follow prompts. Ensure your point file is ordered along
% the contour (counter-clockwise preferred). Each line: "x y".
%
% Notes:
% - Coordinates are expected in meters (or consistent units).
% - For airfoils, ensure the points start and end at the trailing edge and proceed
%   around the surface without crossing.

    clc; fprintf('2‑D Source Panel Method with optional Kutta vortex\n');

    % -------------------- Input: file path --------------------
    file_ok = false;
    while ~file_ok
        fpath = input('Enter path to text file with ordered (x y) points: ','s');
        try
            pts = read_point_file(fpath);
            file_ok = true;
        catch ME
            fprintf(2,'Error: %s\n', ME.message);
            resp = input('Try again? (y/n): ','s');
            if isempty(resp) || lower(resp(1))~='y'
                return;
            end
        end
    end

    % Detect characteristics from filename/content
    [~, fname, ~] = fileparts(fpath);
    isNACA = ~isempty(regexp(lower(fname),'^naca\d{4}_?\d*pts?','once')) || ~isempty(regexp(lower(fname),'^naca\d{4}','once'));
    isCircle, circleInfo = detect_circle(pts); %#ok<ASGLU>

    % -------------------- Input: freestream & options --------------------
    U_inf = ask_positive_scalar('Freestream speed U_inf (m/s): ');
    alpha_deg = ask_scalar('Angle of attack alpha (degrees): ');
    rho = ask_positive_scalar('Fluid density rho (kg/m^3): ');

    default_vortex = isNACA || ~isCircle; % default enable Kutta vortex for airfoils/non-circles
    useVortex = ask_boolean(sprintf('Enable Kutta vortex (recommended for airfoils) [default %s] (y/n): ', ternary(default_vortex,'y','n')), default_vortex);

    % -------------------- Preprocess contour --------------------
    [x, y] = preprocess_contour(pts); % ensure closed, CCW if possible
    if ~is_closed([x y])
        warning('Input contour not closed. Auto-closing by connecting last to first point.');
        x = [x; x(1)]; y = [y; y(1)];
    end

    % Orient CCW for positive interior (affects normals)
    if polygon_signed_area(x,y) < 0
        warning('Contour appears clockwise. Reversing point order to CCW.');
        x = flipud(x); y = flipud(y);
    end

    % Normalize to uniform chord estimate for reporting (spanwise depth = 1)
    % Chord estimated as (max x - min x). Avoid zero.
    chord = max(x)-min(x);
    if chord <= 0
        chord = max(hypot(diff(x),diff(y))); % fallback
    end

    % -------------------- Solve at original resolution --------------------
    alpha = deg2rad(alpha_deg);
    freestream = struct('U',U_inf,'alpha',alpha,'rho',rho);

    % Build panels
    panels = build_panels(x,y);

    % Solve source strengths (and vortex if enabled)
    solv = solve_source_panel(panels, freestream, useVortex, true); % use Kutta when vortex on

    % Postprocess velocities, Cp, lift
    res = postprocess(panels, solv, freestream);

    % Output Cp CSV
    outcsv = sprintf('%s_Cp.csv', fname);
    writematrix([res.ctrl_x, res.Cp], outcsv);
    fprintf('Wrote Cp to %s (columns: x, Cp)\n', outcsv);

    % Plot Cp vs x
    figure('Name','Cp vs x');
    plot(res.ctrl_x, res.Cp, 'o-'); set(gca,'YDir','reverse');
    xlabel('x'); ylabel('Cp'); title('Surface Cp'); grid on;

    % Report lift coefficients
    fprintf('\nLift results (reference chord c = %.4g, unit span):\n', chord);
    fprintf(' - Cl (from Kutta–Joukowski via vortex) = %.6f\n', res.Cl_gamma);
    fprintf(' - Cl (from surface pressure integration) = %.6f\n', res.Cl_pressure);

    % -------------------- Built-in comparisons --------------------
    if isCircle
        compare_circle(panels, solv, freestream);
    end
    if isNACA
        compare_thin_airfoil(alpha, res.Cl_pressure);
    end

    % -------------------- Convergence study via re-paneling --------------------
    fprintf('\nGrid convergence study (re-paneling via linear interpolation):\n');
    Nlist = [40 80 160];
    conv_tbl = zeros(numel(Nlist),5); % N, max|dCp| vs prev, Cl_gamma, Cl_press, L2(Cp)
    prev_Cp = [];
    for k = 1:numel(Nlist)
        Npan = Nlist(k);
        [xi, yi] = repanel_linear(x, y, Npan+1);
        pan_k = build_panels(xi, yi);
        solv_k = solve_source_panel(pan_k, freestream, useVortex, true);
        res_k = postprocess(pan_k, solv_k, freestream);

        if isempty(prev_Cp)
            dCp_max = NaN; L2 = NaN;
        else
            % interpolate previous Cp to new control x for a rough comparison
            Cp_prev_interp = interp1(prev_x, prev_Cp, res_k.ctrl_x, 'linear', 'extrap');
            dCp = res_k.Cp - Cp_prev_interp;
            dCp_max = max(abs(dCp));
            L2 = sqrt(mean(dCp.^2));
        end

        conv_tbl(k,:) = [Npan, dCp_max, res_k.Cl_gamma, res_k.Cl_pressure, L2];
        fprintf(' N=%4d: max|ΔCp|=%-10.3e  Cl_gamma=%-10.6f  Cl_press=%-10.6f  L2(ΔCp)=%-10.3e\n', ...
            Npan, dCp_max, res_k.Cl_gamma, res_k.Cl_pressure, L2);
        prev_Cp = res_k.Cp; prev_x = res_k.ctrl_x; %#ok<NASGU>
    end

    disp('Done.');

% ---------------------------- Local functions ----------------------------

function pts = read_point_file(fpath)
    if ~ischar(fpath) && ~isstring(fpath)
        error('File path must be a string.');
    end
    if ~exist(fpath,'file')
        error('File not found: %s', fpath);
    end
    data = readmatrix(fpath);
    if ~ismatrix(data) || size(data,2) < 2
        error('File must contain at least two columns: x y per line.');
    end
    pts = data(:,1:2);
    if any(any(~isfinite(pts)))
        error('File contains NaN or Inf values.');
    end
    if size(pts,1) < 3
        error('At least 3 points are required to define a closed contour.');
    end

function tf = is_closed(pts)
    if size(pts,2)~=2, pts = pts(:); end
    if size(pts,2)~=2, tf=false; return; end
    tf = norm(pts(1,:) - pts(end,:)) < 1e-10;

function [x,y] = preprocess_contour(pts)
    x = pts(:,1); y = pts(:,2);
    % Remove duplicate sequential points
    keep = [true; hypot(diff(x),diff(y)) > eps(max(hypot(x,y)))];
    x = x(keep); y = y(keep);
    % If first and last are extremely close but not equal, snap to equal
    if norm([x(1)-x(end), y(1)-y(end)]) < 1e-12
        x(end) = x(1); y(end) = y(1);
    end

function A = polygon_signed_area(x,y)
