function [isCirc, info] = detect_circle(pts)
    % Rough test: fit circle to points using linear least squares
    x = pts(:,1); y = pts(:,2);
    x = x - mean(x); y = y - mean(y);
    A = [-2*x, -2*y, ones(size(x))];
    b = -(x.^2 + y.^2);
    c = A\b;
    xc = c(1); yc = c(2); r = sqrt(c(1)^2 + c(2)^2 - c(3));
    % Residual measure
    res = sqrt(mean((hypot(x - xc, y - yc) - r).^2));
    isCirc = res < 1e-3*max(r,1);
    info = struct('xc',xc+mean(pts(:,1)),'yc',yc+mean(pts(:,2)),'r',r,'res',res);

function panels = build_panels(x, y)
    % Build N panels from N points (closed). Points are nodes; panels between i->i+1
    if ~is_closed([x y])
        x = [x; x(1)]; y = [y; y(1)];
    end
    N = numel(x)-1;
    panels.N = N;
    panels.xa = x(1:N);   panels.ya = y(1:N);
    panels.xb = x(2:N+1); panels.yb = y(2:N+1);
    panels.xc = 0.5*(panels.xa + panels.xb);
    panels.yc = 0.5*(panels.ya + panels.yb);
    dx = panels.xb - panels.xa; dy = panels.yb - panels.ya;
    panels.len = hypot(dx,dy);
    panels.tx = dx ./ panels.len; panels.ty = dy ./ panels.len; % tangential unit
    panels.nx =  panels.ty; panels.ny = -panels.tx; % outward normal for CCW contour
    panels.beta = atan2(dy, dx); % panel angle from x-axis

function S = influence_source(panels)
    % Compute source influence matrices at control points for constant-strength sources
    % Using standard 2D panel method logarithmic/atan2 formulas in local coordinates
    N = panels.N;
    S.An = zeros(N,N);
    S.At = zeros(N,N);
    for i = 1:N  % control point i
        for j = 1:N  % panel j
            if i==j
                % Self influence (analytical limits)
                S.An(i,j) = 0.5;   % normal velocity coefficient
                S.At(i,j) = 0.0;   % tangential velocity coefficient from source on itself
                continue;
            end
            % Transform control point i to panel j local coords
            dx = panels.xc(i) - panels.xa(j);
            dy = panels.yc(i) - panels.ya(j);
            cosb = panels.tx(j); sinb = panels.ty(j);
            x_local =  dx*cosb + dy*sinb;
            y_local = -dx*sinb + dy*cosb;
            x2 = panels.len(j);

            [In, It] = source_coeff(x_local, y_local, x2); % per unit source strength / (2π)
            % The returned coefficients are normalized with 1/(2π); apply to get
            % velocities in global components dot with normal/tangent
            % Here we directly store normal and tangential coefficients
            S.An(i,j) = In;
            S.At(i,j) = It;
        end
    end

function [In, It] = source_coeff(x, y, L)
    % Influence of a unit-strength constant source panel along x in local coords
    % Returns normal and tangential velocity coefficients at control point,
    % divided by 2π (consistent with standard panel method conventions).
    % Based on Hess & Smith formulations.
    epsy = 1e-14;
    y = max(min(y, 1e20), -1e20); % avoid inf
    % Distances to endpoints
    r1 = sqrt(x.^2 + y.^2);
    r2 = sqrt((x-L).^2 + y.^2);

    % Angles
    theta1 = atan2(y, x);
    theta2 = atan2(y, x-L);
    dtheta = theta2 - theta1;
    % Ensure -pi..pi for stability
    dtheta = wrapToPi(dtheta);

    % Log term
    Q = log(r2./r1 + (r2==0).*epsy + (r1==0).*epsy);

    % Velocity components in local coordinates (Hess-Smith, normalized by 2π)
    u = (1/(2*pi)) * dtheta;                % along panel (tangential)
    v = (1/(2*pi)) * Q;                     % normal (positive away from panel)
    % For robustness if y=0 on panel line but not on panel: limit
    if abs(y) < 1e-14
        v = 0; % symmetric limit
    end
    % Normal is local +y, tangential is local +x
    In = v;
    It = u;

function V = influence_vortex(panels)
    % Influence of a constant-strength vortex panel (circulation gamma const on panel)
    % Returns normal and tangential velocity coefficients per unit vortex strength/(2π)
    N = panels.N;
    V.An = zeros(N,N);
    V.At = zeros(N,N);
    for i=1:N
        for j=1:N
            if i==j
                V.An(i,j) = 0.0;
                V.At(i,j) = 0.5; % self tangential influence for vortex panel
                continue;
            end
            dx = panels.xc(i) - panels.xa(j);
            dy = panels.yc(i) - panels.ya(j);
            cosb = panels.tx(j); sinb = panels.ty(j);
            x_local =  dx*cosb + dy*sinb;
            y_local = -dx*sinb + dy*cosb;
            x2 = panels.len(j);

            [In, It] = vortex_coeff(x_local, y_local, x2);
            V.An(i,j) = In;
            V.At(i,j) = It;
        end
    end

function [In, It] = vortex_coeff(x, y, L)
    % Influence of a constant-strength vortex panel aligned with x-axis (local coords)
    % Returns normal and tangential velocity coefficients per unit vortex/(2π).
    % From Hess-Smith.
    r1 = sqrt(x.^2 + y.^2);
    r2 = sqrt((x-L).^2 + y.^2);
    theta1 = atan2(y, x);
    theta2 = atan2(y, x-L);
    dtheta = wrapToPi(theta2 - theta1);
    Q = log(r2./r1 + (r2==0).*eps + (r1==0).*eps);

    % For vortex panel, velocity induced is rotated: u = -Q/(2π), v = dtheta/(2π)
    u = -(1/(2*pi))*Q;   % tangential local
    v =  (1/(2*pi))*dtheta; % normal local
    In = v;
    It = u;

function solv = solve_source_panel(panels, freestream, useVortex, useKutta)
    % Assemble linear system enforcing zero normal velocity on surface
    N = panels.N;
    S = influence_source(panels);
    if useVortex
        V = influence_vortex(panels);
    end

    % Freestream normal velocity at control points
    Un = freestream.U * (cos(freestream.alpha)*panels.nx + sin(freestream.alpha)*panels.ny);

    % System: sum_j sigma_j * An_ij + gamma * Vn_total_i = -Un_i
    if ~useVortex
        A = S.An; rhs = -Un;
        sigma = A\rhs;
        gamma = 0;
    else
        % Add a single unknown gamma (constant around body) to enforce Kutta
        % Build augmented matrix [S.An   vn]; unknowns [sigma(1..N); gamma]
        vn_total = sum(V.An,2); % normal influence at each control point per unit gamma
        A = [S.An, vn_total];
        rhs = -Un;

        % Kutta condition: tangential velocity equal on upper/lower trailing-edge panels
        % Use trailing edge as panel 1 end. Choose last and first panels' control tangential vel.
        % Tangential velocity: U_t = U_inf*t·ex + sum sigma*At + gamma*vt_total
        vt_total = sum(V.At,2); % per unit gamma
        Ut_fs = freestream.U * (cos(freestream.alpha)*panels.tx + sin(freestream.alpha)*panels.ty);
        % Kutta: U_t at last panel control + U_t at first panel control = 0 (no cusp singularity)
        i1 = 1; i2 = panels.N;
        kutta_row = [S.At(i1,:) + S.At(i2,:), vt_total(i1) + vt_total(i2)];
        A = [A; kutta_row];
        rhs = [rhs; -(Ut_fs(i1) + Ut_fs(i2))];

        sol = A\rhs;
        sigma = sol(1:N);
        gamma = sol(end);
    end

    solv.sigma = sigma;
    solv.gamma = gamma;

function res = postprocess(panels, solv, freestream)
    % Compute tangential velocity at control points, Cp, and lift
    N = panels.N;
    S = influence_source(panels);
    if abs(solv.gamma) > 0
        V = influence_vortex(panels);
        vt_gamma = sum(V.At,2) * solv.gamma;
    else
        vt_gamma = zeros(N,1);
    end
    % Tangential velocity from sources
    vt_src = S.At * solv.sigma;

    % Add freestream tangential
    Ut_fs = freestream.U * (cos(freestream.alpha)*panels.tx + sin(freestream.alpha)*panels.ty);
    Ut = Ut_fs + vt_src + vt_gamma;

    Cp = 1 - (Ut./freestream.U).^2;

    % Circulation from gamma (constant-strength vortex around body)
    Gamma = solv.gamma * 2*pi; % note: our V coefficients are per unit/(2π); gamma here is the "strength" such that total circ = 2π*gamma
    L_per_span = freestream.rho * freestream.U * Gamma;
    % Reference dynamic pressure and chord for Cl
    chord = max(panels.xb) - min(panels.xa);
    qinf = 0.5*freestream.rho*freestream.U^2;
    Cl_gamma = L_per_span / (qinf * chord);

    % Pressure-integration lift: integrate Cp*n_y*ds in body coords projected to lift direction
    % Force per span: F = ∮(-p n) ds = q_inf ∮ Cp n ds
    % Lift is negative y if freestream along +x; but we compute component perpendicular to freestream
    nx = panels.nx; ny = panels.ny;
    ds = panels.len;
    % Pressure force components (positive outward normal times pressure; lift is opposite)
    Fx = qinf * sum(Cp .* nx .* ds);
    Fy = qinf * sum(Cp .* ny .* ds);
    % Lift perpendicular to freestream direction (angle alpha)
    ex = cos(freestream.alpha); ey = sin(freestream.alpha);
    % Perpendicular unit vector (rotate -90 deg)
    eLx = -ey; eLy = ex;
    L_press = -(Fx*eLx + Fy*eLy); % sign so positive lift upward for small alpha
    Cl_pressure = L_press / (qinf * chord);

    res.ctrl_x = panels.xc;
    res.Cp = Cp;
    res.Ut = Ut;
    res.Cl_gamma = Cl_gamma;
    res.Cl_pressure = Cl_pressure;
    res.Gamma = Gamma;

function compare_circle(panels, solv, freestream)
    % Analytic Cp on circle of radius R centered at (xc,yc). We approximate R and center
    xc = mean([panels.xa; panels.xb]); yc = mean([panels.ya; panels.yb]);
    r_pts = hypot(panels.xc - xc, panels.yc - yc);
    R = mean(r_pts);
    theta = atan2(panels.yc - yc, panels.xc - xc); % polar angle from +x

    % With no circulation: tangential velocity U_theta = -2U_inf sin(theta - alpha)
    % With circulation Gamma: U_theta = -2U_inf sin(theta - alpha) + Gamma/(2πR)
    Gamma = solv.gamma * 2*pi;
    Utheta_analytic = -2*freestream.U * sin(theta - freestream.alpha) + Gamma/(2*pi*R);
    Cp_analytic = 1 - (Utheta_analytic./freestream.U).^2;

    % Numeric Cp
    S = postprocess(panels, solv, freestream);
    Cp_num = S.Cp;

    err = abs(Cp_num - Cp_analytic);
    fprintf('\nCircle comparison (R≈%.4g):\n', R);
    fprintf(' Cp max abs error = %.3e, mean abs error = %.3e\n', max(err), mean(err));

function compare_thin_airfoil(alpha, Cl_num)
    Cl_thin = 2*pi*alpha;
    fprintf('\nNACA/thin-airfoil comparison:\n');
    fprintf(' Cl (thin-airfoil theory) = %.6f\n', Cl_thin);
    fprintf(' Cl (from pressure integration) = %.6f\n', Cl_num);
    fprintf(' Error (Cl_num - Cl_thin) = %.6f\n', Cl_num - Cl_thin);

function [xi, yi] = repanel_linear(x, y, M)
    % Reparameterize the closed polyline to have M points (M-1 panels)
    if ~is_closed([x y])
        x = [x; x(1)]; y = [y; y(1)];
    end
    s = [0; cumsum(hypot(diff(x), diff(y)))];
    L = s(end);
    s_query = linspace(0, L, M).';
    xi = interp1(s, x, s_query, 'linear');
    yi = interp1(s, y, s_query, 'linear');

% ---------------------------- End of file ----------------------------
end

% Trust-region visualization for a specific quadratic model in 2D
% Objective: f(x) = (x1 - 1)^2 + 2(x2 + 2)^2 + x1*x2
% The script:
%  - defines f as anonymous function and derives gradient/Hessian analytically
%  - evaluates g and B at xA, xB
%  - builds quadratic model m_k(p)
%  - plots contour lines of m_k(p), overlays trust-region circles
%  - solves the trust-region subproblem for a sweep of radii using an exact 2D solver
%  - shows Cauchy point and unconstrained minimizer when inside the region
%
% Run as a single script.

clear; clc; close all;

%% Define objective, gradient, Hessian (analytical)
% f(x) = (x1 - 1)^2 + 2(x2 + 2)^2 + x1*x2
f  = @(x) (x(1) - 1).^2 + 2*(x(2) + 2).^2 + x(1).*x(2);

% Gradient: ∇f = [2(x1-1) + x2; 4(x2+2) + x1]
gradf = @(x) [2*(x(1) - 1) + x(2);
              4*(x(2) + 2) + x(1)];

% Hessian: ∇²f = [2  1; 1  4] (constant)
Hf = [2, 1; 1, 4];
hessf = @(x) Hf;

%% Points xA and xB
xA = [0; -1];
xB = [0;  0.5];

% Pack into a cell for iteration
X   = {xA, xB};
names = {'x_A = [0; -1]', 'x_B = [0; 0.5]'};

%% Trust-region radii to sweep
Delta_vec = linspace(0, 2, 41);  % includes 0 and 2

%% Grid for plotting p-space
p1 = linspace(-2, 2, 201);
p2 = linspace(-2, 2, 201);
[P1, P2] = meshgrid(p1, p2);

%% Loop over the two expansion points
for idx = 1:2
    xk = X{idx};
    fk = f(xk);
    gk = gradf(xk);
    Bk = hessf(xk);     % constant here

    % Define quadratic model m_k(p) = f(xk) + gk' p + 0.5 p' Bk p
    mk_fun = @(p) fk + gk.'*p + 0.5*(p.'*Bk*p);

    % Evaluate m_k(P) on grid
    mk_vals = zeros(size(P1));
    for i = 1:numel(P1)
        p = [P1(i); P2(i)];
        mk_vals(i) = mk_fun(p);
    end

    % Unconstrained minimizer p_u = -B^{-1} g
    p_unc = - (Bk \ gk);

    % Cauchy point (steepest descent within trust region):
    % p_c(Δ) = - (α(Δ)) * g with α(Δ) = min( ||g||^3 / (Δ g' B g) if curvature positive else Δ/||g||, and
    % more precisely α* = argmin_t mk(-t g) on [0, Δ/||g||]:
    % t* = min( (g'g)/(g'Bg), Δ/||g|| ) if g'Bg > 0; if g'Bg <= 0 then t* = Δ/||g||.
    g = gk;
    Bg = Bk*g;
    gg = g.'*g;
    gBg = g.'*Bg;

    cauchy_dir = -g / norm(g); % direction only; point depends on Δ

    % Precompute eigen-decomposition for exact TRS solver
    [Q, D] = eig(Bk);
    lam = diag(D);  % eigenvalues
    % B is SPD here (eigs: 1.381966..., 4.6180...), but solver handles PSD/indef cases.

    % Solve TRS for each Delta using exact eigenvalue-based method in 2D.
    P_star = zeros(2, numel(Delta_vec));
    is_boundary = false(1, numel(Delta_vec));

    for j = 1:numel(Delta_vec)
        Delta = Delta_vec(j);

        % Attempt unconstrained solution
        p_try = p_unc;
        if norm(p_try) <= Delta
            % Unconstrained minimizer is feasible
            P_star(:, j) = p_try;
            is_boundary(j) = false;
        else
            % Boundary case: solve (B + lambda I) p = -g with ||p|| = Delta, lambda >= 0
            % Use secular equation phi(lambda) = sum_i ( (q_i' g)^2 / (lambda + lam_i)^2 ) - Delta^2 = 0
            % with lambda > -min_eig(B) (and >= 0 if B is PSD). Here B is SPD, so lambda >= 0.
            qt_g = Q.' * g;
            % Define phi(lambda)
            phi = @(l) sum( (qt_g.^2) ./ ( (lam + l).^2 ) ) - Delta^2;

            % Bracket lambda: start at 0, grow upper bound until phi>0 at 0 and phi(upper)<0 or vice versa.
            % For SPD and infeasible p_unc, phi(0) = ||B^{-1} g||^2 - Delta^2 > 0, and phi(l) -> -Delta^2 as l->inf.
            % So root exists on (0, inf).
            if phi(0) <= 0
                % Numerical fallback: should not happen when p_unc is infeasible. Still handle gracefully.
                P_star(:, j) = p_try * min(1, Delta / max(norm(p_try), eps));
                is_boundary(j) = abs(norm(P_star(:, j)) - Delta) > 1e-10;
            else
                % Find lambda by safeguarded Newton on phi with derivative
                dphi = @(l) -2 * sum( (qt_g.^2) ./ ( (lam + l).^3 ) );
                lambda = 0;
                % Newton iteration with backtracking and upper bound growth
                ub = 1; while phi(ub) > 0, ub = 2*ub; if ub > 1e12, break; end, end
                if phi(ub) > 0
                    % If we failed to push below zero numerically, clamp to large lambda
                    lambda = ub;
                else
                    % Bisection-Newton hybrid
                    a = 0; b = ub;
                    lambda = 0.5*(a+b);
                    for it = 1:60
                        val = phi(lambda);
                        if abs(val) < 1e-12, break; end
                        der = dphi(lambda);
                        % Newton step
                        step = -val / max(der, -eps);
                        l_new = lambda + step;
                        % Safeguard: keep in (a,b)
                        if ~(l_new > a && l_new < b)
                            l_new = 0.5*(a+b);
                        end
                        % Update bracket
                        if phi(l_new) > 0
                            a = l_new;
                        else
                            b = l_new;
                        end
                        lambda = l_new;
                    end
                end
                % Recover p*(Delta)
                p_star = - (Bk + lambda*eye(2)) \ g;
                % Ensure it lies on boundary numerically
                if norm(p_star) > 0
                    p_star = p_star * (Delta / norm(p_star));
                end
                P_star(:, j) = p_star;
                is_boundary(j) = true;
            end
        end
    end

    % Prepare figure
    figure('Color','w'); hold on; box on; axis equal;
    % Contours of m_k(p) in p-space (subtract fk for readability)
    contour_levels = linspace(min(mk_vals(:))-fk, min(mk_vals(:))-fk+10, 16);
    contour(P1, P2, mk_vals - fk, contour_levels, 'LineWidth', 1.0);
    colormap(parula);
    xlabel('p_1'); ylabel('p_2');
    title(sprintf('Quadratic model m_k(p) around %s', names{idx}));

    % Overlay trust-region circles
    th = linspace(0, 2*pi, 200);
    colors = [0.85 0.85 0.85];
    for j = 1:5:numel(Delta_vec)
        Delta = Delta_vec(j);
        plot(Delta*cos(th), Delta*sin(th), '-', 'Color', colors, 'LineWidth', 0.8);
    end

    % Plot locus of optimal p*(Δ)
    plot(P_star(1, :), P_star(2, :), 'r-', 'LineWidth', 2.0);
    scatter(P_star(1, 1), P_star(2, 1), 36, 'r', 'filled'); % at Δ=0

    % Plot Cauchy ray and a few Cauchy points for selected Δ
    sel = [11, 21, 31, 41]; sel = sel(sel <= numel(Delta_vec));
    pc_pts = zeros(2, numel(sel));
    for s = 1:numel(sel)
        Delta = Delta_vec(sel(s));
        if gBg > 0
            t_star = min(gg / gBg, Delta / norm(g));
        else
            t_star = Delta / norm(g);
        end
        pc = -t_star * g;
        pc_pts(:, s) = pc;
    end
    plot(pc_pts(1, :), pc_pts(2, :), 'ms', 'MarkerFaceColor', 'm', 'DisplayName', 'Cauchy points');

    % Plot unconstrained minimizer
    plot(p_unc(1), p_unc(2), 'bo', 'MarkerFaceColor', 'b', 'DisplayName', 'Unconstrained minimizer');

    % If the unconstrained minimizer is feasible for the largest Δ, mark it
    if norm(p_unc) <= max(Delta_vec) + 1e-12
        text(p_unc(1), p_unc(2), '  p_{unc}', 'Color', 'b', 'FontSize', 10);
    end

    legend({'m_k contours', 'trust-region circles', 'optimal p^*(\Delta) locus', 'p^*(0)', 'Cauchy points', 'unconstrained minimizer'}, ...
        'Location', 'bestoutside');

    xlim([min(p1), max(p1)]);
    ylim([min(p2), max(p2)]);

    % Print numerical values at xk
    fprintf('Point %s\n', names{idx});
    fprintf('  f(xk) = %.6f\n', fk);
    fprintf('  gk = [%.6f; %.6f]\n', gk(1), gk(2));
    fprintf('  Bk = [%.6f %.6f; %.6f %.6f]\n', Bk(1,1), Bk(1,2), Bk(2,1), Bk(2,2));
    fprintf('  p_unc = [%.6f; %.6f], ||p_unc|| = %.6f\n\n', p_unc(1), p_unc(2), norm(p_unc));
end

% Notes:
% - The TRS solver uses the classic eigenvalue-based secular equation in 2D.
% - Because B is SPD here, the solution curve starts at p*(0)=0, follows the boundary,
%   and ends at the unconstrained minimizer once Δ >= ||p_unc||.
% - The Cauchy points shown correspond to selected Δ values along the steepest-descent ray.

Here is a self-contained MATLAB script that defines f(x) = (x1 - 1)^2 + 5*(x2 + 2)^2, computes its gradient and Hessian, evaluates them at the two requested points, builds the quadratic model, solves the trust-region subproblem for Δ ∈ [0, 2], and visualizes contours and the solution path p*(Δ). You can paste this into a single .m file (e.g., run_trust_region_demo.m) and run it.

----------------
% Trust-region demo for f(x) = (x1 - 1)^2 + 5*(x2 + 2)^2
% Self-contained script: defines f, grad, Hessian; evaluates at two points;
% solves quadratic trust-region subproblem; and visualizes.

clear; clc; close all;

% Define function handle, gradient, and Hessian (analytical)
f  = @(x) (x(1) - 1).^2 + 5*(x(2) + 2).^2;
gfun = @(x) [2*(x(1) - 1); 10*(x(2) + 2)];
Hfun = @(x) [2, 0; 0, 10];  % Constant Hessian for this quadratic

% Points to analyze
Xlist = {[0; -1], [0; 0.5]};
Xnames = {'x = [0; -1]', 'x = [0; 0.5]'};

% Trust region radii to sweep
Delta_list = 0:0.05:2;

% Plot grid for p = [p1; p2]
pmin = -2; pmax = 2; ngrid = 121;
p1 = linspace(pmin, pmax, ngrid);
p2 = linspace(pmin, pmax, ngrid);
[P1, P2] = meshgrid(p1, p2);

for ix = 1:numel(Xlist)
    xk = Xlist{ix};
    gk = gfun(xk);
    Bk = Hfun(xk);
    fk = f(xk);

    % Display gradient and Hessian at this point
    fprintf('Point %s\n', Xnames{ix});
    fprintf('  f(xk) = %.6f\n', fk);
    fprintf('  gk = [% .6f; % .6f]\n', gk(1), gk(2));
    fprintf('  Bk = [%.6f, %.6f; %.6f, %.6f]\n', Bk(1,1), Bk(1,2), Bk(2,1), Bk(2,2));

    % Quadratic model m_k(p) = f(xk) + gk'' p + 0.5 p'' Bk p
    % Evaluate m_k(p) on grid
    mgrid = zeros(size(P1));
    for i = 1:numel(P1)
        p = [P1(i); P2(i)];
        mgrid(i) = fk + gk.'*p + 0.5*p.'*Bk*p;
    end

    % Solve the trust-region subproblem for each Delta
    % Bk is positive definite for this function: [2 0; 0 10]
    % Unconstrained minimizer: pN = -Bk \ gk
    pN = -Bk \ gk;
    norm_pN = norm(pN);

    % Precompute eigendecomposition for secular equation solves
    [Q, D] = eig(Bk);              % D = diag(d1, d2)
    d = diag(D);
    % Project gradient into eigenbasis
    gtil = Q.' * gk;

    % Prepare storage for path
    Pstar = zeros(2, numel(Delta_list));

    for j = 1:numel(Delta_list)
        Delta = Delta_list(j);

        if norm_pN <= Delta
            % Interior solution (Newton step feasible)
            Pstar(:, j) = pN;
        else
            % Boundary solution: solve for lambda >= 0 such that
            % ||(Bk + lambda I)^(-1) gk|| = Delta
            lam = solve_secular_pd(d, gtil, Delta);
            % Compute p*(Delta) in original coordinates
            p_lam_eig = -( (gtil) ./ (d + lam) );  % elementwise division
            p_lam = Q * p_lam_eig;
            Pstar(:, j) = p_lam;
        end
    end

    % Plot contours of m_k(p) and trust-region path p*(Delta)
    figure('Color', 'w', 'Name', sprintf('Trust-region at %s', Xnames{ix}));
    hold on; box on; axis equal;
    % Choose contour levels around m at p = 0
    m0 = fk;
    % Build a set of contour levels based on percentiles of mgrid
    mvals = sort(mgrid(:));
    lev_idx = round(linspace(1, numel(mvals), 12));
    levels = unique(mvals(lev_idx));
    contour(P1, P2, mgrid, levels, 'LineWidth', 1.0);
    colormap(parula(12));
    % Plot TR path
    plot(Pstar(1, :), Pstar(2, :), 'r-', 'LineWidth', 2, 'DisplayName', 'p^*(\Delta)');
    % Mark a few Delta values
    mark_D = [0, 0.5, 1.0, 1.5, 2.0];
    for md = mark_D
        [~, jj] = min(abs(Delta_list - md));
        plot(Pstar(1, jj), Pstar(2, jj), 'ko', 'MarkerFaceColor', 'y', ...
             'DisplayName', sprintf('\\Delta=%.2f', Delta_list(jj)));
    end
    % Also mark the Newton step and origin (p = 0)
    plot(0, 0, 'ks', 'MarkerSize', 7, 'MarkerFaceColor', [0.7 0.7 0.7], 'DisplayName', 'p=0');
    plot(pN(1), pN(2), 'md', 'MarkerSize', 7, 'MarkerFaceColor', 'm', 'DisplayName', 'p_N');
    xlabel('p_1'); ylabel('p_2');
    title(sprintf('Quadratic model contours and TR path at %s', Xnames{ix}));
    legend('Location', 'bestoutside');
    xlim([pmin, pmax]); ylim([pmin, pmax]);
    grid on;

    % Also overlay a few trust-region boundaries to show feasibility sets
    for rr = [0.5, 1.0, 1.5, 2.0]
        th = linspace(0, 2*pi, 200);
        plot(rr*cos(th), rr*sin(th), 'k--', 'HandleVisibility', 'off');
    end
end

% Local solver for secular equation when B is positive definite and 2x2
% Finds lambda >= 0 such that sum_i (gtil_i / (d_i + lambda))^2 = Delta^2
function lam = solve_secular_pd(d, gtil, Delta)
    % d: vector of eigenvalues (positive)
    % gtil: gradient in eigenbasis Q' * g
    % Delta: trust-region radius
    %
    % If Delta is zero, lambda -> +inf; return large number and effectively p=0.
    if Delta == 0
        lam = 1e8;
        return;
    end

    % Check if Newton step is inside; if yes, lambda = 0
    if norm(gtil ./ d) <= Delta
        lam = 0;
        return;
    end

    % Define phi(lambda) = ||(B + lambda I)^{-1} g|| - Delta
    % We solve phi(lambda) = 0 for lambda >= 0.
    phi = @(l) norm(gtil ./ (d + l)) - Delta;
    % Its derivative (used in Newton) for positive definite diagonal d
    dphi = @(l) -sum( (gtil.^2) ./ (d + l).^3 ) / norm(gtil ./ (d + l) + eps);

    % Bracket root: since phi(0) > 0 and phi(l) -> -Delta as l->inf, we can increase l until phi<0
    l_low = 0;
    l_high = 1;
    while phi(l_high) > 0
        l_high = 2*l_high + 1;
        if l_high > 1e12
            break;
        end
    end

    % Use safeguarded Newton or bisection on [l_low, l_high]
    lam = l_high;
    for it = 1:50
        % Newton step (if derivative is safe)
        if l_high < 1e12
            lamN = lam - phi(lam)/max(dphi(lam), 1e-16);
            % Safeguard into [l_low, l_high]
            if ~(lamN > l_low && lamN < l_high) || ~isfinite(lamN)
                lamN = 0.5*(l_low + l_high);
            end
        else
            lamN = 0.5*(l_low + l_high);
        end

        fN = phi(lamN);
        if abs(fN) < 1e-10
            lam = lamN;
            break;
        end

        % Update bracket
        if fN > 0
            l_low = lamN;
        else
            l_high = lamN;
        end
        lam = lamN;
    end

    lam = max(lam, 0);
end
----------------

Notes:
- The Hessian is constant and positive definite: B = diag(2, 10), so the Newton step pN is the unconstrained minimizer of the quadratic model. If ||pN|| <= Δ, it is also the trust-region solution; otherwise the boundary solution is obtained via the secular equation.
- The code computes the entire path p*(Δ) for Δ ∈ [0, 2], overlays it on contour plots of m_k(p), and marks several Δ values.
- It repeats everything for both x = [0; -1] and x = [0; 0.5], generating separate figures with legends and titles.

Below is a self-contained MATLAB script that:

- Defines f(x) = (x1 − 1)^2 + 2(x2 + 2)^2 + x1*x2
- Computes its gradient and Hessian, and evaluates them at x = [0; -1] and x = [0; 0.5]
- Solves the 2D trust-region subproblem for m_k(p) = f(x_k) + g_k' p + 0.5 p' B_k p with B_k = ∇²f(x_k) for trust-region radii Δ ∈ [0, 2]
- Plots:
  - Contours of m_k(p) on a grid in p
  - The family of trust-region minimizers p*(Δ) for Δ ∈ [0, 2]
  - The Cauchy point and the unconstrained Newton step
- Repeats all visualizations for both x_k points

Copy-paste into a new file (e.g., trust_region_demo.m) and run.

% trust_region_demo.m
clear; close all; clc;

%==============================================================
% 1) Define function, gradient, and Hessian
%==============================================================
f  = @(x) (x(1)-1).^2 + 2*(x(2)+2).^2 + x(1).*x(2);
gf = @(x) [2*(x(1)-1) + x(2);
           4*(x(2)+2) + x(1)];
Hf = @(x) [2, 1;
           1, 4];  % constant Hessian for this quadratic

% Points x_k to analyze
Xk_list = {[0; -1], [0; 0.5]};

% Evaluate gradient and Hessian at both points (display to console)
disp('Function, gradient, Hessian evaluations:');
for i = 1:numel(Xk_list)
    xk = Xk_list{i};
    fprintf('\nAt x = [%g; %g]:\n', xk(1), xk(2));
    val = f(xk);
    gk  = gf(xk);
    Bk  = Hf(xk);
    fprintf('f(x)   = %.6f\n', val);
    fprintf('g(x)   = [%.6f; %.6f]\n', gk(1), gk(2));
    fprintf('H(x) = \n'); disp(Bk);
end

%==============================================================
% 2) Trust-region subproblem in 2D
%    m_k(p) = f(x_k) + g_k^T p + 0.5 p^T B_k p
%    with B_k = Hessian at x_k (here constant), Δ in [0, 2]
%
%    - Newton step pN = -B^{-1} g
%    - Cauchy point pC = -alpha * g, with alpha chosen as:
%        alpha_star = min( ||g||^2 / (g' B g), Δ/||g|| ) if g' B g > 0
%        If g' B g <= 0 (nonconvex along g), use alpha = Δ/||g||
%    - Exact TRS solution in 2D:
%        If ||pN|| <= Δ, p* = pN (unconstrained minimizer).
%        Else p* = -(B + λ I)^{-1} g with λ >= 0 chosen so ||p*|| = Δ.
%      We solve for λ via scalar root-finding.
%==============================================================

% Trust-region radii to sample
Delta_min = 0;
Delta_max = 2;
nDelta = 400;         % fine grid for path
Delta_grid = linspace(Delta_min, Delta_max, nDelta);

% Grid in p for contour plots
pmax = 2.5;
ng = 201;
p1 = linspace(-pmax, pmax, ng);
p2 = linspace(-pmax, pmax, ng);
[P1, P2] = meshgrid(p1, p2);

% Visualization for each x_k
for i = 1:numel(Xk_list)
    xk = Xk_list{i};
    fk = f(xk);
    gk = gf(xk);
    Bk = Hf(xk);

    % Precompute function values on the p-grid for contouring
    % m_k(p) = fk + gk' p + 0.5 p' Bk p
    mk_grid = zeros(size(P1));
    for r = 1:numel(P1)
        p = [P1(r); P2(r)];
        mk_grid(r) = fk + gk.'*p + 0.5 * (p.' * Bk * p);
    end

    % Unconstrained Newton step
    pN = -Bk \ gk;

    % Cauchy point along -g
    gBg = gk.' * (Bk \ gk); % not g'Bg; compute later properly
    % For alpha_star, we need g'Bg = g' B g (scalar)
    gBg_quadratic = gk.' * (Bk * gk);
    gnorm = norm(gk);
    if gBg_quadratic > 0
        alpha_par = (gnorm^2) / gBg_quadratic;
    else
        alpha_par = inf; % implies stepping to boundary
    end
    % For each Δ, Cauchy point is limited by Δ/||g||
    % We'll compute and mark at Δ_max for visualization purposes, and also plot its ray.
    alphaC = min(alpha_par, Delta_max / max(gnorm, eps));
    pC = -alphaC * gk;

    % Compute the family p*(Δ) by solving the TRS
    Pstar = zeros(2, nDelta);
    lambda_star = zeros(1, nDelta);
    for j = 1:nDelta
        Delta = Delta_grid[j];
        if Delta == 0
            Pstar(:, j) = [0; 0];
            lambda_star(j) = 0;
            continue;
        end
        % Check if unconstrained Newton step is feasible
        if norm(pN) <= Delta + 1e-12
            Pstar(:, j) = pN;
            lambda_star(j) = 0;
            continue;
        end
        % Otherwise, solve (B + λ I) p = -g with ||p|| = Δ, λ > 0
        % In 2D, find λ via scalar root-finding on phi(λ) = ||(B+λI)^{-1} g|| - Δ = 0
        phi = @(lam) norm(-(Bk + lam*eye(2)) \ gk) - Delta;
        % Bracket λ. Since Bk is SPD here, λ ∈ (0, ∞). Start from small and expand.
        lamL = 0;          % phi(lamL) > 0 because ||pN|| > Δ
        lamU = 1;
        % Increase lamU until phi(lamU) <= 0
        valU = phi(lamU);
        iterExpand = 0;
        while valU > 0 && iterExpand < 60
            lamU = lamU * 2;
            valU = phi(lamU);
            iterExpand = iterExpand + 1;
        end
        % Bisection
        lam_lo = lamL; lam_hi = lamU;
        for it = 1:60
            lam_mid = 0.5*(lam_lo + lam_hi);
            val_mid = phi(lam_mid);
            if val_mid > 0
                lam_lo = lam_mid;
            else
                lam_hi = lam_mid;
            end
        end
        lam = 0.5*(lam_lo + lam_hi);
        lambda_star(j) = lam;
        Pstar(:, j) = -(Bk + lam*eye(2)) \ gk;
        % Numerical safeguard: project back to the boundary if needed
        nP = norm(Pstar(:, j));
        if nP > Delta*(1+1e-8)
            Pstar(:, j) = Pstar(:, j) * (Delta / nP);
        end
    end

    % Prepare figure
    figure('Name', sprintf('Trust-region visualization at x = [%.3g; %.3g]', xk(1), xk(2)), ...
           'Color', 'w', 'Position', [100 100 1200 500]);

    %--------------------------
    % Left subplot: contour of m_k(p)
    %--------------------------
    subplot(1,2,1); hold on; grid on; axis equal;
    title(sprintf('Contours of m_k(p) at x = [%.3g; %.3g]', xk(1), xk(2)));
    xlabel('p_1'); ylabel('p_2');

    % Choose contour levels centered around the minimum value on grid
    mk_min = min(mk_grid(:));
    mk_max = max(mk_grid(:));
    levels = linspace(mk_min, mk_min + 0.75*(mk_max - mk_min), 20);
    contour(P1, P2, mk_grid, levels, 'LineWidth', 1.0);

    % Plot trust-region circles for a few sample radii
    for Delta_plot = [0.5 1.0 1.5 2.0]
        th = linspace(0, 2*pi, 200);
        plot(Delta_plot*cos(th), Delta_plot*sin(th), 'k--', 'LineWidth', 0.8);
    end

    % Plot Newton step and Cauchy point
    plot(pN(1), pN(2), 'rp', 'MarkerSize', 12, 'MarkerFaceColor', 'r', 'DisplayName', 'Newton step');
    plot(pC(1), pC(2), 'bs', 'MarkerSize', 9, 'MarkerFaceColor', 'b', 'DisplayName', 'Cauchy point');

    % Plot p*(Δ) path
    plot(Pstar(1, :), Pstar(2, :), 'm-', 'LineWidth', 2, 'DisplayName', 'p^*(\Delta), \Delta \in [0,2]');

    legend('Location', 'best');

    %--------------------------
    % Right subplot: parameterization by Δ
    %--------------------------
    subplot(1,2,2); 
    tl = tiledlayout(2,1, 'TileSpacing','compact', 'Padding','compact');

    % Position path vs Δ
    nexttile; hold on; grid on;
    title('Trust-region minimizer components vs \Delta');
    xlabel('\Delta'); ylabel('p^*_1, p^*_2');
    plot(Delta_grid, Pstar(1, :), 'b-', 'LineWidth', 1.5, 'DisplayName', 'p_1^*(\Delta)');
    plot(Delta_grid, Pstar(2, :), 'r-', 'LineWidth', 1.5, 'DisplayName', 'p_2^*(\Delta)');
    % Mark where solution switches from boundary to Newton (if any)
    idxN = find(vecnorm(Pstar,2,1) < 1e-6 + Delta_grid, 1, 'last'); %#ok<NASGU>
    legend('Location', 'best');

    % Norm vs Δ and dual λ
    nexttile; hold on; grid on;
    title('Norm of p^*(\Delta) and dual \lambda(\Delta)');
    xlabel('\Delta'); yyaxis left;
    plot(Delta_grid, vecnorm(Pstar,2,1), 'k-', 'LineWidth', 1.5, 'DisplayName', '||p^*(\Delta)||');
    yline(0.5, 'k:'); yline(1.0, 'k:'); yline(1.5, 'k:'); yline(2.0, 'k:');
    ylabel('||p^*(\Delta)||');

    yyaxis right;
    plot(Delta_grid, lambda_star, 'm--', 'LineWidth', 1.5, 'DisplayName', '\lambda(\Delta)');
    ylabel('\lambda');

    % Add a legend using dummy handles (one per axis)
    yyaxis left; h1 = plot(nan, nan, 'k-', 'LineWidth', 1.5, 'DisplayName', '||p^*(\Delta)||'); %#ok<NASGU>
    yyaxis right; h2 = plot(nan, nan, 'm--', 'LineWidth', 1.5, 'DisplayName', '\lambda(\Delta)'); %#ok<NASGU>
end

%==============================================================
% Notes:
% - For this quadratic, Hessian is constant SPD: B = [2 1; 1 4].
% - The trust-region solution is unique. The code uses a robust 1D solve
%   for the boundary case and defaults to the Newton step when feasible.
% - The Cauchy point displayed corresponds to the optimal step along -g
%   capped at Δ_max; along the path plot, the exact minimizers p*(Δ)
%   are shown for all Δ ∈ [0,2].
%==============================================================

Below is complete, runnable MATLAB code that:

- Defines the Rosenbrock function f(x) = (1 − x1)^2 + 100(x2 − x1^2)^2
- Computes its gradient and Hessian symbolically and evaluates them at x = [0; −1] and x = [0; 0.5]
- For each point x_k, builds the quadratic model m_k(p) = f(x_k) + g_k' p + 0.5 p' B_k p
- Plots level sets of m_k(p), trust-region circles ||p|| ≤ Δ for Δ ∈ [0, 2], and overlays the exact trust-region solutions p*(Δ) for Δ on a fine grid using a 2D exact solver (unconstrained Newton step inside or boundary solution via secular equation solved with eigen-decomposition)
- Repeats for both base points
- Includes clear comments

Copy into a single MATLAB script (e.g., rosenbrock_trust_region_demo.m) and run.

% rosenbrock_trust_region_demo.m
% Trust-region visualization for Rosenbrock model at two points
% - Symbolic gradient/Hessian
% - Quadratic model contours in p-space
% - Exact trust-region solutions p*(Δ) for Δ in [0,2]

clear; close all; clc;

%% 1) Define Rosenbrock function, gradient, Hessian symbolically
syms x1 x2 real
f_sym = (1 - x1)^2 + 100*(x2 - x1^2)^2;
g_sym = gradient(f_sym, [x1; x2]);
H_sym = hessian(f_sym, [x1, x2]);

f_fun = matlabFunction(f_sym, 'Vars', {[x1; x2]});
g_fun_sym = matlabFunction(g_sym, 'Vars', {[x1; x2]});
H_fun_sym = matlabFunction(H_sym, 'Vars', {[x1; x2]});

%% 2) Points of interest
X_list = {[0; -1], [0; 0.5]};
labels = {'x = [0; -1]', 'x = [0; 0.5]'};

% Trust-region radii to display
Delta_display = linspace(0,2,9);     % few circles to draw
Delta_solve   = 0:0.02:2;            % fine grid for solution curve

for idx = 1:numel(X_list)
    xk = X_list{idx};
    fk = f_fun(xk);
    gk = g_fun_sym(xk);
    Bk = H_fun_sym(xk);

    % Display symbolic values for verification in Command Window
    fprintf('\nPoint %s\n', labels{idx});
    fprintf('f(xk) = %.6f\n', fk);
    fprintf('gk = [% .6f; % .6f]\n', gk(1), gk(2));
    fprintf('Bk = [%.6f %.6f; %.6f %.6f]\n', Bk(1,1), Bk(1,2), Bk(2,1), Bk(2,2));

    %% 3) Define quadratic model m_k(p) = fk + gk'' p + 0.5 p'' Bk p
    % For plotting, we only need the value up to an additive constant.
    m_fun = @(p1,p2) fk + gk(1).*p1 + gk(2).*p2 + 0.5*(Bk(1,1).*p1.^2 + 2*Bk(1,2).*p1.*p2 + Bk(2,2).*p2.^2);

    %% 4) Build grid in p-space and compute m_k(p)
    % Choose a window that captures relevant regions. We can adapt it using Newton step norm.
    % Unconstrained Newton step (if Bk is nonsingular)
    NewtonAvailable = (abs(det(Bk)) > 1e-14);
    pN = [NaN; NaN];
    if NewtonAvailable
        pN = -Bk\gk;
    end

    % Set plotting window centered around origin and possibly including pN
    baseR = 2.0;                % base radius
    rN = max(norm(pN), 0);
    R = max(baseR, 1.2*rN + 0.5);
    p1 = linspace(-R, R, 401);
    p2 = linspace(-R, R, 401);
    [P1, P2] = meshgrid(p1, p2);
    M = m_fun(P1, P2);

    %% 5) Solve trust-region subproblem for each Delta and collect p*(Delta)
    % Exact 2D solver using eigen-decomposition and secular equation (Moré–Sorensen style).
    p_star = zeros(2, numel(Delta_solve));
    for j = 1:numel(Delta_solve)
        Delta = Delta_solve(j);
        p_star(:, j) = trust_region_exact_2d(gk, Bk, Delta);
    end

    %% 6) Plot: contours of m_k, trust-region circles, and solution path
    figure('Color','w','Name',sprintf('Trust-Region Model at %s', labels{idx}));
    hold on; box on; axis equal; grid on;

    % Contours of m_k(p) (choose levels automatically, clipped)
    % For better contrast, shift by fk (optional)
    contour(P1, P2, M, 30, 'LineWidth', 1.0, 'LineColor', [0.4 0.4 0.4]);

    % Plot trust-region circles
    th = linspace(0, 2*pi, 400);
    for Delta = Delta_display
        plot(Delta*cos(th), Delta*sin(th), 'Color', [0.6 0.8 1], 'LineWidth', 1.0);
    end

    % Plot Newton step (if available) and Cauchy point at Delta=2 for reference
    if NewtonAvailable
        plot(pN(1), pN(2), 'rp', 'MarkerFaceColor','r', 'MarkerSize',10);
        text(pN(1), pN(2), '  Newton', 'Color','r', 'FontSize',10, 'VerticalAlignment','bottom');
    end
    pC2 = cauchy_point(gk, Bk, 2.0); % along -g at Delta=2
    plot(pC2(1), pC2(2), 'ms', 'MarkerFaceColor','m', 'MarkerSize',7);
    text(pC2(1), pC2(2), '  Cauchy(Δ=2)', 'Color','m', 'FontSize',10, 'VerticalAlignment','bottom');

    % Overlay solution curve p*(Delta)
    plot(p_star(1, :), p_star(2, :), 'b-', 'LineWidth', 2);
    scatter(p_star(1, 1), p_star(2, 1), 36, 'b', 'filled'); % Δ=0
    scatter(p_star(1, end), p_star(2, end), 36, 'b', 'filled'); % Δ=max

    xlabel('p_1'); ylabel('p_2');
    title(sprintf('Quadratic model m_k(p) and trust-region solutions, %s', labels{idx}));
    legend({'m_k contours', 'trust-region circles', 'Newton step', 'Cauchy point (Δ=2)', 'p^*(Δ) path'}, ...
        'Location','bestoutside');
    xlim([-R R]); ylim([-R R]);
end

%% Helper functions

function p = trust_region_exact_2d(g, B, Delta)
% Solve min 0.5 p' B p + g' p  s.t. ||p|| <= Delta
% Returns the exact solution p*(Delta) in R^2.
% Strategy:
% - If B is PD and Newton step pN = -B\g is inside the ball, return pN.
% - Else, solve the boundary problem using eigen-decomposition:
%   Solve (B + lambda I) p = -g with ||p|| = Delta and lambda >= 0.
%
% Robust 2D implementation follows classical trust-region methods.

    % Numerical tolerances
    tol = 1e-12;
    maxIt = 100;

    % Try Newton step when B is nonsingular
    singular = (abs(det(B)) < 1e-14);
    if ~singular
        pN = -B\g;
        if (g.'*pN + 0.5*pN.'*B*pN) <= (g.'*zeros(2,1)) + 0.5*zeros(1,1) % no-op; just ensures scalars
        end
        if norm(pN) <= Delta && is_posdef(B)
            p = pN;
            return;
        end
    end

    % Boundary solution via secular equation using eigen-decomposition
    [Q, D] = eig((B + B.')/2);          % symmetrize for robustness
    d = diag(D);
    gtil = Q.' * g;

    % Handle the "hard case": when some d_i are minimal and gtil component nearly zero
    dmin = min(d);
    % lambda must be >= max(0, -dmin) to make (B + lambda I) PSD
    lambda_lo = max(0, -dmin) + 0;      % lower bound
    % Upper bound for lambda: increase until norm decreases below Delta
    % Start with something modest, then expand
    lambda_hi = lambda_lo;
    pnorm = inf;
    for k = 1:50
        denom = d + lambda_hi;
        p = -Q * ( (gtil ./ denom) );
        pnorm = norm(p);
        if pnorm <= Delta
            break;
        end
        lambda_hi = max(1, 2*lambda_hi + 1);
    end
    if pnorm > Delta
        % As a fallback, take Cauchy point on boundary
        p = cauchy_point(g, B, Delta);
        return;
    end

    % Define phi(lambda) = 1/||p(lambda)|| - 1/Delta with p(lambda) = -Q*diag(1./(d+lambda))*gtil
    % We find lambda s.t. ||p(lambda)|| = Delta; phi is monotone decreasing for lambda >= -dmin
    function [pnorm, p] = p_of_lambda(lam)
        denom = d + lam;
        v = gtil ./ denom;
        p = -Q * v;
        pnorm = norm(p);
    end

    % If lambda_lo already feasible and B+lambda_lo*I PSD, choose that
    [pnorm_lo, p_lo] = p_of_lambda(lambda_lo);
    if abs(pnorm_lo - Delta) <= 1e-10
        p = p_lo; return;
    end

    % Bracket root between lambda_lo and lambda_hi
    f_lo = pnorm_lo - Delta;
    [pnorm_hi, ~] = p_of_lambda(lambda_hi);
    f_hi = pnorm_hi - Delta;
    if f_lo < 0
        % Already inside at lower bound; if B not PD or pN outside, must be boundary with lambda=0
        % In that case, move along direction to hit boundary
        if pnorm_lo == 0
            % If gradient is zero, any direction works; return zero step
            p = [0;0]; return;
        else
            p = (Delta/pnorm_lo)*p_lo;
            return;
        end
    end
    if f_hi > 0
        % Should not happen due to selection of lambda_hi; fallback
        p = cauchy_point(g, B, Delta); return;
    end

    % Use safeguarded Newton or bisection on secular equation psi(lambda) = ||p(lambda)|| - Delta = 0
    lamL = lambda_lo; lamU = lambda_hi;
    lam = max(lambda_lo, 0);
    for it = 1:maxIt
        % Compute function and derivative of psi(lambda) = ||p|| - Delta
        denom = d + lam;
        v = gtil ./ denom;
        p = -Q * v;
        pnorm = norm(p);
        psi = pnorm - Delta;

        if abs(psi) <= 1e-10*(1+Delta)
            break;
        end

        % Derivative: d/dlam ||p|| = - || W v ||^2 / ||p|| where W = diag(1./(d+lam)) in eigen-space
        w = gtil ./ (denom.^2);
        psi_prime = -sqrt( (v.'*v + eps) ) \ (w.'*w); % stable negative value
        if ~isfinite(psi_prime) || psi_prime >= 0
            % Fallback to bisection
            if psi > 0
                lamL = lam;
            else
                lamU = lam;
            end
            lam = 0.5*(lamL + lamU);
            continue;
        end

        % Newton step with safeguarding
        lam_new = lam - psi/psi_prime;
        if lam_new <= lamL || lam_new >= lamU || ~isfinite(lam_new)
            % fall back to bisection
            lam_new = 0.5*(lamL + lamU);
        end

        % Update bracket
        if psi > 0
            lamL = lam;
        else
            lamU = lam;
        end
        lam = lam_new;
    end
    % Final p at lam
    denom = d + lam;
    v = gtil ./ denom;
    p = -Q * v;
    % Normalize to boundary if small numeric drift
    nrm = norm(p);
    if nrm > 0
        p = min(1, Delta/max(nrm, eps)) * p;
    end
end

function tf = is_posdef(A)
% Check positive definiteness robustly via Cholesky
    [~,p] = chol((A + A')/2);
    tf = (p == 0);
end

function pC = cauchy_point(g, B, Delta)
% Cauchy point: minimizer of m along -g, truncated at trust-region boundary
% pC = -alpha * g, where alpha = argmin_{alpha in [0, Delta/||g||]} m(-alpha g)
% alpha* = min( ||g||^2 / (g' B g), Delta/||g|| ) when g' B g > 0; else alpha* = Delta/||g||
    gnorm = norm(g);
    if gnorm == 0
        pC = [0;0];
        return;
    end
    gBg = g'*(B*g);
    if gBg > 0
        alpha_star = min( (gnorm^2)/gBg, Delta/gnorm );
    else
        alpha_star = Delta/gnorm;
    end
    pC = -alpha_star * g;
end

