// src/services/csvImportService.js
// Streams a CSV with Papa Parse, batches rows, bulk-upserts to DB, supports parallel sanitization, and robust error handling.

const fs = require('fs');
const { pipeline } = require('stream');
const Papa = require('papaparse');
const { Worker } = require('worker_threads');
const os = require('os');
const pool = require('../db/pool');
const config = require('../config');

// --- Helpers ---
function createPapaStreamParser(onRow, onComplete, onError) {
  return Papa.parse(Papa.NODE_STREAM_INPUT, {
    header: true,
    skipEmptyLines: 'greedy',
    dynamicTyping: false,
    transformHeader: (h) => h.trim(),
    error: onError,
    complete: onComplete,
    step: (results) => {
      // results.data is a row object; results.errors is an array per row
      if (results.errors && results.errors.length > 0) {
        // Surface first row-level parse error but continue streaming
        const err = new Error(`CSV row parse error: ${results.errors[0].message}`);
        err.code = 'CSV_ROW_PARSE_ERROR';
        onError(err, { recoverable: true });
      }
      onRow(results.data);
    },
  });
}

function validateRequiredColumns(headers) {
  const required = config.import.requiredColumns || [];
  const missing = required.filter((c) => !headers.includes(c));
  if (missing.length) {
    const err = new Error(`Missing required CSV columns: ${missing.join(', ')}`);
    err.code = 'CSV_MISSING_COLUMNS';
    throw err;
  }
}

function mapRowToCustomer(row) {
  const map = config.import.customersCsvMapping;
  return {
    email: String(row[map.email] || '').trim().toLowerCase(),
    first_name: String(row[map.first_name] || '').trim() || null,
    last_name: String(row[map.last_name] || '').trim() || null,
    phone: String(row[map.phone] || '').trim() || null,
    address: String(row[map.address] || '').trim() || null,
    city: String(row[map.city] || '').trim() || null,
    state: String(row[map.state] || '').trim() || null,
    zip: String(row[map.zip] || '').trim() || null,
  };
}

// Optional parallel sanitizer using worker_threads
typeof globalThis.__customerSanitizeWorkers === 'undefined' && (globalThis.__customerSanitizeWorkers = null);

function getSanitizeWorkers() {
  if (globalThis.__customerSanitizeWorkers) return globalThis.__customerSanitizeWorkers;
  const cpu = Math.max(1, Math.min(os.cpus().length - 1, 4));
  const workers = Array.from({ length: cpu }, () => new Worker(`
    const { parentPort } = require('worker_threads');
    function sanitize(r) {
      // Example lightweight normalization; extend as needed
      if (r.email) r.email = r.email.toLowerCase();
      return r;
    }
    parentPort.on('message', (batch) => {
      try {
        const out = batch.map(sanitize);
        parentPort.postMessage({ ok: true, out });
      } catch (e) {
        parentPort.postMessage({ ok: false, error: e.message });
      }
    });
  `, { eval: true }));
  globalThis.__customerSanitizeWorkers = workers;
  return workers;
}

async function sanitizeBatchParallel(batch) {
  const workers = getSanitizeWorkers();
  const chunkSize = Math.ceil(batch.length / workers.length) || batch.length;
  const chunks = [];
  for (let i = 0; i < batch.length; i += chunkSize) chunks.push(batch.slice(i, i + chunkSize));
  return await Promise.all(chunks.map((chunk, i) => new Promise((resolve, reject) => {
    const w = workers[i % workers.length];
    const onMessage = (msg) => {
      w.off('message', onMessage);
      if (msg.ok) resolve(msg.out); else reject(new Error(msg.error || 'Sanitization failed'));
    };
    w.on('message', onMessage);
    w.postMessage(chunk);
  }))).then(parts => parts.flat());
}

// Bulk upsert repository (PostgreSQL) — adjust SQL for your schema
async function bulkUpsertCustomers(client, customers) {
  if (!customers.length) return;
  const cols = ['email','first_name','last_name','phone','address','city','state','zip'];
  const values = [];
  const params = [];
  let p = 1;
  for (const c of customers) {
    values.push(`(${cols.map(() => `$${p++}`).join(',')})`);
    params.push(c.email, c.first_name, c.last_name, c.phone, c.address, c.city, c.state, c.zip);
  }
  const sql = `
    INSERT INTO customers (${cols.join(',')})
    VALUES ${values.join(',')}
    ON CONFLICT (email) DO UPDATE SET
      first_name = EXCLUDED.first_name,
      last_name  = EXCLUDED.last_name,
      phone      = EXCLUDED.phone,
      address    = EXCLUDED.address,
      city       = EXCLUDED.city,
      state      = EXCLUDED.state,
      zip        = EXCLUDED.zip
  `;
  await client.query(sql, params);
}

// Core importer
async function importCustomersFromCsv({ filePath, batchSize = config.import.batchSize, parallelSanitize = true, onProgress }) {
  if (!filePath) throw Object.assign(new Error('filePath is required'), { code: 'ARG_FILEPATH_MISSING' });
  if (!fs.existsSync(filePath)) throw Object.assign(new Error(`CSV file not found: ${filePath}`), { code: 'FILE_NOT_FOUND' });

  const fileStream = fs.createReadStream(filePath);
  const parsedRows = [];
  let headersChecked = false;
  let total = 0;
  let failed = 0;

  const flushBatch = async (client) => {
    if (parsedRows.length === 0) return;
    const batch = parsedRows.splice(0, parsedRows.length);
    let toWrite = batch;
    try {
      if (parallelSanitize) {
        toWrite = await sanitizeBatchParallel(batch);
      }
      await bulkUpsertCustomers(client, toWrite);
      total += toWrite.length;
      onProgress && onProgress({ total, failed });
    } catch (e) {
      // If one batch fails, log and continue (don’t halt entire import)
      failed += batch.length;
      console.error('Batch upsert error:', e);
    }
  };

  const client = await pool.connect();
  const papaParser = createPapaStreamParser(
    (row) => {
      try {
        if (!headersChecked) {
          headersChecked = true; // First step gives access to header metadata via parser meta
          // Papa's stream API doesn't pass headers directly; validate when first row arrives
          validateRequiredColumns(Object.values(config.import.customersCsvMapping));
        }
        const mapped = mapRowToCustomer(row);
        if (!mapped.email) {
          failed += 1; // skip invalid row
          return;
        }
        parsedRows.push(mapped);
        if (parsedRows.length >= batchSize) {
          // backpressure: pause stream until DB write finishes
          fileStream.pause();
          flushBatch(client).finally(() => fileStream.resume());
        }
      } catch (e) {
        failed += 1;
        console.error('Row handling error:', e);
      }
    },
    async () => {
      try {
        // final flush
        await flushBatch(client);
      } finally {
        client.release();
      }
    },
    (err, meta) => {
      if (meta && meta.recoverable) {
        // log and continue
        console.warn('Recoverable parse error:', err.message);
        return;
      }
      // Unrecoverable – ensure stream is torn down
      console.error('Unrecoverable CSV parse error:', err);
      try { fileStream.destroy(err); } catch {}
    }
  );

  await new Promise((resolve, reject) => {
    pipeline(fileStream, papaParser, (err) => {
      if (err) reject(err); else resolve();
    });
  });

  return { imported: total, failed };
}

module.exports = { importCustomersFromCsv };
