// src/routes/importRoute.js
// Express route that kicks off background processing and returns immediately to avoid timeouts.

const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const Queue = require('bull');
const config = require('../config');
const { importCustomersFromCsv } = require('../services/csvImportService');
const { sendAdminEmail } = require('../services/mailer');

const upload = multer({ dest: path.join(process.cwd(), 'uploads') });
const importQueue = new Queue('customer-import', config.redisUrl);

// Background worker
importQueue.process(async (job) => {
  const { filePath } = job.data;
  const result = await importCustomersFromCsv({
    filePath,
    parallelSanitize: true,
    onProgress: (p) => job.progress(p.total),
  });
  await sendAdminEmail({
    to: config.adminEmail,
    subject: 'Customer import completed',
    text: `Imported: ${result.imported}, Failed: ${result.failed}`,
  });
  try { fs.unlinkSync(filePath); } catch {}
  return result;
});

const router = express.Router();

router.post('/imports/customers', upload.single('file'), async (req, res, next) => {
  try {
    if (!req.file) return res.status(400).json({ error: 'CSV file is required (form field: file)' });
    const filePath = req.file.path;
    const job = await importQueue.add({ filePath }, { removeOnComplete: true, removeOnFail: true });
    // Immediate response to avoid request timeout
    res.status(202).json({ jobId: job.id, message: 'Import started' });
  } catch (e) {
    next(e);
  }
});

module.exports = router;
