// Notes:
// - Papa Parse is used in streaming mode via NODE_STREAM_INPUT for low memory usage.
// - Batching with backpressure avoids overwhelming the DB and keeps memory bounded.
// - worker_threads provide optional parallel sanitization for CPU-bound row normalization.
// - Bull (Redis) runs the import in the background; the HTTP request returns 202 immediately.
// - Robust error handling: input validation, recoverable vs. unrecoverable parse errors, per-batch DB try/catch, email failures logged not fatal.

Below is an incremental improvement of the earlier toy translator (SQL AST -> Relational Algebra AST) with focused error handling and practical notes about pitfalls. It includes:

- A stricter translation pipeline that validates tables, aliases, and columns.
- A basic name-resolution pass that qualifies unqualified columns and catches ambiguity.
- Clear exceptions for common problems (unknown/ambiguous columns, duplicate aliases, missing FROM, etc.).
- Examples of input SQL queries (as strings for readability) and their corresponding RA trees or raised errors.

Note: We still assume you start from an existing SQL AST, not raw SQL text. Small catalogs are optional but enable much better error messages.

```python
from __future__ import annotations
from dataclasses import dataclass
from typing import Dict, List, Optional, Set, Union

# ---------- Exceptions: explicit, precise messages ----------

class TranslationError(Exception):
    pass

class EmptyFromError(TranslationError):
    pass

class EmptySelectListError(TranslationError):
    pass

class DuplicateAliasError(TranslationError):
    pass

class UnknownTableError(TranslationError):
    pass

class UnknownColumnError(TranslationError):
    pass

class AmbiguousColumnError(TranslationError):
    pass

class UnsupportedFeatureError(TranslationError):
    pass


# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # qualified as table.column if given

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>'
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]  # or items including AllColumns()
    from_tables: List[TableRef]
    where: Optional[SQLExpr] = None


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]  # project expressions (and aliases) from SQL AST
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


# ---------- Helpers: expression traversal and name resolution ----------

def map_expr(e: SQLExpr, f) -> SQLExpr:
    """Post-order map over SQLExpr; applies f to each node, returns possibly transformed node."""
    if isinstance(e, Comparison):
        left = map_expr(e.left, f)
        right = map_expr(e.right, f)
        e = Comparison(e.op, left, right)
    elif isinstance(e, BooleanOp):
        left = map_expr(e.left, f)
        right = map_expr(e.right, f)
        e = BooleanOp(e.op, left, right)
    elif isinstance(e, Not):
        child = map_expr(e.expr, f)
        e = Not(child)
    elif isinstance(e, (Column, Literal, AllColumns)):
        pass
    else:
        raise UnsupportedFeatureError(f"Unsupported SQL expression node: {type(e).__name__}")
    return f(e)

class NameResolver:
    """
    Resolves unqualified columns to a unique table alias, validates existence of tables/columns,
    and catches ambiguity. If a catalog is provided, it enables strong column validation.
    """
    def __init__(self, from_tables: List[TableRef], catalog: Optional[Dict[str, Set[str]]] = None, strict: bool = True):
        self.from_tables = from_tables
        self.catalog = catalog
        self.strict = strict
        # alias_key -> table_name
        self.alias_to_table: Dict[str, str] = {}
        self._init_aliases()

    def _init_aliases(self) -> None:
        seen: Set[str] = set()
        for t in self.from_tables:
            alias_key = t.alias if t.alias else t.name
            if alias_key in seen:
                raise DuplicateAliasError(f"Duplicate table alias/name in FROM: '{alias_key}'")
            seen.add(alias_key)
            self.alias_to_table[alias_key] = t.name

    def check_tables_exist(self) -> None:
        if not self.catalog:
            return
        for tr in self.from_tables:
            if tr.name not in self.catalog:
                raise UnknownTableError(f"Unknown table '{tr.name}'")

    def _table_aliases(self) -> List[str]:
        # Return alias keys in input order (alias if present, else name)
        return [t.alias if t.alias else t.name for t in self.from_tables]

    def resolve_expr(self, e: SQLExpr) -> SQLExpr:
        def resolve(node: SQLExpr) -> SQLExpr:
            if not isinstance(node, Column):
                return node

            col = node
            # If qualified, ensure table exists in FROM and column exists (if catalog provided)
            if col.table:
                if col.table not in self.alias_to_table:
                    raise UnknownTableError(f"Unknown table or alias '{col.table}' in column '{col.table}.{col.name}'")
                if self.catalog and col.table in self.alias_to_table:
                    table_name = self.alias_to_table[col.table]
                    if table_name in self.catalog and self.strict and col.name not in self.catalog[table_name]:
                        raise UnknownColumnError(f"Unknown column '{col.table}.{col.name}'")
                return col

            # Unqualified: try to bind to exactly one table
            candidates: List[str] = []
            for alias in self._table_aliases():
                table_name = self.alias_to_table[alias]
                if not self.catalog:
                    candidates.append(alias)
                else:
                    # Only consider aliases whose base table has the column
                    if table_name in self.catalog and col.name in self.catalog[table_name]:
                        candidates.append(alias)

            if not candidates:
                # With no catalog, we cannot prove non-existence; in strict mode, require at least one table
                if self.catalog:
                    raise UnknownColumnError(f"Unknown unqualified column '{col.name}'")
                if len(self._table_aliases()) == 1:
                    return Column(name=col.name, table=self._table_aliases()[0])
                raise AmbiguousColumnError(
                    f"Unqualified column '{col.name}' cannot be resolved without a catalog in multi-table FROM"
                )

            if len(candidates) > 1:
                raise AmbiguousColumnError(f"Ambiguous column '{col.name}' (candidates: {', '.join(candidates)})")

            return Column(name=col.name, table=candidates[0])

        return map_expr(e, resolve)


# ---------- Translator with validation and error handling ----------

def build_from_tree(tables: List[TableRef]) -> RAExpr:
    if not tables:
        raise EmptyFromError("Missing FROM clause (no tables)")
    ra: RAExpr = RATable(tables[0].name, alias=(tables[0].alias or tables[0].name))
    for tr in tables[1:]:
        right = RATable(tr.name, alias=(tr.alias or tr.name))
        ra = RAProduct(ra, right)
    return ra


def translate_select(stmt: SelectStmt, catalog: Optional[Dict[str, Set[str]]] = None) -> RAExpr:
    # Basic validations
    if not stmt.select_list:
        raise EmptySelectListError("SELECT list must not be empty")

    resolver = NameResolver(stmt.from_tables, catalog=catalog, strict=True)
    resolver.check_tables_exist()

    # Build FROM (cross product for multiple tables)
    ra_tree = build_from_tree(stmt.from_tables)

    # WHERE (resolve and attach)
    if stmt.where is not None:
        resolved_where = resolver.resolve_expr(stmt.where)
        ra_tree = RASelection(predicate=resolved_where, child=ra_tree)

    # SELECT list (resolve expressions)
    if len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns):
        # Project-all: omit explicit projection node
        return ra_tree

    resolved_items = [
        SelectItem(expr=resolver.resolve_expr(item.expr), alias=item.alias)
        for item in stmt.select_list
    ]
    ra_tree = RAProjection(items=resolved_items, child=ra_tree)

    return ra_tree


# ---------- Examples: inputs and expected RA or errors ----------
if __name__ == "__main__":
    # Tiny catalog: table -> set(columns)
    catalog = {
        "users": {"id", "name", "age"},
        "orders": {"id", "user_id", "total"},
    }

    examples = [
        (
            "Basic single-table with WHERE",
            SelectStmt(
                select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
                from_tables=[TableRef("users", alias="u")],
                where=Comparison(">", Column("age"), Literal(18)),
            ),
        ),
        (
            "SELECT * from two tables (implicit cross product)",
            SelectStmt(
                select_list=[SelectItem(AllColumns())],
                from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
                where=None,
            ),
        ),
        (
            "Join-like WHERE with qualified columns",
            SelectStmt(
                select_list=[SelectItem(Column("name", table="u")), SelectItem(Column("total", table="o"))],
                from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
                where=Comparison("=", Column("id", table="u"), Column("user_id", table="o")),
            ),
        ),
        (
            "Ambiguous unqualified column across tables (should error)",
            SelectStmt(
                select_list=[SelectItem(Column("id"))],  # 'id' exists in both users and orders
                from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
                where=None,
            ),
        ),
        (
            "Unknown column (should error)",
            SelectStmt(
                select_list=[SelectItem(Column("nonexistent", table="u"))],
                from_tables=[TableRef("users", alias="u")],
                where=None,
            ),
        ),
    ]

    for title, stmt in examples:
        print("\n== ", title)
        try:
            ra = translate_select(stmt, catalog=catalog)
            print(ra_to_str(ra))
        except TranslationError as e:
            print("Error:", type(e).__name__, str(e))
```

Common pitfalls and notes:
- Ambiguous unqualified columns: In multi-table queries, an unqualified name may match multiple tables. Resolve with explicit qualifiers or raise AmbiguousColumnError.
- Missing or duplicate aliases: Two tables with the same alias/name in FROM cause confusion; detect early with DuplicateAliasError.
- Unknown tables/columns: With a catalog, report UnknownTableError/UnknownColumnError precisely. Without a catalog, be conservative; ambiguity often cannot be resolved.
- SELECT * handling: Often you can omit a projection node. If later you need column pruning or ordering, keep an explicit RAProjection even for *.
- Expression coverage: Keep an UnsupportedFeatureError for unimplemented SQL nodes (e.g., arithmetic, functions) so unsupported inputs fail fast with clear messages.
- Order of operations: Build FROM (possibly as Product), then Selection from WHERE, then Projection. This mirrors standard RA normalization and simplifies debugging.
- Error messaging: Include the offending identifier and context (table alias, column) to make debugging straightforward.

Example SQL-to-RA correspondences (conceptual):
- SQL: SELECT u.name, o.total FROM users AS u, orders AS o WHERE u.id = o.user_id
  RA: Project[u.name, o.total](Select[u.id = o.user_id](Product(Table(users AS u), Table(orders AS o))))
- SQL: SELECT * FROM users
  RA: Table(users)
- SQL: SELECT id FROM users AS u, orders AS o  -- ambiguous id
  Error: AmbiguousColumnError("Ambiguous column 'id' (candidates: u, o)")

Here’s a concise, hands-on introduction to a toy “query parser” that converts a pre-parsed SQL AST (Abstract Syntax Tree) into a relational algebra (RA) expression tree.

Key ideas:
- We do not parse SQL text. Instead, we start with Python objects that already represent the SQL query (SQL AST).
- We translate that SQL AST into a relational algebra AST using basic operators: Table (base relation), Selection (WHERE), Projection (SELECT), and Product (cross-product for multiple tables).
- We include examples of input SQL strings (for readability), the code that constructs their AST, and the resulting RA expressions.

Code and examples:

```python
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Optional

# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # e.g., "users.id" => Column(name="id", table="users")

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>', '<=', '>='
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]         # items in SELECT clause
    from_tables: List[TableRef]           # tables in FROM clause
    where: Optional[SQLExpr] = None       # optional WHERE predicate


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]  # project expressions (and aliases)
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


# ---------- Translator: SQL AST -> RA AST ----------

class TranslationError(Exception):
    pass

def fold_product(tables: List[TableRef]) -> RAExpr:
    assert len(tables) >= 1
    ra: RAExpr = RATable(tables[0].name, alias=tables[0].alias)
    for tr in tables[1:]:
        ra = RAProduct(left=ra, right=RATable(tr.name, alias=tr.alias))
    return ra

def translate_select(stmt: SelectStmt) -> RAExpr:
    # Basic validation
    if not stmt.from_tables:
        raise TranslationError("Missing FROM clause.")
    if not stmt.select_list:
        raise TranslationError("Empty SELECT list is not allowed.")

    # 1) FROM: single table or multiple tables => Product chain
    if len(stmt.from_tables) == 1:
        ra: RAExpr = RATable(name=stmt.from_tables[0].name, alias=stmt.from_tables[0].alias)
    else:
        ra = fold_product(stmt.from_tables)

    # 2) WHERE: add Selection
    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    # 3) SELECT: add Projection, unless it's SELECT *
    only_star = len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    if only_star:
        return RAProjection(items=[SelectItem(AllColumns())], child=ra)
    else:
        return RAProjection(items=stmt.select_list, child=ra)


# ---------- Examples (SQL input and RA output) ----------

if __name__ == "__main__":
    # Example 1
    # SQL: SELECT id, name FROM users WHERE age > 18;
    stmt1 = SelectStmt(
        select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
        from_tables=[TableRef("users")],
        where=Comparison(">", Column("age"), Literal(18)),
    )
    ra1 = translate_select(stmt1)
    print("SQL: SELECT id, name FROM users WHERE age > 18;")
    print(ra_to_str(ra1), end="\n\n")

    # Example 2
    # SQL: SELECT * FROM users;
    stmt2 = SelectStmt(
        select_list=[SelectItem(AllColumns())],
        from_tables=[TableRef("users")],
        where=None,
    )
    ra2 = translate_select(stmt2)
    print("SQL: SELECT * FROM users;")
    print(ra_to_str(ra2), end="\n\n")

    # Example 3 (multi-table with join condition expressed in WHERE)
    # SQL:
    #   SELECT u.id, o.total
    #   FROM users AS u, orders AS o
    #   WHERE u.id = o.user_id AND o.total > 100;
    stmt3 = SelectStmt(
        select_list=[SelectItem(Column("id", table="u")), SelectItem(Column("total", table="o"))],
        from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
        where=BooleanOp(
            "AND",
            left=Comparison("=", Column("id", "u"), Column("user_id", "o")),
            right=Comparison(">", Column("total", "o"), Literal(100)),
        ),
    )
    ra3 = translate_select(stmt3)
    print("SQL: SELECT u.id, o.total FROM users AS u, orders AS o WHERE u.id = o.user_id AND o.total > 100;")
    print(ra_to_str(ra3), end="\n\n")
```

Under the hood:
- FROM builds RATable or a left-deep RAProduct chain.
- WHERE wraps it with RASelection.
- SELECT wraps it with RAProjection (we explicitly keep Project[*] to show the projection stage for SELECT *).

Common pitfalls to watch for next steps (not implemented here):
- Ambiguous unqualified columns when multiple tables are present.
- Distinguishing explicit JOIN syntax vs comma-join lowered to Product + Selection.
- Handling aggregates, GROUP BY/ORDER BY, and NULL semantics.

Below is a focused, end-to-end plan to move a .NET/SQL lookup service to a Nest.js (Express) microservice with an optional MongoDB backend. It starts with an in-memory XML ingest (fastest path, no DB) and cleanly upgrades to Mongo when needed—without changing the API. It also includes containerization and a reference deployment pipeline.

High-level migration plan
- Phase 0: Discovery and contract
  - Inventory current endpoints, response shapes, error semantics, clients, SLAs.
  - Extract canonical data shape from SQL/XML; list lookup fields and primary key.
  - Decide normalization rules (trim, lowercase, Unicode, “00123” kept as string).
  - Define acceptance: API parity on golden set, latency targets, readiness/health.

- Phase 1: In-memory Nest.js service (no DB)
  - Build a Nest service that:
    - Parses XML at startup and builds in-memory indexes by primary and lookup fields.
    - Exposes: GET /lookup, GET /lookup/fields, GET /lookup/count, GET /health.
    - Supports POST /lookup/reload with admin token; atomic index swap to avoid downtime.
  - Add normalization to match legacy lookup semantics.
  - Optional: file watch with debounced auto-reload.

- Phase 2: MongoDB option and ETL
  - Add USE_MONGO toggle; when true, use Mongo with indexes on same fields.
  - Implement XML→Mongo ETL (and optional SQL→Mongo) to seed data.
  - Keep identical HTTP contract in both modes.

- Phase 3: Hardening
  - Input validation (allowlist of fields), rate limiting (if external), structured logs.
  - Metrics (RPS, latency, reload duration, heap), tracing IDs in logs.
  - Readiness gate: only ready after in-memory index is loaded or Mongo connected.
  - Security: gate admin reload with token; optional API key/JWT guard.

- Phase 4: Containerization and CI/CD
  - Multi-stage Dockerfile; set Node heap below container memory limit.
  - docker-compose for local; Kubernetes manifests for prod (Deployment, Service).
  - CI pipeline: build, test, scan, push image, deploy to non-prod and prod.

- Phase 5: Rollout
  - Shadow compare against .NET; capture diffs on a golden sample.
  - Canary 5–10% traffic; monitor latency/errors/heap.
  - Full cutover; keep feature flag to roll back quickly.

- Phase 6: Decommission and tidy-up
  - Remove shadow, finalize runbooks/dashboards/alerts, decommission legacy infra.

Key risks and mitigations
- Data model mismatch: Normalize and keep strict: false in Mongo initially; tighten later.
- Normalization parity: Lock rules early; enforce at both index and query.
- Memory growth: Start in-memory; move to Mongo or partial indexing as data grows.
- Reload safety: Parse+validate to temp store; swap only if valid.

