tools/xml_to_mongo.ts (ETL)
```python
import { XMLParser } from 'fast-xml-parser';
import { MongoClient } from 'mongodb';
import { readFile } from 'fs/promises';

async function main() {
  const uri = process.env.MONGO_URI!;
  const dbName = process.env.MONGO_DB || 'lookupdb';
  const colName = process.env.MONGO_COLLECTION || 'records';
  const pk = process.env.PRIMARY_KEY_FIELD || 'id';
  const xmlPath = process.env.XML_PATH || './data/records.xml';
  const recordPath = process.env.XML_RECORD_PATH || 'records.record';

  const xml = await readFile(xmlPath, 'utf-8');
  const parser = new XMLParser({ ignoreAttributes: false, trimValues: true });
  const parsed = parser.parse(xml);
  const records = recordPath.split('.').reduce((a, k) => (a ? a[k] : undefined), parsed);
  if (!Array.isArray(records)) throw new Error('recordPath did not resolve to array');

  const client = new MongoClient(uri);
  await client.connect();
  const col = client.db(dbName).collection(colName);
  await col.deleteMany({});
  // normalize keys minimally to preserve string semantics (e.g., leading zeros)
  const docs = records.map((r: any) => ({ ...r, [pk]: r[pk] }));
  await col.insertMany(docs, { ordered: false });
  await col.createIndex({ [pk]: 1 }, { name: `idx_${pk}` });
  const extra = (process.env.LOOKUP_INDEX_FIELDS || 'code').split(',').map(s => s.trim()).filter(Boolean);
  for (const f of extra) await col.createIndex({ [f]: 1 }, { name: `idx_${f}` });
  await client.close();
}

main().catch(err => { console.error(err); process.exit(1); });
