static const char* BASE32_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

static bool base32_decode(const std::string& in, std::vector<uint8_t>& out) {
    // RFC 4648 base32 without padding for onion/ed25519 keys
    std::vector<int> map(256, -1);
    for (int i = 0; i < 32; ++i) map[(unsigned char)BASE32_ALPHABET[i]] = i;
    for (int i = 0; i < 32; ++i) map[(unsigned char)tolower(BASE32_ALPHABET[i])] = i;

    int buffer = 0, bitsLeft = 0;
    out.clear();
    for (unsigned char c : in) {
        if (c == '=') break;
        int val = map[c];
        if (val < 0) return false;
        buffer = (buffer << 5) | val;
        bitsLeft += 5;
        if (bitsLeft >= 8) {
            bitsLeft -= 8;
            out.push_back((uint8_t)((buffer >> bitsLeft) & 0xFF));
        }
    }
    return true;
}

static std::string base32_encode(const uint8_t* data, size_t len) {
    std::string out;
    int buffer = 0;
    int bitsLeft = 0;
    for (size_t i = 0; i < len; ++i) {
        buffer = (buffer << 8) | data[i];
        bitsLeft += 8;
        while (bitsLeft >= 5) {
            int val = (buffer >> (bitsLeft - 5)) & 0x1F;
            bitsLeft -= 5;
            out.push_back(BASE32_ALPHABET[val]);
        }
    }
    if (bitsLeft > 0) {
        int val = (buffer << (5 - bitsLeft)) & 0x1F;
        out.push_back(BASE32_ALPHABET[val]);
    }
    // No padding for onion
    return out;
}

static bool base64_decode(const std::string& in, std::vector<uint8_t>& out) {
    BIO* b64 = BIO_new(BIO_f_base64());
    if (!b64) return false;
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    BIO* bio = BIO_new_mem_buf(in.data(), (int)in.size());
    if (!bio) { BIO_free(b64); return false; }
    bio = BIO_push(b64, bio);
    out.resize(in.size());
    int len = BIO_read(bio, out.data(), (int)out.size());
    if (len < 0) { BIO_free_all(bio); return false; }
    out.resize((size_t)len);
    BIO_free_all(bio);
    return true;
}

static std::string hex(const uint8_t* d, size_t n) {
