struct HttpResponse {
    DWORD status = 0;
    std::vector<uint8_t> body;
    std::wstring headers;
};

static bool http_get_ip_insecure(const std::string& ip, int port, const std::wstring& host_for_sni, const std::wstring& path, HttpResponse& out) {
    // Insecure: disable certificate validation and connect by IP only.
    HINTERNET hSession = WinHttpOpen(L"TorProtoStub/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                     WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0);
    if (!hSession) { log_err("WinHttpOpen", lastErrorMessage()); return false; }

    HINTERNET hConnect = WinHttpConnect(hSession, std::wstring(ip.begin(), ip.end()).c_str(), (INTERNET_PORT)port, 0);
    if (!hConnect) { log_err("WinHttpConnect", lastErrorMessage()); WinHttpCloseHandle(hSession); return false; }

    HINTERNET hRequest = WinHttpOpenRequest(hConnect, L"GET", path.c_str(),
                                            NULL, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES,
                                            (port == 443 ? WINHTTP_FLAG_SECURE : 0));
    if (!hRequest) {
        log_err("WinHttpOpenRequest", lastErrorMessage());
        WinHttpCloseHandle(hConnect);
        WinHttpCloseHandle(hSession);
        return false;
    }

    // Disable SSL verification (INSECURE, for demo only)
    DWORD flags = SECURITY_FLAG_IGNORE_CERT_CN_INVALID
                | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID
                | SECURITY_FLAG_IGNORE_UNKNOWN_CA
                | SECURITY_FLAG_IGNORE_CERT_WRONG_USAGE;
    WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &flags, sizeof(flags));

    // Force Host header/SNI
    if (!host_for_sni.empty()) {
        WinHttpSetOption(hRequest, WINHTTP_OPTION_DISABLE_FEATURE, (LPVOID)&(DWORD){WINHTTP_DISABLE_COOKIES}, sizeof(DWORD));
        BOOL r = WinHttpSetOption(hRequest, WINHTTP_OPTION_SERVER_SPN_USED, (LPVOID)L"", sizeof(L""));
        (void)r;
        WinHttpAddRequestHeaders(hRequest, (L"Host: " + host_for_sni + L"\r\n").c_str(), -1L, WINHTTP_ADDREQ_FLAG_ADD | WINHTTP_ADDREQ_FLAG_REPLACE);
        WinHttpSetOption(hRequest, WINHTTP_OPTION_UPGRADE_TO_HTTP2, &(BOOL){FALSE}, sizeof(BOOL));
        WinHttpSetOption(hRequest, WINHTTP_OPTION_ENABLE_HTTP_PROTOCOL, (LPVOID)&(DWORD){WINHTTP_PROTOCOL_FLAG_HTTP2}, sizeof(DWORD)); // won't enable without ALPN/cert, but harmless.
        // SNI override
        WinHttpSetOption(hRequest, WINHTTP_OPTION_SERVER_CERT_CONTEXT, NULL, 0); // no-op; we rely on ignore flags
        WinHttpSetOption(hRequest, WINHTTP_OPTION_CLIENT_CERT_CONTEXT, NULL, 0);
        WinHttpSetOption(hRequest, WINHTTP_OPTION_URL, (LPVOID)path.c_str(), (DWORD)((path.size() + 1) * sizeof(wchar_t)));
        WinHttpSetOption(hRequest, WINHTTP_OPTION_DECOMPRESSION, (LPVOID)&(DWORD){WINHTTP_DECOMPRESSION_FLAG_GZIP | WINHTTP_DECOMPRESSION_FLAG_DEFLATE}, sizeof(DWORD));
    }

    BOOL bResults = WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0,
                                       WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
    if (!bResults) {
        log_err("WinHttpSendRequest", lastErrorMessage());
        WinHttpCloseHandle(hRequest);
        WinHttpCloseHandle(hConnect);
        WinHttpCloseHandle(hSession);
        return false;
    }
    bResults = WinHttpReceiveResponse(hRequest, NULL);
    if (!bResults) {
        log_err("WinHttpReceiveResponse", lastErrorMessage());
        WinHttpCloseHandle(hRequest);
        WinHttpCloseHandle(hConnect);
        WinHttpCloseHandle(hSession);
        return false;
    }

    DWORD status = 0, size = sizeof(status);
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &status, &size, WINHTTP_NO_HEADER_INDEX);
    out.status = status;

    DWORD dwSize = 0;
    std::vector<uint8_t> buf;
    for (;;) {
        dwSize = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &dwSize)) {
            log_err("WinHttpQueryDataAvailable", lastErrorMessage());
            break;
        }
        if (dwSize == 0) break;
        size_t old = buf.size();
        buf.resize(old + dwSize);
        DWORD dwRead = 0;
        if (!WinHttpReadData(hRequest, buf.data() + old, dwSize, &dwRead)) {
            log_err("WinHttpReadData", lastErrorMessage());
            break;
        }
        buf.resize(old + dwRead);
    }
    out.body = std::move(buf);

    // headers
    DWORD hdrSize = 0;
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, WINHTTP_NO_OUTPUT_BUFFER, &hdrSize, WINHTTP_NO_HEADER_INDEX);
    if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
        std::wstring hdrs;
        hdrs.resize(hdrSize / sizeof(wchar_t));
        if (WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_RAW_HEADERS_CRLF, WINHTTP_HEADER_NAME_BY_INDEX, hdrs.data(), &hdrSize, WINHTTP_NO_HEADER_INDEX)) {
            out.headers = hdrs;
        }
    }

    WinHttpCloseHandle(hRequest);
    WinHttpCloseHandle(hConnect);
    WinHttpCloseHandle(hSession);
    return true;
}

// ==============================
// Tor data models (simplified)
// ==============================

struct Relay {
    std::string nickname;
    std::string ipv4; // connect by IP only
    uint16_t orport = 0;
    uint16_t dirport = 0; // may be 0; many relays disable DirPort
    std::vector<uint8_t> ed25519_id; // 32 bytes
    std::vector<uint8_t> rsa_fingerprint; // 20 bytes digest of RSA identity (legacy) if available
    bool guard = false;
    bool exit_eligible = false;
    bool hsdir = false;
};

struct Consensus {
    std::vector<Relay> relays;
};

// ==============================
// Consensus download and parsing (microdescs flavor URL, but this endpoint serves consensus text)
// ==============================

static bool parse_consensus_text(const std::string& txt, Consensus& out) {
    // Very simplified parser: extracts relays from 'r ' and 's ' and 'w ' lines; looks for 'a ' line with IPv4/ORPort
    // Does NOT validate signatures or vote weights. For demo only.
    // Tor consensus lines doc: https://spec.torproject.org/dir-spec/consensus-format.html
    std::istringstream iss(txt);
    std::string line;
    Relay cur;
    bool in_router = false;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("r ", 0) == 0) {
            // new router
            if (in_router) {
                out.relays.push_back(cur);
            }
            in_router = true;
            cur = Relay();
            // fields: r nickname identity digest publication IP ORPort DirPort
            // identity digest are legacy RSA fingerprint in base64? In "r" line the identity and digest are base64-encoded hashes of the RSA identity and descriptor. We mostly need IP/ORPort and flags later.
            std::istringstream rs(line.substr(2));
            rs >> cur.nickname;
            std::string id_b64, sdesc_b64, pub1, pub2;
            rs >> id_b64 >> sdesc_b64 >> pub1 >> pub2 >> cur.ipv4 >> cur.orport >> cur.dirport;
            // best effort: decode RSA identity from base64 (should be 20 bytes)
            std::vector<uint8_t> idraw;
            base64_decode(id_b64, idraw);
            cur.rsa_fingerprint = idraw;
        } else if (line.rfind("s ", 0) == 0 && in_router) {
            // flags, e.g. "s Exit Fast HSDir Running Stable V2Dir Valid"
            // mark guard/exit/hsdir
            std::istringstream fs(line.substr(2));
            std::string f;
            while (fs >> f) {
                if (f == "Guard") cur.guard = true;
                if (f == "Exit") cur.exit_eligible = true;
                if (f == "HSDir") cur.hsdir = true;
            }
        } else if (line.rfind("a ", 0) == 0 && in_router) {
            // alternative address lines, e.g., "a 2001:db8::1" or IP:port; we ignore for now.
        } else if (line.rfind("id ed25519 ", 0) == 0 && in_router) {
            // ed25519 identity is base64 encoded 32 bytes
            std::string b64 = line.substr(strlen("id ed25519 "));
            std::vector<uint8_t> raw;
            if (base64_decode(b64, raw) && raw.size() == 32) {
                cur.ed25519_id = raw;
            }
        } else if (line.rfind("w ", 0) == 0) {
            // bandwidth weights (ignored for now)
        } else if (!in_router) {
            // header lines ignored
        } else if (line.empty()) {
            // separator
        }
    }
    if (in_router) out.relays.push_back(cur);
    // Filter out entries without IP/ORPort
    out.relays.erase(std::remove_if(out.relays.begin(), out.relays.end(),
        [](const Relay& r){ return r.ipv4.empty() || r.orport == 0; }), out.relays.end());
    return !out.relays.empty();
}

static bool download_and_parse_consensus(const std::string& authority_ip, const std::wstring& sni_host, Consensus& out) {
    HttpResponse resp;
    // Insecure: connect by IP over HTTPS, disable cert validation, set fake SNI/Host header
    if (!http_get_ip_insecure(authority_ip, 443, sni_host, L"/tor/status-vote/current/consensus", resp)) {
        log_err("download_consensus", "HTTP GET failed");
        return false;
    }
    if (resp.status != 200) {
        log_err("download_consensus", "HTTP status " + std::to_string(resp.status));
        return false;
    }
    std::string body(resp.body.begin(), resp.body.end());
    if (!parse_consensus_text(body, out)) {
        log_err("parse_consensus", "Failed or empty");
        return false;
    }
    log_info("consensus", "Parsed " + std::to_string(out.relays.size()) + " relays");
    return true;
}

// ==============================
// HSDir index computation for v3 descriptors
// ==============================

// v3 onion address is base32 of: PUBKEY(32) | checksum(2) | version(1), where version=3
// For HSDir index, one needs time-period calculation and blake2/sha3 depending on spec versions.
// For simplicity we outline the computation and provide a placeholder that returns an index.
// TODO: Implement full v3 HSDir index (see rend-spec-v3.txt: "HSDir selection")
// We provide the structure and compute a mock-ish index using SHA3-256 over onion pubkey+period.
static bool onion_address_to_pubkey32(const std::string& onion56, std::vector<uint8_t>& pubkey32) {
    // Decode base32, expect 35 bytes: 32 pubkey + 2 checksum + 1 version
    std::vector<uint8_t> raw;
    if (!base32_decode(onion56, raw)) return false;
    if (raw.size() != 35) return false;
    if (raw[34] != 3) return false;
    pubkey32.assign(raw.begin(), raw.begin() + 32);
    // TODO: verify checksum per spec: checksum = SHA3-256("hs3" | pubkey | version)[:2]
    return true;
}

static uint64_t current_time_period(uint64_t now) {
    // v3 default time period is 24 hours and offset. For demo: 24h.
    // TODO: Implement exact offset and period per spec (using SRV_TIME_PERIOD)
    return now / (24 * 60 * 60);
}

static std::array<uint8_t,32> sha3_256(const uint8_t* d, size_t n) {
    std::array<uint8_t,32> out{};
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr);
    EVP_DigestUpdate(ctx, d, n);
    unsigned int l=0;
    EVP_DigestFinal_ex(ctx, out.data(), &l);
    EVP_MD_CTX_free(ctx);
    return out;
}

static uint64_t hsdir_index_for_onion(const std::vector<uint8_t>& pubkey32, uint64_t tp) {
    // TODO: Use exact "hsdir_index" computation per spec (including blinding and replica)
    // Placeholder: index = first 8 bytes of SHA3-256(pubkey32 || tp_be)
    uint8_t buf[32+8];
    memcpy(buf, pubkey32.data(), 32);
    for (int i=0;i<8;i++) buf[32+i] = (uint8_t)((tp >> (56 - 8*i)) & 0xFF);
    auto h = sha3_256(buf, sizeof(buf));
    uint64_t x=0;
    for (int i=0;i<8;i++) x = (x<<8) | h[i];
    return x;
}

// Select N HSDir relays closest to target index using ed25519 identity as ring position (spec uses "hsdir_identity" hashing).
// Here we approximate using the relay's ed25519 id (if missing, skip).
static std::vector<Relay> select_hsdirs(const Consensus& con, uint64_t index, size_t need) {
    struct Item { Relay r; uint64_t pos; uint64_t dist; };
    std::vector<Item> items;
    for (const auto& r : con.relays) {
        if (!r.hsdir || r.dirport == 0 || r.ed25519_id.size() != 32) continue;
        auto h = sha3_256(r.ed25519_id.data(), r.ed25519_id.size());
        uint64_t pos=0;
        for (int i=0;i<8;i++) pos = (pos<<8) | h[i];
        uint64_t dist = (pos >= index) ? (pos - index) : (UINT64_MAX - (index - pos) + 1);
        items.push_back({r,pos,dist});
    }
    std::sort(items.begin(), items.end(), [](const Item& a, const Item& b){ return a.dist < b.dist; });
    std::vector<Relay> out;
    for (size_t i=0; i<items.size() && out.size()<need; ++i) out.push_back(items[i].r);
    return out;
}

