static const uint16_t RELAY_EXTEND2 = 14;
static const uint16_t RELAY_EXTENDED2 = 15;
static const uint16_t RELAY_BEGIN_DIR = 13;

struct TlsConn {
    SSL_CTX* ctx = nullptr;
    SSL* ssl = nullptr;
    BIO* rbio = nullptr;
    BIO* wbio = nullptr;
    SOCKET sock = INVALID_SOCKET;
};

static bool tcp_connect_ip(const std::string& ip, uint16_t port, SOCKET& s) {
    s = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (s == INVALID_SOCKET) { log_err("socket", lastErrorMessage()); return false; }
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip.c_str(), &addr.sin_addr) != 1) {
        log_err("inet_pton", "Invalid IP");
        closesocket(s); s = INVALID_SOCKET;
        return false;
    }
    if (connect(s, (sockaddr*)&addr, sizeof(addr)) != 0) {
        log_err("connect", lastErrorMessage());
        closesocket(s); s = INVALID_SOCKET;
        return false;
    }
    return true;
}

static bool tls_connect_insecure(const std::string& ip, uint16_t port, TlsConn& out) {
    openssl_init();
    SOCKET s;
    if (!tcp_connect_ip(ip, port, s)) return false;
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) { log_err("SSL_CTX_new", openssl_err()); closesocket(s); return false; }
    // Insecure: no cert validation, no SNI
    SSL_CTX_set_verify(ctx, SSL_VERIFY_NONE, nullptr);

    SSL* ssl = SSL_new(ctx);
    if (!ssl) { log_err("SSL_new", openssl_err()); SSL_CTX_free(ctx); closesocket(s); return false; }
    BIO* sbio = BIO_new_socket((int)s, BIO_NOCLOSE);
    if (!sbio) { log_err("BIO_new_socket", openssl_err()); SSL_free(ssl); SSL_CTX_free(ctx); closesocket(s); return false; }
    SSL_set_bio(ssl, sbio, sbio);

    if (SSL_connect(ssl) != 1) {
        log_err("SSL_connect", openssl_err());
        SSL_free(ssl); SSL_CTX_free(ctx); closesocket(s); return false;
    }
    out.ctx = ctx; out.ssl = ssl; out.sock = s;
    return true;
}

static void tls_close(TlsConn& c) {
    if (c.ssl) SSL_shutdown(c.ssl);
    if (c.ssl) SSL_free(c.ssl);
    if (c.ctx) SSL_CTX_free(c.ctx);
    if (c.sock != INVALID_SOCKET) closesocket(c.sock);
    c = TlsConn{};
}

