struct Circuit {
    // placeholders
    bool open = false;
    Relay guard, middle, exitr;
    TlsConn guard_tls, middle_tls, exit_tls; // In reality only one TLS (to guard); rest via relay cells.
    // But stub opens TCP+TLS to every hop just for demo, which is NOT how Tor works.
};

static bool pick_relays(const Consensus& c, Relay& guard, Relay& mid, Relay& exitr) {
    std::vector<Relay> guards, mids, exits;
    for (const auto& r : c.relays) {
        if (r.guard) guards.push_back(r);
        if (r.exit_eligible) exits.push_back(r);
        // consider all as middle if running/valid assumed; here we re-use non-exit/guard too
        mids.push_back(r);
    }
    if (guards.size() < 3 || mids.size() < 3 || exits.size() < 3) {
        log_warn("pick_relays", "Not enough relays with desired flags; picking best-effort.");
    }
    auto pick = [](const std::vector<Relay>& v)->Relay {
        if (v.empty()) return Relay();
        return v[rand() % v.size()];
    };
    guard = pick(guards.empty() ? c.relays : guards);
    mid = pick(mids);
    exitr = pick(exits.empty() ? c.relays : exits);
    if (guard.ipv4.empty() || mid.ipv4.empty() || exitr.ipv4.empty()) return false;
    return true;
}

static bool build_circuit_stub(const Consensus& con, Circuit& circ) {
    Relay g, m, e;
    if (!pick_relays(con, g, m, e)) {
        log_err("circuit", "Failed to pick relays");
        return false;
    }
    log_info("circuit", "Selected guard=" + g.ipv4 + ":" + std::to_string(g.orport) +
            " middle=" + m.ipv4 + ":" + std::to_string(m.orport) +
            " exit=" + e.ipv4 + ":" + std::to_string(e.orport));

    // Stub: open TLS connections to each hop directly (NOT actual Tor behavior).
    // Actual Tor: only one TLS to guard; CREATE2 to build circuit; EXTEND2 to add m and e.
    if (!tls_connect_insecure(g.ipv4, g.orport, circ.guard_tls)) {
        log_err("circuit", "TLS to guard failed");
        return false;
    }
    if (!tls_connect_insecure(m.ipv4, m.orport, circ.middle_tls)) {
        log_warn("circuit", "TLS to middle failed (stub continues)");
    }
    if (!tls_connect_insecure(e.ipv4, e.orport, circ.exit_tls)) {
        log_warn("circuit", "TLS to exit failed (stub continues)");
    }
    circ.guard = g; circ.middle = m; circ.exitr = e;
    circ.open = true; // Stub marks as open
    log_warn("circuit", "Circuit marked open (stub). NTor/relay crypto NOT implemented.");
    return true;
}

