static void usage() {
    printf("Usage: tor_client_stub.exe <onion_address_56chars> [authority_ip] [authority_host]\n");
    printf("Defaults: authority_ip=128.31.0.39 authority_host=tor-authority.example\n");
    printf("WARNING: Insecure demo (no cert validation), many Tor protocol parts are stubs.\n");
}

int main(int argc, char** argv) {
    openssl_init();
    WSADATA wsa;
    if (WSAStartup(MAKEWORD(2,2), &wsa) != 0) {
        log_err("WSAStartup", "failed");
        return 1;
    }

    std::string onion56;
    std::string authority_ip = "128.31.0.39";
    std::wstring authority_host = L"tor-authority.example";
    if (argc < 2) {
        usage();
        WSACleanup();
        return 1;
    }
    onion56 = argv[1];
    if (onion56.size() != 56) {
        log_err("args", "onion_address must be 56 chars (no .onion)");
        WSACleanup();
        return 1;
    }
    if (argc >= 3) authority_ip = argv[2];
    if (argc >= 4) {
        std::string tmp = argv[3];
        authority_host = std::wstring(tmp.begin(), tmp.end());
    }

    Consensus con;
    if (!download_and_parse_consensus(authority_ip, authority_host, con)) {
        log_err("main", "Failed to get consensus");
        WSACleanup();
        return 1;
    }

    // Collect at least 3 guards, 3 middles, 3 exits (best effort)
    int gcount=0, mcount=0, ecount=0;
    for (const auto& r : con.relays) {
        if (r.guard) ++gcount;
        if (r.exit_eligible) ++ecount;
        ++mcount; // all relays can be middles for this simplified count
    }
    log_info("main", "Counts: guards=" + std::to_string(gcount) + " middles=" + std::to_string(mcount) + " exits=" + std::to_string(ecount));

    HSDescriptor desc;
    if (!fetch_hs_descriptor_v3(con, onion56, desc)) {
        log_warn("main", "HS descriptor fetch failed or parse stubbed; continuing with stubs.");
    }

    Circuit circ;
    if (!build_circuit_stub(con, circ)) {
        log_err("main", "Failed to build circuit (stub)");
        WSACleanup();
        return 1;
    }

    if (!rendezvous_with_service_stub(desc, onion56, circ)) {
        log_err("main", "Rendezvous failed (stub)");
        WSACleanup();
        return 1;
    }

    std::string get_body, post_body;
    if (!http_get_post_over_tor_stub(circ, "/", "/post", "name=value", get_body, post_body)) {
        log_err("main", "HTTP over Tor stream failed (stub)");
        WSACleanup();
        return 1;
    }
    printf("GET body:\n%s\n\n", get_body.c_str());
    printf("POST body:\n%s\n", post_body.c_str());

    // Cleanup
    tls_close(circ.guard_tls);
    tls_close(circ.middle_tls);
    tls_close(circ.exit_tls);
    WSACleanup();
    return 0;
}
