// Simple error helper
static std::string LastErrorMessage(DWORD err = GetLastError()) {
    LPWSTR buf = nullptr;
    DWORD len = FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_FROM_SYSTEM|FORMAT_MESSAGE_IGNORE_INSERTS,
                               nullptr, err, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT), (LPWSTR)&buf, 0, nullptr);
    std::wstring wmsg = (len && buf) ? std::wstring(buf, len) : L"Unknown error";
    if (buf) LocalFree(buf);
    int utf8len = WideCharToMultiByte(CP_UTF8, 0, wmsg.c_str(), (int)wmsg.size(), nullptr, 0, nullptr, nullptr);
    std::string out(utf8len, '\0');
    WideCharToMultiByte(CP_UTF8, 0, wmsg.c_str(), (int)wmsg.size(), out.data(), utf8len, nullptr, nullptr);
    return out;
}

