// Minimal Base32 (RFC4648) encode for readability; Tor uses base32 with lowercase no padding.
static const char* B32_ALPH = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
std::string Base32Encode(const std::vector<uint8_t>& data, bool lowercase=true, bool pad=false){
    std::string out;
    size_t i=0; uint32_t buffer=0; int bitsLeft=0;
    while (i < data.size()){
        buffer = (buffer<<8) | data[i++];
        bitsLeft += 8;
        while (bitsLeft >= 5){
            int idx = (buffer >> (bitsLeft-5)) & 0x1F;
            out.push_back(B32_ALPH[idx]);
            bitsLeft -= 5;
        }
    }
    if (bitsLeft){
        int idx = (buffer << (5-bitsLeft)) & 0x1F;
        out.push_back(B32_ALPH[idx]);
    }
    if (lowercase){ for (auto& c: out) c = (char)tolower((unsigned char)c); }
    if (pad){ while(out.size()%8) out.push_back('='); }
    return out;
}

// WinHTTP helper to perform HTTPS GET/POST and return body as string
struct HttpResponse { DWORD status=0; std::string body; };

std::optional<HttpResponse> WinHttpRequest(const std::wstring& host, INTERNET_PORT port,
                                           const std::wstring& path, bool useTLS,
                                           const std::wstring& method,
                                           const std::string& requestBody = std::string(),
                                           const std::wstring& headers = L"Accept: */*\r\nUser-Agent: WinHTTP-Tor-Scaffold/1.0\r\n")
{
    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP-Tor-Scaffold/1.0",
                                       WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME,
                                       WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::cerr << "WinHttpOpen failed: " << LastErrorMessage() << "\n"; return std::nullopt; }

    WinHttpHandle hConnect(WinHttpConnect(hSession, host.c_str(), port, 0));
    if (!hConnect) { std::cerr << "WinHttpConnect failed: " << LastErrorMessage() << "\n"; return std::nullopt; }

    DWORD flags = useTLS ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), path.c_str(), nullptr,
                                              WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES,
                                              flags));
    if (!hRequest) { std::cerr << "WinHttpOpenRequest failed: " << LastErrorMessage() << "\n"; return std::nullopt; }

    // Harden TLS a bit
    DWORD secureFlags = SECURITY_FLAG_IGNORE_UNKNOWN_CA; // For demo only; in production validate properly.
    WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &secureFlags, sizeof(secureFlags));

    BOOL bOK = TRUE;
    if (!requestBody.empty()){
        bOK = WinHttpSendRequest(hRequest, headers.c_str(), (DWORD)-1L,
                                 (LPVOID)requestBody.data(), (DWORD)requestBody.size(), (DWORD)requestBody.size(), 0);
    } else {
        bOK = WinHttpSendRequest(hRequest, headers.c_str(), (DWORD)-1L, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
    }
    if (!bOK) { std::cerr << "WinHttpSendRequest failed: " << LastErrorMessage() << "\n"; return std::nullopt; }

    if (!WinHttpReceiveResponse(hRequest, nullptr)){
        std::cerr << "WinHttpReceiveResponse failed: " << LastErrorMessage() << "\n"; return std::nullopt; }

    DWORD statusCode=0; DWORD len=sizeof(statusCode);
    if (!WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
                             WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &len, WINHTTP_NO_HEADER_INDEX)){
        std::cerr << "WinHttpQueryHeaders(status) failed: " << LastErrorMessage() << "\n";
    }

    std::string body;
    for(;;){
        DWORD avail=0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)){
            std::cerr << "WinHttpQueryDataAvailable failed: " << LastErrorMessage() << "\n"; break; }
        if (avail==0) break;
        std::string chunk(avail, '\0');
        DWORD read=0;
        if (!WinHttpReadData(hRequest, chunk.data(), avail, &read)){
            std::cerr << "WinHttpReadData failed: " << LastErrorMessage() << "\n"; break; }
        chunk.resize(read);
        body.append(chunk);
    }

    return HttpResponse{statusCode, body};
}

