// Simple Base64 decode via OpenSSL BIO
static bool Base64Decode(const std::string& in, std::vector<unsigned char>& out) {
    out.clear();
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* bio = BIO_new_mem_buf(in.data(), (int)in.size());
    if (!b64 || !bio) { if (b64) BIO_free(b64); if (bio) BIO_free(bio); return false; }
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    bio = BIO_push(b64, bio);
    std::vector<unsigned char> buf(in.size());
    int n = BIO_read(bio, buf.data(), (int)buf.size());
    BIO_free_all(bio);
    if (n <= 0) return false;
    buf.resize((size_t)n);
    out.swap(buf);
    return true;
}

// Minimal HTTP GET/POST via WinHTTP (direct, no Tor). Used here to download plaintext docs.
static bool HttpRequest(const std::wstring& method,
                        const std::wstring& url,
                        const std::string* body,
                        std::string& out_body,
                        int* http_status) {
    out_body.clear(); if (http_status) *http_status = 0;

    URL_COMPONENTS uc{}; uc.dwStructSize = sizeof(uc);
    std::wstring host; std::wstring path; INTERNET_PORT port = 0; bool https = false;
    wchar_t host_buf[512] = {0}; wchar_t path_buf[2048] = {0};
    uc.lpszHostName = host_buf; uc.dwHostNameLength = ARRAYSIZE(host_buf);
    uc.lpszUrlPath = path_buf;  uc.dwUrlPathLength  = ARRAYSIZE(path_buf);

    if (!WinHttpCrackUrl(url.c_str(), (DWORD)url.size(), 0, &uc)) {
        std::wcerr << L"WinHttpCrackUrl failed: " << FormatLastError() << L"\n"; return false;
    }
    host.assign(uc.lpszHostName, uc.dwHostNameLength);
    path.assign(uc.lpszUrlPath, uc.dwUrlPathLength);
    https = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    port  = uc.nPort ? uc.nPort : (https ? 443 : 80);

    WinHttpHandle hSession(WinHttpOpen(L"WinHTTP/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }

    WinHttpHandle hConnect(WinHttpConnect(hSession, host.c_str(), port, 0));
    if (!hConnect) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }

    DWORD flags = https ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), path.c_str(), nullptr,
                                              WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    if (https) {
        DWORD sec_flags = SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_CN_INVALID |
                          SECURITY_FLAG_IGNORE_CERT_DATE_INVALID | SECURITY_FLAG_IGNORE_CERT_WRONG_USAGE;
        WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &sec_flags, sizeof(sec_flags));
    }

    BOOL b = FALSE;
    if (body) {
        std::wstring hdr = L"Content-Type: application/x-www-form-urlencoded\r\n";
        b = WinHttpSendRequest(hRequest, hdr.c_str(), (DWORD)hdr.size(),
                               (LPVOID)body->data(), (DWORD)body->size(), (DWORD)body->size(), 0);
    } else {
        b = WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0,
                               WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
    }
    if (!b) { std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n"; return false; }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) {
        std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n"; return false; }

    DWORD status = 0; DWORD len = sizeof(status);
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX,
                        &status, &len, WINHTTP_NO_HEADER_INDEX);
    if (http_status) *http_status = (int)status;

    std::string buf; buf.reserve(16 * 1024);
    for (;;) {
        DWORD avail = 0; if (!WinHttpQueryDataAvailable(hRequest, &avail)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n"; return false; }
        if (avail == 0) break;
        std::string chunk; chunk.resize(avail);
        DWORD read = 0; if (!WinHttpReadData(hRequest, &chunk[0], avail, &read)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n"; return false; }
        chunk.resize(read); buf.append(chunk);
    }
    out_body.swap(buf);
    return true;
}

// Very small, lenient Tor consensus parser skeleton: extracts relay nicknames and fingerprints.
struct ConsensusRelay { std::string nickname; std::string fingerprint_hex; };
static std::vector<ConsensusRelay> ParseConsensus(const std::string& text) {
    std::vector<ConsensusRelay> relays;
    std::istringstream iss(text);
    std::string line;
    while (std::getline(iss, line)) {
        if (line.size() && (line.back() == '\r' || line.back() == '\n')) line.pop_back();
        if (line.rfind("r ", 0) == 0) {
            // r <nick> <id_hex> <digest> <published> <ip> <orport> <dirport>
            std::istringstream ls(line);
            std::string tag; ConsensusRelay r; std::string id_hex;
            ls >> tag >> r.nickname >> id_hex; // id_hex is base64 in actual spec; many mirrors show hex
            // Normalize: keep hex-alike chars
            r.fingerprint_hex.clear();
            for (char c : id_hex) if (std::isxdigit((unsigned char)c)) r.fingerprint_hex.push_back((char)std::toupper((unsigned char)c));
            relays.push_back(std::move(r));
        }
    }
    return relays;
}

// Minimal v3 HS descriptor parser skeleton: extracts lines under "introduction-point" sections.
struct HSIntroPoint { std::map<std::string, std::string> fields; };
struct HSDescriptor { std::vector<HSIntroPoint> intro_points; };

static HSDescriptor ParseHSDescriptor(const std::string& text) {
    HSDescriptor desc; HSIntroPoint cur; bool in_ip = false;
    std::istringstream iss(text); std::string line;
    while (std::getline(iss, line)) {
        if (!line.empty() && (line.back() == '\r' || line.back() == '\n')) line.pop_back();
        if (line == "introduction-point") {
            if (in_ip) { desc.intro_points.push_back(cur); cur = HSIntroPoint{}; }
            in_ip = true; continue;
        }
        if (in_ip) {
            if (line.empty()) { desc.intro_points.push_back(cur); cur = HSIntroPoint{}; in_ip = false; continue; }
            auto sp = line.find(' ');
            if (sp != std::string::npos) {
                std::string k = line.substr(0, sp);
                std::string v = line.substr(sp + 1);
                cur.fields[k] = v;
            } else {
                cur.fields[line] = "";
            }
        }
    }
    if (in_ip) desc.intro_points.push_back(cur);
    return desc;
}

// Download helpers
static bool DownloadText(const std::wstring& url, std::string& out_text) {
    int status = 0; if (!HttpRequest(L"GET", url, nullptr, out_text, &status)) return false;
    if (status < 200 || status >= 300) {
        std::wcerr << L"HTTP status " << status << L" for " << url << L"\n"; return false; }
    return true;
}

static bool HttpGetText(const std::wstring& url, std::string& out_text) { return DownloadText(url, out_text); }
static bool HttpPostForm(const std::wstring& url, const std::string& form, std::string& out_text) {
    int status = 0; if (!HttpRequest(L"POST", url, &form, out_text, &status)) return false;
    if (status < 200 || status >= 300) {
        std::wcerr << L"HTTP status " << status << L" for POST " << url << L"\n"; return false; }
    return true;
}

// Command-line parsing
struct Args {
    std::wstring consensus_url;
    std::wstring descriptor_url;
    std::wstring get_url;
    std::wstring post_url; std::string post_body;
};

static Args ParseArgs(int argc, wchar_t** argv) {
    Args a;
    for (int i = 1; i < argc; ++i) {
        std::wstring k = argv[i];
        auto nextw = [&](std::wstring& out){ if (i + 1 < argc) { out = argv[++i]; return true; } return false; };
        auto nexta = [&](std::string& out){ if (i + 1 < argc) { out = WideToUtf8(argv[++i]); return true; } return false; };
        if (k == L"--consensus-url") nextw(a.consensus_url);
        else if (k == L"--descriptor-url") nextw(a.descriptor_url);
        else if (k == L"--get") nextw(a.get_url);
        else if (k == L"--post") { nextw(a.post_url); nexta(a.post_body); }
    }
    return a;
}

static void PrintConsensusSummary(const std::vector<ConsensusRelay>& relays) {
    std::wcout << L"Consensus relays parsed: " << (unsigned)relays.size() << L"\n";
    for (size_t i = 0; i < std::min<size_t>(relays.size(), 5); ++i) {
        std::wcout << L"  [" << i << L"] nick=" << Utf8ToWide(relays[i].nickname)
                   << L" fp=" << Utf8ToWide(relays[i].fingerprint_hex) << L"\n";
    }
}

static void PrintHSSummary(const HSDescriptor& d) {
    std::wcout << L"HS descriptor: intro points=" << (unsigned)d.intro_points.size() << L"\n";
    for (size_t i = 0; i < d.intro_points.size(); ++i) {
        std::wcout << L"  intro-point[" << i << L"] fields=" << (unsigned)d.intro_points[i].fields.size() << L"\n";
    }
}

int wmain(int argc, wchar_t** argv) {
    OpenSSLInit ssl_init;

    Args args = ParseArgs(argc, argv);
    bool did = false;

    if (!args.consensus_url.empty()) {
        std::string text;
        if (HttpGetText(args.consensus_url, text)) {
            auto relays = ParseConsensus(text);
            PrintConsensusSummary(relays);
            did = true;
        } else {
            std::wcerr << L"Failed to download/parse consensus from: " << args.consensus_url << L"\n";
        }
    }

    if (!args.descriptor_url.empty()) {
        std::string text;
        if (HttpGetText(args.descriptor_url, text)) {
            auto hs = ParseHSDescriptor(text);
            PrintHSSummary(hs);
            did = true;
        } else {
            std::wcerr << L"Failed to download/parse HS descriptor from: " << args.descriptor_url << L"\n";
        }
    }

    if (!args.get_url.empty()) {
        std::string body;
        if (HttpGetText(args.get_url, body)) {
            std::wcout << L"GET ok, bytes=" << (unsigned)body.size() << L"\n";
            did = true;
        } else {
            std::wcerr << L"GET failed: " << args.get_url << L"\n";
        }
    }

    if (!args.post_url.empty()) {
        std::string body;
        if (HttpPostForm(args.post_url, args.post_body, body)) {
            std::wcout << L"POST ok, bytes=" << (unsigned)body.size() << L"\n";
            did = true;
        } else {
            std::wcerr << L"POST failed: " << args.post_url << L"\n";
        }
    }

    if (!did) {
        std::wcout << L"Usage:\n"
                   << L"  --consensus-url <https_url_to_consensus>\n"
                   << L"  --descriptor-url <https_url_to_hs_descriptor>\n"
                   << L"  --get <https_url>\n"
                   << L"  --post <https_url> <body>\n";
    }
    return did ? 0 : 1;
}

