// Simple base64 decode using OpenSSL BIO
static bool Base64Decode(const std::string& in, std::vector<unsigned char>& out) {
    BIO* b64 = BIO_new(BIO_f_base64());
    BIO* bio = BIO_new_mem_buf(in.data(), (int)in.size());
    if (!b64 || !bio) { if (b64) BIO_free(b64); if (bio) BIO_free(bio); return false; }
    BIO_set_flags(b64, BIO_FLAGS_BASE64_NO_NL);
    bio = BIO_push(b64, bio);
    out.resize(in.size());
    int n = BIO_read(bio, out.data(), (int)out.size());
    BIO_free_all(bio);
    if (n <= 0) return false;
    out.resize(n);
    return true;
}

// Tor v3 .onion validation (base32 decode and checksum verification per spec)
// Address = base32(pubkey(32) || checksum(2) || version(1)) + ".onion", where
// checksum = first 2 bytes of SHA3-256(".onion checksum" || pubkey || version)
// Here we implement decoding with OpenSSL's SHA3-256 via EVP.

static const int ONION_V3_LEN = 56; // without ".onion"

static int Base32Val(char c) {
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= '2' && c <= '7') return 26 + (c - '2');
    if (c >= 'A' && c <= 'Z') return c - 'A';
    return -1;
}

static bool Base32DecodeNoPad(const std::string& in, std::vector<unsigned char>& out) {
    int bits = 0; int acc = 0; out.clear();
    for (char ch : in) {
        if (ch == '=') break;
        int v = Base32Val(ch);
        if (v < 0) return false;
        acc = (acc << 5) | v;
        bits += 5;
        if (bits >= 8) {
            bits -= 8;
            out.push_back((unsigned char)((acc >> bits) & 0xFF));
        }
    }
    return true;
}

static bool Sha3_256(const unsigned char* data, size_t len, unsigned char out[32]) {
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) return false;
    const EVP_MD* md = EVP_sha3_256();
    bool ok = EVP_DigestInit_ex(ctx, md, nullptr) == 1 &&
              EVP_DigestUpdate(ctx, data, len) == 1 &&
              EVP_DigestFinal_ex(ctx, out, nullptr) == 1;
    EVP_MD_CTX_free(ctx);
    return ok;
}

static bool ValidateV3Onion(const std::string& onion, std::vector<unsigned char>& pubkey32) {
    pubkey32.clear();
    if (onion.size() < ONION_V3_LEN + 6) return false; // + ".onion"
    if (onion.substr(onion.size() - 6) != ".onion") return false;
    std::string label = onion.substr(0, onion.size() - 6);
    if (label.size() != ONION_V3_LEN) return false;
    std::string lower = label; std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
    std::vector<unsigned char> decoded;
    if (!Base32DecodeNoPad(lower, decoded)) return false;
    if (decoded.size() != 35) return false; // 32 pubkey + 2 checksum + 1 version
    const unsigned char* pk = decoded.data();
    const unsigned char* csum = decoded.data() + 32;
    unsigned char ver = decoded[34];
    if (ver != 0x03) return false;
    // compute checksum
    const char* tag = ".onion checksum";
    std::vector<unsigned char> buf; buf.reserve(15 + 32 + 1);
    buf.insert(buf.end(), tag, tag + 15);
    buf.insert(buf.end(), pk, pk + 32);
    buf.push_back(ver);
    unsigned char digest[32];
    if (!Sha3_256(buf.data(), buf.size(), digest)) return false;
    if (digest[0] != csum[0] || digest[1] != csum[1]) return false;
    pubkey32.assign(pk, pk + 32);
    return true;
}

// WinHTTP helpers
struct HttpResponse { DWORD status = 0; std::string body; std::map<std::string, std::string> headers; };

static bool SplitUrl(const std::wstring& url, std::wstring& host, INTERNET_PORT& port, std::wstring& path, bool& secure) {
    URL_COMPONENTS uc{}; uc.dwStructSize = sizeof(uc);
    wchar_t hbuf[256]{}; wchar_t pbuf[2048]{};
    uc.lpszHostName = hbuf; uc.dwHostNameLength = _countof(hbuf);
    uc.lpszUrlPath = pbuf; uc.dwUrlPathLength = _countof(pbuf);
    secure = false;
    if (!WinHttpCrackUrl(url.c_str(), 0, 0, &uc)) return false;
    host.assign(uc.lpszHostName, uc.dwHostNameLength);
    path.assign(uc.lpszUrlPath, uc.dwUrlPathLength);
    port = uc.nPort;
    secure = (uc.nScheme == INTERNET_SCHEME_HTTPS);
    return true;
}

static std::string GetLastErrorMsg(DWORD err) {
    LPWSTR buf = nullptr;
    FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
                   nullptr, err, 0, (LPWSTR)&buf, 0, nullptr);
    std::wstring w = buf ? buf : L"";
    if (buf) LocalFree(buf);
    return WideToUtf8(w);
}

static bool HttpRequest(const std::wstring& url, const std::wstring& method, const std::string* body, HttpResponse& out) {
    out = HttpResponse{};
    std::wstring host, path; INTERNET_PORT port = 0; bool secure = false;
    if (!SplitUrl(url, host, port, path, secure)) { std::cerr << "WinHttpCrackUrl failed\n"; return false; }

    HINTERNET hSession = WinHttpOpen(L"winhttp-client/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0);
    if (!hSession) { std::cerr << "WinHttpOpen: " << GetLastErrorMsg(GetLastError()) << "\n"; return false; }

    DWORD flags = secure ? WINHTTP_FLAG_SECURE : 0;
    HINTERNET hConnect = WinHttpConnect(hSession, host.c_str(), port, 0);
    if (!hConnect) { std::cerr << "WinHttpConnect: " << GetLastErrorMsg(GetLastError()) << "\n"; WinHttpCloseHandle(hSession); return false; }

    HINTERNET hRequest = WinHttpOpenRequest(hConnect, method.c_str(), path.c_str(), nullptr, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags);
    if (!hRequest) { std::cerr << "WinHttpOpenRequest: " << GetLastErrorMsg(GetLastError()) << "\n"; WinHttpCloseHandle(hConnect); WinHttpCloseHandle(hSession); return false; }

    if (secure) {
        DWORD secFlags = 0;
        WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags));
    }

    BOOL bret = TRUE;
    if (body && !body->empty()) {
        std::wstring hdr = L"Content-Type: application/x-www-form-urlencoded\r\n";
        bret = WinHttpSendRequest(hRequest, hdr.c_str(), (DWORD)hdr.size(), (LPVOID)body->data(), (DWORD)body->size(), (DWORD)body->size(), 0);
    } else {
        bret = WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
    }
    if (!bret) { std::cerr << "WinHttpSendRequest: " << GetLastErrorMsg(GetLastError()) << "\n"; WinHttpCloseHandle(hRequest); WinHttpCloseHandle(hConnect); WinHttpCloseHandle(hSession); return false; }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) { std::cerr << "WinHttpReceiveResponse: " << GetLastErrorMsg(GetLastError()) << "\n"; WinHttpCloseHandle(hRequest); WinHttpCloseHandle(hConnect); WinHttpCloseHandle(hSession); return false; }

    DWORD status = 0; DWORD slen = sizeof(status);
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &status, &slen, WINHTTP_NO_HEADER_INDEX);
    out.status = status;

    // Read body
    std::string resp;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &avail)) { std::cerr << "WinHttpQueryDataAvailable: " << GetLastErrorMsg(GetLastError()) << "\n"; break; }
        if (!avail) break;
        std::vector<char> buf(avail);
        DWORD read = 0;
        if (!WinHttpReadData(hRequest, buf.data(), avail, &read)) { std::cerr << "WinHttpReadData: " << GetLastErrorMsg(GetLastError()) << "\n"; break; }
        resp.append(buf.data(), buf.data() + read);
    }
    out.body = std::move(resp);

    WinHttpCloseHandle(hRequest);
    WinHttpCloseHandle(hConnect);
    WinHttpCloseHandle(hSession);
    return true;
}

// Very minimal Tor consensus parser: extracts router lines and flags section markers
struct ConsensusInfo { size_t router_count = 0; bool valid = false; };

static ConsensusInfo ParseConsensus(const std::string& txt) {
    std::istringstream iss(txt);
    std::string line; size_t routers = 0; bool have_valid_after = false;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.rfind("valid-after ", 0) == 0) have_valid_after = true;
        if (line.rfind("r ", 0) == 0) routers++;
    }
    ConsensusInfo ci; ci.router_count = routers; ci.valid = have_valid_after; return ci;
}

// Minimal HS descriptor parser: detects type and key blocks
struct HSDescInfo { bool is_v3 = false; bool have_signing_key = false; bool have_intro_points = false; };

static HSDescInfo ParseHSDescriptor(const std::string& txt) {
    HSDescInfo d;
    std::istringstream iss(txt); std::string line;
    while (std::getline(iss, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.find("hs-descriptor 3") != std::string::npos) d.is_v3 = true;
        if (line.find("hs-descriptor 2") != std::string::npos) d.is_v3 = false;
        if (line.rfind("descriptor-signing-key ", 0) == 0) d.have_signing_key = true;
        if (line.rfind("introduction-points ", 0) == 0) d.have_intro_points = true;
    }
    return d;
}

static void PrintHex(const unsigned char* p, size_t n) {
    std::ios::fmtflags f(std::cout.flags());
    for (size_t i = 0; i < n; ++i) std::cout << std::hex << std::setw(2) << std::setfill('0') << (int)p[i];
    std::cout.flags(f);
}

