    }

    if (!httpUrl.empty()) {
        HttpResponse r;
        const std::string* bptr = method == L"POST" ? &postData : nullptr;
        if (HttpRequest(httpUrl, method, bptr, r)) {
            std::cout << "http: status=" << r.status << " bytes=" << r.body.size() << "\n";
        } else {
            std::cerr << "HTTP request failed\n";
