// ---------------- Base32 (lowercase, no padding) ----------------
static const int8_t B32LUT[256] = {
    /* initialize all to -1, then set 'a'-'z','2'-'7' */
};
static void InitB32() {
    static bool inited = false;
    if (inited) return;
    inited = true;
    for (int i = 0; i < 256; ++i) const_cast<int8_t&>(B32LUT[i]) = -1; // hack for static const
}
static bool Base32DecodeLowerNoPad(const std::string& in, std::vector<uint8_t>& out) {
    static int8_t lut[256];
    static bool once=false; if (!once){ for(int i=0;i<256;++i) lut[i]=-1; for(char c='a';c<='z';++c) lut[(unsigned char)c]=c-'a'; for(char c='2';c<='7';++c) lut[(unsigned char)c]=26+(c-'2'); once=true; }
    uint32_t buffer=0; int bits=0; out.clear(); out.reserve(in.size()*5/8);
    for (unsigned char c: in) {
        if (c=='=') break;
        int v = lut[c]; if (v<0) return false;
        buffer = (buffer<<5) | (uint32_t)v; bits += 5;
        if (bits >= 8) { bits -= 8; out.push_back((uint8_t)((buffer>>bits)&0xFF)); }
    }
    return true;
}

// ---------------- Tor v3 onion parsing helpers ----------------
static bool DecodeOnionV3(const std::string& onion, std::array<uint8_t,32>& pubkey_out) {
    // strip optional ".onion"
    std::string host = onion;
    auto pos = host.find(".onion"); if (pos != std::string::npos) host = host.substr(0,pos);
    if (host.size() != 56) return false;
    std::vector<uint8_t> dec; if (!Base32DecodeLowerNoPad(host, dec)) return false;
    if (dec.size() != 35) return false; // 32 pubkey + 2 checksum + 1 version
    if (dec.back() != 0x03) return false; // version
    std::copy(dec.begin(), dec.begin()+32, pubkey_out.begin());
    // checksum = first 2 bytes of SHA3-256(".onion checksum" || pubkey || 0x03)
    // OpenSSL legacy SHA3 via EVP
    uint8_t msg[15+32+1]; size_t off=0;
    const char tag[] = ".onion checksum"; memcpy(msg+off, tag, sizeof(tag)-1); off += sizeof(tag)-1;
    memcpy(msg+off, pubkey_out.data(), 32); off += 32; msg[off++] = 0x03;
    uint8_t digest[32];
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) return false;
    bool ok = EVP_DigestInit_ex(ctx, EVP_sha3_256(), nullptr) == 1 &&
              EVP_DigestUpdate(ctx, msg, off) == 1 &&
              EVP_DigestFinal_ex(ctx, digest, nullptr) == 1;
    EVP_MD_CTX_free(ctx);
    if (!ok) return false;
    if (dec[32] != digest[0] || dec[33] != digest[1]) return false;
    return true;
}

// ---------------- Minimal Tor consensus/descriptor parsing ----------------
static void ParseConsensus(const std::string& txt) {
    size_t relays=0, flags_authority=0; std::string valid_after;
    std::istringstream iss(txt); std::string line;
    while (std::getline(iss, line)) {
        if (line.rfind("valid-after ",0)==0) valid_after = line.substr(12);
        else if (line.rfind("r ",0)==0) ++relays;
        else if (line.rfind("s ",0)==0) {
            if (line.find(" Authority ")!=std::string::npos) ++flags_authority;
        }
    }
    std::cout << "Consensus: valid-after=" << valid_after << ", relays=" << relays << ", authority-flagged=" << flags_authority << "\n";
}
static void ParseDescriptorV3(const std::string& txt) {
    std::string hs_type, intro_auth, blinded_key_alg; size_t intro2_cnt=0, single_onion=0;
    std::istringstream iss(txt); std::string line;
    while (std::getline(iss, line)) {
        if (line.rfind("hs-descriptor ",0)==0) hs_type = line.substr(13);
        else if (line.rfind("intro-auth-required ",0)==0) intro_auth = line.substr(20);
        else if (line.rfind("create2-formats ",0)==0) {/*ignored*/}
        else if (line.rfind("intro-point ",0)==0) ++intro2_cnt;
        else if (line.rfind("single-onion ",0)==0) ++single_onion;
        else if (line.rfind("blinded-key ",0)==0) blinded_key_alg = "present";
    }
    std::cout << "Descriptor: hs-descriptor=" << hs_type << ", intro-points=" << intro2_cnt
              << ", intro-auth=" << intro_auth << ", blinded-key=" << (blinded_key_alg.empty()?"no":"yes")
              << ", single-onion=" << single_onion << "\n";
}

// ---------------- WinHTTP fetch via optional SOCKS5 proxy ----------------
static bool HttpFetch(const std::wstring& url, const std::wstring& socksProxy, const std::wstring& method,
                      const std::string* body, std::string& out_body, DWORD& status_out) {
    ParsedUrl pu; if (!CrackUrl(url, pu)) return false;
    WinHttpHandle hSession(WinHttpOpen(L"tor-onion-tool/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                                       WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0));
    if (!hSession) { std::wcerr << L"WinHttpOpen failed: " << FormatLastError() << L"\n"; return false; }

    if (!socksProxy.empty()) {
        WINHTTP_PROXY_INFO pi{};
        std::wstring px = L"socks=" + socksProxy; // e.g., socks=127.0.0.1:9050
        pi.dwAccessType = WINHTTP_ACCESS_TYPE_NAMED_PROXY;
        pi.lpszProxy = (LPWSTR)px.c_str();
        if (!WinHttpSetOption(hSession, WINHTTP_OPTION_PROXY, &pi, sizeof(pi))) {
            std::wcerr << L"WinHttpSetOption(PROXY) failed: " << FormatLastError() << L"\n";
            return false;
        }
    }

    WinHttpHandle hConnect(WinHttpConnect(hSession, pu.host.c_str(), pu.port ? pu.port : (pu.https?INTERNET_DEFAULT_HTTPS_PORT:INTERNET_DEFAULT_HTTP_PORT), 0));
    if (!hConnect) { std::wcerr << L"WinHttpConnect failed: " << FormatLastError() << L"\n"; return false; }

    DWORD flags = pu.https ? WINHTTP_FLAG_SECURE : 0;
    WinHttpHandle hRequest(WinHttpOpenRequest(hConnect, method.c_str(), pu.path.c_str(), nullptr,
                                              WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, flags));
    if (!hRequest) { std::wcerr << L"WinHttpOpenRequest failed: " << FormatLastError() << L"\n"; return false; }

    // For .onion over HTTPS, relax name check (since certs rarely match). Keep for .onion only.
    if (pu.https) {
        std::wstring hostLower = pu.host; std::transform(hostLower.begin(), hostLower.end(), hostLower.begin(), ::towlower);
        if (hostLower.find(L".onion") != std::wstring::npos) {
            DWORD secFlags = SECURITY_FLAG_IGNORE_CERT_CN_INVALID | SECURITY_FLAG_IGNORE_CERT_WRONG_USAGE | SECURITY_FLAG_IGNORE_UNKNOWN_CA | SECURITY_FLAG_IGNORE_CERT_DATE_INVALID;
            if (!WinHttpSetOption(hRequest, WINHTTP_OPTION_SECURITY_FLAGS, &secFlags, sizeof(secFlags))) {
                std::wcerr << L"WinHttpSetOption(SECURITY_FLAGS) failed: " << FormatLastError() << L"\n";
            }
        }
    }

    std::wstring headers = L"User-Agent: tor-onion-tool/1.0\r\n";
    BOOL sent = FALSE;
    if (body && method == L"POST") {
        std::wstring ct = L"Content-Type: application/x-www-form-urlencoded\r\n";
        std::wstring all = headers + ct;
        sent = WinHttpSendRequest(hRequest, all.c_str(), (DWORD)-1L,
                                  (LPVOID)body->data(), (DWORD)body->size(), (DWORD)body->size(), 0);
    } else {
        sent = WinHttpSendRequest(hRequest, headers.c_str(), (DWORD)-1L, WINHTTP_NO_REQUEST_DATA, 0, 0, 0);
    }
    if (!sent) { std::wcerr << L"WinHttpSendRequest failed: " << FormatLastError() << L"\n"; return false; }

    if (!WinHttpReceiveResponse(hRequest, nullptr)) { std::wcerr << L"WinHttpReceiveResponse failed: " << FormatLastError() << L"\n"; return false; }

    DWORD statusCode=0, len=sizeof(statusCode);
    WinHttpQueryHeaders(hRequest, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER, WINHTTP_HEADER_NAME_BY_INDEX, &statusCode, &len, WINHTTP_NO_HEADER_INDEX);
    status_out = statusCode;

    out_body.clear();
    std::vector<char> buf(16*1024);
    DWORD dwDownloaded = 0;
    do {
        dwDownloaded = 0;
        if (!WinHttpQueryDataAvailable(hRequest, &dwDownloaded)) {
            std::wcerr << L"WinHttpQueryDataAvailable failed: " << FormatLastError() << L"\n"; return false;
        }
        if (dwDownloaded == 0) break;
        if (buf.size() < dwDownloaded) buf.resize(dwDownloaded);
        DWORD dwRead = 0;
        if (!WinHttpReadData(hRequest, buf.data(), dwDownloaded, &dwRead)) {
            std::wcerr << L"WinHttpReadData failed: " << FormatLastError() << L"\n"; return false;
        }
        out_body.append(buf.data(), buf.data()+dwRead);
    } while (dwDownloaded > 0);

    return true;
}

// ---------------- CLI & demo ----------------
int wmain(int argc, wchar_t* argv[]) {
    std::wstring socks; std::wstring getUrl; std::wstring postUrl; std::string postBody;
    std::wstring consensusUrl; std::wstring descriptorUrl; std::wstring onionCheck;

    for (int i=1;i<argc;++i) {
        std::wstring a = argv[i];
        if (a == L"--socks" && i+1<argc) { socks = argv[++i]; }
        else if (a == L"--get" && i+1<argc) { getUrl = argv[++i]; }
        else if (a == L"--post" && i+2<argc) { postUrl = argv[++i]; postBody = WideToUtf8(argv[++i]); }
        else if (a == L"--consensus-url" && i+1<argc) { consensusUrl = argv[++i]; }
        else if (a == L"--descriptor-url" && i+1<argc) { descriptorUrl = argv[++i]; }
        else if (a == L"--onion-check" && i+1<argc) { onionCheck = argv[++i]; }
    }

    // Onion check using OpenSSL SHA3-256
    if (!onionCheck.empty()) {
        std::array<uint8_t,32> pk{};
        bool ok = DecodeOnionV3(WideToUtf8(onionCheck), pk);
        std::cout << "onion-check: " << (ok?"valid":"invalid") << "\n";
    }

    // Fetch & parse consensus
    if (!consensusUrl.empty()) {
        std::string body; DWORD status=0;
        if (!HttpFetch(consensusUrl, socks, L"GET", nullptr, body, status)) return 1;
        std::cout << "Consensus HTTP status: " << status << "\n";
        if (status==200) ParseConsensus(body);
    }

    // Fetch & parse v3 descriptor
    if (!descriptorUrl.empty()) {
        std::string body; DWORD status=0;
        if (!HttpFetch(descriptorUrl, socks, L"GET", nullptr, body, status)) return 1;
        std::cout << "Descriptor HTTP status: " << status << "\n";
        if (status==200) ParseDescriptorV3(body);
    }

    // Real GET/POST including .onion via Tor SOCKS5 (WinHTTP socks= proxy)
    if (!getUrl.empty()) {
        std::string resp; DWORD status=0;
        if (!HttpFetch(getUrl, socks, L"GET", nullptr, resp, status)) return 1;
        std::wcout << L"GET status: " << status << L" length=" << resp.size() << L"\n";
        std::cout << resp << "\n";
    }
    if (!postUrl.empty()) {
        std::string resp; DWORD status=0;
        if (!HttpFetch(postUrl, socks, L"POST", &postBody, resp, status)) return 1;
        std::wcout << L"POST status: " << status << L" length=" << resp.size() << L"\n";
        std::cout << resp << "\n";
    }

    return 0;
}

