        if (cam == null) return screenPos;
        screenPos.z = _zToCam;
        return cam.ScreenToWorldPoint(screenPos);
    }

    void UpdateTrajectoryPreview()
    {
        if (cam == null) cam = Camera.main;

        // Current drag vector in screen space
        Vector3 currentScreen = Input.mousePosition;
        Vector3 currentWorld = ScreenToWorldWithZ(currentScreen);
        Vector2 dragWorld = (Vector2)(currentWorld - _startDragWorldProjected);
        if (invertDrag) dragWorld = -dragWorld;

        // Compute initial velocity
        Vector2 initialVel = dragWorld * power;
        if (initialVel.magnitude > maxLaunchSpeed)
        {
            initialVel = initialVel.normalized * maxLaunchSpeed;
        }
        _pendingLaunchVelocity = initialVel;

        // Physics params
        Vector2 startPos = transform.position;
        Vector2 gravity = Physics2D.gravity * _rb.gravityScale;

        // Prepare arrays for line renderer
        Vector3[] worldPoints = null;
        if (useLineRenderer && lineRenderer != null)
        {
            if (lineRenderer.positionCount != dotsCount)
                lineRenderer.positionCount = dotsCount;
            worldPoints = new Vector3[dotsCount];
        }

        // Update dots and line positions
        ShowDots();
        for (int i = 0; i < dotsCount; i++)
        {
            float t = (i + 1) * dotTimeStep;
            Vector2 p = startPos + initialVel * t + 0.5f * gravity * (t * t);

            // Line uses world positions
            if (worldPoints != null)
            {
                worldPoints[i] = new Vector3(p.x, p.y, transform.position.z);
            }

            // UI dot position on canvas
            if (_canvasRect != null && i < _dots.Count && _dots[i] != null)
            {
                Vector2 screen = RectTransformUtility.WorldToScreenPoint(targetCanvas.worldCamera != null ? targetCanvas.worldCamera : cam, p);
                Vector2 local;
                if (RectTransformUtility.ScreenPointToLocalPointInRectangle(_canvasRect, screen, targetCanvas.renderMode == RenderMode.ScreenSpaceOverlay ? null : targetCanvas.worldCamera, out local))
                {
                    _dots[i].anchoredPosition = local;
                }
            }
        }

        if (worldPoints != null)
        {
            lineRenderer.SetPositions(worldPoints);
            ApplyLineRendererStyle(CalcLineLength(worldPoints));
        }
    }

    float CalcLineLength(IList<Vector3> points)
    {
        float len = 0f;
        for (int i = 1; i < points.Count; i++)
        {
            len += Vector3.Distance(points[i - 1], points[i]);
        }
        return Mathf.Max(0.0001f, len);
    }

    void ApplyLineRendererStyle(float lineWorldLength)
    {
        if (!useLineRenderer || lineRenderer == null) return;

        if (dashedLine && dashedLineMaterial != null)
        {
            // Ensure Tile mode and dashed material
            lineRenderer.textureMode = LineTextureMode.Tile;
            if (lineRenderer.sharedMaterial != dashedLineMaterial)
            {
                lineRenderer.sharedMaterial = dashedLineMaterial;
            }

            // mainTextureScale based on dashLengthWorld and dashTilingMultiplier
            float cycles = Mathf.Max(0.0001f, lineWorldLength / Mathf.Max(0.0001f, dashLengthWorld));
            float tilingX = cycles * Mathf.Max(0.0001f, dashTilingMultiplier);
            var mat = lineRenderer.material; // instance for per-line changes
            if (mat != null)
            {
                mat.mainTextureScale = new Vector2(tilingX, 1f);

                // animate offset by dashScrollSpeed
                _dashOffsetPhase += dashScrollSpeed * Time.deltaTime;
                mat.mainTextureOffset = new Vector2(_dashOffsetPhase, 0f);
            }
        }
        else
        {
            // Solid line: restore original material and defaults
            if (_originalLineMaterial != null)
            {
                lineRenderer.sharedMaterial = _originalLineMaterial;
            }
            lineRenderer.textureMode = LineTextureMode.Stretch;
            if (lineRenderer.material != null)
            {
                lineRenderer.material.mainTextureScale = new Vector2(1f, 1f);
                lineRenderer.material.mainTextureOffset = Vector2.zero;
            }
        }
    }
}
