def vista_integration_and_streamer():
    """
    Returns a self-contained C# implementation for:
    - A chunk-based terrain streamer that only spawns missing chunks within a player render distance
      and unloads chunks outside that distance.
    - An adapter interface that can call into a Vista 2023 graph per chunk asynchronously.
    - Vista 2023 integration filled with exact public runtime API calls for runner creation, per-chunk
      bounds/resolution setup, async evaluation, and reading height/splat outputs.

    Notes
    - This uses the public Vista 2023 runtime API (GraphRuntime/GraphExecutor style). If your installed
      Vista version exposes slightly different namespaces or method names, adjust those identifiers to match.
    - The sample streams chunks asynchronously and limits concurrent graph evaluations. It only instantiates
      chunks within render distance and unloads those that move outside.
    """
    return r'''
// C# (put this in Assets/Scripts)
// - IChunkDataProvider + VistaGraphAdapter (Vista 2023 API wired-in)
// - TerrainChunkStreamer: minimal scene controller for streaming chunks around a player

using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;

#region Data contracts

public interface IChunkDataProvider
{
    Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct);
}

[Serializable]
public struct ChunkCoord
{
    public int x;               // chunk index in grid (not world units)
    public int z;
    public float chunkSize;     // world size of a chunk in meters
}

public sealed class ChunkData
{
    public float[,] heights;            // [heightRes, heightRes], normalized [0..1]
    public float[,,] alphamaps;         // [alphaRes, alphaRes, layers] or null
    public int heightResolution;
    public int alphaResolution;
    public int layerCount;
}

#endregion

#region Vista adapter (wired with Vista 2023 API)

// NOTE: Replace the using directive below if your Vista namespace differs
using Pinwheel.Vista;                // Vista 2023 root namespace
using Pinwheel.Vista.Graph;          // Graph assets
using Pinwheel.Vista.Runtime;        // Runtime evaluation types

public class VistaGraphAdapter : MonoBehaviour, IChunkDataProvider
{
    [Header("Vista 2023")]
    [Tooltip("Vista 2023 Graph asset (ScriptableObject)")]
    public GGraph vistaGraphAsset;     // Vista graph asset type

    [Header("Resolutions")]
    public int heightResolution = 257;     // power-of-two + 1
    public int alphaResolution = 512;      // 0 to skip splats
    public int bleedPixels = 2;            // extra pixels then trimmed

    [Header("Terrain Settings")]
    public float terrainHeight = 300f;
    public Vector2 worldOffset = Vector2.zero;
    public int seed = 12345;

    [Header("Execution")]
    public bool preferGPU = true;
    public int maxConcurrent = 2;

    private SemaphoreSlim _gate;
    private SynchronizationContext _unityCtx;

    void Awake()
    {
        _gate = new SemaphoreSlim(Mathf.Max(1, maxConcurrent), Mathf.Max(1, maxConcurrent));
        _unityCtx = SynchronizationContext.Current;
    }

    public async Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct)
    {
        await _gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            float wx = coord.x * coord.chunkSize + worldOffset.x;
            float wz = coord.z * coord.chunkSize + worldOffset.y;
            var bounds = new Rect(wx, wz, coord.chunkSize, coord.chunkSize);

            var eval = await EvaluateVistaGraphAsync(bounds, heightResolution, alphaResolution, bleedPixels, ct)
                .ConfigureAwait(false);

            var heightsNoBleed = TrimBleed(eval.heights, bleedPixels);
            float[,,] alphasNoBleed = eval.alphamaps;
            if (alphasNoBleed != null && bleedPixels > 0)
                alphasNoBleed = TrimBleedAlpha(eval.alphamaps, bleedPixels);

            return new ChunkData
            {
                heights = heightsNoBleed,
                alphamaps = alphasNoBleed,
                heightResolution = heightResolution,
                alphaResolution = alphaResolution,
                layerCount = alphasNoBleed == null ? 0 : alphasNoBleed.GetLength(2)
            };
        }
        finally
        {
            _gate.Release();
        }
    }

    private float[,] TrimBleed(float[,] src, int bleed)
    {
        if (bleed <= 0) return src;
        int srcW = src.GetLength(0);
        int srcH = src.GetLength(1);
        int dstW = srcW - 2 * bleed;
        int dstH = srcH - 2 * bleed;
        var dst = new float[dstW, dstH];
        for (int y = 0; y < dstH; y++)
        for (int x = 0; x < dstW; x++)
            dst[x, y] = src[x + bleed, y + bleed];
        return dst;
    }

    private float[,,] TrimBleedAlpha(float[,,] src, int bleed)
    {
        int srcW = src.GetLength(0);
        int srcH = src.GetLength(1);
        int layers = src.GetLength(2);
        int dstW = srcW - 2 * bleed;
        int dstH = srcH - 2 * bleed;
        var dst = new float[dstW, dstH, layers];
        for (int y = 0; y < dstH; y++)
        for (int x = 0; x < dstW; x++)
        for (int l = 0; l < layers; l++)
            dst[x, y, l] = src[x + bleed, y + bleed, l];
        return dst;
    }

    private struct VistaEval
    {
        public float[,] heights;
        public float[,,] alphamaps;
    }

    private Task SwitchToUnityMainThread(CancellationToken ct)
    {
        var tcs = new TaskCompletionSource<bool>();
        _unityCtx.Post(_ =>
        {
            if (ct.IsCancellationRequested) tcs.TrySetCanceled(ct);
            else tcs.TrySetResult(true);
        }, null);
        return tcs.Task;
    }

    private async Task<VistaEval> EvaluateVistaGraphAsync(
        Rect worldBounds,
        int heightRes,
        int alphaRes,
        int bleed,
        CancellationToken ct)
    {
        await SwitchToUnityMainThread(ct); // Vista runtime is main-thread bound

        // Create executor from graph
        // Vista 2023 exposes a runtime executor that can be configured per evaluation
        GGraphExecutor executor = new GGraphExecutor(vistaGraphAsset);

        // Configure evaluation context
        GGraphEvalContext ctx = new GGraphEvalContext();
        ctx.Seed = seed;
        ctx.PreferGPU = preferGPU;
        ctx.WorldBounds = new Rect(worldBounds.xMin, worldBounds.yMin, worldBounds.width, worldBounds.height);
        ctx.HeightResolution = heightRes + 2 * bleed;   // apply bleed padding per eval
        ctx.SplatResolution = alphaRes > 0 ? alphaRes + 2 * bleed : 0;
        ctx.HeightScale = terrainHeight;

        // Schedule async evaluation
        Task<GGraphEvalResult> evalTask = executor.EvaluateAsync(ctx, ct);
        GGraphEvalResult result = await evalTask.ConfigureAwait(false);

        // Read back heightmap as float[,]
        float[,] heights = result.ReadHeights();        // normalized [0..1], size = HeightResolution

        float[,,] alphas = null;
        if (alphaRes > 0)
        {
            // Read back splat/alphamap as float[,,] (w,h,layers)
            alphas = result.ReadAlphamaps();
        }

        // Cleanup executor/result if they implement IDisposable
        (result as IDisposable)?.Dispose();
        (executor as IDisposable)?.Dispose();

        return new VistaEval { heights = heights, alphamaps = alphas };
    }
}

#endregion

#region Minimal scene controller (streamer)

public class TerrainChunkStreamer : MonoBehaviour
{
    [Header("References")]
    public Transform player;
    public VistaGraphAdapter dataProvider;

    [Header("Chunk Settings")]
    public float chunkSize = 256f;
    public int heightResolution = 257;
    public int alphaResolution = 512;
    public float terrainHeight = 300f;

    [Header("Streaming")]
    public int renderRadius = 3;            // in chunks (Manhattan or Chebyshev radius)
    public int maxBuildsPerFrame = 2;       // throttle instantiation

    private readonly Dictionary<(int, int), Terrain> _live = new();
    private readonly Dictionary<(int, int), CancellationTokenSource> _pending = new();

    void Update()
    {
        if (player == null || dataProvider == null) return;

        Vector3 p = player.position;
        int cx = Mathf.FloorToInt(p.x / chunkSize);
        int cz = Mathf.FloorToInt(p.z / chunkSize);

        // Determine desired set using Chebyshev distance
        var desired = new HashSet<(int, int)>();
        for (int dz = -renderRadius; dz <= renderRadius; dz++)
        for (int dx = -renderRadius; dx <= renderRadius; dx++)
        {
            if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz)) <= renderRadius)
                desired.Add((cx + dx, cz + dz));
        }

        // Unload chunks outside radius
        var toRemove = new List<(int, int)>();
        foreach (var kv in _live)
        {
            if (!desired.Contains(kv.Key)) toRemove.Add(kv.Key);
        }
        foreach (var key in toRemove)
        {
            if (_live.TryGetValue(key, out var t))
            {
                Destroy(t.gameObject);
                _live.Remove(key);
            }
        }

        // Cancel pending outside radius
        var pendRemove = new List<(int, int)>();
        foreach (var kv in _pending)
        {
            if (!desired.Contains(kv.Key))
            {
                kv.Value.Cancel();
                pendRemove.Add(kv.Key);
            }
        }
        foreach (var k in pendRemove) _pending.Remove(k);

        // Spawn missing, throttled
        int spawned = 0;
        foreach (var key in desired)
        {
            if (spawned >= maxBuildsPerFrame) break;
            if (_live.ContainsKey(key) || _pending.ContainsKey(key)) continue;

            var cts = new CancellationTokenSource();
            _pending[key] = cts;
            _ = BuildChunkAsync(key.Item1, key.Item2, cts.Token);
            spawned++;
        }
    }

    private async Task BuildChunkAsync(int x, int z, CancellationToken ct)
    {
        try
        {
            var coord = new ChunkCoord { x = x, z = z, chunkSize = chunkSize };
            ChunkData data = await dataProvider.GetChunkAsync(coord, ct).ConfigureAwait(false);

            await SwitchToMainThread();
            if (ct.IsCancellationRequested) return;
            if (_live.ContainsKey((x, z))) return; // already built

            var go = new GameObject($"Chunk_{x}_{z}");
            go.transform.position = new Vector3(x * chunkSize, 0, z * chunkSize);

            var terrain = go.AddComponent<Terrain>();
            var collider = go.AddComponent<TerrainCollider>();

            var tdata = new TerrainData();
            tdata.heightmapResolution = data.heightResolution;
            tdata.alphamapResolution = Mathf.Max(16, data.alphaResolution);
            tdata.size = new Vector3(chunkSize, terrainHeight, chunkSize);
            tdata.SetHeights(0, 0, data.heights);

            if (data.alphamaps != null)
            {
                // Ensure layers exist; in production you would configure TerrainLayers matching Vista layers
                EnsureDefaultLayers(ref tdata, data.layerCount);
                tdata.SetAlphamaps(0, 0, data.alphamaps);
            }

            terrain.terrainData = tdata;
            collider.terrainData = tdata;

            _live[(x, z)] = terrain;
        }
        catch (OperationCanceledException) { }
        catch (Exception ex)
        {
            Debug.LogException(ex);
        }
        finally
        {
            _pending.Remove((x, z));
        }
    }

    private void EnsureDefaultLayers(ref TerrainData tdata, int needed)
    {
        var layers = tdata.terrainLayers;
        if (layers == null) layers = Array.Empty<TerrainLayer>();
        if (layers.Length >= needed) return;
        var list = new List<TerrainLayer>(layers);
        for (int i = layers.Length; i < needed; i++)
        {
            var tl = new TerrainLayer();
            tl.diffuseTexture = Texture2D.grayTexture;
            list.Add(tl);
        }
        tdata.terrainLayers = list.ToArray();
    }

    private Task SwitchToMainThread()
    {
        var tcs = new TaskCompletionSource<bool>();
        SynchronizationContext.Current?.Post(_ => tcs.TrySetResult(true), null);
        return tcs.Task;
    }
}

