using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;

#region Data contracts

public interface IChunkDataProvider
{
    Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct);
}

[Serializable]
public struct ChunkCoord
{
    public int x; // chunk index in grid (not world units)
    public int z;
    public float chunkSize; // world size of this chunk in meters
}

public sealed class ChunkData
{
    public float[,] heights;                  // [hRes, hRes], normalized [0..1]
    public float[,,] alphamaps;               // [aRes, aRes, layers] or null
    public int heightResolution;              // e.g., 257
    public int alphaResolution;               // e.g., 512
    public int layerCount;                    // number of splat layers
}

#endregion

#region Vista adapter (Perlin fallback + Vista 2023 bridge)

public class VistaGraphAdapter : MonoBehaviour, IChunkDataProvider
{
    [Header("Vista 2023")]
    [Tooltip("Reference to your Vista 2023 graph asset (ScriptableObject)")]
    public ScriptableObject vistaGraphAsset;

    [Header("Resolutions")]
    [Tooltip("TerrainData.heightmapResolution (power of two + 1, e.g., 257)")]
    public int heightResolution = 257;
    [Tooltip("TerrainData.alphamapResolution (e.g., 512). Set 0 to skip splats.")]
    public int alphaResolution = 512;
    [Tooltip("Extra pixels around the tile for seam safety (trimmed after readback)")]
    public int bleedPixels = 2;

    [Header("Terrain Settings")]
    [Tooltip("Terrain vertical scale in meters")]
    public float terrainHeight = 300f;
    [Tooltip("World-space offset if your graph expects a non-zero origin")]
    public Vector2 worldOffset = Vector2.zero;
    [Tooltip("Seed for Vista graph if supported")]
    public int seed = 12345;

    [Header("Execution")]
    [Tooltip("Prefer GPU evaluation when supported by Vista")]
    public bool preferGPU = true;
    [Tooltip("Limit concurrent evaluations to avoid spikes")]
    public int maxConcurrent = 2;

    private SemaphoreSlim _gate;

    void Awake()
    {
        _gate = new SemaphoreSlim(Mathf.Max(1, maxConcurrent), Mathf.Max(1, maxConcurrent));
    }

    public async Task<ChunkData> GetChunkAsync(ChunkCoord coord, CancellationToken ct)
    {
        await _gate.WaitAsync(ct);
        try
        {
#if VISTA_2023
            if (vistaGraphAsset != null)
            {
                return await EvaluateVistaGraphAsync(coord, ct);
            }
#endif
            return await EvaluatePerlinFallbackAsync(coord, ct);
        }
        finally
        {
            _gate.Release();
        }
    }

#if VISTA_2023
    private async Task<ChunkData> EvaluateVistaGraphAsync(ChunkCoord coord, CancellationToken ct)
    {
        // Compute world bounds for this chunk
        float xMin = coord.x * coord.chunkSize + worldOffset.x;
        float zMin = coord.z * coord.chunkSize + worldOffset.y;
        float size = coord.chunkSize;

        int hResOut = Mathf.Max(2, heightResolution);
        int aResOut = Mathf.Max(0, alphaResolution);
        int bleed = Mathf.Max(0, bleedPixels);

        // 1) Create/Acquire a runner/evaluator bound to this graph
        using (var runner = VistaRuntimeBridge.CreateRunner(vistaGraphAsset, seed, preferGPU))
        {
            ct.ThrowIfCancellationRequested();

            // 2) Configure per-chunk world bounds and output resolutions (include bleed for heights if supported)
            VistaRuntimeBridge.SetChunkBounds(runner, xMin, zMin, size, size);
            VistaRuntimeBridge.SetOutputResolutions(runner, hResOut, aResOut, bleed);

            // 3) Kick off async evaluation (runner may run on main thread depending on Vista API)
            await VistaRuntimeBridge.EvaluateAsync(runner, ct);
            ct.ThrowIfCancellationRequested();

            // 4) Read back height and splat data
            float[,] heightsWithBleed = VistaRuntimeBridge.ReadHeights(runner, out int hResWithBleed);
            float[,,] splats = (aResOut > 0) ? VistaRuntimeBridge.ReadSplatmaps(runner, out int aRes, out int layers) : null;

            // 5) Trim bleed from heights if runner produced expanded borders
            float[,] heights = TrimBleedIfNeeded(heightsWithBleed, hResOut, bleed);

            var data = new ChunkData
            {
                heights = heights,
                alphamaps = splats,
                heightResolution = hResOut,
                alphaResolution = (splats != null ? splats.GetLength(0) : 0),
                layerCount = (splats != null ? splats.GetLength(2) : 0)
            };
            return data;
        }
    }

    private static float[,] TrimBleedIfNeeded(float[,] src, int targetRes, int bleed)
    {
        int srcRes = src.GetLength(0);
        if (bleed <= 0 || srcRes == targetRes)
            return src;

        int start = Mathf.Clamp(bleed, 0, srcRes - 1);
        int end = Mathf.Clamp(srcRes - bleed, 0, srcRes);
        int outRes = end - start;
        if (outRes != targetRes)
        {
            // Fallback: resample center to targetRes if mismatch
            return ResizeHeightsBilinear(src, targetRes);
        }

        float[,] dst = new float[targetRes, targetRes];
        for (int y = 0; y < targetRes; y++)
        for (int x = 0; x < targetRes; x++)
            dst[y, x] = src[start + y, start + x];
        return dst;
    }

    private static float[,] ResizeHeightsBilinear(float[,] src, int targetRes)
    {
        int srcRes = src.GetLength(0);
        float[,] dst = new float[targetRes, targetRes];
        float scale = (srcRes - 1f) / (targetRes - 1f);
        for (int y = 0; y < targetRes; y++)
        {
            float sy = y * scale;
            int y0 = Mathf.Clamp(Mathf.FloorToInt(sy), 0, srcRes - 1);
            int y1 = Mathf.Clamp(y0 + 1, 0, srcRes - 1);
            float fy = sy - y0;
            for (int x = 0; x < targetRes; x++)
            {
                float sx = x * scale;
                int x0 = Mathf.Clamp(Mathf.FloorToInt(sx), 0, srcRes - 1);
                int x1 = Mathf.Clamp(x0 + 1, 0, srcRes - 1);
                float fx = sx - x0;
                float v00 = src[y0, x0];
                float v01 = src[y0, x1];
                float v10 = src[y1, x0];
                float v11 = src[y1, x1];
                float v0 = Mathf.Lerp(v00, v01, fx);
                float v1 = Mathf.Lerp(v10, v11, fx);
                dst[y, x] = Mathf.Lerp(v0, v1, fy);
            }
        }
        return dst;
    }
#else
    private async Task<ChunkData> EvaluateVistaGraphAsync(ChunkCoord coord, CancellationToken ct)
    {
        // Define VISTA_2023 and implement VistaRuntimeBridge to enable Vista path.
        return await EvaluatePerlinFallbackAsync(coord, ct);
    }
#endif

    private async Task<ChunkData> EvaluatePerlinFallbackAsync(ChunkCoord coord, CancellationToken ct)
    {
        // Simple async wrapper to avoid blocking streamer
        return await Task.Run(() =>
        {
            int hRes = Mathf.Max(2, heightResolution);
            int aRes = Mathf.Max(0, alphaResolution);
            float[,] heights = new float[hRes, hRes];
            float scale = 0.0035f * coord.chunkSize;
            float ox = coord.x * coord.chunkSize + worldOffset.x;
            float oz = coord.z * coord.chunkSize + worldOffset.y;

            for (int y = 0; y < hRes; y++)
            {
                for (int x = 0; x < hRes; x++)
                {
                    float wx = ox + (x / (float)(hRes - 1)) * coord.chunkSize;
                    float wz = oz + (y / (float)(hRes - 1)) * coord.chunkSize;
                    float v = Mathf.PerlinNoise(wx * scale + seed * 0.01f, wz * scale + seed * 0.01f);
                    heights[y, x] = v;
                }
            }

            float[,,] splats = null;
            int layers = 0;
            if (aRes > 0)
            {
                layers = 2;
                splats = new float[aRes, aRes, layers];
                for (int y = 0; y < aRes; y++)
                for (int x = 0; x < aRes; x++)
                {
                    float h = heights[(int)((y / (float)(aRes - 1)) * (hRes - 1)), (int)((x / (float)(aRes - 1)) * (hRes - 1))];
                    float g0 = Mathf.SmoothStep(0.0f, 0.6f, h);
                    float g1 = 1f - g0;
                    float sum = g0 + g1 + 1e-6f;
                    splats[y, x, 0] = g0 / sum;
                    splats[y, x, 1] = g1 / sum;
                }
            }

            return new ChunkData
            {
                heights = heights,
                alphamaps = splats,
                heightResolution = hRes,
                alphaResolution = aRes,
                layerCount = layers
            };
        }, ct);
    }
}

