#region Terrain chunk streamer

public class TerrainChunkStreamer : MonoBehaviour
{
    [Header("References")]
    public Transform player;
    public MonoBehaviour dataProviderComponent; // must implement IChunkDataProvider

    [Header("Streaming")]
    public float chunkSize = 256f;
    public int renderRadiusChunks = 2; // Chebyshev radius
    public float updateInterval = 0.25f;

    private IChunkDataProvider _provider;
    private readonly Dictionary<(int, int), Terrain> _active = new();
    private readonly Dictionary<(int, int), CancellationTokenSource> _inflight = new();
    private float _nextTick;

    void Awake()
    {
        _provider = dataProviderComponent as IChunkDataProvider;
        if (_provider == null)
        {
            Debug.LogError("Data Provider must implement IChunkDataProvider");
        }
    }

    void OnDisable()
    {
        foreach (var kv in _inflight)
        {
            kv.Value.Cancel();
            kv.Value.Dispose();
        }
        _inflight.Clear();
    }

    void Update()
    {
        if (player == null || _provider == null) return;
        if (Time.time < _nextTick) return;
        _nextTick = Time.time + updateInterval;
        Tick();
    }

    private void Tick()
    {
        var center = WorldToChunk(player.position);
        var desired = new HashSet<(int, int)>();

        for (int dz = -renderRadiusChunks; dz <= renderRadiusChunks; dz++)
        {
            for (int dx = -renderRadiusChunks; dx <= renderRadiusChunks; dx++)
            {
                if (Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz)) > renderRadiusChunks) continue;
                int cx = center.x + dx;
                int cz = center.z + dz;
                desired.Add((cx, cz));

                if (_active.ContainsKey((cx, cz)) || _inflight.ContainsKey((cx, cz)))
                    continue;

                // Spawn missing chunk asynchronously
                var cts = new CancellationTokenSource();
                _inflight[(cx, cz)] = cts;
                var coord = new ChunkCoord { x = cx, z = cz, chunkSize = chunkSize };
                _ = SpawnChunkAsync(coord, cts.Token);
            }
        }

        // Unload chunks that left the radius
        var toRemove = new List<(int, int)>();
        foreach (var kv in _active)
        {
            if (!desired.Contains(kv.Key))
            {
                toRemove.Add(kv.Key);
            }
        }
        foreach (var key in toRemove)
        {
            if (_active.TryGetValue(key, out var ter) && ter != null)
            {
                Destroy(ter.gameObject);
            }
            _active.Remove(key);

            if (_inflight.TryGetValue(key, out var cts))
            {
                cts.Cancel();
                cts.Dispose();
                _inflight.Remove(key);
            }
        }

        // Update neighbors after add/remove
        WireNeighbors();
    }

    private async Task SpawnChunkAsync(ChunkCoord coord, CancellationToken ct)
    {
        try
        {
            ChunkData data = await _provider.GetChunkAsync(coord, ct);
            ct.ThrowIfCancellationRequested();

            // Create TerrainData
            var tdata = new TerrainData
            {
                heightmapResolution = data.heightResolution,
                alphamapResolution = Mathf.Max(16, data.alphaResolution),
                baseMapResolution = Mathf.Max(16, data.alphaResolution)
            };
            tdata.size = new Vector3(coord.chunkSize, GetTerrainHeightFromProvider(), coord.chunkSize);

            // Heights
            tdata.SetHeights(0, 0, data.heights);

            // Splatmaps
            if (data.alphamaps != null && data.layerCount > 0)
            {
                EnsureTerrainLayers(tdata, data.layerCount);
                tdata.SetAlphamaps(0, 0, data.alphamaps);
            }

            // Create Terrain object
            var go = Terrain.CreateTerrainGameObject(tdata);
            go.name = $"Terrain_{coord.x}_{coord.z}";
            go.transform.position = new Vector3(coord.x * coord.chunkSize, 0f, coord.z * coord.chunkSize);
            var terrain = go.GetComponent<Terrain>();
            terrain.drawInstanced = true;

            _active[(coord.x, coord.z)] = terrain;
        }
        catch (OperationCanceledException)
        {
            // Swallow
        }
        catch (Exception ex)
        {
            Debug.LogError($"Chunk ({coord.x},{coord.z}) generation failed: {ex}");
        }
        finally
        {
            _inflight.Remove((coord.x, coord.z));
        }
    }

    private float GetTerrainHeightFromProvider()
    {
        // Try to read from VistaGraphAdapter if present
        if (dataProviderComponent is VistaGraphAdapter v)
            return Mathf.Max(1f, v.terrainHeight);
        return 300f;
    }

    private void EnsureTerrainLayers(TerrainData td, int needed)
    {
        var layers = td.terrainLayers;
        if (layers == null || layers.Length < needed)
        {
            int old = layers?.Length ?? 0;
            Array.Resize(ref layers, needed);
            for (int i = old; i < needed; i++)
            {
                var tl = new TerrainLayer();
                tl.diffuseTexture = Texture2D.grayTexture;
                tl.tileSize = new Vector2(10, 10);
                tl.name = $"AutoLayer_{i}";
                layers[i] = tl;
            }
            td.terrainLayers = layers;
        }
    }

    private void WireNeighbors()
    {
        foreach (var kv in _active)
        {
            int x = kv.Key.Item1;
            int z = kv.Key.Item2;
            _active.TryGetValue((x - 1, z), out var left);
            _active.TryGetValue((x + 1, z), out var right);
            _active.TryGetValue((x, z + 1), out var top);
            _active.TryGetValue((x, z - 1), out var bottom);
            kv.Value.SetNeighbors(left, top, right, bottom);
        }
    }

    private (int x, int z) WorldToChunk(Vector3 pos)
    {
        int cx = Mathf.FloorToInt(pos.x / chunkSize);
        int cz = Mathf.FloorToInt(pos.z / chunkSize);
        return (cx, cz);
    }
}

