% Local functions
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function T = Braking_torque(P, T_brk_max)
% Braking_torque
% Inputs:
%   P         - normalized brake pressure command [0..1]
%   T_brk_max - maximum brake torque [N*m]
% Output:
%   T         - brake torque [N*m]
    P = max(0.0, min(1.0, P));
    T = P * T_brk_max;
end

function P_new = ramp(P_cur, P_target, dP_up, dP_down, dt, P_min, P_max)
% ramp
% Rate-limited ramp from current pressure to target pressure.
% Inputs:
%   P_cur    - current pressure (normalized)
%   P_target - target pressure (normalized)
%   dP_up    - max increase rate [1/s]
%   dP_down  - max decrease rate [1/s]
%   dt       - timestep [s]
%   P_min    - minimum pressure clamp
%   P_max    - maximum pressure clamp
% Output:
%   P_new    - updated pressure after rate limit and clamping
    delta = P_target - P_cur;
    if delta > 0
        step = min(delta, dP_up*dt);
    else
        step = max(delta, -dP_down*dt);
    end
    P_new = P_cur + step;
    P_new = max(P_min, min(P_max, P_new));
end

function s = slip(v, w, R)
% slip
% Computes braking slip s = (v - w*R) / v, guarded near zero speed.
% Inputs:
%   v - vehicle longitudinal speed [m/s]
%   w - wheel angular speed [rad/s]
%   R - wheel effective radius [m]
% Output:
%   s - slip (bounded to [0, 1] for braking)
    if v <= 0.1
        s = 0.0;
        return;
    end
    s = (v - w*R) / max(v, 1e-6);
    s = max(0.0, min(1.0, s));
end

function P_next = ABScycle(slip_k, s_low, s_high, P_cur, dt, dP_up, dP_down, P_min, P_max)
% ABScycle
% Simple bang-bang ABS controller that maintains slip within [s_low, s_high].
% Inputs:
%   slip_k  - current slip
%   s_low   - lower slip threshold
%   s_high  - upper slip threshold
%   P_cur   - current normalized brake pressure
%   dt      - timestep [s]
%   dP_up   - pressure increase rate [1/s]
%   dP_down - pressure decrease rate [1/s]
%   P_min   - min clamp
%   P_max   - max clamp
% Output:
%   P_next  - next pressure command after ABS logic and rate limit
    if slip_k > s_high
        % Too much slip (incipient lock) -> decrease pressure
        P_tgt = P_min;
    elseif slip_k < s_low
        % Too little slip -> increase pressure
        P_tgt = P_max;
    else
        % Within band -> hold
        P_tgt = P_cur;
    end
    P_next = ramp(P_cur, P_tgt, dP_up, dP_down, dt, P_min, P_max);
end

function mu = tiremodel(slip_k, tire)
% tiremodel (Burckhardt-type)
% Maps slip to friction coefficient using a basic Burckhardt formulation.
% Inputs:
%   slip_k - current slip [0..1]
%   tire   - struct with fields a1, a2, a3 (surface-dependent)
% Output:
%   mu     - longitudinal friction coefficient [-]
    s = max(0.0, min(1.0, slip_k));
    mu = tire.a1 * (1 - exp(-tire.a2 * s)) - tire.a3 * s;
    mu = max(0.0, mu); % clamp to non-negative for stability
end

Below is a minimal, self-contained Rust workspace that builds two binaries:

- sysx-init: PID 1 init at /sbin/sysx
- sysx: CLI at /usr/bin/sysx

It implements:
- Early mounts (/proc, /sys, /dev via devtmpfs), fsck, mount -a
- Optional networking via ip and udhcpc
- Supervised tasks: getty@tty1 and dummy-sleeper with restart policies and simple backoff
- Signal handling: reaping, shutdown on SIGTERM/SIGINT/USR1/PWR
- Per-task logs at /var/log/sysx/<task>.log with crude rotation
- Control socket /run/sysx.sock with simple JSON protocol
- CLI: list, start, stop, status, tail

Notes and caveats:
- PID 1 avoids panics; logs to /dev/console on critical errors.
- No tokio in PID 1; synchronous loop.
- CLI uses tokio for tail streaming with a blocking fallback.
- No persistence: tasks added via CLI are kept only in-memory for this run.
- Graceful shutdown is minimal; uses /sbin/poweroff -f or /sbin/reboot -f if available.

Directory layout:
- Cargo.toml (workspace)
- sysx-common (shared protocol and types)
- sysx-init (init, PID 1)
- sysx (CLI)

Build:
- cargo build --release
- Install: copy target/release/sysx-init to /sbin/sysx and target/release/sysx to /usr/bin/sysx (ensure ownership and perms)
- Make /sbin/sysx the init in your bootloader/kernel cmdline: init=/sbin/sysx

