use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub enum RestartPolicy {
    Always,
    OnFailure,
    Never,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TaskSpec {
    pub name: String,
    pub cmd: Vec<String>,         // argv
    pub env: HashMap<String, String>,
    pub cwd: Option<String>,
    pub restart: RestartPolicy,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TaskStatus {
    pub name: String,
    pub pid: Option<i32>,
    pub running: bool,
    pub last_exit: Option<i32>,
    pub restarts: u32,
    pub log_path: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Request {
    List,
    Start { spec: TaskSpec },
    Stop { name: String },
    Status { name: String },
    Tail { name: String, follow: bool, lines: usize }, // for CLI -> init: request to start stream; init replies with error or ok and then streams raw lines (simplified)
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Response {
    Ok,
    Error { msg: String },
    TaskList { tasks: Vec<TaskStatus> },
    TaskStatus { status: TaskStatus },
    TailStartOk, // followed by streaming lines (not JSON) over the same socket
}

impl TaskSpec {
    pub fn new<S: Into<String>>(name: S, cmd: Vec<String>, restart: RestartPolicy) -> Self {
        Self { name: name.into(), cmd, env: HashMap::new(), cwd: None, restart }
    }
}

