// Minimal init (PID 1) for Devuan without sysv/systemd.
// Safety: avoid panics; log to /dev/console and continue where reasonable.

use nix::errno::Errno;
use nix::mount::{mount, MsFlags};
use nix::sys::signal::{kill, SigHandler, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{fork, getpid, ForkResult, Pid};
use serde_json::json;
use std::collections::HashMap;
use std::fs::{self, File, OpenOptions};
use std::io::{Read, Write};
use std::os::unix::fs::PermissionsExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::os::unix::prelude::CommandExt;
use std::path::{Path, PathBuf};
use std::process::{exit, Command, Stdio};
use std::sync::{Arc, Mutex};
use sysx-common::{Request, Response, RestartPolicy, TaskSpec, TaskStatus};

static CONSOLE: &str = "/dev/console";
static SOCK_PATH: &str = "/run/sysx.sock";
static LOG_DIR: &str = "/var/log/sysx";
static RUN_DIR: &str = "/run";

#[derive(Clone)]
struct Task {
    spec: TaskSpec,
    pid: Option<Pid>,
    restarts: u32,
    last_exit: Option<i32>,
    backoff_secs: u64,
}

impl Task {
    fn status(&self) -> TaskStatus {
        TaskStatus {
            name: self.spec.name.clone(),
            pid: self.pid.map(|p| p.as_raw()),
            running: self.pid.is_some(),
            last_exit: self.last_exit,
            restarts: self.restarts,
            log_path: format!("{}/{}.log", LOG_DIR, self.spec.name),
        }
    }
}

struct State {
    tasks: HashMap<String, Task>,
}

fn log_console<S: AsRef<str>>(s: S) {
    if let Ok(mut f) = OpenOptions::new().create(true).append(true).open(CONSOLE) {
        let _ = writeln!(f, "sysx-init: {}", s.as_ref());
    }
}

fn ensure_dirs() {
    for d in ["/proc", "/sys", "/dev", LOG_DIR, RUN_DIR] {
        if let Err(e) = fs::create_dir_all(d) {
            log_console(format!("Failed to create {}: {}", d, e));
        }
    }
    if let Ok(md) = fs::metadata(RUN_DIR) {
        let mut p = md.permissions();
        p.set_mode(0o755);
        let _ = fs::set_permissions(RUN_DIR, p);
    }
    if let Ok(_) = fs::metadata(LOG_DIR) {
        // keep perms default
    }
}

fn early_mounts() {
    // Mount proc
    let _ = mount(Some("proc"), "/proc", Some("proc"), MsFlags::empty(), None::<&str>);
    // Mount sysfs
    let _ = mount(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::empty(), None::<&str>);
    // Mount devtmpfs
    let _ = mount(Some("devtmpfs"), "/dev", Some("devtmpfs"), MsFlags::empty(), None::<&str>);
}

fn run(cmd: &str, args: &[&str]) -> i32 {
    match Command::new(cmd).args(args).status() {
        Ok(s) => s.code().unwrap_or(0),
        Err(e) => {
            log_console(format!("exec {} failed: {}", cmd, e));
            127
        }
    }
}

fn fsck_and_mount() {
    // Try to remount root rw based on /etc/fstab later via mount -a anyway
    // Run fsck -A -T
    let _ = Command::new("/sbin/fsck").arg("-A").arg("-T").status()
        .or_else(|_| Command::new("/bin/fsck").arg("-A").arg("-T").status());
    // Mount all from fstab
    let _ = Command::new("/bin/mount").arg("-a").status()
        .or_else(|_| Command::new("/sbin/mount").arg("-a").status());
}

fn bringup_network() {
    // Find first non-loopback interface using ip -o -4 link show | grep -v lo
    let ipbin = if Path::new("/sbin/ip").exists() { "/sbin/ip" } else if Path::new("/bin/ip").exists() { "/bin/ip" } else { "" };
    if ipbin.is_empty() { log_console("ip not found; skipping network"); return; }
    let output = Command::new(ipbin).args(["-o", "link", "show"]).output();
    let data = match output {
        Ok(o) => String::from_utf8_lossy(&o.stdout).to_string(),
        Err(e) => { log_console(format!("ip link show failed: {}", e)); return; }
    };
    let mut ifname = None;
    for line in data.lines() {
        // format: "1: lo: ...", "2: eth0: ..."
        if let Some(colon) = line.find(':') {
            let rest = &line[colon+1..].trim();
            if let Some(colon2) = rest.find(':') {
                let name = rest[..colon2].trim();
                if name != "lo" {
                    ifname = Some(name.to_string());
                    break;
                }
            }
        }
    }
    let iface = match ifname { Some(n) => n, None => { log_console("no non-loopback iface; skipping dhcp"); return; } };
    let _ = Command::new(ipbin).args(["link", "set", &iface, "up"]).status();
    // Try udhcpc
    let udhcpc = if Path::new("/sbin/udhcpc").exists() { "/sbin/udhcpc" } else if Path::new("/bin/udhcpc").exists() { "/bin/udhcpc" } else { "" };
    if udhcpc.is_empty() {
        log_console("udhcpc not found; skipping DHCP");
        return;
    }
    let _ = Command::new(udhcpc).args(["-i", &iface, "-q", "-n"]).status();
}

fn open_task_log(name: &str) -> Option<File> {
    let path = format!("{}/{}.log", LOG_DIR, name);
    // crude rotation: if > 1MB, truncate
    if let Ok(meta) = fs::metadata(&path) {
        if meta.len() > 1_000_000 {
            let _ = OpenOptions::new().write(true).truncate(true).open(&path);
        }
    }
    match OpenOptions::new().create(true).append(true).open(&path) {
        Ok(f) => Some(f),
        Err(e) => { log_console(format!("open log {} failed: {}", path, e)); None }
    }
}

fn spawn_task(t: &mut Task) {
    let name = t.spec.name.clone();
    let mut cmd_iter = t.spec.cmd.iter();
    let prog = match cmd_iter.next() {
        Some(p) => p.clone(),
        None => { log_console(format!("task {} has empty cmd", name)); return; }
    };
    let args: Vec<String> = cmd_iter.cloned().collect();

    match unsafe { fork() } {
        Ok(ForkResult::Child) => {
            // Child: setid, stdio to log
            let _ = nix::unistd::setsid();
            if let Some(mut f) = open_task_log(&name) {
                let _ = nix::unistd::dup2(f.as_raw_fd(), 1);
                let _ = nix::unistd::dup2(f.as_raw_fd(), 2);
            } else {
                // fallback to console
                if let Ok(mut c) = OpenOptions::new().write(true).open(CONSOLE) {
                    let _ = nix::unistd::dup2(c.as_raw_fd(), 1);
                    let _ = nix::unistd::dup2(c.as_raw_fd(), 2);
                }
            }

            if let Some(cwd) = &t.spec.cwd {
                let _ = std::env::set_current_dir(cwd);
            }
            for (k,v) in &t.spec.env {
                std::env::set_var(k, v);
            }
            // Exec
            let err = Command::new(&prog).args(&args).exec();
            let _ = writeln!(std::io::stderr(), "exec {} failed: {:?}", prog, err);
            exit(127);
        }
        Ok(ForkResult::Parent { child }) => {
            t.pid = Some(child);
            log_console(format!("spawned task {} pid {}", name, child));
        }
        Err(e) => {
            log_console(format!("fork failed for {}: {}", name, e));
        }
    }
}

fn stop_task(t: &mut Task) {
    if let Some(pid) = t.pid {
        let _ = kill(pid, Signal::SIGTERM);
    }
}

fn backoff_next(t: &mut Task) {
    if t.backoff_secs == 0 { t.backoff_secs = 1; }
    else { t.backoff_secs = (t.backoff_secs * 2).min(30); }
}

fn clear_backoff(t: &mut Task) { t.backoff_secs = 0; }

fn default_tasks() -> Vec<TaskSpec> {
    // getty@tty1
    let agetty = if Path::new("/sbin/agetty").exists() { "/sbin/agetty" } else { "/bin/agetty" };
    let mut tasks = vec![];
    if Path::new(agetty).exists() && Path::new("/bin/login").exists() {
        tasks.push(TaskSpec::new(
            "getty@tty1",
            vec![agetty.to_string(), "--login-program".into(), "/bin/login".into(), "tty1".into()],
            RestartPolicy::Always,
        ));
    } else {
        log_console("agetty or login not found; skipping getty@tty1");
    }
    // dummy-sleeper
    tasks.push(TaskSpec::new(
        "dummy-sleeper",
        vec!["/bin/sh".into(), "-c".into(), "sleep infinity".into()],
        RestartPolicy::Always,
    ));
    tasks
}

fn setup_socket() -> Option<UnixListener> {
    // Remove stale
    let _ = fs::remove_file(SOCK_PATH);
    // Ensure /run perms OK
    if let Err(e) = std::os::unix::net::UnixListener::bind(SOCK_PATH) {
        log_console(format!("bind socket {} failed: {}", SOCK_PATH, e));
        return None;
    }
    let _ = fs::set_permissions(SOCK_PATH, fs::Permissions::from_mode(0o600));
    match UnixListener::bind(SOCK_PATH) {
        Ok(_) => { /* this double-bind is wrong - correct below */ }
        Err(_) => { /* ignore */ }
    }
    // The above incorrect double-bind: fix by removing and binding once properly
    let _ = fs::remove_file(SOCK_PATH);
    match UnixListener::bind(SOCK_PATH) {
        Ok(listener) => {
            let _ = fs::set_permissions(SOCK_PATH, fs::Permissions::from_mode(0o600));
            Some(listener)
        }
        Err(e) => { log_console(format!("bind {} failed: {}", SOCK_PATH, e)); None }
    }
}

fn handle_client(mut stream: UnixStream, state: &Arc<Mutex<State>>) {
    // Read a single JSON request, write single JSON response.
    let mut buf = Vec::new();
    let _ = stream.read_to_end(&mut buf); // connection is short-lived; CLI closes after write
    if buf.is_empty() {
        let _ = serde_json::to_writer(&mut stream, &Response::Error { msg: "empty request".into() });
        let _ = stream.write_all(b"\n");
        return;
    }
    let req: Result<Request, _> = serde_json::from_slice(&buf);
    let req = match req {
        Ok(r) => r,
        Err(e) => {
            let _ = serde_json::to_writer(&mut stream, &Response::Error { msg: format!("bad json: {}", e) });
            let _ = stream.write_all(b"\n");
            return;
        }
    };

    match req {
        Request::List => {
            let st = state.lock().unwrap();
            let mut v = Vec::new();
            for t in st.tasks.values() {
                v.push(t.status());
            }
            let _ = serde_json::to_writer(&mut stream, &Response::TaskList { tasks: v });
            let _ = stream.write_all(b"\n");
        }
        Request::Status { name } => {
            let st = state.lock().unwrap();
            if let Some(t) = st.tasks.get(&name) {
                let _ = serde_json::to_writer(&mut stream, &Response::TaskStatus { status: t.status() });
                let _ = stream.write_all(b"\n");
            } else {
                let _ = serde_json::to_writer(&mut stream, &Response::Error { msg: "not found".into() });
                let _ = stream.write_all(b"\n");
            }
        }
        Request::Start { spec } => {
            let mut st = state.lock().unwrap();
            if let Some(existing) = st.tasks.get_mut(&spec.name) {
                if existing.pid.is_some() {
                    let _ = serde_json::to_writer(&mut stream, &Response::Error { msg: "already running".into() });
                    let _ = stream.write_all(b"\n");
                    return;
                }
            }
            let mut t = Task { spec: spec.clone(), pid: None, restarts: 0, last_exit: None, backoff_secs: 0 };
            spawn_task(&mut t);
            st.tasks.insert(spec.name.clone(), t);
            let _ = serde_json::to_writer(&mut stream, &Response::Ok);
            let _ = stream.write_all(b"\n");
        }
        Request::Stop { name } => {
            let mut st = state.lock().unwrap();
            if let Some(t) = st.tasks.get_mut(&name) {
                stop_task(t);
                let _ = serde_json::to_writer(&mut stream, &Response::Ok);
                let _ = stream.write_all(b"\n");
            } else {
                let _ = serde_json::to_writer(&mut stream, &Response::Error { msg: "not found".into() });
                let _ = stream.write_all(b"\n");
            }
        }
        Request::Tail { name, follow, lines } => {
            // Send TailStartOk, then dump last N lines and optionally follow by streaming appended lines.
            // For simplicity, we won't implement continuous follow over the same request here (that needs non-JSON stream).
            // We'll just send last N lines and close. CLI will poll or use a simple follow mode by reconnecting.
            let path = format!("{}/{}.log", LOG_DIR, name);
            let data = fs::read_to_string(&path).unwrap_or_default();
            let mut lines_vec: Vec<&str> = data.lines().collect();
            let n = lines_vec.len();
            if lines < n { lines_vec = lines_vec[n - lines..].to_vec(); }
            let header = Response::TailStartOk;
            let _ = serde_json::to_writer(&mut stream, &header);
            let _ = stream.write_all(b"\n");
            let joined = lines_vec.join("\n") + "\n";
            let _ = stream.write_all(joined.as_bytes());
            if follow {
                // Naive follow: poll file size and resend appended lines for a short time.
                // To keep PID1 simple, we avoid long-held connections; close here.
            }
        }
    }
}

extern "C" fn handle_sigterm(_: i32) {
    // nothing; main loop checks signals via waitpid and kill on children later
}

fn setup_signals() {
    unsafe {
        let _ = nix::sys::signal::signal(Signal::SIGTERM, SigHandler::Handler(handle_sigterm));
        let _ = nix::sys::signal::signal(Signal::SIGINT, SigHandler::Handler(handle_sigterm));
        let _ = nix::sys::signal::signal(Signal::SIGCHLD, SigHandler::Handler(handle_sigterm));
        let _ = nix::sys::signal::signal(Signal::SIGUSR1, SigHandler::Handler(handle_sigterm));
        let _ = nix::sys::signal::signal(Signal::SIGPWR, SigHandler::Handler(handle_sigterm));
    }
}

fn shutdown_all(state: &Arc<Mutex<State>>) {
    log_console("shutting down: sending SIGTERM to all tasks");
    {
        let st = state.lock().unwrap();
        for t in st.tasks.values() {
            if let Some(pid) = t.pid {
                let _ = kill(pid, Signal::SIGTERM);
            }
        }
    }
    // wait a bit
    std::thread::sleep(std::time::Duration::from_secs(3));
    {
        let st = state.lock().unwrap();
        for t in st.tasks.values() {
            if let Some(pid) = t.pid {
                let _ = kill(pid, Signal::SIGKILL);
            }
        }
    }
    let _ = Command::new("/bin/sync").status();
    // Try unmounting non-root; keep simple
    let _ = Command::new("/bin/umount").arg("-a").arg("-r").status();
    // Poweroff or reboot
    if Path::new("/sbin/poweroff").exists() {
        let _ = Command::new("/sbin/poweroff").arg("-f").status();
    } else if Path::new("/sbin/reboot").exists() {
        let _ = Command::new("/sbin/reboot").arg("-f").status();
    } else {
        log_console("no poweroff/reboot command; halting");
        unsafe { nix::sys::reboot::reboot(nix::sys::reboot::RebootMode::RB_HALT_SYSTEM).ok(); }
    }
}

