        // Start a one-time socket server thread on first iteration
        static STARTED_SOCK: std::sync::Once = std::sync::Once::new();
        STARTED_SOCK.call_once(|| {
            let st = state.clone();
            std::thread::spawn(move || {
                // Fresh bind
                let _ = fs::remove_file(SOCK_PATH);
                let listener = match UnixListener::bind(SOCK_PATH) {
                    Ok(l) => l,
                    Err(e) => { log_console(format!("socket bind failed in thread: {}", e)); return; }
                };
                let _ = fs::set_permissions(SOCK_PATH, fs::Permissions::from_mode(0o600));
                for conn in listener.incoming() {
                    match conn {
                        Ok(stream) => {
                            handle_client(stream, &st);
                        }
                        Err(e) => {
                            log_console(format!("socket accept err: {}", e));
                            // brief sleep to avoid busy loop
                            std::thread::sleep(std::time::Duration::from_millis(100));
                        }
                    }
                }
            });
        });

        // Sleep 1s tick, and decrement backoffs
        {
            let mut st = state.lock().unwrap();
            for t in st.tasks.values_mut() {
                if t.pid.is_none() && t.backoff_secs > 0 {
                    t.backoff_secs -= 1;
                }
            }
        }
        std::thread::sleep(std::time::Duration::from_secs(1));
    }
