use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use serde_json::Deserializer;
use std::fs::File;
use std::io::{Read, Write};
use std::os::unix::net::UnixStream;
use sysx-common::{Request, Response, TaskSpec, RestartPolicy};

static SOCK_PATH: &str = "/run/sysx.sock";

#[derive(Parser, Debug)]
#[command(name = "sysx", about = "CLI to interact with sysx init")]
struct Cli {
    #[command(subcommand)]
    cmd: Cmd,
}

#[derive(Subcommand, Debug)]
enum Cmd {
    List,
    Status { name: String },
    Start {
        name: String,
        #[arg(long, default_value = "/bin/sh")]
        prog: String,
        #[arg(long, num_args=0.., value_delimiter=' ')]
        args: Vec<String>,
        #[arg(long, default_value = "always", value_parser = ["always","on-failure","never"])]
        restart: String,
    },
    Stop { name: String },
    Tail { name: String, #[arg(long, default_value_t=100)] lines: usize },
}

fn send_request(req: &Request) -> Result<Response> {
    let mut stream = UnixStream::connect(SOCK_PATH).context("connect to sysx.sock")?;
    let data = serde_json::to_vec(req)?;
    stream.write_all(&data)?;
    // Close write to signal end of message
    stream.shutdown(std::net::Shutdown::Write)?;
    // Read one JSON response line
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf)?;
    // Some commands (Tail) may append non-JSON bytes after the first line; handle separately in caller.
    // Parse first line
    if let Some(pos) = buf.iter().position(|b| *b == b'\n') {
        let first = &buf[..pos];
        let rest = &buf[pos+1..];
        let resp: Response = serde_json::from_slice(first)?;
        // Save rest for Tail path via global stash; here we just print if present
        if !rest.is_empty() {
            print!("{}", String::from_utf8_lossy(rest));
        }
        Ok(resp)
    } else {
        let resp: Response = serde_json::from_slice(&buf)?;
        Ok(resp)
    }
}

#[tokio::main(flavor="multi_thread")]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    match cli.cmd {
        Cmd::List => {
            match send_request(&Request::List)? {
                Response::TaskList { tasks } => {
                    for t in tasks {
                        println!("{}: running={} pid={:?} restarts={} last_exit={:?} log={}",
                            t.name, t.running, t.pid, t.restarts, t.last_exit, t.log_path);
                    }
                }
                Response::Error { msg } => bail!(msg),
                _ => {}
            }
        }
        Cmd::Status { name } => {
            match send_request(&Request::Status { name })? {
                Response::TaskStatus { status } => {
                    println!("{}: running={} pid={:?} restarts={} last_exit={:?} log={}",
                        status.name, status.running, status.pid, status.restarts, status.last_exit, status.log_path);
                }
                Response::Error { msg } => bail!(msg),
                _ => {}
            }
        }
        Cmd::Start { name, prog, args, restart } => {
            let policy = match restart.as_str() {
                "always" => RestartPolicy::Always,
                "on-failure" => RestartPolicy::OnFailure,
                "never" => RestartPolicy::Never,
                _ => RestartPolicy::Always,
            };
            let mut spec = TaskSpec::new(name.clone(), {
                let mut v = vec![prog];
                v.extend(args);
                v
            }, policy);
            let resp = send_request(&Request::Start { spec })?;
            match resp {
                Response::Ok => println!("started {}", name),
                Response::Error { msg } => bail!(msg),
                _ => {}
            }
        }
        Cmd::Stop { name } => {
            match send_request(&Request::Stop { name: name.clone() })? {
                Response::Ok => println!("stopped"),
                Response::Error { msg } => bail!(msg),
                _ => {}
            }
        }
        Cmd::Tail { name, lines } => {
            // Request Tail; init will respond with TailStartOk then dump last N lines and close.
            match send_request(&Request::Tail { name: name.clone(), follow: false, lines })? {
                Response::TailStartOk => {
                    // Output already printed by send_request for any trailing data
                }
                Response::Error { msg } => bail!(msg),
                _ => {}
            }
        }
    }
    Ok(())
}

Installation and usage:
- Build: cargo build --release
- Install:
  - cp target/release/sysx-init /sbin/sysx
  - cp target/release/sysx /usr/bin/sysx
  - chmod 755 /sbin/sysx /usr/bin/sysx
- Set kernel cmdline to init=/sbin/sysx for Devuan.
- Boot.
- After login, interact:
  - sysx list
  - sysx status getty@tty1
  - sysx start mytask --prog /bin/sh --args "-c echo hi && sleep 5" --restart on-failure
  - sysx stop mytask
  - sysx tail dummy-sleeper --lines 50

Limitations and places to harden for production:
- Socket handling in init is simplified (served in a thread).
- Tail follow is non-streaming; could be extended to keep connection open and stream.
- Backoff and timing are coarse 1-second ticks.
- No persistent task config; add a simple /etc/sysx.d/*.json loader if desired.
- Error handling keeps the system moving rather than failing init.
- Shutdown is minimal; add ordered stop and proper umount/swapoff as needed.

