use std::os::fd::{AsRawFd, FromRawFd, RawFd};
use std::os::unix::fs::PermissionsExt;
use std::os::unix::io::OwnedFd;
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::{Path, PathBuf};
use std::process;
use std::str::FromStr;
use std::thread;
use std::time::{Duration, Instant};

const CTL_SOCK: &str = "/run/sysx/ctl.sock";
const LOG_DIR: &str = "/var/log/sysx";
const RUN_DIR: &str = "/run/sysx";

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
enum TaskState {
    Inactive,
    Starting,
    Running,
    Backoff,
    Failed,
    Stopped,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct TaskInfo {
    name: String,
    state: TaskState,
    restarts: u32,
    last_exit: Option<i32>,
    backoff_until: Option<u64>, // unix millis
    pid: Option<i32>,
    policy: RestartPolicy,
}

#[derive(Debug, Clone)]
struct TaskSpec {
    name: String,
    policy: RestartPolicy,
    kind: TaskKind,
}

#[derive(Debug, Clone)]
enum TaskKind {
    Oneshoot(fn() -> i32), // run-to-completion in a child; exit status defines success/failure
    Longrun(Vec<String>),  // exec a process, supervise
}

#[derive(Debug, Serialize, Deserialize)]
enum CtlRequest {
    List,
    Start { name: String },
    Stop { name: String },
    Logs { name: String, tail: Option<usize> },
}

