fn main() {
    // If PID 1, default to init role unless user explicitly passed "ctl".
    let pid = unsafe { libc::getpid() };
    let is_pid1 = pid == 1;

    let cli = Command::new("sysx")
        .about("Minimal init and controller")
        .subcommand_required(false)
        .subcommand(Command::new("init").about("Run init (PID 1 path)"))
        .subcommand(
            Command::new("ctl")
                .about("Controller CLI")
                .subcommand_required(true)
                .subcommand(Command::new("list").about("List tasks"))
                .subcommand(
                    Command::new("start")
                        .about("Start a task")
                        .arg(Arg::new("task").required(true)),
                )
                .subcommand(
                    Command::new("stop")
                        .about("Stop a task")
                        .arg(Arg::new("task").required(true)),
                )
                .subcommand(
                    Command::new("logs")
                        .about("Show task logs")
                        .arg(Arg::new("task").required(true))
                        .arg(
                            Arg::new("tail")
                                .long("tail")
                                .action(ArgAction::Set)
                                .value_parser(clap::value_parser!(usize))
                                .required(false),
                        ),
                ),
        );

    let matches = cli.get_matches();

    match matches.subcommand() {
        Some(("init", _)) => init_main(),
        Some(("ctl", sub)) => ctl_main(sub),
        _ => {
            if is_pid1 {
                init_main();
            } else {
                // Default to ctl path: "list"
                let mut default = Command::new("sysx ctl");
                let _ = default; // avoid unused variable in some builds
                ctl_default();
            }
        }
    }
}

// ============ Controller CLI ============

fn ctl_default() {
    // Default to 'list'
    let req = CtlRequest::List;
