                    t.name, t.state, t.restarts, t.last_exit, t.pid
                );
            }
        }
        Ok(other) => {
            eprintln!("unexpected response: {:?}", other);
            process::exit(1);
        }
        Err(e) => {
            eprintln!("sysx ctl error: {e}");
            process::exit(1);
        }
    }
}

fn ctl_main(matches: &ArgMatches) {
    match matches.subcommand() {
        Some(("list", _)) => {
            match ctl_send(CtlRequest::List) {
                Ok(CtlResponse::List(list)) => {
                    for t in list {
                        println!(
                            "{}\t{:?}\trestarts:{}\tlast_exit:{:?}\tpid:{:?}",
                            t.name, t.state, t.restarts, t.last_exit, t.pid
                        );
                    }
                }
