                    process::exit(1);
                }
            }
        }
        Some(("start", m)) => {
            let name = m.get_one::<String>("task").unwrap().clone();
            match ctl_send(CtlRequest::Start { name }) {
                Ok(CtlResponse::Ok) => println!("OK"),
                Ok(CtlResponse::Error(e)) => {
