                    process::exit(1);
                }
            }
        }
        Some(("stop", m)) => {
            let name = m.get_one::<String>("task").unwrap().clone();
            match ctl_send(CtlRequest::Stop { name }) {
                Ok(CtlResponse::Ok) => println!("OK"),
                Ok(CtlResponse::Error(e)) => {
                    eprintln!("error: {e}");
                    process::exit(1);
                }
                Ok(other) => {
                    eprintln!("unexpected response: {:?}", other);
                    process::exit(1);
                }
                Err(e) => {
                    eprintln!("sysx ctl stop error: {e}");
                    process::exit(1);
                }
            }
        }
        Some(("logs", m)) => {
            let name = m.get_one::<String>("task").unwrap().clone();
            let tail = m.get_one::<usize>("tail").cloned();
            match ctl_send(CtlRequest::Logs { name, tail }) {
                Ok(CtlResponse::Logs(s)) => print!("{s}"),
