fn ctl_send(req: CtlRequest) -> Result<CtlResponse, SysxError> {
    let sock_path = Path::new(CTL_SOCK);
    let mut stream = UnixStream::connect(sock_path)?;
    let data = serde_json::to_vec(&req).unwrap();
    stream.write_all(&(data.len() as u32).to_be_bytes())?;
    stream.write_all(&data)?;
    // read response length + body
    let mut lenbuf = [0u8; 4];
    stream.read_exact(&mut lenbuf)?;
    let len = u32::from_be_bytes(lenbuf) as usize;
    let mut body = vec![0u8; len];
    stream.read_exact(&mut body)?;
    let resp: CtlResponse = serde_json::from_slice(&body).unwrap();
    Ok(resp)
}

// ============ Init and Supervision ============

#[derive(Default)]
struct Runtime {
    tasks: HashMap<String, TaskRuntime>,
    order: Vec<String>,
    shutting_down: bool,
}

struct TaskRuntime {
    spec: TaskSpec,
    state: TaskState,
    restarts: u32,
    last_exit: Option<i32>,
    pid: Option<Pid>,
    backoff_until: Option<Instant>,
    log_file: File,
    // Pipes for capturing child's stdout/err
    stdout_r: Option<OwnedFd>,
    stderr_r: Option<OwnedFd>,
    // Next backoff duration
    next_backoff: Duration,
}

impl Runtime {
    fn new() -> Result<Self, SysxError> {
        fs::create_dir_all(RUN_DIR)?;
        fs::create_dir_all(LOG_DIR)?;
        Ok(Self {
            tasks: HashMap::new(),
            order: vec![],
            shutting_down: false,
        })
    }

    fn add_task(&mut self, spec: TaskSpec) -> Result<(), SysxError> {
        let log_path = format!("{}/{}.log", LOG_DIR, spec.name.replace('/', "_"));
        let log_file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)?;
        let rt = TaskRuntime {
            spec: spec.clone(),
            state: TaskState::Inactive,
            restarts: 0,
            last_exit: None,
            pid: None,
            backoff_until: None,
            log_file,
            stdout_r: None,
            stderr_r: None,
            next_backoff: Duration::from_millis(500),
        };
        self.order.push(spec.name.clone());
        self.tasks.insert(spec.name.clone(), rt);
        Ok(())
    }

    fn task_info(&self, name: &str) -> Option<TaskInfo> {
        self.tasks.get(name).map(|t| TaskInfo {
            name: name.to_string(),
            state: t.state,
            restarts: t.restarts,
            last_exit: t.last_exit,
            backoff_until: t.backoff_until.map(|i| {
                let dur = i.saturating_duration_since(Instant::now());
                let until = (libc::time(std::ptr::null_mut()) as u128)
                    + (dur.as_millis() as u128);
                until as u64
            }),
            pid: t.pid.map(|p| p.as_raw()),
            policy: t.spec.policy,
        })
    }

    fn list(&self) -> Vec<TaskInfo> {
        let mut v = Vec::new();
        for n in &self.order {
            if let Some(i) = self.task_info(n) {
                v.push(i);
            }
        }
        v
    }

    fn start_task(&mut self, name: &str) -> Result<(), SysxError> {
        let tr = match self.tasks.get_mut(name) {
            Some(t) => t,
            None => return Err(SysxError::Other(format!("unknown task {name}"))),
        };
        if matches!(tr.state, TaskState::Running | TaskState::Starting) {
            return Ok(());
        }
        // Respect backoff
        if let Some(until) = tr.backoff_until {
            if Instant::now() < until {
                tr.state = TaskState::Backoff;
                return Ok(());
            }
        }

        // Set up pipes for stdout/stderr if longrun; oneshoot uses same
        let (out_r, out_w) = pipe()?;
        let (err_r, err_w) = pipe()?;
        let out_r = unsafe { OwnedFd::from_raw_fd(out_r) };
        let err_r = unsafe { OwnedFd::from_raw_fd(err_r) };

        match unsafe { fork()? } {
            ForkResult::Parent { child } => {
                // Parent: close write ends, keep read ends
                unsafe {
                    close(out_w)?;
                    close(err_w)?;
                }
                tr.pid = Some(child);
                tr.state = TaskState::Starting;
                tr.stdout_r = Some(out_r);
                tr.stderr_r = Some(err_r);
                // Spawn logger thread for this task
                spawn_logger_threads(name.to_string(), tr.stdout_r.as_ref().unwrap().as_raw_fd(), tr.stderr_r.as_ref().unwrap().as_raw_fd(), tr.log_file.try_clone()?);
            }
            ForkResult::Child => {
                // Child: setsid to detach, redirect stdio to pipes, then exec/do work.
                unsafe { libc::setsid(); }
                // Reset signals to defaults
                unsafe {
                    libc::signal(SIGTERM, libc::SIG_DFL);
                    libc::signal(SIGINT, libc::SIG_DFL);
                    libc::signal(SIGCHLD, libc::SIG_DFL);
                }
                // Duplicate pipe write ends to stdout/stderr
                dup2(out_w, libc::STDOUT_FILENO)?;
                dup2(err_w, libc::STDERR_FILENO)?;
                // Close unused fds
                unsafe {
                    close(out_w).ok();
                    close(err_w).ok();
                }
                // Execute based on kind
                match &tr.spec.kind {
                    TaskKind::Oneshoot(f) => {
                        let code = f();
                        unsafe { libc::_exit(code as i32) };
                    }
                    TaskKind::Longrun(argv) => {
                        // Build CString argv
                        let cargs: Vec<CString> = argv.iter().map(|s| CString::new(s.as_str()).unwrap()).collect();
                        if cargs.is_empty() {
                            eprintln!("empty argv");
                            unsafe { libc::_exit(127) };
                        }
                        // execv requires path as first arg
                        if execv(&cargs[0], &cargs).is_err() {
                            eprintln!("exec failed: {}", argv.join(" "));
                            unsafe { libc::_exit(127) };
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn stop_task(&mut self, name: &str) -> Result<(), SysxError> {
        let tr = match self.tasks.get_mut(name) {
            Some(t) => t,
            None => return Err(SysxError::Other(format!("unknown task {name}"))),
        };
        if let Some(pid) = tr.pid {
            // Send SIGTERM; if not exiting, SIGKILL later in reaper loop
            let _ = kill(pid, Signal::SIGTERM);
        }
        tr.state = TaskState::Stopped;
        Ok(())
    }

    fn tick(&mut self) {
        // Called after SIGCHLD or periodically to handle backoff timeouts.
        // Reap children
        loop {
            match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
                Ok(WaitStatus::Exited(pid, status)) => {
                    self.on_child_exit(pid, status);
                }
                Ok(WaitStatus::Signaled(pid, sig, _)) => {
                    self.on_child_exit(pid, 128 + sig as i32);
                }
                Ok(WaitStatus::StillAlive) => break,
                Ok(_) => {}
                Err(nix::Error::Sys(Errno::ECHILD)) => break,
                Err(_) => break,
            }
        }

        // Start tasks that are due after backoff
        let names: Vec<String> = self.order.clone();
        for name in names {
            let need_start = {
                if let Some(t) = self.tasks.get(&name) {
                    match t.state {
                        TaskState::Inactive | TaskState::Failed | TaskState::Backoff | TaskState::Stopped => {
                            // Eligible to start if policy demands (and not shutting down)
                            if self.shutting_down {
                                false
                            } else {
                                match t.spec.policy {
                                    RestartPolicy::Always => true,
                                    RestartPolicy::OnFailure => matches!(t.state, TaskState::Failed | TaskState::Backoff | TaskState::Inactive),
                                    RestartPolicy::Never => false,
                                }
                            }
                        }
                        _ => false,
                    }
                } else {
                    false
                }
            };
            if need_start {
                let due = {
                    if let Some(t) = self.tasks.get(&name) {
                        if let Some(until) = t.backoff_until {
                            Instant::now() >= until
                        } else {
                            true
                        }
                    } else {
                        false
                    }
                };
                if due {
                    let _ = self.start_task(&name);
                } else {
                    if let Some(t) = self.tasks.get_mut(&name) {
                        t.state = TaskState::Backoff;
                    }
                }
            }
        }
    }

    fn on_child_exit(&mut self, pid: Pid, status: i32) {
        let mut found = None;
        for (name, t) in self.tasks.iter_mut() {
            if t.pid == Some(pid) {
                t.last_exit = Some(status);
                t.pid = None;
                // Close readers so logger threads exit
                t.stdout_r = None;
                t.stderr_r = None;

                // Determine next state per policy
                let success = status == 0;
                match t.spec.policy {
                    RestartPolicy::Never => {
                        t.state = if success { TaskState::Inactive } else { TaskState::Failed };
                    }
                    RestartPolicy::OnFailure => {
                        if success {
                            t.state = TaskState::Inactive;
                            t.restarts = 0;
                            t.next_backoff = Duration::from_millis(500);
                            t.backoff_until = None;
                        } else {
                            t.state = TaskState::Backoff;
                            t.restarts += 1;
                            t.backoff_until = Some(Instant::now() + t.next_backoff);
                            t.next_backoff = std::cmp::min(t.next_backoff * 2, Duration::from_secs(30));
                        }
                    }
                    RestartPolicy::Always => {
                        t.state = TaskState::Backoff;
                        t.restarts += 1;
                        t.backoff_until = Some(Instant::now() + t.next_backoff);
                        t.next_backoff = std::cmp::min(t.next_backoff * 2, Duration::from_secs(30));
                    }
                }
                found = Some(name.clone());
                break;
            }
        }
        if found.is_none() {
            // Unknown child: ignored
        }
    }

    fn shutdown(&mut self) {
        self.shutting_down = true;
        // Stop tasks in reverse order
        for name in self.order.iter().rev() {
            let _ = self.stop_task(name);
        }
        // Give them a moment to exit
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let mut any = false;
            for t in self.tasks.values() {
                if t.pid.is_some() {
                    any = true;
                    break;
                }
            }
            if !any || Instant::now() >= deadline {
                break;
            }
            // Reap if any
            self.tick();
            thread::sleep(Duration::from_millis(100));
        }
        // SIGKILL remaining
        for t in self.tasks.values() {
            if let Some(pid) = t.pid {
                let _ = kill(pid, Signal::SIGKILL);
            }
        }
    }
}

// Attach threads that read from child's stdout/stderr FDs and write lines to log
fn spawn_logger_threads(task: String, out_fd: RawFd, err_fd: RawFd, mut log_file: File) {
    let t1 = task.clone();
    let mut out_reader = unsafe { File::from_raw_fd(out_fd) };
    thread::spawn(move || {
        let mut buf = [0u8; 4096];
        let mut line = Vec::new();
        loop {
            match out_reader.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    for &b in &buf[..n] {
                        if b == b'\n' {
                            let _ = writeln!(log_file, "[stdout] {}", String::from_utf8_lossy(&line));
                            let _ = log_file.flush();
                            line.clear();
                        } else {
                            line.push(b);
                        }
                    }
                }
                Err(_) => break,
            }
        }
        if !line.is_empty() {
            let _ = writeln!(log_file, "[stdout] {}", String::from_utf8_lossy(&line));
            let _ = log_file.flush();
        }
        // prevent closing of fd twice; out_reader owns it
    });

    let mut err_reader = unsafe { File::from_raw_fd(err_fd) };
    thread::spawn(move || {
        let mut buf = [0u8; 4096];
        let mut line = Vec::new();
        loop {
            match err_reader.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    for &b in &buf[..n] {
                        if b == b'\n' {
                            let _ = writeln!(log_file, "[stderr] {}", String::from_utf8_lossy(&line));
                            let _ = log_file.flush();
                            line.clear();
                        } else {
                            line.push(b);
                        }
                    }
                }
                Err(_) => break,
            }
        }
        if !line.is_empty() {
            let _ = writeln!(log_file, "[stderr] {}", String::from_utf8_lossy(&line));
            let _ = log_file.flush();
        }
    });
}

// ============ System Helpers ============

fn ensure_dir<P: AsRef<Path>>(p: P, mode: u32) -> io::Result<()> {
    if !p.as_ref().exists() {
        fs::create_dir_all(&p)?;
        fs::set_permissions(&p, fs::Permissions::from_mode(mode))?;
    }
    Ok(())
}

fn safe_mountpoint(path: &str) -> io::Result<()> {
    let p = Path::new(path);
    if !p.exists() {
        fs::create_dir_all(p)?;
    }
    Ok(())
}

fn do_mounts() -> i32 {
    // This runs inside a forked child (oneshoot task). Return 0 on success-like path,
    // but we do best-effort and continue to mount what we can.
    // 1) Remount / ro if needed and create base mount points
    let _ = ensure_dir("/proc", 0o755);
    let _ = ensure_dir("/sys", 0o755);
    let _ = ensure_dir("/dev", 0o755);
    let _ = ensure_dir("/run", 0o755);
    let _ = ensure_dir(RUN_DIR, 0o755);
    let _ = ensure_dir(LOG_DIR, 0o755);

    // Try remount root ro if not ro already
    unsafe {
        let ret = libc::mount(
            std::ptr::null(),
            CString::new("/").unwrap().as_ptr(),
            std::ptr::null(),
            (MsFlags::MS_REMOUNT | MsFlags::MS_RDONLY).bits() as libc::c_ulong,
            std::ptr::null(),
        );
        if ret != 0 {
            // ignore error: likely already ro or not allowed yet
        }
    }

    // Mount proc
    let _ = safe_mountpoint("/proc");
    let _ = mount(
        Some("proc"),
        "/proc",
        Some("proc"),
        MsFlags::MS_NOSUID | MsFlags::MS_NOEXEC | MsFlags::MS_NODEV,
        None::<&str>,
    );

    // Mount sysfs
    let _ = safe_mountpoint("/sys");
    let _ = mount(
        Some("sysfs"),
        "/sys",
        Some("sysfs"),
        MsFlags::MS_NOSUID | MsFlags::MS_NOEXEC | MsFlags::MS_NODEV,
        None::<&str>,
    );

    // Mount devtmpfs
    let _ = safe_mountpoint("/dev");
    let _ = mount(
        Some("devtmpfs"),
        "/dev",
        Some("devtmpfs"),
        MsFlags::empty(),
        Some("mode=0755,size=50%,nr_inodes=1k"),
    );

    // Make sure /dev/pts and /dev/shm exist as some tools expect them
    let _ = ensure_dir("/dev/pts", 0o755);
    let _ = ensure_dir("/dev/shm", 0o1777);
    let _ = mount(
        Some("devpts"),
        "/dev/pts",
        Some("devpts"),
        MsFlags::MS_NOSUID | MsFlags::MS_NOEXEC,
        Some("newinstance,ptmxmode=0666,mode=0620,gid=5"),
    )
    .ok();
    let _ = mount(
        Some("tmpfs"),
        "/dev/shm",
        Some("tmpfs"),
        MsFlags::MS_NOSUID | MsFlags::MS_NODEV,
        Some("mode=1777"),
    );

    // 2) fsck -AT -a
    run_command_log(
        "/sbin/fsck",
        &["/sbin/fsck", "-AT", "-a"],
        "/var/log/sysx/fsck.log",
    );

    // 2b) mount -a
    run_command_log("/bin/mount", &["/bin/mount", "-a"], "/var/log/sysx/mount-a.log");

    0
}

fn run_command_log(cmd: &str, argv: &[&str], log_path: &str) -> i32 {
    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path)
        .unwrap_or_else(|_| File::create("/dev/null").unwrap());

    let (out_r, out_w) = pipe().expect("pipe");
    let (err_r, err_w) = pipe().expect("pipe");

    match unsafe { fork().expect("fork") } {
        ForkResult::Parent { child } => {
            unsafe {
                close(out_w).ok();
                close(err_w).ok();
            }
            // logger inline (blocking) until the child exits
            let mut out_reader = unsafe { File::from_raw_fd(out_r) };
            let mut err_reader = unsafe { File::from_raw_fd(err_r) };

            let mut out_buf = [0u8; 4096];
            let mut err_buf = [0u8; 4096];
            let mut out_line = Vec::new();
            let mut err_line = Vec::new();

            loop {
                match waitpid(child, Some(WaitPidFlag::WNOHANG)) {
                    Ok(WaitStatus::StillAlive) => {
                        // pump I/O non-blockingly with small sleeps
                        if let Ok(n) = out_reader.read(&mut out_buf) {
                            if n > 0 {
                                for &b in &out_buf[..n] {
                                    if b == b'\n' {
                                        let _ = writeln!(file, "[stdout] {}", String::from_utf8_lossy(&out_line));
                                        out_line.clear();
                                    } else {
                                        out_line.push(b);
                                    }
                                }
                            }
                        }
                        if let Ok(n) = err_reader.read(&mut err_buf) {
                            if n > 0 {
                                for &b in &err_buf[..n] {
                                    if b == b'\n' {
                                        let _ = writeln!(file, "[stderr] {}", String::from_utf8_lossy(&err_line));
                                        err_line.clear();
                                    } else {
                                        err_line.push(b);
                                    }
                                }
                            }
                        }
                        thread::sleep(Duration::from_millis(20));
                    }
                    Ok(WaitStatus::Exited(_, code)) => {
                        // drain remaining
                        let _ = drain_reader(&mut out_reader, &mut file, "[stdout]");
                        let _ = drain_reader(&mut err_reader, &mut file, "[stderr]");
                        let _ = writeln!(file, "exit code: {}", code);
                        let _ = file.flush();
                        return code;
                    }
                    Ok(WaitStatus::Signaled(_, sig, _)) => {
                        let _ = drain_reader(&mut out_reader, &mut file, "[stdout]");
                        let _ = drain_reader(&mut err_reader, &mut file, "[stderr]");
                        let _ = writeln!(file, "signaled: {}", sig as i32);
                        let _ = file.flush();
                        return 128 + sig as i32;
                    }
                    Ok(_) => thread::sleep(Duration::from_millis(20)),
                    Err(_) => {
                        return 127;
                    }
                }
            }
        }
        ForkResult::Child => {
            // Child: redirect stdio
            dup2(out_w, libc::STDOUT_FILENO).ok();
            dup2(err_w, libc::STDERR_FILENO).ok();
            unsafe {
                close(out_w).ok();
                close(err_w).ok();
                close(out_r).ok();
                close(err_r).ok();
            }
            let ccmd = CString::new(cmd).unwrap();
            let cargs: Vec<CString> = argv.iter().map(|s| CString::new(*s).unwrap()).collect();
            if let Err(e) = execv(&ccmd, &cargs) {
                eprintln!("exec {} failed: {}", cmd, e);
                unsafe { libc::_exit(127) };
            }
            unreachable!();
        }
    }
}

fn drain_reader(reader: &mut File, file: &mut File, tag: &str) -> io::Result<()> {
    let mut buf = [0u8; 4096];
    let mut line = Vec::new();
    loop {
        let n = match reader.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => n,
            Err(_) => break,
        };
        for &b in &buf[..n] {
            if b == b'\n' {
                writeln!(file, "{} {}", tag, String::from_utf8_lossy(&line)).ok();
                line.clear();
            } else {
                line.push(b);
            }
        }
    }
    if !line.is_empty() {
        writeln!(file, "{} {}", tag, String::from_utf8_lossy(&line)).ok();
    }
    Ok(())
}

// Networking: bring up lo and try DHCP via udhcpc
fn do_network() -> i32 {
    // ip link set lo up
    let _ = run_command_log(
        "/sbin/ip",
        &["/sbin/ip", "link", "set", "lo", "up"],
        "/var/log/sysx/ip.log",
    );

    // Determine first non-loopback iface using /sys/class/net
    let ifname = std::fs::read_dir("/sys/class/net")
        .ok()
        .and_then(|rd| {
            for e in rd.flatten() {
                let name = e.file_name().into_string().ok()?;
                if name != "lo" {
                    return Some(name);
                }
            }
            None
        });

    if let Some(iface) = ifname {
        // Try udhcpc -q -n -i <iface>
        if Path::new("/sbin/udhcpc").exists() {
            let args = vec![
                "/sbin/udhcpc".to_string(),
                "-q".to_string(),
                "-n".to_string(),
                "-i".to_string(),
                iface.clone(),
            ];
            let refs: Vec<&str> = args.iter().map(|s| s.as_str()).collect();
            let _ = run_command_log("/sbin/udhcpc", &refs, "/var/log/sysx/udhcpc.log");
        } else {
            // fall back to just bringing the link up
            let _ = run_command_log(
                "/sbin/ip",
                &["/sbin/ip", "link", "set", &iface, "up"],
                "/var/log/sysx/ip.log",
            );
        }
    }
    0
}

// ============ Init main ============

fn init_main() {
    // Make sure we are session leader and have sane umask
    unsafe { libc::setsid(); }
    unsafe { libc::umask(0o22); }
    let _ = chdir("/");

    // Set up a simple signal pipe to notify main loop
    let (sig_r, sig_w) = pipe().expect("signal pipe");
    // Register signals: write a byte to sig_w
    let sig_w_clone = sig_w;
    let handle_chld = signal_hook::flag::register(SIGCHLD, move || {
        let _ = unsafe { libc::write(sig_w_clone, b"C" as *const u8 as *const libc::c_void, 1) };
    });
    let sig_w_clone2 = sig_w;
    let handle_term = signal_hook::flag::register(SIGTERM, move || {
        let _ = unsafe { libc::write(sig_w_clone2, b"T" as *const u8 as *const libc::c_void, 1) };
    });
    let sig_w_clone3 = sig_w;
    let handle_int = signal_hook::flag::register(SIGINT, move || {
        let _ = unsafe { libc::write(sig_w_clone3, b"I" as *const u8 as *const libc::c_void, 1) };
    });
    let _ = (handle_chld, handle_term, handle_int);

    // Prepare control socket
    let _ = fs::create_dir_all(RUN_DIR);
    if Path::new(CTL_SOCK).exists() {
        let _ = fs::remove_file(CTL_SOCK);
    }
    let listener = UnixListener::bind(CTL_SOCK).expect("bind ctl socket");
    // set permissions 0660 root:root
    let _ = fs::set_permissions(CTL_SOCK, fs::Permissions::from_mode(0o660));

    // Build tasks
    let mut rt = Runtime::new().expect("runtime");
    // mounts: oneshoot, OnFailure (don't restart on success)
    rt.add_task(TaskSpec {
        name: "mounts".to_string(),
        policy: RestartPolicy::OnFailure,
        kind: TaskKind::Oneshoot(do_mounts),
    })
    .unwrap();

    // network: oneshoot, OnFailure to retry if it errors out
    rt.add_task(TaskSpec {
        name: "network".to_string(),
        policy: RestartPolicy::OnFailure,
        kind: TaskKind::Oneshoot(do_network),
    })
    .unwrap();

    // getty@tty1: longrun, Always
    rt.add_task(TaskSpec {
        name: "getty@tty1".to_string(),
        policy: RestartPolicy::Always,
        kind: TaskKind::Longrun(vec![
            "/sbin/agetty".to_string(),
            "--noclear".to_string(),
            "115200".to_string(),
            "tty1".to_string(),
            "linux".to_string(),
        ]),
    })
    .unwrap();

    // Immediately attempt to start mounts and network (policy will handle retries)
    let _ = rt.start_task("mounts");
    let _ = rt.start_task("network");
    let _ = rt.start_task("getty@tty1");

    // Main event loop: handle control socket and signals
    // We'll use blocking accept/read with small sleeps; environment is small and single-threaded.
    listener.set_nonblocking(true).ok();

    // File descriptor for reading signals
    let mut sig_reader = unsafe { File::from_raw_fd(sig_r) };

    loop {
        // Handle any pending control requests
        loop {
            match listener.accept() {
                Ok((mut stream, _addr)) => {
                    if let Err(e) = handle_ctl_conn(&mut rt, &mut stream) {
                        eprintln!("ctl error: {e}");
                    }
                }
                Err(e) if e.kind() == io::ErrorKind::WouldBlock => break,
                Err(_) => break,
            }
        }

        // Drain signals if any
        let mut b = [0u8; 16];
        match sig_reader.read(&mut b) {
            Ok(0) => {}
            Ok(n) => {
                for &ch in &b[..n] {
                    match ch {
                        b'C' => {
                            rt.tick();
                        }
                        b'T' | b'I' => {
                            // Graceful shutdown requested
                            graceful_shutdown(&mut rt);
                            // never returns
                        }
                        _ => {}
                    }
                }
            }
            Err(_) => {}
        }

        // Periodic tick to evaluate backoff/start
        rt.tick();

        // Simple sleep to avoid busy loop
        thread::sleep(Duration::from_millis(200));
    }
}

fn handle_ctl_conn(rt: &mut Runtime, stream: &mut UnixStream) -> Result<(), SysxError> {
    // read len + body
    let mut lenbuf = [0u8; 4];
    stream.read_exact(&mut lenbuf)?;
    let len = u32::from_be_bytes(lenbuf) as usize;
    let mut body = vec![0u8; len];
    stream.read_exact(&mut body)?;
    let req: CtlRequest = serde_json::from_slice(&body).map_err(|e| SysxError::Other(e.to_string()))?;

    let resp = match req {
        CtlRequest::List => CtlResponse::List(rt.list()),
        CtlRequest::Start { name } => match rt.start_task(&name) {
            Ok(_) => CtlResponse::Ok,
            Err(e) => CtlResponse::Error(format!("{e}")),
        },
        CtlRequest::Stop { name } => match rt.stop_task(&name) {
            Ok(_) => CtlResponse::Ok,
            Err(e) => CtlResponse::Error(format!("{e}")),
        },
        CtlRequest::Logs { name, tail } => {
            let path = format!("{}/{}.log", LOG_DIR, name.replace('/', "_"));
            match read_tail(&path, tail.unwrap_or(1000)) {
                Ok(s) => CtlResponse::Logs(s),
                Err(e) => CtlResponse::Error(format!("read logs: {e}")),
            }
        }
    };

    let data = serde_json::to_vec(&resp).unwrap();
    stream.write_all(&(data.len() as u32).to_be_bytes())?;
    stream.write_all(&data)?;
    Ok(())
}

fn read_tail(path: &str, n: usize) -> io::Result<String> {
    let f = OpenOptions::new().read(true).open(path)?;
    let reader = BufReader::new(f);
    let mut lines: Vec<String> = reader.lines().flatten().collect();
    let len = lines.len();
    if n >= len {
        Ok(lines.join("\n") + "\n")
    } else {
        Ok(lines[len - n..].join("\n") + "\n")
    }
}

fn graceful_shutdown(rt: &mut Runtime) -> ! {
    // Stop tasks
    rt.shutdown();

    // Sync disks
    unsafe { libc::sync(); }

    // Try to unmount and remount root ro
    // Best-effort: umount common mounts, then remount /
    let _ = umount2("/dev/pts", MntFlags::MNT_DETACH);
    let _ = umount2("/dev/shm", MntFlags::MNT_DETACH);
    let _ = umount2("/proc", MntFlags::MNT_DETACH);
    let _ = umount2("/sys", MntFlags::MNT_DETACH);

    unsafe {
        let _ = libc::mount(
            std::ptr::null(),
            CString::new("/").unwrap().as_ptr(),
            std::ptr::null(),
            (MsFlags::MS_REMOUNT | MsFlags::MS_RDONLY).bits() as libc::c_ulong,
            std::ptr::null(),
        );
    }

    // Power off
    let _ = reboot(RebootMode::RB_POWER_OFF);
    // If reboot fails, halt the CPU in a loop
    loop {
        unsafe { libc::pause(); }
    }
}

// End of file.

Below is a single-file Cargo project implementing a minimal “sysx” for Devuan. It can run as PID 1 (init) and also act as a CLI tool to manage supervised tasks via a Unix domain socket. It avoids systemd/sysvinit/dbus/X/etc., uses only std and nix/libc, and targets stable Rust 1.72+ on x86_64-unknown-linux-gnu.

Instructions:
- Create a new cargo project: cargo new sysx && cd sysx
- Replace Cargo.toml and src/main.rs with the contents below.
- Build: cargo build --release
- To test CLI (not as PID 1), you can run sysx in a container or VM as init. As PID 1 it will mount, fsck, mount -a, bring up networking, and spawn agetty on tty1.
- CLI examples (when init is running): sysx tasks | sysx status getty@tty1 | sysx stop getty@tty1 | sysx start getty@tty1

Cargo.toml:
[package]
name = "sysx"
version = "0.1.0"
edition = "2021"

[dependencies]
nix = { version = "0.27", default-features = false, features = ["process", "mount", "signal", "unistd", "sched", "fs", "poll", "time", "socket"] }
libc = "0.2"
serde = { version = "1", features = ["derive"] }
serde_json = "1"

src/main.rs:
/*
A minimal init and CLI for Devuan named "sysx".

Highlights:
- Runs as PID 1 and performs:
  - Mount /proc (proc), /sys (sysfs), /dev (devtmpfs), /run (tmpfs)
  - Run /sbin/fsck -AT -a and interpret exit codes
  - Mount real filesystems: /bin/mount -a
  - Bring up lo and first non-lo interface via 'ip' (and optional dhclient)
  - Spawn and supervise /sbin/agetty 38400 tty1 linux
  - Reap zombies, handle SIGTERM/SIGINT, sync, remount RO, poweroff/reboot
  - Structured logging to /run/sysx/log and per-task logs in /run/sysx/tasks
- Provides a CLI over a Unix socket /run/sysx/sysx.sock with simple JSON lines
- No systemd/sysvinit/dbus/X, only std + nix/libc used for syscalls
- Buildable on stable Rust 1.72+

Notes:
- Paths are adjustable in the CONSTANTS section.
- This is intentionally minimal and not feature-complete; it aims to be clear.
- When not PID 1, the same binary acts as a CLI: "sysx tasks|start|stop|status".
*/

use libc::{SIGHUP, SIGINT, SIGTERM};
use nix::errno::Errno;
use nix::libc;
use nix::mount::{mount, MsFlags};
use nix::poll::{poll, PollFd, PollFlags};
use nix::sys::signal;
use nix::sys::signal::SigSet;
use nix::sys::socket::{
    accept, bind, connect, listen, recv, send, socket, AddressFamily, MsgFlags, SockAddr,
    SockFlag, SockType, UnixAddr,
};
use nix::sys::time::{TimeSpec, TimeValLike};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, close, dup2, execv, fork, getpid, getppid, getuid, pipe, read, setsid, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::ffi::{CString, OsStr, OsString};
use std::fs::{self, File, OpenOptions};
use std::io::{Read as IoRead, Write as IoWrite};
use std::os::fd::{AsRawFd, FromRawFd, RawFd};
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::PermissionsExt;
use std::os::unix::io::OwnedFd;
use std::path::{Path, PathBuf};
use std::process;
use std::time::{Duration, SystemTime};

// ============================ CONSTANTS ============================

const PATH_PROC: &str = "/proc";
const PATH_SYS: &str = "/sys";
const PATH_DEV: &str = "/dev";
const PATH_RUN: &str = "/run";
const PATH_RUN_SYSX: &str = "/run/sysx";
const PATH_RUN_SYSX_LOG: &str = "/run/sysx/log";
const PATH_RUN_SYSX_TASKS: &str = "/run/sysx/tasks";
const PATH_SOCKET: &str = "/run/sysx/sysx.sock";

const BIN_FSCK: &str = "/sbin/fsck";
const BIN_MOUNT: &str = "/bin/mount";
const BIN_IP: &str = "/sbin/ip";
const BIN_DHCLIENT: &str = "/sbin/dhclient";
const BIN_AGETTY: &str = "/sbin/agetty";
const BIN_POWEROFF: &str = "/sbin/poweroff";
const BIN_REBOOT: &str = "/sbin/reboot";

// Supervision and backoff
const BACKOFF_INITIAL_MS: u64 = 1000;
const BACKOFF_MAX_MS: u64 = 30_000;

// ============================ LOGGING ============================

fn ensure_dirs() {
    let _ = fs::create_dir_all(PATH_RUN);
    let _ = fs::create_dir_all(PATH_RUN_SYSX);
    let _ = fs::create_dir_all(PATH_RUN_SYSX_TASKS);
    // Create and open main log
    let _ = OpenOptions::new()
        .create(true)
        .append(true)
        .open(PATH_RUN_SYSX_LOG);
}

fn now_mono_ms() -> u128 {
    // Fallback using SystemTime; acceptable for minimal init.
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_millis()
}

fn log_line(msg: &str) {
    // Write to stderr and /run/sysx/log
    let line = format!("[{}] {}\n", now_mono_ms(), msg);
    let _ = std::io::stderr().write_all(line.as_bytes());
    if let Ok(mut f) = OpenOptions::new()
        .create(true)
        .append(true)
        .open(PATH_RUN_SYSX_LOG)
    {
        let _ = f.write_all(line.as_bytes());
    }
}

macro_rules! log_info {
    ($($arg:tt)*) => {{
        log_line(&format!("[INFO] {}", format!($($arg)*)));
    }};
}
macro_rules! log_warn {
    ($($arg:tt)*) => {{
        log_line(&format!("[WARN] {}", format!($($arg)*)));
    }};
}
macro_rules! log_err {
    ($($arg:tt)*) => {{
        log_line(&format!("[ERROR] {}", format!($($arg)*)));
    }};
}

// ============================ TASK MODEL ============================

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
enum RestartPolicy {
    Always,
    OnFailure,
    Never,
}

#[derive(Debug, Clone)]
struct TaskSpec {
    name: &'static str,
    argv: &'static [&'static str],
    restart: RestartPolicy,
}

#[derive(Debug, Clone, Serialize)]
struct TaskStatus {
    name: String,
    pid: Option<i32>,
    running: bool,
    restart_policy: RestartPolicy,
    last_exit: Option<i32>,
    next_restart_ms: Option<u128>,
    backoff_ms: u64,
    log_path: String,
}

#[derive(Debug)]
struct TaskRuntime {
    spec: TaskSpec,
    pid: Option<Pid>,
    running: bool,
    last_exit: Option<i32>,
    backoff_ms: u64,
    next_restart_at: Option<u128>,
    log_path: PathBuf,
}

impl TaskRuntime {
    fn to_status(&self) -> TaskStatus {
        TaskStatus {
            name: self.spec.name.to_string(),
            pid: self.pid.map(|p| p.as_raw()),
            running: self.running,
            restart_policy: self.spec.restart,
            last_exit: self.last_exit,
            next_restart_ms: self
                .next_restart_at
                .map(|t| t.saturating_sub(now_mono_ms())),
            backoff_ms: self.backoff_ms,
            log_path: self.log_path.display().to_string(),
        }
    }
}

// The static task table: only getty@tty1 by default.
fn task_table() -> Vec<TaskSpec> {
    vec![TaskSpec {
        name: "getty@tty1",
        argv: &[BIN_AGETTY, "38400", "tty1", "linux"],
        restart: RestartPolicy::OnFailure, // restart unless clean exit 0
    }]
}

// ============================ UTILS ============================

fn cstr(s: &str) -> CString {
    CString::new(s).unwrap()
}

fn spawn_with_pipes_to_file(
    argv: &[&str],
    log_path: &Path,
    make_session: bool,
) -> nix::Result<Pid> {
    // Open log file for stdout/stderr redirection
    let log_fd = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path)
        .map_err(|e| nix::Error::from_errno(Errno::from_i32(e.raw_os_error().unwrap_or(1))))?;
    let log_fd = log_fd.into_raw_fd();

    match unsafe { fork()? } {
        ForkResult::Parent { child } => Ok(child),
        ForkResult::Child => {
            // Optional setsid() for getty-like programs
            if make_session {
                let _ = setsid();
            }

            // Redirect stdout/stderr to log file; keep stdin as-is unless getty requires tty.
            // For getty we expect it to set its own ctty on the tty device it opens.
            let _ = dup2(log_fd, libc::STDOUT_FILENO);
            let _ = dup2(log_fd, libc::STDERR_FILENO);
            let _ = close(log_fd);

            // Exec
            let cargv: Vec<CString> = argv.iter().map(|a| cstr(a)).collect();
            let prog = &cargv[0];
            execv(prog, &cargv)?;
            // If exec fails:
            let _ = eprintln!("exec failed: {:?}", argv);
            unsafe { libc::_exit(127) };
        }
    }
}

fn run_cmd_capture_status(argv: &[&str]) -> i32 {
    match unsafe { fork() } {
        Ok(ForkResult::Parent { child }) => loop {
            match waitpid(child, None) {
                Ok(WaitStatus::Exited(_, code)) => return code,
                Ok(WaitStatus::Signaled(_, sig, _)) => return 128 + sig as i32,
                Ok(_) => continue,
                Err(_) => return 127,
            }
        },
        Ok(ForkResult::Child) => {
            // Redirect stdout/stderr to main log for visibility
            let _ = OpenOptions::new()
                .create(true)
                .append(true)
                .open(PATH_RUN_SYSX_LOG)
                .and_then(|mut f| {
                    let _ = writeln!(f, "[{}] [CMD] {:?}", now_mono_ms(), argv);
                    Ok(())
                });

            let cargv: Vec<CString> = argv.iter().map(|a| cstr(a)).collect();
            let prog = &cargv[0];
            let _ = execv(prog, &cargv);
            unsafe { libc::_exit(127) };
        }
        Err(_) => 127,
    }
}

fn exists_exec(path: &str) -> bool {
    std::fs::metadata(path).map(|m| m.is_file()).unwrap_or(false)
}

// ============================ MOUNTING/BOOT ============================

fn ensure_mountpoint(p: &str) {
    let path = Path::new(p);
    if !path.exists() {
        let _ = fs::create_dir_all(path);
    }
}

fn do_early_mounts() {
    ensure_mountpoint(PATH_PROC);
    ensure_mountpoint(PATH_SYS);
    ensure_mountpoint(PATH_DEV);
    ensure_mountpoint(PATH_RUN);

    // proc
    let _ = mount(
        Some("proc"),
        PATH_PROC,
        Some("proc"),
        MsFlags::empty(),
        None::<&str>,
    )
    .map_err(|e| log_warn!("mount proc failed: {}", e));

    // sysfs
    let _ = mount(
        Some("sysfs"),
        PATH_SYS,
        Some("sysfs"),
        MsFlags::empty(),
        None::<&str>,
    )
    .map_err(|e| log_warn!("mount sysfs failed: {}", e));

    // devtmpfs
    let _ = mount(
        Some("udev"), // commonly "udev" or "devtmpfs" as source is ignored
        PATH_DEV,
        Some("devtmpfs"),
        MsFlags::empty(),
        None::<&str>,
    )
    .or_else(|_| {
        mount(
            Some("devtmpfs"),
            PATH_DEV,
            Some("devtmpfs"),
            MsFlags::empty(),
            None::<&str>,
        )
    })
    .map_err(|e| log_warn!("mount devtmpfs failed: {}", e));

    // /run as tmpfs
    let _ = mount(
        Some("tmpfs"),
        PATH_RUN,
        Some("tmpfs"),
        MsFlags::empty(),
        Some("mode=0755"),
    )
    .map_err(|e| log_warn!("mount tmpfs on /run failed: {}", e));
}

fn do_fsck_and_mount_all() {
    // fsck: /sbin/fsck -AT -a
    if exists_exec(BIN_FSCK) {
        log_info!("Running filesystem check: {} -AT -a", BIN_FSCK);
        let code = run_cmd_capture_status(&[BIN_FSCK, "-AT", "-a"]);
        // Interpret fsck exit codes:
        // 0 - no errors, 1 - filesystems repaired, 2 - system should be rebooted,
        // 4 - errors uncorrected, 8 - operational error, 16 - usage/invalid,
        // 32 - canceled by user, 128 - shared-library error
        match code {
            0 | 1 => log_info!("fsck finished: code {}", code),
            2 | 3 => {
                log_warn!("fsck indicates reboot is required (code {}), continuing to mount single-user", code);
            }
            4 | 8 => {
                log_err!("fsck reported errors (code {}), continuing to single-user mode", code);
            }
            _ => {
                log_warn!("fsck returned code {}, continuing", code);
            }
        }
    } else {
        log_warn!("{} not found; skipping fsck", BIN_FSCK);
    }

    // mount -a
    if exists_exec(BIN_MOUNT) {
        log_info!("Mounting filesystems: {} -a", BIN_MOUNT);
        let code = run_cmd_capture_status(&[BIN_MOUNT, "-a"]);
        if code != 0 {
            log_warn!("mount -a exited with {}", code);
        }
    } else {
        log_err!("{} not found; cannot mount -a", BIN_MOUNT);
    }
}

fn bring_up_network() {
    // Bring up loopback
    if exists_exec(BIN_IP) {
        let _ = run_cmd_capture_status(&[BIN_IP, "link", "set", "lo", "up"]);
        let _ = run_cmd_capture_status(&[BIN_IP, "addr", "add", "127.0.0.1/8", "dev", "lo"]);

        // Find first non-lo interface via "ip -o link"
        // We'll parse "N: IFACE: <...>" lines and pick first with name != "lo"
        let mut iface: Option<String> = None;
        if let Ok(output) = std::process::Command::new(BIN_IP)
            .args(["-o", "link"])
            .output()
        {
            if output.status.success() {
                if let Ok(s) = String::from_utf8(output.stdout) {
                    for line in s.lines() {
                        // Example: "2: ens3: <BROADCAST,MULTICAST,UP,LOWER_UP> ..."
                        if let Some(colon) = line.find(':') {
                            let rest = &line[colon + 1..].trim();
                            if let Some(colon2) = rest.find(':') {
                                let name = rest[..colon2].trim().to_string();
                                if name != "lo" {
                                    iface = Some(name);
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }

        if let Some(iface_name) = iface {
            log_info!("Bringing up interface {}", iface_name);
            let _ = run_cmd_capture_status(&[BIN_IP, "link", "set", &iface_name, "up"]);
            if exists_exec(BIN_DHCLIENT) {
                log_info!("Attempting DHCP via {}", BIN_DHCLIENT);
                let _ = run_cmd_capture_status(&[BIN_DHCLIENT, &iface_name]);
            } else {
                log_warn!("{} not found; skipping DHCP", BIN_DHCLIENT);
            }
        } else {
            log_warn!("No non-lo interface found");
        }
    } else {
        log_err!("{} not found; networking skipped", BIN_IP);
    }
}

// ============================ SUPERVISOR ============================

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "cmd", rename_all = "lowercase")]
enum RpcRequest {
    List,
    Start { name: String },
    Stop { name: String },
    Status { name: String },
}

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "ok", rename_all = "lowercase")]
enum RpcResponse {
    True { data: serde_json::Value },
    False { error: String },
}

struct Supervisor {
    tasks: HashMap<String, TaskRuntime>,
}

impl Supervisor {
    fn new() -> Self {
        let mut map = HashMap::new();
        for spec in task_table() {
            let log_path = Path::new(PATH_RUN_SYSX_TASKS).join(format!("{}.log", spec.name));
            map.insert(
                spec.name.to_string(),
                TaskRuntime {
                    spec,
                    pid: None,
                    running: false,
                    last_exit: None,
                    backoff_ms: BACKOFF_INITIAL_MS,
                    next_restart_at: None,
                    log_path,
                },
            );
        }
        Supervisor { tasks: map }
    }

    fn list(&self) -> Vec<TaskStatus> {
        self.tasks.values().map(|t| t.to_status()).collect()
    }

    fn status(&self, name: &str) -> Result<TaskStatus, String> {
        self.tasks
            .get(name)
            .map(|t| t.to_status())
            .ok_or_else(|| "no such task".to_string())
    }

    fn start(&mut self, name: &str) -> Result<TaskStatus, String> {
        let t = self
            .tasks
            .get_mut(name)
            .ok_or_else(|| "no such task".to_string())?;
        if t.running {
            return Ok(t.to_status());
        }
        let make_session = t.spec.argv.get(0).copied() == Some(BIN_AGETTY);
        match spawn_with_pipes_to_file(t.spec.argv, &t.log_path, make_session) {
            Ok(pid) => {
                t.pid = Some(pid);
                t.running = true;
                t.next_restart_at = None;
                t.backoff_ms = BACKOFF_INITIAL_MS;
                log_info!("task {} started pid {}", name, pid);
                Ok(t.to_status())
            }
            Err(e) => {
                let msg = format!("spawn failed: {}", e);
                log_err!("task {} {}", name, msg);
                Err(msg)
            }
        }
    }

    fn stop(&mut self, name: &str) -> Result<TaskStatus, String> {
        let t = self
            .tasks
            .get_mut(name)
            .ok_or_else(|| "no such task".to_string())?;
        if let Some(pid) = t.pid {
            log_info!("stopping task {} pid {}", name, pid);
            let _ = signal::kill(pid, signal::Signal::SIGTERM);
        }
        t.next_restart_at = None;
        Ok(t.to_status())
    }

    fn handle_exit(&mut self, pid: Pid, status_code: Option<i32>) {
        // Find owning task
        let mut owner: Option<String> = None;
        for (name, t) in &self.tasks {
            if t.pid == Some(pid) {
                owner = Some(name.clone());
                break;
            }
        }
        if let Some(name) = owner {
            let t = self.tasks.get_mut(&name).unwrap();
            t.pid = None;
            t.running = false;
            t.last_exit = status_code;

            let should_restart = match t.spec.restart {
                RestartPolicy::Always => true,
                RestartPolicy::OnFailure => status_code.map(|c| c != 0).unwrap_or(true),
                RestartPolicy::Never => false,
            };

            if should_restart {
                // Schedule restart with exponential backoff up to cap
                let now = now_mono_ms();
                let backoff = t.backoff_ms.min(BACKOFF_MAX_MS);
                t.next_restart_at = Some(now + backoff as u128);
                t.backoff_ms = (t.backoff_ms * 2).min(BACKOFF_MAX_MS);
                log_info!(
                    "task {} exited code {:?}, scheduling restart in {} ms",
                    name,
                    status_code,
                    backoff
                );
            } else {
                t.next_restart_at = None;
                log_info!("task {} exited code {:?}, not restarting", name, status_code);
            }
        } else {
            log_info!("reaped unknown child pid {}", pid);
        }
    }

    fn tick(&mut self) {
        // Start any tasks with scheduled restart and due time
        let now = now_mono_ms();
        let names: Vec<String> = self
            .tasks
            .iter()
            .filter_map(|(name, t)| {
                if !t.running {
                    if let Some(at) = t.next_restart_at {
                        if at <= now {
                            return Some(name.clone());
                        }
                    }
                }
                None
            })
            .collect();

        for name in names {
            let _ = self.start(&name);
        }
    }

    fn shutdown_all(&mut self) {
        // Send SIGTERM to all running tasks, wait a bit, then SIGKILL if needed
        for (name, t) in &self.tasks {
            if let Some(pid) = t.pid {
                log_info!("shutdown: SIGTERM to {} (pid {})", name, pid);
                let _ = signal::kill(pid, signal::Signal::SIGTERM);
            }
        }

        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        loop {
            let mut any = false;
            for (_name, t) in &self.tasks {
                if t.pid.is_some() {
                    any = true;
                    break;
                }
            }
            if !any {
                break;
            }
            if std::time::Instant::now() > deadline {
                break;
            }
            // Reap if possible
            match waitpid(Pid::from_raw(-1), WaitPidFlag::WNOHANG) {
                Ok(WaitStatus::Exited(pid, code)) => self.handle_exit(pid, Some(code)),
                Ok(WaitStatus::Signaled(pid, sig, _)) => {
                    self.handle_exit(pid, Some(128 + sig as i32))
                }
                Ok(WaitStatus::StillAlive) | Ok(_) => {}
                Err(_) => {}
            }
            std::thread::sleep(Duration::from_millis(100));
        }

        // SIGKILL stubborn ones
        for (name, t) in &self.tasks {
            if let Some(pid) = t.pid {
                log_warn!("shutdown: SIGKILL to {} (pid {})", name, pid);
                let _ = signal::kill(pid, signal::Signal::SIGKILL);
            }
        }
    }
}

// ============================ SOCKET RPC ============================

fn make_server_socket() -> nix::Result<RawFd> {
    // Ensure directory exists and permissions sane
    ensure_dirs();
    let _ = fs::remove_file(PATH_SOCKET);
    let fd = socket(
        AddressFamily::Unix,
        SockType::Stream,
        SockFlag::SOCK_CLOEXEC,
        None,
    )?;
    let addr = UnixAddr::new(PATH_SOCKET.as_bytes()).unwrap();
    bind(fd, &SockAddr::Unix(addr))?;
    // Restrict access to root only by default
    let _ = std::fs::set_permissions(PATH_SOCKET, std::fs::Permissions::from_mode(0o700));
    listen(fd, 16)?;
    Ok(fd)
}

fn accept_one_and_serve(fd: RawFd, sup: &mut Supervisor) {
    match accept(fd) {
        Ok(cfd) => {
            // Read a single line of JSON; respond with a single JSON object line.
            let mut buf = [0u8; 4096];
            let n = recv(cfd, &mut buf, MsgFlags::empty()).unwrap_or(0);
            if n == 0 {
                let _ = close(cfd);
                return;
            }
            let line = match std::str::from_utf8(&buf[..n]) {
                Ok(s) => s.trim(),
                Err(_) => "",
            };
            let resp = handle_rpc_line(sup, line);
            let payload = serde_json::to_string(&resp).unwrap();
            let _ = send(cfd, payload.as_bytes(), MsgFlags::empty());
            let _ = send(cfd, b"\n", MsgFlags::empty());
            let _ = close(cfd);
        }
        Err(e) => {
            log_warn!("accept failed: {}", e);
        }
    }
}

fn handle_rpc_line(sup: &mut Supervisor, line: &str) -> RpcResponse {
    let req: Result<RpcRequest, _> = serde_json::from_str(line);
    match req {
        Ok(RpcRequest::List) => {
            let list = sup.list();
            RpcResponse::True {
                data: serde_json::to_value(list).unwrap(),
            }
        }
        Ok(RpcRequest::Start { name }) => match sup.start(&name) {
            Ok(st) => RpcResponse::True {
                data: serde_json::to_value(st).unwrap(),
            },
            Err(e) => RpcResponse::False { error: e },
        },
        Ok(RpcRequest::Stop { name }) => match sup.stop(&name) {
            Ok(st) => RpcResponse::True {
                data: serde_json::to_value(st).unwrap(),
            },
            Err(e) => RpcResponse::False { error: e },
        },
        Ok(RpcRequest::Status { name }) => match sup.status(&name) {
            Ok(st) => RpcResponse::True {
                data: serde_json::to_value(st).unwrap(),
            },
            Err(e) => RpcResponse::False { error: e },
        },
        Err(e) => RpcResponse::False {
            error: format!("bad request: {}", e),
        },
    }
}

fn client_send(req: &RpcRequest) -> Result<serde_json::Value, String> {
    let fd = socket(
        AddressFamily::Unix,
        SockType::Stream,
        SockFlag::empty(),
        None,
    )
    .map_err(|e| format!("socket: {}", e))?;
    let addr = UnixAddr::new(PATH_SOCKET.as_bytes()).map_err(|e| format!("{}", e))?;
    connect(fd, &SockAddr::Unix(addr)).map_err(|e| format!("connect: {}", e))?;
    let text = serde_json::to_string(req).unwrap() + "\n";
    send(fd, text.as_bytes(), MsgFlags::empty()).map_err(|e| format!("send: {}", e))?;
    let mut buf = Vec::new();
    buf.resize(8192, 0);
    let n = recv(fd, &mut buf, MsgFlags::empty()).map_err(|e| format!("recv: {}", e))?;
    let s = std::str::from_utf8(&buf[..n]).map_err(|e| format!("utf8: {}", e))?;
    let resp: RpcResponse =
        serde_json::from_str(s.trim()).map_err(|e| format!("parse resp: {}", e))?;
    match resp {
        RpcResponse::True { data } => Ok(data),
        RpcResponse::False { error } => Err(error),
    }
}

// ============================ SIGNALS/REAP ============================

fn setup_signal_mask() -> SigSet {
    let mut set = SigSet::empty();
    set.add(signal::Signal::SIGCHLD);
    set.add(signal::Signal::SIGTERM);
    set.add(signal::Signal::SIGINT);
    set
}

fn handle_reaps(sup: &mut Supervisor) {
    loop {
        match waitpid(Pid::from_raw(-1), WaitPidFlag::WNOHANG) {
            Ok(WaitStatus::Exited(pid, code)) => sup.handle_exit(pid, Some(code)),
            Ok(WaitStatus::Signaled(pid, sig, _)) => {
                sup.handle_exit(pid, Some(128 + sig as i32))
            }
            Ok(WaitStatus::StillAlive) => break,
            Ok(_) => {}
            Err(Errno::ECHILD) => break,
            Err(e) => {
                log_warn!("waitpid error: {}", e);
                break;
            }
        }
    }
}

// ============================ SHUTDOWN ============================

fn do_remount_ro() {
    if exists_exec(BIN_MOUNT) {
        let _ = run_cmd_capture_status(&[BIN_MOUNT, "-a", "-o", "remount,ro"]);
    }
    let _ = nix::unistd::sync();
}

fn do_poweroff() {
    if exists_exec(BIN_POWEROFF) {
        let _ = run_cmd_capture_status(&[BIN_POWEROFF]);
    } else {
        unsafe { libc::reboot(libc::LINUX_REBOOT_CMD_POWER_OFF) };
    }
}

fn do_reboot() {
    if exists_exec(BIN_REBOOT) {
        let _ = run_cmd_capture_status(&[BIN_REBOOT]);
    } else {
        unsafe { libc::reboot(libc::LINUX_REBOOT_CMD_RESTART) };
    }
}

// ============================ INIT MAIN LOOP ============================

fn init_main() -> ! {
    // Basic environment
    let _ = chdir("/");
    ensure_dirs();
    log_info!("sysx init starting (pid {})", getpid());

    // Early mounts
    do_early_mounts();

    // Filesystems
    do_fsck_and_mount_all();

    // Networking
    bring_up_network();

    // Supervisor
    let mut sup = Supervisor::new();

    // Start default tasks
    for name in sup.tasks.clone().keys() {
        let _ = sup.start(name);
    }

    // Create server socket
    let srv_fd = make_server_socket().expect("socket create failed");

    // Install signal handlers: use signalfd-like via pselect/poll on self-pipe is overkill here.
    // We'll use traditional signal handling with flags masked and poll timeout small.
    // Block signals; we will use signalfd-like behavior via sigtimedwait in the poll loop.
    let sigset = setup_signal_mask();
    unsafe {
        let mut raw = std::mem::MaybeUninit::<libc::sigset_t>::uninit();
        sigset.clone().thread_get_mask().ok();
        let _ = signal::pthread_sigmask(signal::SigmaskHow::SIG_BLOCK, Some(&sigset), None);
    }

    // Event loop: poll on server socket + periodic tick + reap + sigtimedwait
    let mut shutting_down = false;
    let mut do_reboot_flag = false;

    loop {
        // Reap any children
        handle_reaps(&mut sup);

        // Ticks: restart due tasks
        sup.tick();

        // Prepare poll fds
        let mut fds = [PollFd::new(srv_fd, PollFlags::POLLIN)];
        // Compute timeout: min until next restart or 1000ms
        let now = now_mono_ms();
        let mut next_due_ms = 1000u64;
        for t in sup.tasks.values() {
            if let Some(at) = t.next_restart_at {
                if at > now {
                    let delta = (at - now) as u64;
                    if delta < next_due_ms {
                        next_due_ms = delta;
                    }
                } else {
                    next_due_ms = 0;
                }
            }
        }

        // Also check signals using sigtimedwait with same timeout
        let ts = TimeSpec::milliseconds(next_due_ms as i64);

        // Poll server socket
        let _ = poll(&mut fds, next_due_ms as i32);

        if let Some(revents) = fds[0].revents() {
            if revents.contains(PollFlags::POLLIN) {
                accept_one_and_serve(srv_fd, &mut sup);
            }
        }

        // Check for signals
        let mut caught_sig: Option<i32> = None;
        let mut siginfo: libc::siginfo_t = unsafe { std::mem::zeroed() };
        let res = unsafe { libc::sigtimedwait(sigset.as_ref(), &mut siginfo, ts.as_ref()) };
        if res > 0 {
            caught_sig = Some(res);
        }

        if let Some(sig) = caught_sig {
            match sig {
                x if x == SIGTERM => {
                    log_info!("caught SIGTERM -> shutdown (poweroff)");
                    shutting_down = true;
                    do_reboot_flag = false;
                }
                x if x == SIGINT => {
                    log_info!("caught SIGINT -> shutdown (reboot)");
                    shutting_down = true;
                    do_reboot_flag = true;
                }
                x if x == libc::SIGCHLD => {
                    // handled by handle_reaps already
                }
                _ => {
                    log_info!("caught signal {}", sig);
                }
            }
        }

        if shutting_down {
            // Stop all tasks, sync, remount ro, and poweroff/reboot
            sup.shutdown_all();
            let _ = nix::unistd::sync();
            do_remount_ro();
            if do_reboot_flag {
                do_reboot();
            } else {
                do_poweroff();
            }
            // If above returns, fallback to kernel reboot syscall
            unsafe { libc::reboot(libc::LINUX_REBOOT_CMD_POWER_OFF) };
            loop {
                nix::unistd::pause();
            }
        }
    }
}

// ============================ CLI ============================

fn print_usage() {
    eprintln!("sysx CLI:
  sysx tasks
  sysx status <task>
  sysx start <task>
  sysx stop <task>");
}

fn cli_main(args: &[String]) -> i32 {
    if args.len() < 2 {
        print_usage();
        return 2;
    }
    match args[1].as_str() {
        "tasks" => match client_send(&RpcRequest::List) {
            Ok(v) => {
                println!("{}", serde_json::to_string_pretty(&v).unwrap());
                0
            }
            Err(e) => {
                eprintln!("error: {}", e);
                1
            }
        },
        "status" => {
            if args.len() < 3 {
                print_usage();
                return 2;
            }
            match client_send(&RpcRequest::Status {
                name: args[2].clone(),
            }) {
                Ok(v) => {
                    println!("{}", serde_json::to_string_pretty(&v).unwrap());
                    0
                }
                Err(e) => {
                    eprintln!("error: {}", e);
                    1
                }
            }
        }
        "start" => {
            if args.len() < 3 {
                print_usage();
                return 2;
            }
            match client_send(&RpcRequest::Start {
                name: args[2].clone(),
            }) {
                Ok(v) => {
                    println!("{}", serde_json::to_string_pretty(&v).unwrap());
                    0
                }
                Err(e) => {
                    eprintln!("error: {}", e);
                    1
                }
            }
        }
        "stop" => {
            if args.len() < 3 {
                print_usage();
                return 2;
            }
            match client_send(&RpcRequest::Stop {
                name: args[2].clone(),
            }) {
                Ok(v) => {
                    println!("{}", serde_json::to_string_pretty(&v).unwrap());
                    0
                }
                Err(e) => {
                    eprintln!("error: {}", e);
                    1
                }
            }
        }
        _ => {
            print_usage();
            2
        }
    }
}

// ============================ ENTRY ============================

fn main() {
    // If running as PID 1, act as init. Otherwise, act as CLI.
    if getpid().as_raw() == 1 {
        init_main();
    } else {
        let args: Vec<String> = std::env::args().collect();
        let code = cli_main(&args);
        process::exit(code);
    }
}

