src/main.rs:

use libc::{SIGHUP, SIGINT, SIGTERM};
use nix::mount::{mount, umount2, MntFlags, MsFlags};
use nix::sys::signal::{kill, signal, SigHandler, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, dup2, fork, getpid, getppid, setsid, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::fs::{self, create_dir_all, File, OpenOptions};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::fd::AsRawFd;
use std::os::unix::fs::PermissionsExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

// -------------------------- Task definitions --------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    autostart: bool,
    log_path: PathBuf,
}

#[derive(Clone, Debug, Serialize)]
enum TaskRunState {
    Starting,
    Running(i32),
    Stopped,
    Crashed(Option<i32>), // exit code or None if signal
}

struct TaskRuntime {
    spec: TaskSpec,
    state: TaskRunState,
    pid: Option<Pid>,
    restarts: u32,
}

impl TaskRuntime {
    fn new(spec: TaskSpec) -> Self {
        Self { spec, state: TaskRunState::Stopped, pid: None, restarts: 0 }
    }
}

// -------------------------- Global state --------------------------

struct State {
    tasks: HashMap<String, TaskRuntime>,
    sock_path: PathBuf,
    shutting_down: bool,
}

impl State {
    fn new(sock_path: PathBuf) -> Self {
        Self { tasks: HashMap::new(), sock_path, shutting_down: false }
    }
}

static INIT_TASKS: &[(&str, &[&str], RestartPolicy, bool, &str)] = &[
    // Supervised getty on tty1
    (
        "getty-tty1",
        &["/sbin/agetty", "--login-pause", "--noclear", "tty1", "115200", "linux"],
        RestartPolicy::Always,
        true,
        "/var/log/sysx/getty-tty1.log",
    ),
];

// -------------------------- Utilities --------------------------

fn log_to_kmsg(msg: &str) {
    let _ = OpenOptions::new().write(true).open("/dev/kmsg").and_then(|mut f| {
        let _ = writeln!(f, "sysx: {}", msg);
        Ok(())
    });
}

fn ensure_dir(p: &Path, mode: u32) -> std::io::Result<()> {
    if !p.exists() {
        create_dir_all(p)?;
    }
    let mut perms = fs::metadata(p)?.permissions();
    perms.set_mode(mode);
    fs::set_permissions(p, perms)
}

fn which(p: &str) -> Option<PathBuf> {
    let paths = env::var("PATH").unwrap_or("/sbin:/bin:/usr/sbin:/usr/bin".into());
    for dir in paths.split(':') {
        let cand = Path::new(dir).join(p);
        if cand.exists() { return Some(cand); }
    }
    None
}

fn run_cmd(mut cmd: Command) -> i32 {
    let status = cmd.status();
    match status {
        Ok(s) => s.code().unwrap_or(255),
        Err(_) => 255,
    }
}

// -------------------------- Early init (PID 1) --------------------------

fn mount_essential() {
    // Mount proc
    let _ = fs::create_dir_all("/proc");
    let _ = unsafe { mount(Some("proc"), "/proc", Some("proc"), MsFlags::empty(), None::<&str>) };

    // Mount sysfs
    let _ = fs::create_dir_all("/sys");
    let _ = unsafe { mount(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::empty(), None::<&str>) };

    // Mount devtmpfs
    let _ = fs::create_dir_all("/dev");
    let _ = unsafe { mount(Some("udev"), "/dev", Some("devtmpfs"), MsFlags::empty(), Some("mode=0755")) };

    // Ensure /run
    let _ = ensure_dir(Path::new("/run"), 0o755);
}

fn fsck_and_mount_all() {
    // Try to remount root read-only before fsck (if not already ro)
    let _ = unsafe { mount::<str, str, str, str>(None, "/", None, MsFlags::MS_REMOUNT | MsFlags::MS_RDONLY, None) };

    // Run fsck -A -T -y if available
    if let Some(fsck) = which("fsck") {
        log_to_kmsg("running fsck -A -T -y");
        let _ = Command::new(fsck).args(["-A", "-T", "-y"]).status();
    }

    // Remount root read-write
    let _ = unsafe { mount::<str, str, str, str>(None, "/", None, MsFlags::MS_REMOUNT, Some("rw")) };

    // Mount all from fstab
    if let Some(mount_bin) = which("mount") {
        let _ = Command::new(mount_bin).arg("-a").status();
    }
}

fn bring_up_networking() {
    // Bring up loopback: ip link set lo up; ip addr add 127.0.0.1/8 dev lo
    if let Some(ip) = which("ip") {
        let _ = Command::new(&ip).args(["link", "set", "lo", "up"]).status();
        let _ = Command::new(&ip).args(["addr", "add", "127.0.0.1/8", "dev", "lo"]).status();
    }
    // If ifupdown is present on Devuan, try ifup -a
    if let Some(ifup) = which("ifup") {
        let _ = Command::new(ifup).arg("-a").status();
    }
}

// -------------------------- Supervision --------------------------

fn open_log(path: &Path) -> Option<File> {
    if let Some(parent) = path.parent() { let _ = create_dir_all(parent); }
    OpenOptions::new().create(true).append(true).open(path).ok()
}

fn spawn_task(rt: &mut TaskRuntime) {
    let cmd = &rt.spec.cmd;
    if cmd.is_empty() { return; }

    // Prepare logging
    let mut stdout_log = open_log(&rt.spec.log_path);
    let mut stderr_log = stdout_log.as_ref().and_then(|_| open_log(&rt.spec.log_path));

    match unsafe { fork() } {
        Ok(ForkResult::Child) => {
            // Child process: detach to its own session
            let _ = unsafe { setsid() };

            // Redirect stdio
            if let Some(ref mut f) = stdout_log {
                let _ = dup2(f.as_raw_fd(), 1);
                let _ = dup2(f.as_raw_fd(), 2);
            } else if let Some(ref mut f) = stderr_log {
                let _ = dup2(f.as_raw_fd(), 2);
            }

            // Execute
            if cmd.len() == 1 {
                let _ = Command::new(&cmd[0]).exec();
            } else {
                let _ = Command::new(&cmd[0]).args(&cmd[1..]).exec();
            }
            // If exec failed
            std::process::exit(127);
        }
        Ok(ForkResult::Parent { child }) => {
            rt.pid = Some(child);
            rt.state = TaskRunState::Running(child.as_raw());
            log_to_kmsg(&format!("started task {} pid {}", rt.spec.name, child));
        }
        Err(_) => {
            rt.state = TaskRunState::Crashed(None);
        }
    }
}

fn restart_needed(policy: RestartPolicy, exit_code: Option<i32>) -> bool {
    match policy {
        RestartPolicy::Always => true,
        RestartPolicy::OnFailure => exit_code.map(|c| c != 0).unwrap_or(true),
        RestartPolicy::Never => false,
    }
}

fn supervise_loop(state: Arc<Mutex<State>>) {
    loop {
        // Handle child exits
        match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::Exited(pid, code)) => {
                let mut st = state.lock().unwrap();
                for (_name, rt) in st.tasks.iter_mut() {
                    if rt.pid == Some(pid) {
                        rt.state = if code == 0 { TaskRunState::Stopped } else { TaskRunState::Crashed(Some(code)) };
                        rt.pid = None;
                        let need = restart_needed(rt.spec.restart, Some(code));
                        if !st.shutting_down && need {
                            rt.restarts += 1;
                            spawn_task(rt);
                        }
                        break;
                    }
                }
            }
            Ok(WaitStatus::Signaled(pid, _sig, _)) => {
                let mut st = state.lock().unwrap();
                for (_name, rt) in st.tasks.iter_mut() {
                    if rt.pid == Some(pid) {
                        rt.state = TaskRunState::Crashed(None);
                        rt.pid = None;
                        let need = restart_needed(rt.spec.restart, None);
                        if !st.shutting_down && need {
                            rt.restarts += 1;
                            spawn_task(rt);
                        }
                        break;
                    }
                }
            }
            Ok(WaitStatus::StillAlive) | Err(_) | Ok(_) => {
                // Nothing to reap now; sleep briefly
                thread::sleep(Duration::from_millis(100));
            }
        }
    }
}

// -------------------------- CLI over Unix socket --------------------------

#[derive(Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "lowercase")]
enum CliReq {
    List,
    Start { name: String },
    Stop { name: String },
}

#[derive(Serialize, Deserialize)]
#[serde(tag = "status", rename_all = "lowercase")]
enum CliResp {
    Ok { message: String, tasks: Option<Vec<(String, String)>> },
    Err { message: String },
}

fn handle_cli_client(mut stream: UnixStream, state: Arc<Mutex<State>>) {
    let mut buf = String::new();
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    if reader.read_line(&mut buf).is_err() { return; }

    let req: Result<CliReq, _> = serde_json::from_str(&buf);
    let resp = match req {
        Ok(CliReq::List) => {
            let st = state.lock().unwrap();
            let mut items = Vec::new();
            for (name, rt) in &st.tasks {
                let s = match &rt.state {
                    TaskRunState::Starting => "starting".to_string(),
                    TaskRunState::Running(pid) => format!("running(pid={})", pid),
                    TaskRunState::Stopped => "stopped".to_string(),
                    TaskRunState::Crashed(code) => format!("crashed({:?})", code),
                };
                items.push((name.clone(), s));
            }
            CliResp::Ok { message: "ok".into(), tasks: Some(items) }
        }
        Ok(CliReq::Start { name }) => {
            let mut st = state.lock().unwrap();
            if let Some(rt) = st.tasks.get_mut(&name) {
                if matches!(rt.state, TaskRunState::Running(_)) {
                    CliResp::Err { message: "already running".into() }
                } else {
                    spawn_task(rt);
                    CliResp::Ok { message: "started".into(), tasks: None }
                }
            } else {
                CliResp::Err { message: "unknown task".into() }
            }
        }
        Ok(CliReq::Stop { name }) => {
            let mut st = state.lock().unwrap();
            if let Some(rt) = st.tasks.get_mut(&name) {
                if let Some(pid) = rt.pid {
                    let _ = kill(pid, Signal::SIGTERM);
                    CliResp::Ok { message: "stopping".into(), tasks: None }
                } else {
                    CliResp::Err { message: "not running".into() }
                }
            } else {
                CliResp::Err { message: "unknown task".into() }
            }
        }
        Err(e) => CliResp::Err { message: format!("bad request: {}", e) },
    };

    let line = serde_json::to_string(&resp).unwrap() + "\n";
    let _ = stream.write_all(line.as_bytes());
}

fn cli_server(state: Arc<Mutex<State>>, sock_path: PathBuf) {
    let _ = ensure_dir(Path::new("/run/sysx"), 0o755);
    let _ = fs::remove_file(&sock_path);
    let listener = UnixListener::bind(&sock_path).expect("bind control socket");
    let mut perms = fs::metadata(&sock_path).unwrap().permissions();
    perms.set_mode(0o660);
    let _ = fs::set_permissions(&sock_path, perms);

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let st = state.clone();
                thread::spawn(move || handle_cli_client(stream, st));
            }
            Err(_) => thread::sleep(Duration::from_millis(50)),
        }
    }
}

// -------------------------- Signal handling for PID 1 --------------------------

extern "C" fn handle_sigterm(_sig: i32) {
    // Just a placeholder handler to interrupt wait; actual shutdown in main loop
}

fn setup_signal_handlers() {
    unsafe {
        let _ = signal(Signal::SIGTERM, SigHandler::Handler(handle_sigterm));
        let _ = signal(Signal::SIGINT, SigHandler::Handler(handle_sigterm));
        let _ = signal(Signal::SIGHUP, SigHandler::Handler(handle_sigterm));
    }
}

// -------------------------- Main (PID 1) --------------------------

fn main() {
    // When invoked as non-PID1, act as CLI client for convenience
    if getpid().as_raw() != 1 {
        run_cli_client();
        return;
    }

    // Minimal environment for children
    env::set_var("PATH", "/sbin:/bin:/usr/sbin:/usr/bin");

    log_to_kmsg("sysx init starting");

    mount_essential();
    fsck_and_mount_all();
    bring_up_networking();

    // Create state and tasks
    let sock_path = PathBuf::from("/run/sysx/sysx.sock");
    let state = Arc::new(Mutex::new(State::new(sock_path.clone())));

    // Register tasks from INIT_TASKS
    {
        let mut st = state.lock().unwrap();
        for (name, argv, restart, autostart, log_path) in INIT_TASKS.iter().cloned() {
            let spec = TaskSpec {
                name: name.into(),
                cmd: argv.iter().map(|s| s.to_string()).collect(),
                restart,
                autostart,
                log_path: PathBuf::from(log_path),
            };
            st.tasks.insert(name.into(), TaskRuntime::new(spec));
        }
    }

    // Start autostart tasks
    {
        let mut st = state.lock().unwrap();
        for (_n, rt) in st.tasks.iter_mut() {
            if rt.spec.autostart {
                rt.state = TaskRunState::Starting;
                spawn_task(rt);
            }
        }
    }

    // Start CLI server thread
    {
        let st = state.clone();
        let sock = sock_path.clone();
        thread::spawn(move || cli_server(st, sock));
    }

    setup_signal_handlers();

    // Reaper + supervisor loop (never returns)
    supervise_loop(state);
}

// -------------------------- CLI client when not PID 1 --------------------------

fn run_cli_client() {
    // Usage: sysx [list | start <name> | stop <name>]
    let args: Vec<String> = env::args().collect();
    let sock = "/run/sysx/sysx.sock";

    let req = match args.get(1).map(|s| s.as_str()) {
        Some("list") | None => CliReq::List,
        Some("start") => {
            let name = args.get(2).cloned().unwrap_or_else(|| {
                eprintln!("usage: sysx start <task>");
                std::process::exit(2);
            });
            CliReq::Start { name }
        }
        Some("stop") => {
            let name = args.get(2).cloned().unwrap_or_else(|| {
                eprintln!("usage: sysx stop <task>");
                std::process::exit(2);
            });
            CliReq::Stop { name }
        }
        Some(other) => {
            eprintln!("unknown command: {}", other);
            std::process::exit(2);
        }
    };

    if let Err(e) = fs::create_dir_all("/run/sysx") { let _ = e; }

    match UnixStream::connect(sock) {
        Ok(mut stream) => {
            let line = serde_json::to_string(&req).unwrap() + "\n";
            let _ = stream.write_all(line.as_bytes());
            let mut resp = String::new();
            let mut reader = BufReader::new(stream);
            let _ = reader.read_line(&mut resp);
            if let Ok(CliResp::Ok { message, tasks }) = serde_json::from_str::<CliResp>(&resp) {
                println!("{}", message);
                if let Some(list) = tasks { for (n, s) in list { println!("{}\t{}", n, s); } }
            } else if let Ok(CliResp::Err { message }) = serde_json::from_str::<CliResp>(&resp) {
                eprintln!("error: {}", message);
                std::process::exit(1);
            } else {
                eprintln!("invalid response");
                std::process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("cannot connect to {}: {}", sock, e);
            std::process::exit(1);
        }
    }
}

Below is a fully self-contained, compilable Rust project for 'sysx' that runs as PID 1 on Devuan and avoids systemd, sysvinit, dbus, X11/Xorg, elogind, xinit, and systemctl. It mounts /proc, /sys, /dev, runs fsck, remounts root rw, mounts fstab, brings up basic networking, supervises services with restart/logging, provides a Unix-socket CLI (list/start/stop), and spawns a getty on tty1.

