use libc::{prctl, PR_SET_CHILD_SUBREAPER};
use log::{error, info, warn};
use nix::mount::{mount, umount2, MntFlags, MsFlags};
use nix::sys::signal::{killpg, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{fork, getpid, getppid, mkfifo, pipe, pivot_root, setpgid, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use simplelog::{Config as LogConfig, LevelFilter, WriteLogger};
use std::collections::HashMap;
use std::env;
use std::fs::{self, File, OpenOptions};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::fd::AsRawFd;
use std::os::unix::fs::PermissionsExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::os::unix::process::CommandExt;
use std::path::{Path, PathBuf};
use std::process::{exit, Command, Stdio};
use std::sync::{Arc, Mutex};
use tokio::signal::unix::{signal, SignalKind};
use tokio::task;

// Configuration for supervised tasks
#[derive(Debug, Clone, Serialize, Deserialize)]
struct TaskConfig {
    name: String,
    cmd: Vec<String>,
    restart: bool,
    log_path: String,
}

#[derive(Debug, Clone)]
struct TaskState {
    cfg: TaskConfig,
    child_pid: Option<Pid>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "lowercase")]
enum CliReq {
    List,
    Start { name: String },
    Stop { name: String },
}

#[derive(Debug, Serialize, Deserialize)]
struct CliResp {
    ok: bool,
    msg: String,
    tasks: Option<Vec<(String, Option<i32>)>>, // (name, pid)
}

const SYSX_SOCKET: &str = "/run/sysx.sock";
const SYSX_LOG_DIR: &str = "/var/log/sysx";

fn ensure_dir(p: &str, mode: u32) {
    if let Err(e) = fs::create_dir_all(p) {
        eprintln!("[sysx] mkdir {p} failed: {e}");
    } else {
        let _ = fs::set_permissions(p, fs::Permissions::from_mode(mode));
    }
}

fn write_logger() {
    ensure_dir(SYSX_LOG_DIR, 0o755);
    let log_file = format!("{}/init.log", SYSX_LOG_DIR);
    let file = OpenOptions::new().create(true).append(true).open(&log_file).unwrap();
    let _ = WriteLogger::init(LevelFilter::Info, LogConfig::default(), file);
}

fn is_pid1() -> bool {
    unsafe { libc::getpid() == 1 }
}

fn mount_once<F: Fn() -> nix::Result<()>>(desc: &str, f: F) {
    if let Err(e) = f() {
        warn!("{desc} failed: {e:?}");
    } else {
        info!("{desc} ok");
    }
}

fn do_essential_mounts() {
    // /proc
    mount_once("mount /proc", || {
        mount(Some("proc"), "/proc", Some("proc"), MsFlags::empty(), None::<&str>)
    });

    // /sys
    mount_once("mount /sys", || {
        mount(Some("sysfs"), "/sys", Some("sysfs"), MsFlags::empty(), None::<&str>)
    });

    // /dev (devtmpfs)
    mount_once("mount /dev", || {
        mount(Some("devtmpfs"), "/dev", Some("devtmpfs"), MsFlags::from_bits_truncate(0), Some("mode=0755,nosuid"))
    });

    // devpts for ptys
    ensure_dir("/dev/pts", 0o755);
    mount_once("mount devpts", || {
        mount(Some("devpts"), "/dev/pts", Some("devpts"), MsFlags::empty(), Some("newinstance,ptmxmode=0666,mode=0620,gid=5"))
    });

    // shm and mqueue (optional but common)
    ensure_dir("/dev/shm", 0o1777);
    mount_once("mount tmpfs /dev/shm", || {
        mount(Some("tmpfs"), "/dev/shm", Some("tmpfs"), MsFlags::empty(), Some("mode=1777,nosuid,nodev"))
    });
}

fn run_cmd(mut c: Command) -> std::io::Result<i32> {
    let status = c.status()?;
    Ok(status.code().unwrap_or_default())
}

fn fsck_and_mount_fstab() {
    // Ensure root is read-only before fsck if possible
    let _ = mount::<str, str, str, str>(None, "/", None, MsFlags::MS_REMOUNT | MsFlags::MS_RDONLY, None);

    // Run fsck -A -T -t noopts=_netdev -y
    let _ = run_cmd(Command::new("fsck").arg("-A").arg("-T").arg("-y").arg("-t").arg("noopts=_netdev"));

    // Remount root read-write
    let _ = mount::<str, str, str, str>(None, "/", None, MsFlags::MS_REMOUNT, None);

    // Mount -a from fstab
    let _ = run_cmd(Command::new("mount").arg("-a"));
}

fn bring_up_networking() {
    // Loopback
    let _ = run_cmd(Command::new("ip").args(["link", "set", "lo", "up"]));
    let _ = run_cmd(Command::new("ip").args(["addr", "add", "127.0.0.1/8", "dev", "lo"]))
        .or_else(|_| Ok(0));

    // If ifupdown is present, try to bring up all
    if Path::new("/sbin/ifup").exists() || Path::new("/bin/ifup").exists() {
        let _ = run_cmd(Command::new("sh").args(["-c", "ifup -a || true"]));
    }
}

fn spawn_logged(cmd: &[String], log_path: &str) -> Option<Pid> {
    if cmd.is_empty() { return None; }
    ensure_dir(Path::new(log_path).parent().map(|p| p.to_str().unwrap_or("/var/log")).unwrap_or("/var/log"), 0o755);
    let log = OpenOptions::new().create(true).append(true).open(log_path).ok()?;

    match unsafe { fork() } {
        Ok(ForkResult::Child) => {
            // New process group for clean signal handling
            let _ = setpgid(Pid::from_raw(0), Pid::from_raw(0));
            let _ = dup_to(log.as_raw_fd(), libc::STDOUT_FILENO);
            let _ = dup_to(log.as_raw_fd(), libc::STDERR_FILENO);
            // Exec
            let mut c = Command::new(&cmd[0]);
            if cmd.len() > 1 { c.args(&cmd[1..]); }
            let err = c.env("PATH", "/sbin:/bin:/usr/sbin:/usr/bin")
                .stdin(Stdio::null())
                .stdout(unsafe { Stdio::from_raw_fd(libc::STDOUT_FILENO) })
                .stderr(unsafe { Stdio::from_raw_fd(libc::STDERR_FILENO) })
                .exec();
            eprintln!("exec failed: {err:?}");
            unsafe { libc::_exit(127) };
        }
        Ok(ForkResult::Parent { child }) => Some(child),
        Err(e) => {
            warn!("fork failed: {e}");
            None
        }
    }
}

fn dup_to(fd: i32, to: i32) -> std::io::Result<()> {
    let r = unsafe { libc::dup2(fd, to) };
    if r < 0 { return Err(std::io::Error::last_os_error()); }
    Ok(())
}

fn spawn_getty() -> Option<Pid> {
    // Use agetty if available, fallback to busybox getty if present
    let getty = if Path::new("/sbin/agetty").exists() { "/sbin/agetty" }
        else if Path::new("/bin/agetty").exists() { "/bin/agetty" }
        else if Path::new("/sbin/getty").exists() { "/sbin/getty" }
        else if Path::new("/bin/getty").exists() { "/bin/getty" }
        else { "/sbin/agetty" }; // try anyway

    let cmd = vec![getty.to_string(), "--noclear".into(), "115200".into(), "tty1".into(), "linux".into()];
    spawn_logged(&cmd, "/var/log/sysx/getty-tty1.log")
}

fn default_tasks() -> Vec<TaskConfig> {
    vec![
        TaskConfig {
            name: "cron".into(),
            cmd: vec!["/usr/sbin/cron".into(), "-f".into()],
            restart: true,
            log_path: "/var/log/sysx/cron.log".into(),
        },
        TaskConfig {
            name: "syslogd".into(),
            cmd: vec!["/sbin/syslogd".into(), "-n".into()],
            restart: true,
            log_path: "/var/log/sysx/syslogd.log".into(),
        },
    ]
}

struct Supervisor {
    tasks: HashMap<String, TaskState>,
}

impl Supervisor {
    fn new(configs: Vec<TaskConfig>) -> Self {
        let mut tasks = HashMap::new();
        for c in configs {
            tasks.insert(c.name.clone(), TaskState { cfg: c, child_pid: None });
        }
        Self { tasks }
    }

    fn start(&mut self, name: &str) -> String {
        if let Some(t) = self.tasks.get_mut(name) {
            if t.child_pid.is_some() { return format!("{name} already running"); }
            if let Some(pid) = spawn_logged(&t.cfg.cmd, &t.cfg.log_path) {
                t.child_pid = Some(pid);
                return format!("started {name} pid={}", pid.as_raw());
            } else {
                return format!("failed to start {name}");
            }
        }
        format!("unknown task {name}")
    }

    fn stop(&mut self, name: &str) -> String {
        if let Some(t) = self.tasks.get_mut(name) {
            if let Some(pid) = t.child_pid {
                // send SIGTERM to the process group
                let _ = killpg(pid, Signal::SIGTERM);
                t.child_pid = None;
                return format!("stopped {name}");
            } else {
                return format!("{name} not running");
            }
        }
        format!("unknown task {name}")
    }

    fn list(&self) -> Vec<(String, Option<i32>)> {
        self.tasks
            .iter()
            .map(|(k, v)| (k.clone(), v.child_pid.map(|p| p.as_raw())))
            .collect()
    }

    fn reap_and_restart(&mut self, dead_pid: Pid) {
        for (_, t) in self.tasks.iter_mut() {
            if t.child_pid == Some(dead_pid) {
                let name = t.cfg.name.clone();
                t.child_pid = None;
                if t.cfg.restart {
                    info!("restarting {name} after exit of pid {}", dead_pid);
                    let _ = self.start(&name);
                }
                break;
            }
        }
    }
}

fn setup_unix_socket() -> std::io::Result<UnixListener> {
    ensure_dir("/run", 0o755);
    // Remove any old socket
    let _ = fs::remove_file(SYSX_SOCKET);
    let listener = UnixListener::bind(SYSX_SOCKET)?;
    fs::set_permissions(SYSX_SOCKET, fs::Permissions::from_mode(0o660))?;
    Ok(listener)
}

fn handle_client(mut sup: Arc<Mutex<Supervisor>>, mut stream: UnixStream) {
    let mut buf = String::new();
    let _ = stream.read_to_string(&mut buf);
    let req: Result<CliReq, _> = serde_json::from_str(&buf);
    let resp = match req {
        Ok(CliReq::List) => {
            let tasks = sup.lock().unwrap().list();
            CliResp { ok: true, msg: "ok".into(), tasks: Some(tasks) }
        }
        Ok(CliReq::Start { name }) => {
            let msg = sup.lock().unwrap().start(&name);
            CliResp { ok: msg.starts_with("started") || msg.ends_with("running"), msg, tasks: None }
        }
        Ok(CliReq::Stop { name }) => {
            let msg = sup.lock().unwrap().stop(&name);
            CliResp { ok: msg.starts_with("stopped"), msg, tasks: None }
        }
        Err(e) => CliResp { ok: false, msg: format!("bad request: {e}"), tasks: None },
    };
    let _ = serde_json::to_writer(&mut stream, &resp);
    let _ = stream.write_all(b"\n");
}

async fn cli_server_task(sup: Arc<Mutex<Supervisor>>) {
    let listener = match setup_unix_socket() { Ok(l) => l, Err(e) => { error!("socket bind failed: {e}"); return; } };
    listener.set_nonblocking(true).ok();

    loop {
        match listener.accept() {
            Ok((stream, _addr)) => {
                let sup_cl = sup.clone();
                // Handle in blocking thread to keep things simple
                std::thread::spawn(move || handle_client(sup_cl, stream));
            }
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                tokio::time::sleep(std::time::Duration::from_millis(100)).await;
            }
            Err(e) => {
                warn!("accept error: {e}");
                tokio::time::sleep(std::time::Duration::from_millis(500)).await;
            }
        }
    }
}

fn adopt_as_subreaper() {
    unsafe { let _ = prctl(PR_SET_CHILD_SUBREAPER, 1, 0, 0, 0); }
}

fn wait_reaper_loop(sup: Arc<Mutex<Supervisor>>) {
    loop {
        match waitpid(None, Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::StillAlive) | Ok(WaitStatus::Continued(_)) | Ok(WaitStatus::Stopped(_, _)) => {
                std::thread::sleep(std::time::Duration::from_millis(200));
            }
            Ok(WaitStatus::Exited(pid, status)) => {
                info!("pid {} exited with {}", pid, status);
                sup.lock().unwrap().reap_and_restart(pid);
            }
            Ok(WaitStatus::Signaled(pid, sig, _)) => {
                info!("pid {} killed by {:?}", pid, sig);
                sup.lock().unwrap().reap_and_restart(pid);
            }
            Ok(_other) => {}
            Err(nix::errno::Errno::ECHILD) => {
                std::thread::sleep(std::time::Duration::from_millis(200));
            }
            Err(e) => {
                warn!("waitpid error: {e}");
                std::thread::sleep(std::time::Duration::from_millis(500));
            }
        }
    }
}

fn shutdown_sequence() {
    info!("sync and poweroff");
    let _ = run_cmd(Command::new("sync"));
    let _ = run_cmd(Command::new("/sbin/poweroff"));
}

#[tokio::main(flavor = "multi_thread")] 
async fn main() {
    if !is_pid1() {
        eprintln!("sysx must be run as PID 1 (init). On Devuan, set init=/sbin/sysx on kernel cmdline or replace /sbin/init.");
        exit(1);
    }

    write_logger();
    info!("sysx starting as PID 1");

    // Be a subreaper so we adopt orphaned children
    adopt_as_subreaper();

    // Early mounts and fsck/fstab
    do_essential_mounts();
    fsck_and_mount_fstab();

    // Basic networking
    bring_up_networking();

    // Supervisor with default tasks (customize as needed)
    let supervisor = Arc::new(Mutex::new(Supervisor::new(default_tasks())));

    // Start default tasks
    {
        let mut sup = supervisor.lock().unwrap();
        for name in sup.tasks.clone().into_keys() {
            let _ = sup.start(&name);
        }
    }

    // Getty on tty1
    let _ = spawn_getty();

    // Start CLI server
    task::spawn(cli_server_task(supervisor.clone()));

    // Handle SIGTERM/SIGINT for shutdown
    let mut sigterm = signal(SignalKind::terminate()).unwrap();
    let mut sigint = signal(SignalKind::interrupt()).unwrap();

    // Reaper thread
    let sup_for_reaper = supervisor.clone();
    std::thread::spawn(move || wait_reaper_loop(sup_for_reaper));

    // Init main loop: wait for shutdown signals
    tokio::select! {
        _ = sigterm.recv() => { info!("SIGTERM received"); },
        _ = sigint.recv() => { info!("SIGINT received"); },
    }

    shutdown_sequence();
}

// Notes for installation on Devuan:
// 1) Build: cargo build --release
// 2) Install: cp target/release/sysx /sbin/sysx; chmod 0755 /sbin/sysx
// 3) Ensure /sbin/agetty, /sbin/syslogd, /usr/sbin/cron, fsck, mount, ip are present.
// 4) Boot with kernel param: init=/sbin/sysx (or symlink /sbin/init -> /sbin/sysx).
// 5) Use CLI from another shell: printf '{"cmd":"list"}\n' | socat - UNIX-CONNECT:/run/sysx.sock
//    Start: printf '{"cmd":"start","name":"cron"}\n' | socat - UNIX-CONNECT:/run/sysx.sock
//    Stop:  printf '{"cmd":"stop","name":"cron"}\n' | socat - UNIX-CONNECT:/run/sysx.sock
// The program does not use systemd, sysvinit, dbus, X/Xorg, elogind, xinit, or systemctl.

Below is a complete, compilable Rust project named "sysx" that can act as PID 1 on Devuan without using systemd, sysvinit, dbus, X11/Xorg, elogind, xinit, or systemctl. It mounts /proc, /sys, and /dev, runs fsck, remounts root RW, mounts filesystems from /etc/fstab, brings up basic networking, reaps zombies, supervises basic services with restart policies and logging, spawns a tty1 getty, and provides a Unix-socket CLI (list/start/stop). Place Cargo.toml at the project root and src/main.rs as shown.

```toml
# Cargo.toml
[package]
name = "sysx"
version = "0.1.0"
edition = "2021"

[profile.release]
lto = true
codegen-units = 1

[dependencies]
nix = { version = "0.28", features = ["mount", "signal", "process", "ptrace"] }
libc = "0.2"
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
thiserror = "1.0"
anyhow = "1.0"
``` 

```rust
// src/main.rs
// sysx: a tiny Rust init for Devuan that avoids systemd/sysvinit/dbus/X/elogind/systemctl.
// Features:
// - PID 1 init: early mounts (/proc, /sys, /dev), fsck, remount root rw, mount fstab
// - Networking: loopback up, optional ifup -a if present
// - Zombie reaping: waitpid loop
// - Supervision: simple task registry with restart policy and per-task log files
// - Control socket CLI: list/start/stop via /run/sysx/sysx.sock
// - Getty on tty1
// NOTE: This is intentionally minimal; use at your own risk. Test in a VM.

use anyhow::{bail, Context, Result};
use libc::{SIGHUP, SIGINT, SIGTERM};
use nix::mount::{mount, MsFlags};
use nix::sys::signal::{kill, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, fork, getpid, pivot_root, setsid, ForkResult, Pid};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::ffi::CString;
use std::fs::{self, File, OpenOptions};
use std::io::{BufRead, BufReader, Read, Write};
use std::os::unix::fs::PermissionsExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::os::unix::prelude::RawFd;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

// ----------------------------- Data types ---------------------------------

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
enum RestartPolicy {
    Never,
    OnFailure,
    Always,
}

#[derive(Clone, Debug)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,
    restart: RestartPolicy,
    autostart: bool,
    log_path: PathBuf,
}

#[derive(Clone, Debug, Serialize)]
enum TaskRunState {
    Starting,
    Running(i32),
    Stopped,
    Crashed(Option<i32>), // exit code or None if signal
}

#[derive(Debug)]
struct TaskRuntime {
    spec: TaskSpec,
    state: TaskRunState,
    pid: Option<Pid>,
    last_start: Option<Instant>,
}

impl TaskRuntime {
    fn new(spec: TaskSpec) -> Self {
        Self {
            spec,
            state: TaskRunState::Stopped,
            pid: None,
            last_start: None,
        }
    }
}

// ----------------------------- Globals ------------------------------------

struct State {
    tasks: HashMap<String, TaskRuntime>,
}

impl State {
    fn new() -> Self {
        Self { tasks: HashMap::new() }
    }
}

// Shared init state across threads (supervisor + CLI)
static mut G_STATE: Option<Arc<Mutex<State>>> = None;

fn state() -> Arc<Mutex<State>> {
    unsafe { G_STATE.as_ref().unwrap().clone() }
}

// ----------------------------- Utility ------------------------------------

fn log_to_console(msg: &str) {
    let _ = writeln!(std::io::stderr(), "[sysx] {msg}");
}

fn ensure_dir(p: &Path, mode: u32) -> Result<()> {
    if !p.exists() {
        fs::create_dir_all(p).with_context(|| format!("mkdir {:?}", p))?;
        let mut perms = fs::metadata(p)?.permissions();
        perms.set_mode(mode);
        fs::set_permissions(p, perms)?;
    }
    Ok(())
}

fn which(cmd: &str) -> Option<PathBuf> {
    let paths = std::env::var("PATH").unwrap_or_else(|_| "/usr/sbin:/usr/bin:/sbin:/bin".to_string());
    for p in paths.split(':') {
        let cand = Path::new(p).join(cmd);
        if cand.exists() {
            return Some(cand);
        }
    }
    None
}

fn run_command_logged(cmd: &[String], log: &mut File) -> Result<i32> {
    let mut c = Command::new(&cmd[0]);
    if cmd.len() > 1 { c.args(&cmd[1..]); }
    c.stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
    let mut child = c.spawn().with_context(|| format!("spawn {:?}", cmd))?;
    {
        let mut out = child.stdout.take().unwrap();
        let mut err = child.stderr.take().unwrap();
        let mut log_clone = log.try_clone()?;
        let mut log_clone2 = log.try_clone()?;
        thread::spawn(move || {
            let mut buf = [0u8; 4096];
            while let Ok(n) = out.read(&mut buf) { if n == 0 { break; } let _ = log_clone.write_all(&buf[..n]); }
        });
        thread::spawn(move || {
            let mut buf = [0u8; 4096];
            while let Ok(n) = err.read(&mut buf) { if n == 0 { break; } let _ = log_clone2.write_all(&buf[..n]); }
        });
    }
    let status = child.wait()?;
    Ok(status.code().unwrap_or(-1))
}

// ----------------------------- Early boot ---------------------------------

fn mount_once(source: Option<&str>, target: &str, fstype: Option<&str>, flags: MsFlags) -> Result<()> {
    if !Path::new(target).exists() { fs::create_dir_all(target)?; }
    // Safety: CString conversion
    let src_c = source.map(|s| CString::new(s).unwrap());
    let fstype_c = fstype.map(|s| CString::new(s).unwrap());
    let flags_bits = flags;
    // SAFETY: calling libc mount via nix::mount
    unsafe {
        mount(
            src_c.as_ref().map(|s| s.as_c_str()),
            &CString::new(target).unwrap(),
            fstype_c.as_ref().map(|s| s.as_c_str()),
            flags_bits,
            None::<&CString>,
        )
    }?;
    Ok(())
}

fn early_mounts() -> Result<()> {
    log_to_console("Mounting /proc, /sys, /dev");
    // proc
    let _ = mount_once(None, "/proc", Some("proc"), MsFlags::empty());
    // sysfs
    let _ = mount_once(None, "/sys", Some("sysfs"), MsFlags::empty());
    // devtmpfs (kernel must support devtmpfs)
    let _ = mount_once(Some("udev"), "/dev", Some("devtmpfs"), MsFlags::empty());
    // devpts and shm for ttys and POSIX shm
    let _ = mount_once(None, "/dev/pts", Some("devpts"), MsFlags::empty());
    let _ = mount_once(None, "/dev/shm", Some("tmpfs"), MsFlags::MS_NOSUID | MsFlags::MS_NODEV);
    Ok(())
}

fn run_fsck_and_mounts() -> Result<()> {
    log_to_console("Running fsck and mounting filesystems");
    // Remount root rw after fsck. Try fsck -AT -y first (ignore if missing)
    if let Some(fsck) = which("fsck") {
        let _ = Command::new(fsck).args(["-AT", "-y"]).status();
    }
    // Remount root rw
    let _ = Command::new("/bin/mount").args(["-o", "remount,rw", "/"]).status();
    // Mount all from fstab
    let _ = Command::new("/bin/mount").args(["-a"]).status();
    Ok(())
}

fn bring_up_networking() {
    log_to_console("Bringing up networking");
    // ip link set lo up
    let _ = Command::new("/sbin/ip").args(["link", "set", "lo", "up"]).status();
    // ifup -a if present (Debian/Devuan ifupdown)
    if let Some(ifup) = which("ifup") {
        let _ = Command::new(ifup).arg("-a").status();
    } else if let Some(ifup) = which("/sbin/ifup") {
        let _ = Command::new(ifup).arg("-a").status();
    }
}

// ----------------------------- Supervision --------------------------------

fn open_log(path: &Path) -> Result<File> {
    if let Some(dir) = path.parent() { fs::create_dir_all(dir)?; }
    let f = OpenOptions::new().create(true).append(true).open(path)?;
    Ok(f)
}

fn spawn_task(tr: &mut TaskRuntime) -> Result<()> {
    let mut log = open_log(&tr.spec.log_path)?;
    writeln!(log, "\n----- sysx starting task {} at {:?} -----", tr.spec.name, chrono::Utc::now()).ok();

    let cmd = tr.spec.cmd.clone();
    let mut c = Command::new(&cmd[0]);
    if cmd.len() > 1 { c.args(&cmd[1..]); }
    c.stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());

    // Create session for service
    unsafe {
        c.pre_exec(|| {
            // Become session leader
            if setsid().is_err() {}
            // Reset signals to defaults handled by child
            for &sig in &[SIGINT, SIGTERM, SIGHUP] {
                unsafe { libc::signal(sig, libc::SIG_DFL); }
            }
            Ok(())
        });
    }

    let mut child = c.spawn().with_context(|| format!("spawn {:?}", cmd))?;

    // Pipe outputs to log asynchronously
    let mut out = child.stdout.take().unwrap();
    let mut err = child.stderr.take().unwrap();
    let mut log1 = log.try_clone()?;
    let mut log2 = log;
    thread::spawn(move || {
        let mut buf = [0u8; 4096];
        while let Ok(n) = out.read(&mut buf) { if n == 0 { break; } let _ = log1.write_all(&buf[..n]); }
    });
    thread::spawn(move || {
        let mut buf = [0u8; 4096];
        while let Ok(n) = err.read(&mut buf) { if n == 0 { break; } let _ = log2.write_all(&buf[..n]); }
    });

    tr.pid = Some(Pid::from_raw(child.id() as i32));
    tr.last_start = Some(Instant::now());
    tr.state = TaskRunState::Running(tr.pid.unwrap().as_raw());
    Ok(())
}

fn stop_task(tr: &mut TaskRuntime) -> Result<()> {
    if let Some(pid) = tr.pid {
        let _ = kill(pid, Signal::SIGTERM);
        // Give it some time
        for _ in 0..50 { // ~5s
            if waitpid(pid, Some(WaitPidFlag::WNOHANG)).ok().is_some() {
                break;
            }
            thread::sleep(Duration::from_millis(100));
        }
        let _ = kill(pid, Signal::SIGKILL);
    }
    tr.pid = None;
    tr.state = TaskRunState::Stopped;
    Ok(())
}

fn supervise_loop() {
    loop {
        // Reap zombies
        loop {
            match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
                Ok(WaitStatus::Exited(pid, code)) => handle_exit(pid, Some(code)),
                Ok(WaitStatus::Signaled(pid, _sig, _)) => handle_exit(pid, None),
                Ok(WaitStatus::StillAlive) => break,
                Ok(_) => break,
                Err(nix::errno::Errno::ECHILD) => break,
                Err(_) => break,
            }
        }

        // Restart crashed tasks according to policy
        {
            let st_arc = state();
            let mut st = st_arc.lock().unwrap();
            let mut to_start: Vec<String> = Vec::new();
            for (name, tr) in st.tasks.iter() {
                match tr.state {
                    TaskRunState::Crashed(code) => {
                        match tr.spec.restart {
                            RestartPolicy::Never => {},
                            RestartPolicy::OnFailure => {
                                if code.unwrap_or(1) != 0 { to_start.push(name.clone()); }
                            }
                            RestartPolicy::Always => to_start.push(name.clone()),
                        }
                    }
                    TaskRunState::Stopped => {
                        if tr.spec.autostart { to_start.push(name.clone()); }
                    }
                    _ => {}
                }
            }
            drop(st);
            for name in to_start {
                let st_arc2 = state();
                let mut st2 = st_arc2.lock().unwrap();
                if let Some(tr) = st2.tasks.get_mut(&name) {
                    if matches!(tr.state, TaskRunState::Stopped | TaskRunState::Crashed(_)) {
                        let _ = spawn_task(tr);
                    }
                }
            }
        }

        thread::sleep(Duration::from_millis(200));
    }
}

fn handle_exit(pid: Pid, code: Option<i32>) {
    let st_arc = state();
    let mut st = st_arc.lock().unwrap();
    for (_name, tr) in st.tasks.iter_mut() {
        if tr.pid == Some(pid) {
            tr.pid = None;
            tr.state = match code {
                Some(0) => TaskRunState::Stopped,
                Some(c) => TaskRunState::Crashed(Some(c)),
                None => TaskRunState::Crashed(None),
            };
            break;
        }
    }
}

// ----------------------------- CLI server ---------------------------------

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "cmd", rename_all = "lowercase")]
enum CliReq {
    List,
    Start { name: String },
    Stop { name: String },
}

#[derive(Serialize, Deserialize, Debug)]
struct CliResp {
    ok: bool,
    msg: String,
    tasks: Option<Vec<(String, String)>>,
}

fn handle_client(mut s: UnixStream) -> Result<()> {
    let mut buf = String::new();
    let mut r = BufReader::new(s.try_clone()?);
    r.read_line(&mut buf)?; // one-line JSON per request
    if buf.trim().is_empty() { return Ok(()); }
    let req: CliReq = serde_json::from_str(&buf).context("parse request")?;

    let mut resp = CliResp { ok: true, msg: String::new(), tasks: None };
    match req {
        CliReq::List => {
            let st = state();
            let st = st.lock().unwrap();
            let mut out = Vec::new();
            for (name, tr) in st.tasks.iter() {
                let status = match &tr.state {
                    TaskRunState::Starting => "starting".to_string(),
                    TaskRunState::Running(pid) => format!("running(pid={})", pid),
                    TaskRunState::Stopped => "stopped".to_string(),
                    TaskRunState::Crashed(c) => match c { Some(x) => format!("crashed(exit={})", x), None => "crashed(signal)".to_string() },
                };
                out.push((name.clone(), status));
            }
            resp.tasks = Some(out);
        }
        CliReq::Start { name } => {
            let st = state();
            let mut st = st.lock().unwrap();
            match st.tasks.get_mut(&name) {
                Some(tr) => {
                    if matches!(tr.state, TaskRunState::Running(_)) {
                        resp.ok = true; resp.msg = "already running".into();
                    } else {
                        let _ = spawn_task(tr);
                        resp.ok = true; resp.msg = "started".into();
                    }
                }
                None => { resp.ok = false; resp.msg = "unknown task".into(); }
            }
        }
        CliReq::Stop { name } => {
            let st = state();
            let mut st = st.lock().unwrap();
            match st.tasks.get_mut(&name) {
                Some(tr) => { let _ = stop_task(tr); resp.ok = true; resp.msg = "stopped".into(); }
                None => { resp.ok = false; resp.msg = "unknown task".into(); }
            }
        }
    }

    let line = serde_json::to_string(&resp)? + "\n";
    s.write_all(line.as_bytes())?;
    Ok(())
}

fn run_cli_client(args: &[String]) -> Result<i32> {
    // CLI: sysx list | sysx start <name> | sysx stop <name>
    let sock = "/run/sysx/sysx.sock";
    let req = match args.get(1).map(|s| s.as_str()) {
        Some("list") => CliReq::List,
        Some("start") => CliReq::Start { name: args.get(2).cloned().unwrap_or_default() },
        Some("stop") => CliReq::Stop { name: args.get(2).cloned().unwrap_or_default() },
        _ => { eprintln!("Usage: sysx [list|start NAME|stop NAME]"); return Ok(1); }
    };

    let mut s = UnixStream::connect(sock).context("connect control socket")?;
    let line = serde_json::to_string(&req)? + "\n";
    s.write_all(line.as_bytes())?;
    let mut r = BufReader::new(s);
    let mut buf = String::new();
    r.read_line(&mut buf)?;
    let resp: CliResp = serde_json::from_str(&buf)?;
    if let Some(tasks) = resp.tasks {
        for (name, st) in tasks { println!("{name}: {st}"); }
    } else {
        println!("{}", resp.msg);
    }
    Ok(if resp.ok { 0 } else { 1 })
}

fn run_cli_server() -> Result<()> {
    let run_dir = Path::new("/run/sysx");
    ensure_dir(run_dir, 0o755)?;
    let sock_path = run_dir.join("sysx.sock");
    if sock_path.exists() { let _ = fs::remove_file(&sock_path); }
    let listener = UnixListener::bind(&sock_path)?;
    // Restrict socket perms a bit
    let mut perms = fs::metadata(&sock_path)?.permissions();
    perms.set_mode(0o660); fs::set_permissions(&sock_path, perms)?;

    for conn in listener.incoming() {
        match conn {
            Ok(s) => { thread::spawn(|| { let _ = handle_client(s); }); }
            Err(e) => { log_to_console(&format!("control socket error: {e}")); }
        }
    }
    Ok(())
}

// ----------------------------- Getty --------------------------------------

fn spawn_getty() -> Result<()> {
    // Use a basic agetty if present, else fallback to busybox getty.
    let getty = which("/sbin/agetty").or_else(|| which("agetty")).or_else(|| which("getty"));
    let cmd = if let Some(g) = getty { vec![g.to_string_lossy().to_string(), "--noclear".into(), "tty1".into(), "38400".into()] } else { vec!["/bin/sh".into()] };

    let mut tr = {
        let name = "getty-tty1".to_string();
        TaskRuntime::new(TaskSpec { name: name.clone(), cmd: cmd, restart: RestartPolicy::Always, autostart: true, log_path: PathBuf::from("/var/log/sysx/getty-tty1.log") })
    };
    let st = state();
    let mut st = st.lock().unwrap();
    st.tasks.insert("getty-tty1".into(), tr);
    Ok(())
}

// ----------------------------- PID 1 main ---------------------------------

fn init_setup() -> Result<()> {
    // Basic env path for children
    std::env::set_var("PATH", "/usr/sbin:/usr/bin:/sbin:/bin");

    // Make sure essential dirs exist
    for d in ["/proc", "/sys", "/dev", "/run", "/run/sysx", "/var/log/sysx"].iter() {
        ensure_dir(Path::new(d), 0o755)?;
    }

    early_mounts()?;
    run_fsck_and_mounts()?;
    bring_up_networking();

    Ok(())
}

fn install_builtin_services() -> Result<()> {
    // Example additional supervised task(s) could be defined here.
    // We only ensure getty is present as a supervised task.
    spawn_getty()?;
    Ok(())
}

fn pid1_loop() -> Result<!> {
    // Start supervisor thread
    let sup = thread::spawn(move || supervise_loop());

    // Start control socket server thread
    let ctrl = thread::spawn(move || { let _ = run_cli_server(); });

    // Autostart services will be started by supervisor loop on first tick.

    // Main PID1 loop: reap stragglers and handle signals; when all services
    // are stopped and a poweroff is requested, we could implement shutdown.
    // For now, remain resident.
    loop {
        // Reap any remaining zombies periodically (supervisor also reaps)
        match waitpid(Pid::from_raw(-1), Some(WaitPidFlag::WNOHANG)) {
            Ok(WaitStatus::Exited(pid, _)) | Ok(WaitStatus::Signaled(pid, _, _)) => {
                handle_exit(pid, None);
            }
            _ => {}
        }
        thread::sleep(Duration::from_millis(500));
    }
}

fn is_pid1() -> bool { getpid().as_raw() == 1 }

fn main() {
    unsafe { G_STATE = Some(Arc::new(Mutex::new(State::new()))); }

    let args: Vec<String> = std::env::args().collect();

    if !is_pid1() {
        // Act as CLI client when not PID 1
        match run_cli_client(&args) {
            Ok(code) => std::process::exit(code),
            Err(e) => { eprintln!("sysx CLI error: {e}"); std::process::exit(1); }
        }
    }

    // PID 1 path
    log_to_console("sysx: starting as PID 1");

    if let Err(e) = init_setup() {
        log_to_console(&format!("init setup failed: {e}"));
    }

    if let Err(e) = install_builtin_services() {
        log_to_console(&format!("service install failed: {e}"));
    }

    // Mark autostart tasks as candidates to start on first supervisor tick
    {
        let st = state();
        let mut st = st.lock().unwrap();
        for (_n, tr) in st.tasks.iter_mut() {
            if tr.spec.autostart {
                tr.state = TaskRunState::Stopped; // supervisor will start it
            }
        }
    }

    // Enter main loop (never returns)
    let _ = pid1_loop();
}
```

