def health() -> Response:
    return Response("OK", mimetype="text/plain")

@app.route("/api/extract", methods=["POST"])  # JSON API
def api_extract():
    try:
        ings, raw = parse_request_text()
        return jsonify({"ingredients": ings, "raw": raw[:2000]})
    except Exception as e:
        return jsonify({"error": str(e)}), 400

@app.route("/api/spell", methods=["POST"])  # JSON API for full spell
def api_spell():
    try:
        ings, raw = parse_request_text()
        knowledge: Dict[str, Dict] = {}
        for ing in ings:
            try:
                knowledge[ing] = fetch_knowledge_for_ingredient(ing)
            except Exception as e:
                logger.warning(f"lookup failed for {ing}: {e}")
                knowledge[ing] = {
                    "ingredient": ing,
                    "wikipedia_summary": "",
                    "wikidata_description": "",
                    "adjectives": [],
                    "related": [],
                    "sources": {}
                }
        spell = build_spell(ings, knowledge)
        return jsonify({
            "ingredients": ings,
            "knowledge": knowledge,
            "spell": spell
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 400

