    LOOKUP_CACHE[ing] = data
    return data

# --------- Spell Generation ---------

def make_spell(ingredients: List[str], knowledge: Dict[str, Dict]) -> str:
    if not ingredients:
        return "No ingredients found to weave into a spell."
    lines = [
        "By hearth and hand, a charm is cast:",
        f"Bind {', '.join(ingredients[:5])} with whispered grace,",
    ]
    for ing in ingredients[:6]:
        info = knowledge.get(ing, {})
        adjs = info.get("adjectives", [])
        rel = info.get("related", [])
        bit = ", ".join(adjs[:2] or rel[:2])
        if bit:
            lines.append(f"Let {ing} be {bit}.")
        elif info.get("wikidata_description"):
            lines.append(f"Recall the nature of {ing}: {truncate(info['wikidata_description'], 120)}")
        elif info.get("wikipedia_summary"):
            lines.append(f"Remember {ing}: {truncate(info['wikipedia_summary'], 120)}")
    lines.append("So mote it be.")
    return "\n".join(lines)

