# --------- Spell Generator ---------

def generate_spell(title: str, ingredients: List[str], knowledge: List[Dict]) -> str:
    incantations = [
        "By moonlit measure and ember's glow,",
        "Whisper soft where wild herbs grow,",
        "Stir the stars in simmered night,",
        "Bind the breeze with fragrant light,",
        "From hearth and hand, let wonders flow,",
    ]
    closing = random.choice([
        "So mote it be.",
        "Let taste become enchantment.",
        "The cauldron hums with harmony.",
        "Spirits of flavor, now arise!",
    ])

    ing_lines = []
    for i, ing in enumerate(ingredients, 1):
        k = next((k for k in knowledge if k.get("ingredient") == ing), {})
        adj = ", ".join(k.get("adjectives", [])[:2])
        desc = k.get("wikidata_description") or k.get("wikipedia_summary") or "a curious essence"
        bits = [ing]
        if adj:
            bits.append(f"({adj})")
        ing_lines.append(f"{i}. {" ".join(bits)} — {truncate(desc, 120)}")

    verse = [
        random.choice(incantations),
        f"Take {', '.join(ingredients[:3])}{' and more' if len(ingredients) > 3 else ''},",
        "Fold memory, laughter, and a pinch of patience,",
        "Let warmth awaken every seed of comfort,",
        closing,
    ]

    title = html.escape(title or "Kitchen Charm")
    body = "\n".join(verse)
    listing = "\n".join(ing_lines)

    return f"## {title}\n\n{body}\n\n— Ingredients of Power —\n{listing}"

