    <footer>For entertainment only • PDF support: {'on' if HAS_PDF else 'off'} • Max upload 2MB</footer>
  </div>
</body>
</html>
"""
    resp = make_response(html_doc, status)
    resp.headers['X-Frame-Options'] = 'ALLOWALL'
    resp.headers['Cache-Control'] = 'no-store'
    return resp


def render_form(error: Optional[str] = None):
    err_html = f"<div class=err>{html.escape(error)}</div>" if error else ""
    body = f"""
