    </div>
  </form>
  <div class="hr"></div>
  <div class="small">No data is stored. External lookups have short timeouts.</div>
</div>
"""
    return render_page(body)


def render_result(title: str, spell_md: str, ingredients: List[str], knowledge: List[Dict]):
    # Minimal Markdown to HTML (headers and line breaks)
    safe = html.escape(spell_md)
    safe = re.sub(r"^## (.*)$", r"<h2>\1</h2>", safe, flags=re.M)
    safe = safe.replace("\n\n", "<br><br>").replace("\n", "<br>")

    src_list = []
    for k in knowledge:
        srcs = k.get("sources", {})
        links = []
        if k.get("wikipedia_summary") and srcs.get("wikipedia"):
            links.append(f"<a href=\"{html.escape(srcs['wikipedia'])}\" target=\"_blank\">Wikipedia</a>")
        if srcs.get("wikidata_search"):
            links.append(f"<a href=\"{html.escape(srcs['wikidata_search'])}\" target=\"_blank\">Wikidata</a>")
        if srcs.get("datamuse"):
            links.append(f"<a href=\"{html.escape(srcs['datamuse'])}\" target=\"_blank\">Datamuse</a>")
        if links:
            src_list.append(f"<li><strong>{html.escape(k.get('ingredient',''))}</strong>: " + ", ".join(links) + "</li>")

    sources_html = "<ul>" + "".join(src_list) + "</ul>" if src_list else "<p class=small>No external sources found within timeouts.</p>"

    body = f"""
<div class="card">
  <a href="/embed" class="small">← Back</a>
  <h1 class="h">Your Enchanted Spell</h1>
  <div class="ok">Ingredients parsed: {len(ingredients)} • Title: {html.escape(title or 'Kitchen Charm')}</div>
  <div class="code">{safe}</div>
  <div class="hr"></div>
  <h3 class="h" style="font-size:18px">Sources</h3>
  {sources_html}
</div>
"""
    return render_page(body)

# --------- Routes ---------

@app.route("/")
def index():
    return redirect("/embed")


@app.route("/embed", methods=["GET"])
def embed():
    return render_form()


@app.route("/process", methods=["POST"])
def process():
    try:
        text = (request.form.get("recipe_text") or "").strip()
        file = request.files.get("recipe_file")

        if file and file.filename:
            fname = (file.filename or "").lower()
            data = file.read()
            if not data:
                return render_form("Uploaded file is empty.")
            if fname.endswith(".txt"):
                try:
                    text = data.decode("utf-8", errors="ignore")
                except Exception:
                    text = data.decode("latin-1", errors="ignore")
            elif fname.endswith(".pdf"):
                try:
                    text = extract_text_from_pdf(data)
                except Exception as e:
                    return render_form(f"PDF error: {e}")
            else:
                return render_form("Unsupported file type. Please upload .txt or .pdf.")

        if not text:
            return render_form("Please paste recipe text or upload a .txt/.pdf file.")

        ingredients = extract_ingredients_from_text(text)
        if not ingredients:
            return render_form("Could not detect ingredients. Make sure your recipe lists them clearly (e.g., '- 2 cups flour').")

        title_match = re.search(r"^\s*([\w ,'-]{3,60})\s*$", text.splitlines()[0]) if text.splitlines() else None
        title = title_match.group(1).strip() if title_match else "Kitchen Charm"

        knowledge = [fetch_knowledge_for_ingredient(ing) for ing in ingredients]
        spell = generate_spell(title, ingredients, knowledge)
        return render_result(title, spell, ingredients, knowledge)

    except Exception as e:
        logger.exception("Unhandled error")
        return render_page(f"<div class=err>Unexpected error: {html.escape(str(e))}</div>", status=500)


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000)
```

Below is a complete, runnable Flask app that delivers a working /embed UI for pasting recipe text or uploading .txt/.pdf files, extracts ingredients, fetches playful knowledge from Wikipedia/Wikidata/Datamuse with timeouts and error handling, generates a whimsical spell, and renders clear success/error pages.

How to use:
- Run locally: pip install flask requests PyPDF2 (PyPDF2 is optional; PDFs will show a clear error if not installed)
- Start: python app.py (defaults to port 8000)
- Deploy to a public URL (Render, Railway, Fly.io, Heroku, etc.)
- Embed in Square: paste this exact snippet (replacing the domain with yours)
  <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>

