# --------- Routes ---------

@app.route("/embed", methods=["GET"])
def embed():
    msg = request.args.get("msg")
    err = request.args.get("err")
    note_html = f"<div class='ok'>{html.escape(msg)}</div>" if msg else ""
    err_html = f"<div class='err'>{html.escape(err)}</div>" if err else ""

    form_html = f"""
<h1>Recipe to Spell</h1>
<p class="muted">Paste your recipe text or upload a .txt/.pdf file. We extract ingredients and weave a whimsical spell using public web data. For fun only.</p>
{note_html}{err_html}
<form class="form" action="/process-text" method="post" enctype="application/x-www-form-urlencoded">
  <label for="recipe_text">Paste recipe text</label>
  <textarea id="recipe_text" name="recipe_text" placeholder="Ingredients\n- 2 cups flour\n- 1 tsp salt\n...\n\nInstructions\n..."></textarea>
  <div class="row">
    <button type="submit">Generate spell from text</button>
    <span class="muted small">No data is stored.</span>
  </div>
</form>
<hr />
<form class="form" action="/process-upload" method="post" enctype="multipart/form-data">
  <label for="recipe_file">Or upload a .txt or .pdf (max 2 MB)</label>
  <input id="recipe_file" name="recipe_file" type="file" accept=".txt,application/pdf" />
  <div class="row">
    <button type="submit">Generate spell from file</button>
    <span class="muted small">PDF support requires PyPDF2 on the server.</span>
  </div>
</form>
<p class="muted small">By using this widget you agree to fetch public info from Wikipedia, Wikidata and Datamuse with short timeouts.</p>
"""
    return page("Recipe to Spell — Embed", form_html)


def _process_recipe_text(raw_text: str) -> Dict:
    if not raw_text or not raw_text.strip():
        raise ValueError("Please paste some recipe text.")
    text = raw_text.strip()
    ings = extract_ingredients_from_text(text)
    if not ings:
        raise ValueError("Could not find ingredients. Please check your recipe formatting.")
    knowledge = [fetch_knowledge_for_ingredient(i) for i in ings]
    spell = generate_spell(ings, knowledge)
    if not spell:
        raise RuntimeError("Failed to generate the spell text.")
    return {"ingredients": ings, "knowledge": knowledge, "spell": spell}


@app.route("/process-text", methods=["POST"])
def process_text():
    try:
        recipe_text = request.form.get("recipe_text", "")
        result = _process_recipe_text(recipe_text)
        return render_result(result)
    except ValueError as e:
        return redirect(f"/embed?err={requests.utils.quote(str(e))}")
    except Exception as e:
        logger.exception("/process-text failed")
        return redirect("/embed?err=An%20unexpected%20error%20occurred.%20Please%20try%20again.")


@app.route("/process-upload", methods=["POST"])
def process_upload():
    try:
        f = request.files.get("recipe_file")
        if not f or not f.filename:
            raise ValueError("Please choose a .txt or .pdf file.")
        filename = f.filename.lower()
        data = f.read()
        if not data or len(data) == 0:
            raise ValueError("Uploaded file is empty.")
        if len(data) > app.config["MAX_CONTENT_LENGTH"]:
            raise ValueError("File is too large (max 2 MB).")

        if filename.endswith(".txt"):
            try:
                text = data.decode("utf-8", errors="replace")
            except Exception:
                text = data.decode("latin-1", errors="replace")
        elif filename.endswith(".pdf"):
            try:
                text = extract_text_from_pdf(data)
            except RuntimeError as e:
                raise ValueError(str(e))
        else:
            raise ValueError("Unsupported file type. Please upload .txt or .pdf.")

        result = _process_recipe_text(text)
        return render_result(result)
    except ValueError as e:
        return redirect(f"/embed?err={requests.utils.quote(str(e))}")
    except Exception:
        logger.exception("/process-upload failed")
        return redirect("/embed?err=An%20unexpected%20error%20occurred.%20Please%20try%20again.")


def render_result(result: Dict):
    ings_html = "".join(f"<li>{html.escape(i)}</li>" for i in result["ingredients"]) or "<li>(none)</li>"
    src_html_parts = []
    for k in result["knowledge"]:
        src_html_parts.append(
            f"<li><strong>{html.escape(k['ingredient'])}</strong> — "
            f"<em>{html.escape((k.get('wikidata_description') or '')[:160])}</em> "
            f"<div class='small muted'>"
            f"<a href='{html.escape(k['sources']['wikipedia'])}' target='_blank' rel='noopener'>Wikipedia</a> · "
            f"<a href='{html.escape(k['sources']['wikidata_search'])}' target='_blank' rel='noopener'>Wikidata</a>"
            f"</div></li>"
        )
    sources_list = "".join(src_html_parts) or "<li class='muted'>No sources found.</li>"

    body = f"""
<h1>Your Spell</h1>
<p class="muted">Parsed {len(result['ingredients'])} ingredient(s).</p>
<h3>Ingredients</h3>
<ul>{ings_html}</ul>
<h3>Spell Text</h3>
<pre>{html.escape(result['spell'])}</pre>
<h3>Sources</h3>
<ul>{sources_list}</ul>
<p><a href="/embed">← Try another recipe</a></p>
"""
    return page("Your Spell", body)


@app.errorhandler(413)
def too_large(_e):
    return redirect("/embed?err=File%20too%20large%20(max%202%20MB).")


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    app.run(host="0.0.0.0", port=port, debug=False)
```

Below is a complete, runnable Flask app that renders a compact /embed UI for pasting recipe text or uploading .txt/.pdf files, extracts ingredients, performs public lookups (Wikipedia/Wikidata/Datamuse) with timeouts and error handling, generates a whimsical “spell,” and displays clear success/error pages.

