- In Square Online > Website > Edit site > Add section > Embed code, paste this exact snippet (replace the domain with yours):
  <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>

```python
# app.py
import io
import os
import re
import html
import random
import logging
from typing import List, Dict, Optional

from flask import Flask, request, make_response, redirect
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024  # 2 MB upload limit

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "ingredients", "instructions", "method", "directions", "steps", "preparation",
    "prep", "cook", "cooking", "baking", "notes", "equipment"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}
HTTP_TIMEOUT = 4.0


def normalize_ingredient_line(line: str) -> Optional[str]:
    line = re.sub(r"\([^)]*\)", "", line)
    line = line.strip().lstrip("-•*").strip()
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)

    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if not tokens:
        return None

    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []
    if not cleaned:
        return None

    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]
    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]

    ing = " ".join(cleaned).strip(" ,.;:-").strip()
    pieces = ing.split()
    if len(pieces) > 5:
        ing = " ".join(pieces[-3:])

    ing = re.sub(r"\s+", " ", ing).strip().lower()
    if not ing or len(ing) < 2:
        return None

    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    if len(ing.split()) <= 1 and not ing.isalpha():
        return None

    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None


def extract_ingredients_from_text(text: str, limit: int = 12) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False

    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if (
                not line
                or any(b in low for b in SECTION_BREAKERS if b != "ingredients")
                or re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low)
            ):
                if ingredients_block:
                    break
                else:
                    in_ing = False
                    continue
            ingredients_block.append(line)

    candidates: List[str] = []
    if found_section and ingredients_block:
        for raw in ingredients_block:
            ing = normalize_ingredient_line(raw)
            if ing:
                candidates.append(ing)
    else:
        for raw in lines:
            if not raw:
                continue
            if raw.strip().startswith(("-", "*", "•")) or re.search(r"\d", raw):
                ing = normalize_ingredient_line(raw)
                if ing:
                    candidates.append(ing)

    seen = set()
    deduped: List[str] = []
    for ing in candidates:
        if ing not in seen:
            seen.add(ing)
            deduped.append(ing)
        if len(deduped) >= limit:
            break
    return deduped


def extract_text_from_pdf(file_bytes: bytes) -> str:
    if not HAS_PDF:
        raise RuntimeError("PDF parsing not available on server")
    try:
        reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
        pages_text = []
        for page in reader.pages:
            try:
                pages_text.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(pages_text).strip()
    except Exception as e:
        raise RuntimeError(f"Failed to read PDF: {e}")

# --------- External Knowledge Lookups ---------

def http_get_json(url: str, params: Optional[dict] = None, timeout: float = HTTP_TIMEOUT) -> Optional[dict]:
    try:
        r = requests.get(url, params=params, headers=USER_AGENT, timeout=timeout)
        if r.status_code == 200:
            return r.json()
        else:
            logger.warning(f"GET {url} returned {r.status_code}")
            return None
    except requests.RequestException as e:
        logger.warning(f"GET {url} failed: {e}")
        return None


def truncate(text: str, max_len: int = 300) -> str:
    if not text:
        return ""
    text = re.sub(r"\s+", " ", text).strip()
    return (text[: max_len - 1] + "…") if len(text) > max_len else text


def wiki_summary(term: str) -> Optional[str]:
    safe_title = term.replace(" ", "_")
    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{requests.utils.quote(safe_title)}"
    try:
        r = requests.get(url, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            data = r.json()
            extract = data.get("extract") or ""
            if extract:
                return truncate(extract, 420)
    except requests.RequestException:
        pass

    search_api = "https://en.wikipedia.org/w/api.php"
    sdata = http_get_json(search_api, {
        "action": "opensearch",
        "search": term,
        "limit": 1,
        "namespace": 0,
        "format": "json",
        "redirects": "resolve",
    })
    if sdata and len(sdata) >= 4 and sdata[1]:
        title = sdata[1][0]
        edata = http_get_json(search_api, {
            "action": "query",
            "prop": "extracts",
            "exintro": 1,
            "explaintext": 1,
            "redirects": 1,
            "titles": title,
            "format": "json",
        })
        if edata:
            pages = edata.get("query", {}).get("pages", {})
            for _, p in pages.items():
                ext = p.get("extract")
                if ext:
                    return truncate(ext, 420)
    return None


def wikidata_description(term: str) -> Optional[str]:
    url = "https://www.wikidata.org/w/api.php"
    data = http_get_json(url, {
        "action": "wbsearchentities",
        "language": "en",
        "format": "json",
        "search": term,
        "limit": 1,
    })
    if data and data.get("search"):
        desc = data["search"][0].get("description")
        return truncate(desc, 160) if desc else None
    return None


def datamuse_adjectives(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"rel_jjb": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen:
                    continue
                if lw in {"good", "many", "more", "much", "little", "other"}:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


def datamuse_similar(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"ml": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen or " " in lw:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


LOOKUP_CACHE: Dict[str, Dict] = {}


def fetch_knowledge_for_ingredient(ing: str) -> Dict:
    if ing in LOOKUP_CACHE:
        return LOOKUP_CACHE[ing]

    summary = wiki_summary(ing) or ""
    desc = wikidata_description(ing) or ""
    adjs = datamuse_adjectives(ing, maxn=5)
    related = datamuse_similar(ing, maxn=5)

    data = {
        "ingredient": ing,
        "wikipedia_summary": summary,
        "wikidata_description": desc,
        "adjectives": adjs,
        "related": related,
        "sources": {
            "wikipedia": f"https://en.wikipedia.org/wiki/{requests.utils.quote(ing.replace(' ', '_'))}",
            "wikidata_search": f"https://www.wikidata.org/w/index.php?search={requests.utils.quote(ing)}",
            "datamuse": "https://api.datamuse.com/words"
        }
    }
    LOOKUP_CACHE[ing] = data
    return data

# --------- Spell Generator ---------

FALLBACK_ADJS = ["mystic", "luminous", "ancient", "whispering", "emberlit"]
FALLBACK_VERBS = ["stir", "summon", "invoke", "weave", "conjure"]
FALLBACK_ENDINGS = ["So mote it be.", "Thus the charm is sealed.", "Let the spell be done."]


def build_spell(ingredients: List[str], lore: Dict[str, Dict]) -> str:
    if not ingredients:
        return "Whisper into the empty cauldron; no ingredients, no incantation."

    adj_pool = []
    for ing in ingredients:
        adjs = lore.get(ing, {}).get("adjectives") or []
        adj_pool.extend(adjs)
    if not adj_pool:
        adj_pool = FALLBACK_ADJS[:]

    lines = []
    random.shuffle(adj_pool)
    epithets = ", ".join(adj_pool[:3]) if adj_pool else "mystic"

    lines.append(f"Hear me, {epithets} winds, as I bind this recipe's essence:")

    for ing in ingredients:
        info = lore.get(ing, {})
        hint = info.get("wikipedia_summary") or info.get("wikidata_description") or ""
        hint = truncate(hint, 160)
        verb = random.choice(FALLBACK_VERBS)
        line = f"- {verb.title()} the {ing}"
        if hint:
            line += f", mindful of its lore: {hint}"
        lines.append(line + ".")

    closing = random.choice(FALLBACK_ENDINGS)
    lines.append(closing)
    return "\n".join(lines)

# --------- HTML Rendering ---------

def page(title: str, body: str, status: int = 200):
    html_doc = f"""
    <!doctype html>
    <html lang=\"en\">
    <head>
      <meta charset=\"utf-8\" />
      <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />
      <title>{html.escape(title)}</title>
      <style>
        body {{ font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif; margin: 0; padding: 0; background:#fafafa; color:#222; }}
        .wrap {{ max-width: 720px; margin: 24px auto; padding: 16px; }}
        .card {{ background:#fff; border:1px solid #e5e5e5; border-radius:8px; padding:16px; box-shadow:0 1px 2px rgba(0,0,0,.04); }}
        h1 {{ font-size: 1.25rem; margin: 0 0 12px; }}
        form {{ display:flex; flex-direction:column; gap:12px; }}
        textarea {{ width:100%; min-height:140px; padding:8px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }}
        .row {{ display:flex; gap:12px; align-items:center; flex-wrap:wrap; }}
        .help {{ color:#555; font-size:.9rem; }}
        .error {{ color:#b00020; background:#ffe9ec; border:1px solid #ffccd3; padding:8px; border-radius:6px; }}
        .success {{ background:#f4fff4; border:1px solid #cfe9cf; padding:8px; border-radius:6px; }}
        button {{ background:#111827; color:#fff; border:none; border-radius:6px; padding:10px 14px; cursor:pointer; }}
        code, pre {{ background:#0b1021; color:#e7f0ff; padding:8px; border-radius:6px; overflow:auto; }}
        .meta {{ color:#555; font-size:.9rem; }}
        a {{ color:#0d47a1; }}
      </style>
    </head>
    <body>
      <div class=\"wrap\">
        <div class=\"card\">{body}</div>
      </div>
    </body>
    </html>
    """
    resp = make_response(html_doc, status)
    resp.headers["Content-Security-Policy"] = "default-src 'self' https:; img-src https: data:; style-src 'unsafe-inline' 'self' https:; frame-ancestors *;"
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["Referrer-Policy"] = "no-referrer"
    return resp


# --------- Routes ---------

@app.route("/embed", methods=["GET"])
def embed_form():
    err = request.args.get("error")
    ok = request.args.get("ok")
    msg = ""
    if err:
        msg = f"<div class='error'>{html.escape(err)}</div>"
    elif ok:
        msg = f"<div class='success'>{html.escape(ok)}</div>"

    body = f"""
      <h1>Spell from Recipe</h1>
      <p class='help'>Paste a recipe or upload a .txt/.pdf. We’ll extract ingredients, gather lore, and weave a playful spell.</p>
      {msg}
      <form action='/process' method='post' enctype='multipart/form-data'>
        <label for='recipe_text'><strong>Recipe text</strong> (optional)</label>
        <textarea id='recipe_text' name='recipe_text' placeholder='Ingredients\n- 2 cups flour\n- 1 tsp salt\n...'></textarea>
        <div class='row'>
          <div>
            <label for='recipe_file'><strong>Or upload .txt/.pdf</strong></label>
            <input id='recipe_file' type='file' name='recipe_file' accept='.txt,application/pdf'>
          </div>
          <button type='submit'>Conjure Spell</button>
        </div>
        <div class='help'>Max 2 MB. We only read ingredients to make the spell.</div>
      </form>
    """
    return page("Spell from Recipe", body)


def validate_and_get_text() -> str:
    text = (request.form.get("recipe_text") or "").strip()
    file = request.files.get("recipe_file")

    if not text and (not file or file.filename == ""):
        raise ValueError("Provide recipe text or upload a .txt/.pdf file.")

    if file and file.filename:
        filename = file.filename
        # Basic content-type and extension checks
        allowed_ext = {".txt", ".pdf"}
        ext = os.path.splitext(filename.lower())[1]
        if ext not in allowed_ext:
            raise ValueError("Only .txt or .pdf files are allowed.")
        data = file.read()
        if not data:
            raise ValueError("Uploaded file is empty.")
        if len(data) > app.config["MAX_CONTENT_LENGTH"]:
            raise ValueError("File exceeds 2 MB limit.")
        if ext == ".txt":
            try:
                text_part = data.decode("utf-8", errors="ignore")
            except Exception:
                raise ValueError("Could not read the text file.")
        else:
            try:
                text_part = extract_text_from_pdf(data)
            except RuntimeError as e:
                raise ValueError(str(e))
        text = (text + "\n" + text_part).strip() if text else text_part

    if not text:
        raise ValueError("No usable text found in input.")

    return text


@app.route("/process", methods=["POST"])
def process():
    try:
        text = validate_and_get_text()
    except ValueError as e:
        return redirect(f"/embed?error={requests.utils.quote(str(e))}")

    ings = extract_ingredients_from_text(text, limit=12)
    if not ings:
        return redirect("/embed?error=" + requests.utils.quote("Could not detect ingredients. Please paste a list like '- 2 cups flour'."))

    lore: Dict[str, Dict] = {}
    for ing in ings:
        try:
            lore[ing] = fetch_knowledge_for_ingredient(ing)
        except Exception as e:
            logger.warning(f"lookup failed for {ing}: {e}")
            lore[ing] = {"ingredient": ing, "adjectives": [], "wikipedia_summary": "", "wikidata_description": "", "related": []}

    spell = build_spell(ings, lore)

    items_html = "".join(
        f"<li><strong>{html.escape(ing)}</strong>"
        f"<div class='meta'>{html.escape((lore.get(ing, {}).get('wikidata_description') or lore.get(ing, {}).get('wikipedia_summary') or '')[:180])}</div>"
        f"</li>" for ing in ings
    )

    body = f"""
      <h1>Your Conjured Spell</h1>
      <p class='help'>Based on the detected ingredients:</p>
      <ul>{items_html}</ul>
      <h2>Incantation</h2>
      <pre>{html.escape(spell)}</pre>
      <p><a href='/embed'>Back</a></p>
    """
    return page("Your Spell", body)


@app.errorhandler(413)
def too_big(e):
    return redirect("/embed?error=" + requests.utils.quote("Upload too large (max 2 MB)."))


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    app.run(host="0.0.0.0", port=port, debug=False)
