// C# code (placed in a Python code fence per request) that embeds drawing primitives
// into a nanoCAD McTable cell using the MultiCAD .NET API.
//
// The function below:
//   1) Creates (or recreates) a dedicated block definition for the target cell.
//   2) Converts input geometry to McDbEntity instances and appends them to that block.
//   3) Computes a fitting scale for the block so it fits inside the cell with optional padding.
//   4) Assigns the block reference as the cell's content and commits the transaction.
//
// Notes:
// - This code targets the MultiCAD/nanoCAD .NET API. Class/member names may vary slightly by SDK version.
// - Replace namespace aliases if your SDK uses different ones (e.g., McDbTable/McDbBlockTableRecord, etc.).

using System;
using System.Collections.Generic;
using System.Linq;
using Multicad.ApplicationServices;
using Multicad.DatabaseServices;
using Multicad.Geometry;
using Multicad.Runtime;

namespace YourCompany.YourPlugin
{
    // Abstract input geometry descriptor. Implement ToEntity() to return a valid McDbEntity (e.g., McDbLine, McDbCircle, etc.).
    public abstract class EntityGeometry
    {
        public abstract McDbEntity ToEntity();
    }

    public static class TableCellGeometryEmbedder
    {
        /// <summary>
        /// Embeds drawing primitives (converted from EntityGeometry) into a specified McTable cell
        /// by creating/updating a dedicated block definition and assigning it to the cell.
        /// </summary>
        /// <param name="table">Target McDbTable (must be database resident)</param>
        /// <param name="row">Zero-based row index</param>
        /// <param name="col">Zero-based column index</param>
        /// <param name="entityGeometry">List of geometry descriptors to convert and embed</param>
        /// <param name="padding">Optional padding inside the cell (in drawing units)</param>
        /// <param name="blockNamePrefix">Prefix used to form a unique block name for the cell</param>
        public static void EmbedGeometryIntoCell(
            McDbTable table,
            int row,
            int col,
            IList<EntityGeometry> entityGeometry,
            double padding = 0.0,
            string blockNamePrefix = "_CellGeom_")
        {
            if (table == null) throw new ArgumentNullException(nameof(table));
            if (entityGeometry == null || entityGeometry.Count == 0)
                throw new ArgumentException("entityGeometry must contain at least one item.", nameof(entityGeometry));
            if (row < 0 || row >= table.RowsCount)
                throw new ArgumentOutOfRangeException(nameof(row), "Row index is out of range.");
            if (col < 0 || col >= table.ColumnsCount)
                throw new ArgumentOutOfRangeException(nameof(col), "Column index is out of range.");
            if (padding < 0) throw new ArgumentOutOfRangeException(nameof(padding), "Padding cannot be negative.");

            var db = table.Database;
            if (db == null)
                throw new InvalidOperationException("The table is not database-resident or has no Database reference.");

            using (var tr = db.TransactionManager.StartTransaction())
            {
                // Open BlockTable for write
                var btId = db.BlockTableId;
                var bt = (McDbBlockTable)tr.GetObject(btId, OpenMode.ForRead);

                // Compose a unique block name per cell
                string blockName = $"{blockNamePrefix}{table.Handle}_{row}_{col}";

                // Create or replace block definition
                ObjectId btrId;
                McDbBlockTableRecord btr;

                if (bt.Has(blockName))
                {
                    // Overwrite existing definition: erase and recreate to ensure fresh content
                    bt.UpgradeOpen();
                    btrId = bt[blockName];
                    btr = (McDbBlockTableRecord)tr.GetObject(btrId, OpenMode.ForWrite);

                    // Erase existing entities in the block
                    var toErase = btr.Cast<ObjectId>().ToList();
                    foreach (var entId in toErase)
                    {
                        var ent = (McDbEntity)tr.GetObject(entId, OpenMode.ForWrite);
                        ent.Erase();
                    }
                }
                else
                {
                    bt.UpgradeOpen();
                    btr = new McDbBlockTableRecord { Name = blockName };
                    btrId = bt.Add(btr);
                    tr.AddNewlyCreatedDBObject(btr, true);
                }

                // Convert each EntityGeometry to an McDbEntity and append to block
                Extents3d? aggExt = null;
                foreach (var eg in entityGeometry)
                {
                    if (eg == null) continue;
                    McDbEntity ent = eg.ToEntity();
                    if (ent == null) continue;

                    var entId = btr.AppendEntity(ent);
                    tr.AddNewlyCreatedDBObject(ent, true);

                    try
                    {
                        var ex = ent.GeometricExtents; // Extents3d
                        aggExt = aggExt.HasValue ? UnionExtents(aggExt.Value, ex) : ex;
                    }
                    catch
                    {
                        // Some entities may not have extents until regen; ignore safely
                    }
                }

                // Get target cell dimensions
                double cellWidth = table.GetColumnWidth(col);
                double cellHeight = table.GetRowHeight(row);

                // Compute scale so block fits in cell (with padding)
                double scale = 1.0;
                Point3d basePoint = new Point3d(0, 0, 0);
                if (aggExt.HasValue)
                {
                    var ext = aggExt.Value;
                    double gw = Math.Max(1e-9, ext.MaxPoint.X - ext.MinPoint.X);
                    double gh = Math.Max(1e-9, ext.MaxPoint.Y - ext.MinPoint.Y);

                    double availW = Math.Max(0.0, cellWidth - 2.0 * padding);
                    double availH = Math.Max(0.0, cellHeight - 2.0 * padding);
                    if (availW <= 0 || availH <= 0)
                        throw new InvalidOperationException("Cell size is too small for the specified padding.");

                    double sx = availW / gw;
                    double sy = availH / gh;
                    scale = Math.Min(sx, sy);

                    // Move geometry so its center is at (0,0) in block space for easy centering in the cell
                    Vector3d toOrigin = new Vector3d(
                        -0.5 * (ext.MinPoint.X + ext.MaxPoint.X),
                        -0.5 * (ext.MinPoint.Y + ext.MaxPoint.Y),
                        0.0);

                    var xform = Matrix3d.Displacement(toOrigin);
                    foreach (ObjectId id in btr)
                    {
                        var e = (McDbEntity)tr.GetObject(id, OpenMode.ForWrite);
                        e.TransformBy(xform);
                    }
                }

                // Place or update a block reference as the cell's content
                // We create a single BlockReference anchored at cell center and scaled uniformly.
                Point3d cellOrigin = table.GetCellPosition(row, col); // lower-left corner of the cell
                double cx = cellOrigin.X + cellWidth * 0.5;
                double cy = cellOrigin.Y + cellHeight * 0.5;
                var insertPt = new Point3d(cx, cy, 0.0);

                // Remove previous block ref content from the cell, if any (implementation depends on API)
                // For robustness, clear cell content first.
                table.UpgradeOpen();
                table.ClearCellContent(row, col);

                // Create a new block reference
                var br = new McDbBlockReference(insertPt, btrId)
                {
                    ScaleFactors = new Scale3d(scale),
                    Rotation = 0.0
                };

                // Append block reference to model space (or table's owner space) so it exists in DB
                var msId = db.CurrentSpaceId;
                var ms = (McDbBlockTableRecord)tr.GetObject(msId, OpenMode.ForWrite);
                var brId = ms.AppendEntity(br);
                tr.AddNewlyCreatedDBObject(br, true);

                // Assign the block reference to the cell as embedded content
                table.SetCellBlockReference(row, col, brId);
                table.SetCellContentAlignment(row, col, CellAlignment.MiddleCenter);

                tr.Commit();
            }
        }

        // Helper to union two extents
        private static Extents3d UnionExtents(Extents3d a, Extents3d b)
        {
            var min = new Point3d(Math.Min(a.MinPoint.X, b.MinPoint.X), Math.Min(a.MinPoint.Y, b.MinPoint.Y), Math.Min(a.MinPoint.Z, b.MinPoint.Z));
            var max = new Point3d(Math.Max(a.MaxPoint.X, b.MaxPoint.X), Math.Max(a.MaxPoint.Y, b.MaxPoint.Y), Math.Max(a.MaxPoint.Z, b.MaxPoint.Z));
            return new Extents3d(min, max);
            }
    }
}

public static bool EmbedPrimitivesIntoTableCell(List<EntityGeometry> geometries, McTable table, int row, int col, string blockName)
{
    // Assumes references:
    // using Multicad.DatabaseServices;
    // using Multicad.DatabaseServices.Table;
    // using Multicad.Geometry;
    // using Multicad.Runtime;
    // using System.Collections.Generic;

    // Minimal input validation
    if (geometries == null || geometries.Count == 0) return false;
    if (table == null) return false;
    if (row < 0 || col < 0) return false;
    if (string.IsNullOrWhiteSpace(blockName)) return false;

    try
    {
        var db = HostApplicationServices.WorkingDatabase;
        if (db == null) return false;

        using (var tr = db.TransactionManager.StartTransaction())
        {
            // Open or create BlockTable
            var bt = (BlockTable)tr.GetObject(db.BlockTableId, OpenMode.ForRead);

            // Find or create the block definition
            ObjectId btrId;
            bool blockExists = bt.Has(blockName);
            BlockTableRecord btr;

            if (blockExists)
            {
                // Open existing block definition for write and purge its entities
                btrId = bt[blockName];
                btr = (BlockTableRecord)tr.GetObject(btrId, OpenMode.ForWrite);

                // Erase existing contents
                var toErase = new List<ObjectId>();
                foreach (ObjectId entId in btr)
                    toErase.Add(entId);
                foreach (var id in toErase)
                {
                    var ent = (Entity)tr.GetObject(id, OpenMode.ForWrite, false);
                    if (ent != null && !ent.IsErased) ent.Erase();
                }
            }
            else
            {
                // Create new block definition
                btr = new BlockTableRecord { Name = blockName };
                bt.UpgradeOpen();
                btrId = bt.Add(btr);
                tr.AddNewlyCreatedDBObject(btr, true);
            }

            // Convert input geometries to DB entities and add to block definition
            var newEntIds = new List<ObjectId>();
            Extents3d? accumExt = null;

            foreach (var g in geometries)
            {
                if (g == null) continue;

                Entity dbEnt = null;

                // Map known geometry types to DB entities
                if (g is Line ln)
                {
                    dbEnt = new McDbLine(ln.StartPoint, ln.EndPoint);
                }
                else if (g is Polyline pl)
                {
                    var dbPl = new McDbPolyline();
                    for (int i = 0; i < pl.NumberOfVertices; i++)
                    {
                        var v = pl.GetPointAt(i);
                        dbPl.AddVertexAt(i, v, 0.0, 0.0, 0.0);
                    }
                    dbPl.Closed = pl.Closed;
                    dbEnt = dbPl;
                }
                else if (g is Circle cir)
                {
                    dbEnt = new McDbCircle(cir.Center, Vector3d.ZAxis, cir.Radius);
                }
                else if (g is Arc arc)
                {
                    dbEnt = new McDbArc(arc.Center, arc.Radius, arc.StartAngle, arc.EndAngle);
                }
                else if (g is Text txt)
                {
                    var dbTxt = new McDbText
                    {
                        Position = txt.Position,
                        TextString = txt.Contents,
                        Height = txt.Height > 0 ? txt.Height : 2.5,
                        Rotation = txt.Rotation
                    };
                    dbEnt = dbTxt;
                }
                else
                {
                    // Unsupported geometry type, ignore safely
                    continue;
                }

                if (dbEnt == null) continue;

                dbEnt.SetDatabaseDefaults();
                btr.AppendEntity(dbEnt);
                tr.AddNewlyCreatedDBObject(dbEnt, true);
                newEntIds.Add(dbEnt.ObjectId);

                // Accumulate extents to compute overall bounds of block contents
                try
                {
                    dbEnt.RecordGraphicsModified(true);
                    var ext = dbEnt.GeometricExtents;
                    if (accumExt.HasValue)
                    {
                        var e = accumExt.Value;
                        e.AddExtents(ext);
                        accumExt = e;
                    }
                    else
                    {
                        accumExt = ext;
                    }
                }
                catch
                {
                    // If extents fail, continue; will fallback later
                }
            }

            // If no entities created, fail gracefully
            if (newEntIds.Count == 0)
            {
                tr.Abort();
                return false;
            }

            // Determine content extents (fallback to unit box if unavailable)
            Extents3d contentExt = accumExt ?? new Extents3d(new Point3d(0, 0, 0), new Point3d(1, 1, 0));
            double contentWidth = System.Math.Max(1e-9, contentExt.MaxPoint.X - contentExt.MinPoint.X);
            double contentHeight = System.Math.Max(1e-9, contentExt.MaxPoint.Y - contentExt.MinPoint.Y);
            var contentCenter = new Point3d(
                (contentExt.MinPoint.X + contentExt.MaxPoint.X) * 0.5,
                (contentExt.MinPoint.Y + contentExt.MaxPoint.Y) * 0.5,
                0.0);

            // Get target cell inner rectangle and center
            var cell = table.GetCell(row, col); // assume this returns a McTableCell or throws if OOR
            // Compute inner rectangle considering margins/padding
            var cellRect = table.GetCellExtents(row, col); // assumed extents in WCS of full cell
            double leftMargin = cell.Margins.Left;
            double rightMargin = cell.Margins.Right;
            double topMargin = cell.Margins.Top;
            double bottomMargin = cell.Margins.Bottom;

            // Build inner rectangle as a Box aligned with cell orientation (assume cells are axis-aligned in WCS)
            double innerMinX = cellRect.MinPoint.X + leftMargin;
            double innerMaxX = cellRect.MaxPoint.X - rightMargin;
            double innerMinY = cellRect.MinPoint.Y + bottomMargin;
            double innerMaxY = cellRect.MaxPoint.Y - topMargin;

            // Guard against negative inner size
            if (innerMaxX <= innerMinX || innerMaxY <= innerMinY)
            {
                tr.Abort();
                return false;
            }

            double innerWidth = innerMaxX - innerMinX;
            double innerHeight = innerMaxY - innerMinY;

            // Compute uniform scale to fit content into inner rectangle while preserving aspect ratio
            double sx = innerWidth / contentWidth;
            double sy = innerHeight / contentHeight;
            double scale = System.Math.Min(sx, sy);

            // Compute insertion point to center content within the inner rectangle
            var innerCenter = new Point3d((innerMinX + innerMaxX) * 0.5, (innerMinY + innerMaxY) * 0.5, 0.0);

            // Create block reference; transform so that contentCenter maps to innerCenter at computed scale
            var br = new McDbBlockReference
            {
                BlockTableRecord = btrId,
                Position = innerCenter
            };

            // Build transform: T = Translate(innerCenter) * Scale(scale) * Translate(-contentCenter)
            // Many APIs expose TransformBy; apply in correct order.
            var toOrigin = Matrix3d.Displacement((Point3d.Origin - contentCenter).GetAsVector());
            var scaleAtOrigin = Matrix3d.Scaling(scale, Point3d.Origin);
            var toCellCenter = Matrix3d.Displacement((innerCenter - Point3d.Origin).GetAsVector());
            var xform = toOrigin.PreMultiplyBy(scaleAtOrigin).PreMultiplyBy(toCellCenter);
            br.TransformBy(xform);

            // Place block reference into ModelSpace (or the table's owner space if required)
            // For simplicity, insert into the same space that owns the table
            var tableOwner = (BlockTableRecord)tr.GetObject(table.OwnerId, OpenMode.ForWrite);
            tableOwner.AppendEntity(br);
            tr.AddNewlyCreatedDBObject(br, true);

            // Assign the block reference to the table cell
            // Assuming API supports setting a block reference handle or id to the cell content.
            // Clear any existing cell content first if needed.
            table.SetCellContent(row, col, TableCellContentType.Block);
            table.SetCellBlock(row, col, br.ObjectId, scale, 0.0); // rotation 0, scale already baked; still provide for API

            // Finalize
            tr.Commit();
            return true;
        }
    }
    catch (System.Exception ex)
    {
        // Log or comment error as required by the host environment
        // Example: System.Diagnostics.Debug.WriteLine($"EmbedPrimitivesIntoTableCell failed: {ex}");
        return false;
    }
}

