public static bool CreateOrUpdateBlockAndPlaceInTableCell(
    Multicad.DatabaseServices.Tables.McTable table,
    int row,
    int col,
    System.Collections.Generic.List<EntityGeometry> geometries,
    string blockName)
{
    // Concrete geometry contracts as requested by the user
    // (Assumes these are defined elsewhere in your project)
    // public enum GeometryType { Line, Polyline, Circle, Arc, Text }
    // public struct EntityGeometry {
    //     public GeometryType Type;
    //     public Multicad.Geometry.McPt3d Start, End;                          // Line
    //     public System.Collections.Generic.List<Multicad.Geometry.McPt3d> Vertices; // Polyline
    //     public bool Closed;                                                  // Polyline
    //     public Multicad.Geometry.McPt3d Center; public double Radius;        // Circle/Arc
    //     public double StartAngle, EndAngle;                                  // Arc (radians)
    //     public Multicad.Geometry.McPt3d Position; public string Value;       // Text
    //     public double Height; public double Rotation;                         // Text
    // }

    // Namespaces used:
    // using Multicad;
    // using Multicad.DatabaseServices;
    // using Multicad.DatabaseServices.Tables;
    // using Multicad.Geometry;
    // using Multicad.ApplicationServices;
    // using Teigha.DatabaseServices;

    // Minimal input validation
    if (table == null) return false;
    if (row < 0 || col < 0 || row >= table.RowsCount || col >= table.ColsCount) return false;
    if (geometries == null || geometries.Count == 0) return false;
    if (string.IsNullOrWhiteSpace(blockName)) return false;

    // Acquire current document and database
    var doc = Multicad.ApplicationServices.McDocumentsManager.GetActiveDocument();
    if (doc == null) return false;
    var db = doc.Database;
    if (db == null) return false;

    Teigha.DatabaseServices.Transaction tr = null;
    try
    {
        // Start a DB transaction
        tr = db.TransactionManager.StartTransaction();

        // Helper to get or create block definition
        Multicad.DatabaseServices.McDbBlockTable bt =
            (Multicad.DatabaseServices.McDbBlockTable)tr.GetObject(db.BlockTableId, Teigha.DatabaseServices.OpenMode.ForRead);

        Multicad.DatabaseServices.McObjectId btrId = Multicad.DatabaseServices.McObjectId.Null;
        if (bt.Has(blockName))
        {
            btrId = bt.GetAt(blockName);
        }
        else
        {
            bt.UpgradeOpen();
            var newBtr = new Multicad.DatabaseServices.McDbBlockTableRecord
            {
                Name = blockName
            };
            btrId = db.AddToModelSpace(newBtr); // Fallback if helper not available
            // Prefer: db.AddObject(newBtr) or bt.Add(newBtr) depending on actual API
            // Ensure added to BlockTable
            if (!bt.Has(blockName))
            {
                bt.Add(newBtr);
            }
        }

        var btr = (Multicad.DatabaseServices.McDbBlockTableRecord)tr.GetObject(btrId, Teigha.DatabaseServices.OpenMode.ForWrite);

        // Clear existing entities from block definition (update scenario)
        {
            var idsToErase = new System.Collections.Generic.List<Multicad.DatabaseServices.McObjectId>();
            foreach (var id in btr)
                idsToErase.Add(id);
            foreach (var id in idsToErase)
            {
                var ent = (Multicad.DatabaseServices.McDbEntity)tr.GetObject(id, Teigha.DatabaseServices.OpenMode.ForWrite, false);
                if (ent != null) ent.Erase();
            }
        }

        // Build entities from geometries and collect extents
        bool hasExtent = false;
        Multicad.Geometry.McExtents3d contentExt = new Multicad.Geometry.McExtents3d();
        var createdIds = new System.Collections.Generic.List<Multicad.DatabaseServices.McObjectId>();

        foreach (var g in geometries)
        {
            Multicad.DatabaseServices.McDbEntity ent = null;
            switch (g.Type)
            {
                case GeometryType.Line:
                {
                    var ln = new Multicad.DatabaseServices.McDbLine
                    {
                        StartPoint = g.Start,
                        EndPoint = g.End
                    };
                    ent = ln;
                    break;
                }
                case GeometryType.Polyline:
                {
                    var pl = new Multicad.DatabaseServices.McDbPolyline();
                    if (g.Vertices != null && g.Vertices.Count > 0)
                    {
                        foreach (var v in g.Vertices)
                            pl.AddVertexAt(pl.NumberOfVertices, v, 0.0, 0.0, 0.0);
                    }
                    pl.Closed = g.Closed;
                    ent = pl;
                    break;
                }
                case GeometryType.Circle:
                {
                    var c = new Multicad.DatabaseServices.McDbCircle
                    {
                        Center = g.Center,
                        Radius = g.Radius
                    };
                    ent = c;
                    break;
                }
                case GeometryType.Arc:
                {
                    var a = new Multicad.DatabaseServices.McDbArc
                    {
                        Center = g.Center,
                        Radius = g.Radius,
                        StartAngle = g.StartAngle,
                        EndAngle = g.EndAngle
                    };
                    ent = a;
                    break;
                }
                case GeometryType.Text:
                {
                    var t = new Multicad.DatabaseServices.McDbText
                    {
                        Position = g.Position,
                        TextString = g.Value ?? string.Empty,
                        Height = g.Height > 0 ? g.Height : 2.5,
                        Rotation = g.Rotation
                    };
                    ent = t;
                    break;
                }
                default:
                    continue;
            }

            if (ent == null) continue;

            // Add entity to block definition
            var id = btr.AppendEntity(ent);
            tr.AddNewlyCreatedDBObject(ent, true);
            createdIds.Add(id);

            // Accumulate extents
            try
            {
                var ext = ent.GeometricExtents;
                if (!hasExtent)
                {
                    contentExt = ext;
                    hasExtent = true;
                }
                else
                {
                    contentExt.AddExtents(ext);
                }
            }
            catch { /* some entities may lack extents until regen; ignore */ }
        }

        if (createdIds.Count == 0)
        {
            tr.Abort();
            return false;
        }

        // Compute transform to normalize block content around origin and fit into unit square temporarily
        // We'll center content at (0,0), then scale uniformly later to cell size
        Multicad.Geometry.McPt3d min = hasExtent ? contentExt.MinPoint : new Multicad.Geometry.McPt3d(0, 0, 0);
        Multicad.Geometry.McPt3d max = hasExtent ? contentExt.MaxPoint : new Multicad.Geometry.McPt3d(1, 1, 0);
        double w = System.Math.Max(1e-9, max.X - min.X);
        double h = System.Math.Max(1e-9, max.Y - min.Y);
        var center = new Multicad.Geometry.McPt3d((min.X + max.X) * 0.5, (min.Y + max.Y) * 0.5, (min.Z + max.Z) * 0.5);

        // Move content so its center is at origin
        var toOrigin = Multicad.Geometry.McGeMatrix3d.Displacement(new Multicad.Geometry.McVector3d(-center.X, -center.Y, -center.Z));
        foreach (var id in createdIds)
        {
            var e = (Multicad.DatabaseServices.McDbEntity)tr.GetObject(id, Teigha.DatabaseServices.OpenMode.ForWrite, false);
            if (e != null) e.TransformBy(toOrigin);
        }

        // Ensure table cell exists and get its extents in WCS
        if (!table.IsCellValid(row, col))
        {
            tr.Abort();
            return false;
        }

        // Get cell rectangle (WCS). API may provide GetCellExtents, otherwise compute by corners.
        Multicad.Geometry.McExtents3d cellExt;
        {
            var p1 = table.GetCellPoint(row, col, Multicad.DatabaseServices.Tables.CellCorner.BottomLeft);
            var p2 = table.GetCellPoint(row, col, Multicad.DatabaseServices.Tables.CellCorner.TopRight);
            var minC = new Multicad.Geometry.McPt3d(System.Math.Min(p1.X, p2.X), System.Math.Min(p1.Y, p2.Y), 0);
            var maxC = new Multicad.Geometry.McPt3d(System.Math.Max(p1.X, p2.X), System.Math.Max(p1.Y, p2.Y), 0);
            cellExt = new Multicad.Geometry.McExtents3d(minC, maxC);
        }

        double cellW = System.Math.Max(1e-9, cellExt.MaxPoint.X - cellExt.MinPoint.X);
        double cellH = System.Math.Max(1e-9, cellExt.MaxPoint.Y - cellExt.MinPoint.Y);

        // Compute uniform scale to fit block content into cell with margin
        const double marginFactor = 0.9; // 10% margin inside the cell
        double sx = (cellW * marginFactor) / w;
        double sy = (cellH * marginFactor) / h;
        double uniScale = System.Math.Min(sx, sy);
        var scaleM = Multicad.Geometry.McGeMatrix3d.Scaling(uniScale, Multicad.Geometry.McPt3d.Origin);

        foreach (var id in createdIds)
        {
            var e = (Multicad.DatabaseServices.McDbEntity)tr.GetObject(id, Teigha.DatabaseServices.OpenMode.ForWrite, false);
            if (e != null) e.TransformBy(scaleM);
        }

        // Insert or replace block reference in the target cell
        // Remove previous content if present
        var prevContentId = table.GetCellContentId(row, col);
        if (!prevContentId.IsNull)
        {
            var prevEnt = tr.GetObject(prevContentId, Teigha.DatabaseServices.OpenMode.ForWrite, false) as Multicad.DatabaseServices.McDbEntity;
            if (prevEnt != null) prevEnt.Erase();
            table.ClearCellContent(row, col);
        }

        // Create block reference at the cell center
        var cellCenter = new Multicad.Geometry.McPt3d(
            (cellExt.MinPoint.X + cellExt.MaxPoint.X) * 0.5,
            (cellExt.MinPoint.Y + cellExt.MaxPoint.Y) * 0.5,
            0.0);

        var br = new Multicad.DatabaseServices.McDbBlockRef
        {
            BlockTableRecord = btrId,
            Position = cellCenter,
            ScaleFactors = new Multicad.Geometry.McScale3d(1.0, 1.0, 1.0),
            Rotation = 0.0
        };

        // Add reference to model space (or table's parent space)
        var ms =
            (Multicad.DatabaseServices.McDbBlockTableRecord)tr.GetObject(db.CurrentSpaceId, Teigha.DatabaseServices.OpenMode.ForWrite);
        var brId = ms.AppendEntity(br);
        tr.AddNewlyCreatedDBObject(br, true);

        // Assign reference to cell so the table manages/display it inside the cell
        table.SetCellContent(row, col, brId);

        // Additional fine centering is not required since we normalized to origin and place ref at cell center

        tr.Commit();
        return true;
    }
    catch
    {
        if (tr != null && tr.Status == Teigha.DatabaseServices.TransactionStatus.Started)
            tr.Abort();
        return false;
    }
