colMissH= input.color(color.new(color.fuchsia, 0), "Missed Pivot High Line Color", group=groupStyle)
colMissL= input.color(color.new(color.aqua, 0), "Missed Pivot Low Line Color", group=groupStyle)
lineStyleH = input.string("Solid", "Missed High Line Style", options=["Solid","Dashed","Dotted"], group=groupStyle)
lineStyleL = input.string("Dashed", "Missed Low Line Style", options=["Solid","Dashed","Dotted"], group=groupStyle)
lineW = input.int(2, "Missed Pivot Line Width", minval=1, maxval=4, group=groupStyle)
shapeSz = input.string("Small", "Regular Pivot Shape Size", options=["Tiny","Small","Normal","Large"], group=groupStyle)

groupTF = "Labeling"
labelTF = input.string("", "Optional timeframe label text (for display only)", tooltip="Purely shown in alert/labels. Does not call security().", group=groupTF)

//========================
// Utilities
//========================
f_line_style(s) =>
    s == "Solid" ? line.style_solid : s == "Dotted" ? line.style_dotted : line.style_dashed

f_shape_size(s) =>
    s == "Tiny" ? size.tiny : s == "Small" ? size.small : s == "Large" ? size.large : size.normal

// Build message helper
f_msg(_type, _price) =>
    sy = syminfo.ticker
    tf = (labelTF == "" ? timeframe.period : labelTF)
    // Include both bar_index and time for clarity
    str.format("{0} | {1} | {2} | price={3} | bar_index={4} | time={5}", sy, tf, _type, tostring(_price, format.mintick), str.tostring(bar_index), str.tostring(time, format=time.format_iso8601))

//========================
// Pivot Detection (confirmed pivots)
//========================
ph = ta.pivothigh(high, phLeft, phRight)  // returns high price at pivot bar when confirmed, else na
pl = ta.pivotlow(low,  plLeft, plRight)

isPhConfirmed = not na(ph)
isPlConfirmed = not na(pl)

// Index of the pivot bar (confirmed at current bar, pivot occurred phRight/plRight bars ago)
phBarIndex = isPhConfirmed ? bar_index - phRight : na
plBarIndex = isPlConfirmed ? bar_index - plRight : na

//========================
/*
Touch logic:
- We consider bars AFTER the pivot is confirmed (current bar), up to N bars later.
- A pivot high is "touched" if:
  - useCloseForTouch: close >= pivotHighPrice
  - else: high >= pivotHighPrice
- A pivot low is "touched" if:
  - useCloseForTouch: close <= pivotLowPrice
  - else: low <= pivotLowPrice
If not touched for N bars, it becomes "missed".
We don't scan full history each bar; we keep active trackers for pending pivots.
*/
//========================

// Trackers for pending (recent) pivots awaiting touch within N bars
var int[]    pendDir      = array.new_int()     // +1 for high, -1 for low
var float[]  pendPrice    = array.new_float()
var int[]    pendStartBar = array.new_int()     // confirmation bar_index
var int[]    pendDeadline = array.new_int()     // last bar_index allowed (start + N)
var label[]  pendWarnLbl  = array.new_label()   // optional small markers for regular confirmations

// Storage for missed pivot lines/labels
var line[]   missLines    = array.new_line()
var label[]  missLabels   = array.new_label()
var int[]    missDir      = array.new_int()     // +1 high, -1 low

//========================
// Handle new confirmed pivots
//========================

// Add new pending pivot when confirmed
if isPhConfirmed
    price = ph
    // Optional visual for regular pivot
    if showRegular
        plotshape(isPhConfirmed, title="Pivot High", style=shape.triangledown, location=location.abovebar, offset=-phRight, color=colPH, size=f_shape_size(shapeSz))
    // Add to pending trackers
    array.push(pendDir, 1)
    array.push(pendPrice, price)
    array.push(pendStartBar, bar_index)                    // confirmation happens now
    array.push(pendDeadline, bar_index + lookN)
    // optional small warn
    regLbl = na
    if showRegWarn
        regLbl := label.new(bar_index, high, "Pivot High confirmed", style=label.style_label_down, color=color.new(colPH, 70), textcolor=color.white, size=size.tiny)
    array.push(pendWarnLbl, regLbl)

if isPlConfirmed
    price = pl
    if showRegular
        plotshape(isPlConfirmed, title="Pivot Low", style=shape.triangleup, location=location.belowbar, offset=-plRight, color=colPL, size=f_shape_size(shapeSz))
    array.push(pendDir, -1)
    array.push(pendPrice, price)
    array.push(pendStartBar, bar_index)
    array.push(pendDeadline, bar_index + lookN)
    regLbl = na
    if showRegWarn
        regLbl := label.new(bar_index, low, "Pivot Low confirmed", style=label.style_label_up, color=color.new(colPL, 70), textcolor=color.white, size=size.tiny)
    array.push(pendWarnLbl, regLbl)

// Alerts for regular confirmation (trigger immediately on confirmation bar)
if alertOnRegHigh and isPhConfirmed
    alert(f_msg("Regular Pivot HIGH confirmed", ph), alert.freq_once_per_bar)
if alertOnRegLow and isPlConfirmed
    alert(f_msg("Regular Pivot LOW confirmed", pl), alert.freq_once_per_bar)

//========================
// Evaluate pending pivots for touch/miss each bar
//========================
f_is_touched(_dir, _price) =>
    // dir +1 (high): look for >=; dir -1 (low): look for <=
    if _dir == 1
        useCloseForTouch ? (close >= _price) : (high >= _price)
    else
        useCloseForTouch ? (close <= _price) : (low <= _price)

// We'll iterate only active pending list (typically small), prune as we go
pendCount = array.size(pendDir)
i = 0
while i < pendCount
    dir  = array.get(pendDir, i)
    p    = array.get(pendPrice, i)
    sBar = array.get(pendStartBar, i)
    dBar = array.get(pendDeadline, i)
    wLbl = array.get(pendWarnLbl, i)

    // If touched at or after confirmation and before deadline, remove tracker
    touched = f_is_touched(dir, p)
    isExpired = bar_index >= dBar

    // If touched before deadline, clean up tracker
    if touched and not isExpired
        // Remove optional warn label
        if not na(wLbl)
            label.delete(wLbl)
        // Remove arrays at i
        array.remove(pendDir, i)
        array.remove(pendPrice, i)
        array.remove(pendStartBar, i)
        array.remove(pendDeadline, i)
        array.remove(pendWarnLbl, i)
        pendCount -= 1
        // do not increment i (shifted)
    else
        // If not touched and deadline passed on this bar => missed
        if isExpired and not touched
            // Create missed object
            if showMissed
                lnColor = dir == 1 ? colMissH : colMissL
                lnStyle = dir == 1 ? f_line_style(lineStyleH) : f_line_style(lineStyleL)
                // horizontal line from start to future (extend right)
                ln = line.new(x1=sBar, y1=p, x2=bar_index, y2=p, extend=extend.right, color=lnColor, width=lineW, style=lnStyle)
                // label warning
                if showMissWarn
                    lblTxt = dir == 1 ? "MISSED Pivot HIGH" : "MISSED Pivot LOW"
                    lblCol = dir == 1 ? color.new(colMissH, 0) : color.new(colMissL, 0)
                    txtCol = color.white
                    yLoc   = dir == 1 ? high : low
                    warnLbl = label.new(bar_index, yLoc, lblTxt, style=(dir==1?label.style_label_down:label.style_label_up), color=color.new(lblCol, 0), textcolor=txtCol, size=size.tiny)
                    // Also drop a small label at price line
                    _ = label.new(bar_index, p, str.format("{0}\n{1}", lblTxt, tostring(p, format.mintick)), style=label.style_label_left, color=color.new(lblCol, 70), textcolor=txtCol, size=size.tiny)
                // store for persistence and pruning
                array.push(missLines, ln)
                array.push(missLabels, na)  // reserved if you want to add a persistent label later
                array.push(missDir, dir)
                // prune if exceeding maxKeep
                while array.size(missLines) > maxKeep
                    oldL = array.shift(missLines)
                    if not na(oldL)
                        line.delete(oldL)
                    _oldLab = array.size(missLabels) > 0 ? array.shift(missLabels) : na
                    if not na(_oldLab)
                        label.delete(_oldLab)
                    _ = array.size(missDir) > 0 ? array.shift(missDir) : na
            // Alerts for missed
            if (dir == 1 and alertOnMissHigh) or (dir == -1 and alertOnMissLow)
                aType = dir == 1 ? "MISSED Pivot HIGH" : "MISSED Pivot LOW"
                alert(f_msg(aType, p), alert.freq_once_per_bar)

            // cleanup tracker
            if not na(wLbl)
                label.delete(wLbl)
            array.remove(pendDir, i)
            array.remove(pendPrice, i)
            array.remove(pendStartBar, i)
            array.remove(pendDeadline, i)
            array.remove(pendWarnLbl, i)
            pendCount -= 1
            // do not increment i
        else
            // still pending and not expired and not touched
            i += 1

//========================
// alertcondition() declarations (required for setting alert rules)
// These conditions will be true only on bars where events happen.
//========================
missHighCond = false
missLowCond  = false
regHighCond  = false
regLowCond   = false

// We reconstruct them using runtime states from this bar:
// Regular confirmations are true at the bar that confirms (current bar when isPhConfirmed/isPlConfirmed)
regHighCond := isPhConfirmed
regLowCond  := isPlConfirmed

// Missed conditions: a missed event happens when a pending pivot expires this bar without touch.
// To capture, we recompute simple local flags:
var bool _missH_evt = false
var bool _missL_evt = false
_missH_evt := false
_missL_evt := false

// We detect expirations by checking bars where bar_index == some deadline and not touched
// Efficiently, check through current pending (before loop adjustments would have removed them).
// For safety, run a lightweight pass without modifying arrays (use indices snapshot).
pendCount2 = array.size(pendDir)
for j = 0 to pendCount2 - 1
    d  = array.get(pendDir, j)
    pr = array.get(pendPrice, j)
    dl = array.get(pendDeadline, j)
    if bar_index >= dl
        // On/after deadline; if touched already, earlier code would have removed; treat as missed for condition
        touchedNow = f_is_touched(d, pr)
        if not touchedNow
            if d == 1
                _missH_evt := true
            else
                _missL_evt := true

missHighCond := _missH_evt
missLowCond  := _missL_evt

// Create alertcondition declarations
alertcondition(alertOnMissHigh ? missHighCond : false, title="Missed Pivot HIGH", message=f_msg("MISSED Pivot HIGH", na))
alertcondition(alertOnMissLow  ? missLowCond  : false, title="Missed Pivot LOW",  message=f_msg("MISSED Pivot LOW",  na))
alertcondition(alertOnRegHigh  ? regHighCond  : false, title="Regular Pivot HIGH Confirmed", message=f_msg("Regular Pivot HIGH confirmed", na))
alertcondition(alertOnRegLow   ? regLowCond   : false, title="Regular Pivot LOW Confirmed",  message=f_msg("Regular Pivot LOW confirmed",  na))

//========================
// Optional: small legend
//========================
var label legend = na
if barstate.islast
    // Remove and redraw to keep on top
    if not na(legend)
        label.delete(legend)
    legendTxt = "Pivots: " + str.format("PH L/R={0}/{1}, PL L/R={2}/{3}", phLeft, phRight, plLeft, plRight) + "\n" +
        str.format("N={0}, Touch={1}", lookN, (useCloseForTouch ? "Close" : "High/Low")) + "\n" +
        (labelTF == "" ? "" : str.format("TF tag: {0}", labelTF))
    legend := label.new(bar_index, na, legendTxt, xloc=xloc.bar_index, yloc=yloc.price, style=label.style_label_right, textcolor=color.white, color=color.new(color.black, 70))
    label.set_y(legend, valuewhen(barstate.islast, high, 0) + (ta.atr(14) * 0.8))

//========================
// Notes:
// - No security() calls used.
// - Uses arrays to manage pending/missed pivots, avoids full-history loops each bar.
// - Lines are pruned to respect max_keep.
// - Alert messages include symbol, tf label, pivot type, price, bar_index, and time.
//========================

//@version=5
indicator("Regular Pivots with Missed-Pivot Alerts (v5)", overlay=true, timeframe="", timeframe_gaps=true)

//---------------------------
// Inputs
//---------------------------
src          = input.source(close, "Source for Pivots")
leftBars     = input.int(5, "Left bars", minval=1)
rightBars    = input.int(5, "Right bars", minval=1)
lookaheadN   = input.int(50, "Lookahead bars for 'missed' test", minval=1)

enableConfirmHigh = input.bool(true,  "Alert on pivot HIGH confirmation")
enableConfirmLow  = input.bool(true,  "Alert on pivot LOW confirmation")
enableMissHigh    = input.bool(true,  "Alert on MISSED pivot HIGH")
enableMissLow     = input.bool(true,  "Alert on MISSED pivot LOW")

colHighPivot  = input.color(color.new(color.red, 0), "Color: Pivot High")
colLowPivot   = input.color(color.new(color.lime, 0), "Color: Pivot Low")
colMissMark   = input.color(color.new(color.orange, 0), "Color: Missed-Pivot Mark (cross)")

plotMissCross = input.bool(true, "Plot cross at missed-pivot finalization")

//---------------------------
// Helpers
//---------------------------
// Check if price touched a level between two bar indexes (inclusive)
f_touched_between(_level, _fromIndex, _toIndex) =>
    var bool touched = false
    touched := false
    startI  = math.min(_fromIndex, _toIndex)
    endI    = math.max(_fromIndex, _toIndex)
    // Iterate across the historical region; only runs once per bar for at most N bars so acceptable
    for i = startI to endI
        // Guard: bar_index - i must be >= 0; using history references directly with i as index offset
        // We'll check using series[] form relative to current bar. i bars ago is [i].
        if not na(high[i]) and not na(low[i])
            if (low[i] <= _level and high[i] >= _level)
                touched := true
                break
    touched

//---------------------------
// Pivot calculations
//---------------------------
// Using built-in pivot functions on chosen source
ph = ta.pivothigh(src, leftBars, rightBars)  // returns price at pivot or na. Confirmed at bar index: bar_index - rightBars
pl = ta.pivotlow(src,  leftBars, rightBars)

phConfirmed = not na(ph)
plConfirmed = not na(pl)

// Bar index and time helpers
curIndex = bar_index

//---------------------------
// Data structures to track pending "missed" pivots
// Each entry holds: price (float), confirmIndex (int), deadlineIndex (int), isHigh (bool), finalized (bool)
// We'll use parallel arrays
//---------------------------
var array<float> aPrice     = array.new<float>()
var array<int>   aConfIdx   = array.new<int>()
var array<int>   aDeadIdx   = array.new<int>()
var array<bool>  aIsHigh    = array.new<bool>()
var array<bool>  aFinalized = array.new<bool>()  // to ensure single-shot finalization

// Store bar_index of finalized "missed" for plotting cross this bar
var int lastMissPlotIndexHigh = na
var int lastMissPlotIndexLow  = na

//---------------------------
// On pivot confirmation, enqueue a pending record
// The pivot is confirmed on the current bar; its confirm bar index is (curIndex - rightBars)
// The missed deadline occurs at confirmIndex + lookaheadN
//---------------------------
if phConfirmed
    confirmIndexHigh = curIndex - rightBars
    priceHigh        = ph
    deadlineHigh     = confirmIndexHigh + lookaheadN
    array.push(aPrice,     priceHigh)
    array.push(aConfIdx,   confirmIndexHigh)
    array.push(aDeadIdx,   deadlineHigh)
    array.push(aIsHigh,    true)
    array.push(aFinalized, false)

if plConfirmed
    confirmIndexLow = curIndex - rightBars
    priceLow        = pl
    deadlineLow     = confirmIndexLow + lookaheadN
    array.push(aPrice,     priceLow)
    array.push(aConfIdx,   confirmIndexLow)
    array.push(aDeadIdx,   deadlineLow)
    array.push(aIsHigh,    false)
    array.push(aFinalized, false)

//---------------------------
// Evaluate pending records: detect touch or finalize as missed at deadline
// We only need to check for new touches across bars added since last check; to keep logic simple and robust,
// we will deem a pivot "touched" if, by the time we reach (deadline), no bar's range touched the pivot level
// after its confirmation bar. If any bar in [confirmIndex+1 ... current bar] touches, it's not missed.
// When current bar index equals deadline and still untouched, it becomes a missed pivot now.
//---------------------------
for i = array.size(aPrice) - 1 to 0
    if i >= 0
        price_i   = array.get(aPrice, i)
        conf_i    = array.get(aConfIdx, i)
        dead_i    = array.get(aDeadIdx, i)
        isHigh_i  = array.get(aIsHigh, i)
        fin_i     = array.get(aFinalized, i)

        // Compute if touched between the first bar AFTER confirmation up to the min(current, deadline)
        // We use [k] historical indexing relative to the current bar.
        // Range: barsAgoFrom = curIndex - (min(curIndex, dead_i)), barsAgoTo = curIndex - (conf_i + 1)
        // Only when these are >= 0 (bars available).
        if not fin_i
            windowEndIndex   = math.min(curIndex, dead_i)
            fromIdx          = conf_i + 1
            toIdx            = windowEndIndex
            touched = false
            // Ensure we only attempt when fromIdx <= toIdx and both within available history
            if toIdx >= fromIdx
                // Convert absolute bar_index to bars-ago for the loop
                // from bars-ago = curIndex - toIdx down to curIndex - fromIdx
                barsAgoStart = curIndex - toIdx
                barsAgoEnd   = curIndex - fromIdx
                // Sanity clamp
                barsAgoStart := math.max(barsAgoStart, 0)
                barsAgoEnd   := math.max(barsAgoEnd, 0)
                // Iterate recent window for touch
                for b = barsAgoStart to barsAgoEnd
                    if not na(high[b]) and not na(low[b])
                        if (low[b] <= price_i and high[b] >= price_i)
                            touched := true
                            break

            // If touched anytime prior to deadline, discard this record
            if touched
                // Remove record (swap with last for O(1) deletion)
                // To preserve order we can simply remove at i
                array.remove(aPrice,     i)
                array.remove(aConfIdx,   i)
                array.remove(aDeadIdx,   i)
                array.remove(aIsHigh,    i)
                array.remove(aFinalized, i)
            else
                // Not touched yet. If we have reached the deadline this bar, finalize as missed.
                if curIndex >= dead_i
                    // Mark as finalized and trigger one-shot alert + cross marker
                    array.set(aFinalized, i, true)
                    if isHigh_i
                        lastMissPlotIndexHigh := curIndex
                    else
                        lastMissPlotIndexLow  := curIndex
                    // After finalizing and marking, we can safely remove it to keep arrays small
                    array.remove(aPrice,     i)
                    array.remove(aConfIdx,   i)
                    array.remove(aDeadIdx,   i)
                    array.remove(aIsHigh,    i)
                    array.remove(aFinalized, i)

//---------------------------
// Plotting pivots
// Plot shapes at the confirmation bar location using offset = -rightBars
//---------------------------
plotshape(phConfirmed, title="Pivot High", style=shape.triangledown, location=location.abovebar, color=colHighPivot, size=size.tiny, offset=-rightBars, text="PH")
plotshape(plConfirmed, title="Pivot Low",  style=shape.triangleup,   location=location.belowbar, color=colLowPivot,  size=size.tiny, offset=-rightBars, text="PL")

// Plot a small cross on the bar where a missed pivot is finalized (current bar)
plotshape(plotMissCross and (lastMissPlotIndexHigh == curIndex), title="Missed Pivot High Mark", style=shape.cross, location=location.abovebar, color=colMissMark, size=size.tiny, text="Miss PH")
plotshape(plotMissCross and (lastMissPlotIndexLow  == curIndex), title="Missed Pivot Low Mark",  style=shape.cross, location=location.belowbar, color=colMissMark, size=size.tiny, text="Miss PL")

//---------------------------
// Alerts
// We need separate alertconditions for:
// - Pivot high confirmed
// - Pivot low confirmed
// - Missed pivot high
// - Missed pivot low
// These must only fire when enabled.
// For confirmation alerts, fire on the bar of confirmation (current bar where ph/pl is non-na).
// For missed alerts, fire on the bar when deadline is reached with no touch (we marked via lastMissPlotIndex*).
//---------------------------

// Build series booleans
confirmHighNow = enableConfirmHigh and phConfirmed
confirmLowNow  = enableConfirmLow  and plConfirmed

missHighNow = enableMissHigh and (lastMissPlotIndexHigh == curIndex)
missLowNow  = enableMissLow  and (lastMissPlotIndexLow  == curIndex)

// Define alertconditions
alertcondition(confirmHighNow, title="Pivot High Confirmed", message="Pivot High confirmed at bar {{time}} price {{close}}")
alertcondition(confirmLowNow,  title="Pivot Low Confirmed",  message="Pivot Low confirmed at bar {{time}} price {{close}}")
alertcondition(missHighNow,    title="Missed Pivot High",    message="Missed Pivot High: price did not revisit the pivot within " + str.tostring(lookaheadN) + " bars.")
alertcondition(missLowNow,     title="Missed Pivot Low",     message="Missed Pivot Low: price did not revisit the pivot within " + str.tostring(lookaheadN) + " bars.")

// Optional realtime visual feedback using plotchar (not necessary for alerts, but helps in strategy)
// plotchar(confirmHighNow, title="PH Confirm Signal", char="H", location=location.top, color=colHighPivot, size=size.tiny)
// plotchar(confirmLowNow,  title="PL Confirm Signal", char="L", location=location.bottom, color=colLowPivot, size=size.tiny)

// Notes on repainting:
// - ta.pivothigh/ta.pivotlow confirm with a delay of 'rightBars' bars. This script uses the confirmation event only.
// - Missed-pivot detection is based on completed bars up to the deadline and triggers only when determinable (at deadline). No lookahead or security calls are used.

Below is a complete Pine Script v5 that compiles and runs in TradingView. It plots clearly visible pivot highs/lows with adjustable left/right lengths and implements input-controlled alertcondition alerts for “missed pivots.” In this implementation, a pivot is considered “missed” if price fails to retest the pivot level within a user-defined number of bars and tolerance. You can toggle the alerts and markers for missed pivots via inputs.

Key behavior:
- Pivots are detected using ta.pivothigh/ta.pivotlow and plotted at the actual pivot bar (offset by -right length).
- “Retest” is defined as price returning within a tolerance of the pivot level within a given number of bars after the pivot bar.
  - For pivot highs: retested if high >= pivotHigh * (1 - tolerance%).
  - For pivot lows: retested if low <= pivotLow * (1 + tolerance%).
- “Missed” occurs when the retest window expires without a retest.
- Alerts are created using alertcondition() and include per-side toggles; the alert condition itself incorporates the toggles so they can be enabled/disabled without editing the alert.

//@version=5
indicator("Pivot High/Low with Missed Retest Alerts (v5)", overlay=true, max_labels_count=500)

//=========================
// Inputs
//=========================
grpPivot  = "Pivot Settings"
leftLen   = input.int(3,  "Left length",  minval=1, maxval=100, group=grpPivot)
rightLen  = input.int(3,  "Right length", minval=1, maxval=100, group=grpPivot)
showPivots= input.bool(true, "Show pivot markers", group=grpPivot)

grpMissed = "Missed Pivot Retest"
missWindow= input.int(20, "Retest window (bars)", minval=1, maxval=1000, group=grpMissed)
missTolPct= input.float(0.2, "Tolerance %", minval=0.0, maxval=5.0, step=0.05, group=grpMissed)
markMissed= input.bool(true, "Show missed-pivot labels", group=grpMissed)

grpAlerts = "Alerts"
enableMissHigh = input.bool(true,  "Enable missed High alerts", group=grpAlerts)
enableMissLow  = input.bool(true,  "Enable missed Low alerts",  group=grpAlerts)

//=========================
// Pivot detection
//=========================
pH = ta.pivothigh(high, leftLen, rightLen)
pL = ta.pivotlow(low,  leftLen, rightLen)

// Pivot bar index is current index minus rightLen when a pivot confirms
phBarIndex = na(pH) ? na : bar_index - rightLen
plBarIndex = na(pL) ? na : bar_index - rightLen

// Plot pivot markers at the pivot bar using offset = -rightLen
plotshape(showPivots and not na(pH), title="Pivot High", style=shape.triangledown, color=color.red, size=size.large, location=location.abovebar, offset=-rightLen, text="PH")
plotshape(showPivots and not na(pL), title="Pivot Low",  style=shape.triangleup,   color=color.lime, size=size.large, location=location.belowbar, offset=-rightLen, text="PL")

//=========================
// Missed pivot tracking
//=========================
var float lastPHPrice = na
var int   lastPHBar   = na
var float lastPLPrice = na
var int   lastPLBar   = na

// When a pivot confirms, store its price and bar index
if not na(pH)
    lastPHPrice := pH
    lastPHBar   := phBarIndex

if not na(pL)
    lastPLPrice := pL
    lastPLBar   := plBarIndex

// Compute tolerance factors
phTol = missTolPct * 0.01
plTol = missTolPct * 0.01

// Retest checks within the window since the pivot bar
// For highs: consider price retested if high returns within (1 - tol) of the pivot price
phRetested = not na(lastPHPrice) and not na(lastPHBar) and bar_index > lastPHBar and high >= lastPHPrice * (1 - phTol)
// For lows: consider price retested if low returns within (1 + tol) of the pivot price
plRetested = not na(lastPLPrice) and not na(lastPLBar) and bar_index > lastPLBar and low  <= lastPLPrice * (1 + plTol)

// Determine if the window has expired without a retest
phWindowExpired = not na(lastPHBar) and bar_index - lastPHBar > missWindow
plWindowExpired = not na(lastPLBar) and bar_index - lastPLBar > missWindow

missedHigh = phWindowExpired and not phRetested
missedLow  = plWindowExpired and not plRetested

//=========================
// Chart labels for missed pivots (optional)
//=========================
if markMissed and missedHigh
    label.new(bar_index, high, text="Missed PH\n" + str.tostring(lastPHPrice, format.mintick), style=label.style_label_down, color=color.new(color.red, 0), textcolor=color.white)

if markMissed and missedLow
