alertcondition(enableMissHigh and missedHigh, title="Missed Pivot High", message="Missed Pivot High: Price did not retest pivot high within window.")
alertcondition(enableMissLow  and missedLow,  title="Missed Pivot Low",  message="Missed Pivot Low: Price did not retest pivot low within window.")

// Optional: plot horizontal lines at last pivot levels for visual reference
