my_attr/src/lib.rs
use proc_macro::TokenStream;
use proc_macro_error::{abort, proc_macro_error};
use quote::quote;
use syn::{parse::Parse, parse::ParseStream, parse_macro_input, AttributeArgs, Ident, ItemFn, Lit, LitStr, Meta, NestedMeta, Result as SynResult, Token};

// Custom struct for named args: #[my_attr(name = "foo", times = 3)]
struct Args {
    name: Option<LitStr>,
    times: Option<usize>,
}

impl Default for Args {
    fn default() -> Self {
        Args { name: None, times: None }
    }
}

// Parse attribute arguments using syn v2-compatible API
impl TryFrom<AttributeArgs> for Args {
    type Error = syn::Error;
    fn try_from(args: AttributeArgs) -> SynResult<Self> {
        let mut out = Args::default();
        for nested in args {
            match nested {
                NestedMeta::Meta(Meta::NameValue(nv)) => {
                    let ident = nv.path.get_ident().cloned();
                    let Some(key) = ident else {
                        return Err(syn::Error::new_spanned(nv.path, "expected simple identifier key"));
                    };
                    match (key.to_string().as_str(), &nv.value) {
                        ("name", ExprLit { lit: Lit::Str(s), .. }) => {
                            out.name = Some(s.clone());
                        }
                        ("times", ExprLit { lit: Lit::Int(i), .. }) => {
                            let v = i.base10_parse::<usize>().map_err(|e| syn::Error::new(i.span(), e))?;
                            out.times = Some(v);
                        }
                        ("name", other) => {
                            return Err(syn::Error::new_spanned(other, "`name` must be a string literal"));
                        }
                        ("times", other) => {
                            return Err(syn::Error::new_spanned(other, "`times` must be an integer literal"));
                        }
                        (other, _) => {
                            return Err(syn::Error::new(key.span(), format!("unknown argument `{}`; expected `name` or `times`", other)));
                        }
                    }
                }
                other => {
                    return Err(syn::Error::new_spanned(other, "expected name-value pairs like name = \"...\", times = 3"));
                }
            }
        }
        Ok(out)
    }
}

use syn::{ExprLit};

#[proc_macro_error]
#[proc_macro_attribute]
pub fn my_attr(attr: TokenStream, item: TokenStream) -> TokenStream {
    // Parse the item first; if it fails, return a compiler error (no panic)
    let input_fn: ItemFn = match syn::parse(item.clone()) {
        Ok(it) => it,
        Err(e) => return proc_macro_error::emit_error!(e).into(),
    };

    // Parse attribute args using syn v2: parse_macro_input! gives AttributeArgs
    let args_raw = parse_macro_input!(attr as AttributeArgs);
    let args: Args = match Args::try_from(args_raw) {
        Ok(a) => a,
        Err(e) => return proc_macro_error::emit_error!(e).into(),
    };

    // Validate arguments and produce helpful diagnostics
    if args.name.is_none() && args.times.is_none() {
        abort!(input_fn.sig.ident, "at least one of `name` or `times` must be provided");
    }

    let fn_ident = &input_fn.sig.ident;
    let name_msg = args
        .name
        .as_ref()
        .map(|s| s.value())
        .unwrap_or_else(|| "<no-name>".to_string());
    let times = args.times.unwrap_or(1);

    // Generate wrapper that prints a message at runtime before calling the original fn
    let vis = &input_fn.vis;
    let sig = &input_fn.sig;
    let block = &input_fn.block;

    let expanded = quote! {
        #vis #sig {
            for _ in 0..#times {
                eprintln!("[my_attr] {} -> {}()", #name_msg, stringify!(#fn_ident));
            }
            #block
        }
    };

    TokenStream::from(expanded)
}

