1) Fetch and parse NASA data (Node script generating data/planets.json)
// tools/fetch_planets.mjs
import fs from 'node:fs/promises';
import { JSDOM } from 'jsdom';
import fetch from 'node-fetch';

const FACTSHEET_URL = 'https://nssdc.gsfc.nasa.gov/planetary/factsheet/planetfact_table_m.html';

function parseAU(value) {
  // Semimajor axes in the table are in 10^6 km; we convert to AU (1 AU = 149,597,870.7 km)
  const km = parseFloat(value.replace(/[^0-9.\-]/g, '')) * 1e6;
  const AU = km / 149_597_870.7;
  return AU;
}

function parseDays(value) {
  // Orbital period in days is provided directly
  return parseFloat(value.replace(/[^0-9.\-]/g, ''));
}

function parseKm(value) {
  // Mean radius in km is provided directly
  return parseFloat(value.replace(/[^0-9.\-]/g, ''));
}

(async () => {
  const res = await fetch(FACTSHEET_URL);
  const html = await res.text();
  const dom = new JSDOM(html);
  const doc = dom.window.document;

  // The factsheet has a big table; we locate rows for each planet
  const planetsOrder = ['Mercury','Venus','Earth','Mars','Jupiter','Saturn','Uranus','Neptune'];

  // Helper: find column indices by header labels
  const headerCells = [...doc.querySelectorAll('table tr')][0].querySelectorAll('th, td');
  const headerText = [...headerCells].map(th => th.textContent.trim());
  const colIndex = (label) => headerText.findIndex(t => new RegExp(label, 'i').test(t));

  // These labels may vary slightly; use forgiving regex matches
  const idxName   = colIndex('Planet');
  const idxA      = colIndex('Semimajor Axis');   // 10^6 km
  const idxPeriod = colIndex('Orbital Period');   // days
  const idxRadius = colIndex('Mean Radius');      // km

  const rows = [...doc.querySelectorAll('table tr')].slice(1); // skip header
  const raw = rows.map(tr => [...tr.querySelectorAll('td')].map(td => td.textContent.trim()));

  const records = raw
    .filter(cols => planetsOrder.includes(cols[idxName]))
    .map(cols => ({
      name: cols[idxName],
      a_AU: parseAU(cols[idxA]),
      period_days: parseDays(cols[idxPeriod]),
      radius_km: parseKm(cols[idxRadius])
    }))
    // Keep canonical planet order
    .sort((a,b) => planetsOrder.indexOf(a.name) - planetsOrder.indexOf(b.name));

  await fs.mkdir('./data', { recursive: true });
  await fs.writeFile('./data/planets.json', JSON.stringify(records, null, 2));
  console.log('Wrote data/planets.json');
})();

How this maps to the simulation
- a_AU maps to on-screen distance via a scale: pixelsPerAU.
- period_days maps to angular velocity: omega = 2π / period_days (scaled by timeScale).
- radius_km maps to rendered radius via pixelsPerKm and a min visual size for visibility.

