// src/main.js
const canvas = document.getElementById('scene');
const ctx = canvas.getContext('2d');
const dpr = Math.max(1, window.devicePixelRatio || 1);

function resize() {
  canvas.width = Math.floor(innerWidth * dpr);
  canvas.height = Math.floor(innerHeight * dpr);
  canvas.style.width = innerWidth + 'px';
  canvas.style.height = innerHeight + 'px';
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
addEventListener('resize', resize);
resize();

// Mapping constants
const AU_IN_KM = 149_597_870.7;
let pixelsPerAU = Math.min(innerWidth, innerHeight) * 0.35; // 1 AU ≈ 35% of min dimension
const pixelsPerKm = (pixelsPerAU / AU_IN_KM); // huge; we will clamp radii visually

const timeScaleInput = document.getElementById('timeScale');
let timeScaleDaysPerSec = Number(timeScaleInput.value); // controls animation speed mapping

timeScaleInput.addEventListener('input', () => {
  timeScaleDaysPerSec = Number(timeScaleInput.value);
});

let planets = [];

async function loadPlanets() {
  const res = await fetch('../data/planets.json'); // local file generated from NASA factsheet
  planets = await res.json();
}

function toScreen(x, y) {
  const cx = innerWidth / 2;
  const cy = innerHeight / 2;
  return [cx + x, cy + y];
}

let last = performance.now();
let simDays = 0; // simulation time in days

function step(dtSec) {
  simDays += dtSec * timeScaleDaysPerSec; // map real seconds to simulation days
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Sun
  const [sx, sy] = toScreen(0, 0);
  ctx.fillStyle = '#FDB813';
  ctx.beginPath();
  ctx.arc(sx, sy, 10, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = 'rgba(255,255,255,.15)';
  ctx.lineWidth = 1;

  for (const p of planets) {
    const aPx = p.a_AU * pixelsPerAU; // distance scaling from AU to pixels

    // Angular position from period: theta = 2π * t / P
    const omega = (2 * Math.PI) / p.period_days; // radians per simulation day
    const theta = omega * simDays; // position mapped by time scale

    const x = Math.cos(theta) * aPx;
    const y = Math.sin(theta) * aPx;

    // Orbit path
    ctx.beginPath();
    ctx.arc(sx, sy, aPx, 0, Math.PI * 2);
    ctx.stroke();

    // Render radius: convert km->px then clamp to a min size for visibility
    const rPx = Math.max(2, p.radius_km * pixelsPerKm * 4000); // exaggerate size for visibility

    // Planet
    ctx.fillStyle = '#8ab5ff';
    ctx.beginPath();
    ctx.arc(sx + x, sy + y, rPx, 0, Math.PI * 2);
    ctx.fill();

    // Label
    ctx.fillStyle = '#ddd';
    ctx.font = '12px system-ui';
    ctx.fillText(p.name, sx + x + rPx + 4, sy + y + 4);
  }
}

function loop(now) {
  const dtSec = Math.min(0.05, (now - last) / 1000); // cap for stability
  last = now;
  step(dtSec);
  draw();
  requestAnimationFrame(loop);
}

await loadPlanets();
requestAnimationFrame(loop);

