// src/render/scale.js
// World/screen scaling and pixel‑ratio aware canvas setup

export function setupHiDPICanvas(canvas) {
  const dpr = Math.max(1, Math.min(3, window.devicePixelRatio || 1));
  const rect = canvas.getBoundingClientRect();
  canvas.width = Math.floor(rect.width * dpr);
  canvas.height = Math.floor(rect.height * dpr);
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { ctx, dpr };
}

// Map AU to pixels; choose a scale that keeps Neptune on screen
export function makeWorldScale(planets, canvas, paddingPx = 40) {
  const maxAU = Math.max(...planets.map(p => p.a_AU));
  const rect = canvas.getBoundingClientRect();
  const radiusPx = Math.min(rect.width, rect.height) / 2 - paddingPx;
  const pxPerAU = radiusPx / maxAU;
  return { pxPerAU };
}
