```js
// src/main.js
import { setupHiDPICanvas, makeWorldScale } from './render/scale.js';
import { createState } from './core/state.js';

const AU_IN_KM = 149_597_870.7; // for reference if needed later

async function loadPlanets() {
  // Load the JSON created by scripts/fetch-planets.js
  const res = await fetch('../data/planets.json');
  if (!res.ok) throw new Error('Failed to load planets.json');
  const json = await res.json();
  return json.planets;
}

function mapToRenderable(planets, canvas) {
  // Compute scaling once
  const { pxPerAU } = makeWorldScale(planets, canvas);

  // Precompute derived render params for each planet
  // angleRate = 2π / period_days (radians per day). We’ll multiply by timeScale in the loop.
  const renderPlanets = planets.map(p => {
    const distancePx = p.a_AU * pxPerAU;            // AU -> pixels
    const angleRate = (2 * Math.PI) / p.period_days; // rad/day

    // Visual radius: scale log to keep small bodies visible; cap min/max in px
    const visualRadius = Math.max(2, Math.min(20, Math.log10(p.radius_km) - 2)) | 0;

    return {
      id: p.id,
      name: p.name,
      color: p.color,
      a_AU: p.a_AU,
      period_days: p.period_days,
      radius_km: p.radius_km,
      distancePx,
      angleRate,
      angle: Math.random() * Math.PI * 2, // random initial phase
      visualRadius
    };
  });

  return { renderPlanets, pxPerAU };
}

function resize(canvas, app) {
  const { ctx } = setupHiDPICanvas(canvas);
  app.ctx = ctx;
}

function draw(app) {
  const { ctx, canvas, renderPlanets } = app;
  const w = canvas.clientWidth;
  const h = canvas.clientHeight;

  ctx.clearRect(0, 0, w, h);

  // Sun at center
  const cx = w / 2;
  const cy = h / 2;

  // Sun glow
  const grd = ctx.createRadialGradient(cx, cy, 0, cx, cy, 60);
  grd.addColorStop(0, '#ffec99');
  grd.addColorStop(1, 'rgba(255, 236, 153, 0)');
  ctx.fillStyle = grd;
  ctx.beginPath();
  ctx.arc(cx, cy, 60, 0, Math.PI * 2);
  ctx.fill();

  // Orbits
  ctx.strokeStyle = 'rgba(255,255,255,0.08)';
  ctx.lineWidth = 1;
  for (const p of renderPlanets) {
    ctx.beginPath();
    ctx.arc(cx, cy, p.distancePx, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Planets
  for (const p of renderPlanets) {
    const x = cx + Math.cos(p.angle) * p.distancePx;
    const y = cy + Math.sin(p.angle) * p.distancePx;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(x, y, p.visualRadius, 0, Math.PI * 2);
    ctx.fill();

    // label
    ctx.fillStyle = 'rgba(255,255,255,0.75)';
    ctx.font = '12px system-ui, sans-serif';
    ctx.fillText(p.name, x + p.visualRadius + 4, y - p.visualRadius - 2);
  }
}

function animate(app) {
  const { renderPlanets, state } = app;
  let last = performance.now();

  function frame(now) {
    const dtMs = now - last;
    last = now;

    // Convert real ms -> sim days: 1s real = 1 day * timeScale (tunable)
    const days = (dtMs / 1000) * state.timeScale;
    state.t += days;

    // Advance each planet by angleRate * days
    for (const p of renderPlanets) {
      p.angle += p.angleRate * days;
    }

    draw(app);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

function setupUI(app) {
  const slider = document.getElementById('timeScale');
  const label = document.getElementById('timeScaleVal');
  if (slider && label) {
    const update = () => {
      app.state.timeScale = parseFloat(slider.value);
      label.textContent = slider.value + 'x';
    };
    slider.addEventListener('input', update);
    update();
  }
}

(async function main() {
  const canvas = document.getElementById('view');
  // ensure canvas fills available space
  const ro = new ResizeObserver(() => resize(canvas, app));

  const planets = await loadPlanets();
  const state = createState({ planets, timeScale: 5 });
  const app = { canvas, state };

  // initial size
  resize(canvas, app);

  // map to renderables (distances -> px, periods -> angular speeds)
  const { renderPlanets } = mapToRenderable(planets, canvas);
  app.renderPlanets = renderPlanets;

  setupUI(app);
  ro.observe(canvas);
  animate(app);
})();
```

How the NASA data is mapped to the simulation
- Distance in pixels: distancePx = a_AU × pxPerAU, where pxPerAU is chosen so Neptune fits on screen.
- Angular speed: angleRate = 2π / period_days (radians per simulated day). Each frame, angle += angleRate × daysElapsed × timeScale.
- Visual radius: log-scaled from physical radius_km to keep small planets visible, clamped to [2, 20] px.

Running it
1) Run the fetch script to create data/planets.json:
   node scripts/fetch-planets.js
2) Serve public/ via a local server (for module import and fetch to work), e.g.:
   npx http-server public -p 8080
   or: npx serve public
3) Open http://localhost:8080

Performance tips
- Use requestAnimationFrame and avoid per-frame allocations. Precompute render parameters (distancePx, angleRate).
- Limit devicePixelRatio to a sane cap (e.g., 3) to avoid excessive fill cost on 4K/5K displays.
- Draw orbits with thin strokes and batch state changes to reduce canvas state churn.
- Consider culling labels/planets when zoomed out; add a simple zoom to explore inner system.
"""
