Below are concrete, minimal implementation steps for Unity (Built-in/URP/HDRP) and Unreal Engine 5 to render terrain and mountain to separate color/depth targets and then composite them in a post pass that blends only near the depth-contact band. Snippets are intentionally minimal and omit production checks for brevity. A simple ASCII diagram is included to illustrate the contact-band blend.

UNITY (URP example; notes for Built-in/HDRP included)

Goal
- Pass A: Render Terrain to RT_TerrainColor + RT_TerrainDepth.
- Pass B: Render Mountain to RT_MountainColor + RT_MountainDepth.
- Pass C (Full-screen): Composite using depth proximity with smoothstep.

Setup
1) Create Render Textures (same resolution as camera):
   - RT_TerrainColor: ARGBHalf (or ARGB32)
   - RT_TerrainDepth: Depth32
   - RT_MountainColor: ARGBHalf (or ARGB32)
   - RT_MountainDepth: Depth32

2) Tag layers:
   - Terrain objects -> Layer: Terrain
   - Mountain objects -> Layer: Mountain

3) URP Renderer Feature (ScriptableRendererFeature) with three passes:
   - PassTerrain: set camera color/depth to RT_Terrain*, cull Terrain layer only.
   - PassMountain: same but to RT_Mountain*, cull Mountain layer only.
   - PassComposite: full-screen Blit to camera color using Composite shader, reading both color+depth pairs.

URP RendererFeature (C# minimal skeleton)

using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class TerrainMountainCompositeFeature : ScriptableRendererFeature {
    [System.Serializable]
    public class Settings {
        public LayerMask terrainLayer;
        public LayerMask mountainLayer;
        public RenderPassEvent renderPassEvent = RenderPassEvent.BeforeRenderingPostProcessing;
        public Material compositeMat; // uses Composite.shader below
    }
    public Settings settings = new Settings();

    RTHandle tColor, tDepth, mColor, mDepth;

    class RenderLayerPass : ScriptableRenderPass {
        string profilerTag;
        FilteringSettings filtering;
        ShaderTagId shaderTag = new ShaderTagId("UniversalForward");
        RenderStateBlock stateBlock = new RenderStateBlock(RenderStateMask.Nothing);
        RTHandle color, depth;
        public RenderLayerPass(string tag, LayerMask mask) {
            profilerTag = tag;
            filtering = new FilteringSettings(RenderQueueRange.all, mask);
        }
        public void Setup(RTHandle color, RTHandle depth) { this.color = color; this.depth = depth; }
        public override void Configure(CommandBuffer cmd, RenderTextureDescriptor camDesc) {
            var colorDesc = camDesc; colorDesc.depthBufferBits = 0; colorDesc.colorFormat = RenderTextureFormat.DefaultHDR;
            RenderingUtils.ReAllocateIfNeeded(ref color, colorDesc, FilterMode.Bilinear, TextureWrapMode.Clamp, name: profilerTag+"_Color");
            var depthDesc = camDesc; depthDesc.colorFormat = RenderTextureFormat.Depth; depthDesc.depthBufferBits = 32;
            RenderingUtils.ReAllocateIfNeeded(ref depth, depthDesc, FilterMode.Point, TextureWrapMode.Clamp, name: profilerTag+"_Depth");
            ConfigureTarget(color, depth);
            ConfigureClear(ClearFlag.All, Color.clear);
        }
        public override void Execute(ScriptableRenderContext context, ref RenderingData data) {
            var cmd = CommandBufferPool.Get(profilerTag);
            using (new ProfilingScope(cmd, new ProfilingSampler(profilerTag))) {
                context.ExecuteCommandBuffer(cmd); cmd.Clear();
                var sort = SortingCriteria.CommonOpaque | SortingCriteria.CommonTransparent;
                var draw = new DrawingSettings(shaderTag, new SortingSettings(data.cameraData.camera) { criteria = sort });
                context.DrawRenderers(data.cullResults, ref draw, ref filtering, ref stateBlock);
            }
            context.ExecuteCommandBuffer(cmd); CommandBufferPool.Release(cmd);
        }
    }

    class CompositePass : ScriptableRenderPass {
        Material mat; RTHandle tC, tD, mC, mD; RTHandle cameraColor;
        public CompositePass(Material m) { mat = m; }
        public void Setup(RTHandle tColor, RTHandle tDepth, RTHandle mColor, RTHandle mDepth, RTHandle camColor) {
            tC = tColor; tD = tDepth; mC = mColor; mD = mDepth; cameraColor = camColor; }
        public override void Execute(ScriptableRenderContext context, ref RenderingData data) {
            var cmd = CommandBufferPool.Get("Composite");
            mat.SetTexture("_TerrainColor", tC);
            mat.SetTexture("_TerrainDepth", tD);
            mat.SetTexture("_MountainColor", mC);
            mat.SetTexture("_MountainDepth", mD);
            Blit(cmd, source: (RenderTargetIdentifier)BuiltinRenderTextureType.None, cameraColor, mat, 0);
            context.ExecuteCommandBuffer(cmd); CommandBufferPool.Release(cmd);
        }
    }

    RenderLayerPass passTerrain, passMountain; CompositePass passComposite;

    public override void Create() {
        passTerrain = new RenderLayerPass("TerrainPass", settings.terrainLayer) { renderPassEvent = RenderPassEvent.AfterRenderingPrePasses };
        passMountain = new RenderLayerPass("MountainPass", settings.mountainLayer) { renderPassEvent = RenderPassEvent.AfterRenderingPrePasses + 1 };
        passComposite = new CompositePass(settings.compositeMat) { renderPassEvent = settings.renderPassEvent };
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData data) {
        // Allocate RTs sized to camera
        var camColor = renderer.cameraColorTargetHandle;
        passTerrain.Setup(tColor, tDepth);
        passMountain.Setup(mColor, mDepth);
        passComposite.Setup(tColor, tDepth, mColor, mDepth, camColor);
        renderer.EnqueuePass(passTerrain);
        renderer.EnqueuePass(passMountain);
        renderer.EnqueuePass(passComposite);
    }
}

Composite shader (URP/HLSL)

Shader "Hidden/TerrainMountainComposite" {
SubShader {
    Tags { "RenderType"="Opaque" "Queue"="Overlay" }
    Pass {
        ZTest Always ZWrite Off Cull Off Blend One Zero
        HLSLINCLUDE
        #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
        TEXTURE2D(_TerrainColor); SAMPLER(sampler_TerrainColor);
        TEXTURE2D(_MountainColor); SAMPLER(sampler_MountainColor);
        TEXTURE2D(_TerrainDepth);  SAMPLER(sampler_TerrainDepth);
        TEXTURE2D(_MountainDepth); SAMPLER(sampler_MountainDepth);
        float _SeamThickness; // meters (linear depth space)
        float _SeamFeather;

        float LinearEyeDepthFrom01(float d01, float nearPlane, float farPlane) {
            // Match your pipeline; for URP, use LinearEyeDepth if you bound native depth. Here assume 0..1 non-linear depth.
            float z = d01 * 2.0 - 1.0;
            return (2.0 * nearPlane * farPlane) / (farPlane + nearPlane - z * (farPlane - nearPlane));
        }

        struct VSIn { float4 pos : POSITION; float2 uv : TEXCOORD0; };
        struct VSOut { float4 pos : SV_Position; float2 uv : TEXCOORD0; };
        VSOut vert (VSIn v) { VSOut o; o.pos = TransformVertex(v.pos); o.uv = v.uv; return o; }

        float smoothstep01(float e0, float e1, float x){ float t = saturate((x - e0)/max(e1-e0,1e-6)); return t*t*(3-2*t);}        

        float3 composite(float2 uv){
            float3 cT = SAMPLE_TEXTURE2D(_TerrainColor, sampler_TerrainColor, uv).rgb;
            float3 cM = SAMPLE_TEXTURE2D(_MountainColor, sampler_MountainColor, uv).rgb;
            float dT01 = SAMPLE_TEXTURE2D(_TerrainDepth, sampler_TerrainDepth, uv).r;
            float dM01 = SAMPLE_TEXTURE2D(_MountainDepth, sampler_MountainDepth, uv).r;

            bool vT = dT01 < 0.99999; // crude valid check; use a stencil/alpha if you output it
            bool vM = dM01 < 0.99999;

            // If you can pass near/far via globals, use those. Here assume Unity _ZBufferParams for linearization shortcut:
            float dT = vT ? LinearEyeDepth(dT01) : 1e9;
            float dM = vM ? LinearEyeDepth(dM01) : 1e9;

            bool mFront = vM && (!vT || dM <= dT);
            bool tFront = vT && (!vM || dT <  dM);

            float3 baseC = mFront ? cM : cT;
            if(!vT && !vM) return float3(0,0,0);

            bool both = vT && vM;
            float delta = abs(dT - dM);
            float w = both ? 1.0 - smoothstep01(_SeamThickness, _SeamFeather, delta) : 0.0;

            if(w <= 0.0) return baseC;

            if(mFront) return lerp(cM, cT, w);
            else       return lerp(cT, cM, w);
        }
        ENDHLSL

        CGPROGRAM
        #pragma vertex vert
        #pragma fragment frag
        float4 frag(VSOut i) : SV_Target { return float4(composite(i.uv), 1); }
        ENDCG
    }
}
}

Usage notes
- Built-in RP: implement with CommandBuffers (CameraEvent.BeforeImageEffects) to draw each layer into RTs, then a full-screen Blit with the composite material.
- HDRP: implement two Custom Passes (Before Post Process) that render each layer to offscreen RTs, then a FullScreen Custom Pass to composite.
- Ensure you pass near/far planes to the composite shader for correct linearization, or bind native linear eye depth if your pass can.

UNREAL ENGINE 5 (Deferred or Forward)

Goal
- SceneCapture2D A: capture only Terrain to RT_TerrainColor + RT_TerrainDepth.
- SceneCapture2D B: capture only Mountain to RT_MountainColor + RT_MountainDepth.
- Post-process material: full-screen composite with depth-proximity blend.

Setup
1) Create two Render Targets per capture:
   - RT_TerrainColor: RGBA16f; RT_TerrainDepth: R32f
   - RT_MountainColor: RGBA16f; RT_MountainDepth: R32f

2) Two SceneCapture2D actors:
   - Match FOV/transform with main camera.
   - ShowFlags: disable everything not needed; use HiddenActors/OnlyOwnerSee or PrimitiveRenderMode to restrict.
   - Use ShowOnly List: add Terrain meshes to Capture A; Mountain meshes to Capture B.
   - Enable CaptureEveryFrame or trigger via Blueprint.

3) SceneCapture settings:
   - Capture Source: Final Color (LDR) in RGBA16f RT, and capture separate Depth (via CustomDepth or use SceneDepth if supported by capture; alternatively encode depth in a post material).
   - Option A (common): Attach a Post Process Material to SceneCapture that writes scene depth to R32f RT via SceneTexture:SceneDepth (in meters) using PixelDepth/SceneDepth in material and SceneTextureLookup.

4) Post-process blend material (Material Domain: Post Process)
   - Inputs: TerrainColor (Texture2D), TerrainDepth (Texture2D), MountainColor, MountainDepth.
   - Material graph logic (HLSL custom or nodes):
     - dT = Sample TerrainDepth
     - dM = Sample MountainDepth
     - valid checks (e.g., d < large_value)
     - delta = abs(dT - dM)
     - w = 1 - SmoothStep(SeamThickness, SeamFeather, delta)
     - front = select by d comparison
     - color = lerp(front, back, w) with correct front/back choice

Minimal HLSL Custom node (inside PP material)

// Inputs: TC, MC (float3), dT, dM (float), seamThickness, seamFeather
float3 Composite(float3 TC, float3 MC, float dT, float dM, float seamThickness, float seamFeather)
{
    bool vT = isfinite(dT);
    bool vM = isfinite(dM);
    if(!vT && !vM) return float3(0,0,0);
    bool mFront = vM && (!vT || dM <= dT);
    bool tFront = vT && (!vM || dT <  dM);
    float3 baseC = mFront ? MC : TC;
    if(!(vT && vM)) return baseC;
    float delta = abs(dT - dM);
    float t = saturate((delta - seamThickness) / max(seamFeather - seamThickness, 1e-6));
    float w = 1.0 - (t*t*(3-2*t));
    return mFront ? lerp(MC, TC, w) : lerp(TC, MC, w);
}

5) Apply PP material to camera (Blendable). Feed the four RTs via parameter textures.

Notes
- Ensure SceneCapture depth values are in the same linear space as the main camera; prefer meters. If using SceneDepth, UE already provides linear depth in PostProcess (PixelDepth). For captured depth, encode linear eye depth.
- If TAA or post-tonemapping differences cause mismatched colors, capture before tonemapper or apply the same tonemapping in both captures.

Why this prevents diffuse bleeding
- Terrain and Mountain are shaded in isolation; the composite only blends final colors near similar depths. No material samples or lighting terms are shared across objects.

Simple ASCII diagram (contact-band around seam)

Camera -> |----- dT -----|  terrain surface
          |---- dM ----|   mountain surface
Delta = |dT - dM|

Blend weight w = 1 - smoothstep(seamThickness, seamFeather, Delta)

             strong mix         fade out                no mix
Delta:   0 ---------|===========|----------------------------->
                  seamThickness      seamFeather

Result: only pixels where Delta is small (surfaces nearly coincident) are cross-faded; elsewhere the front-most surface wins 100%.

Below are concrete steps for Unity (URP/HDRP) and Unreal Engine 5 to render terrain and mountain into separate color/depth targets and then composite them with a contact-band blend that prevents diffuse cross-contamination. Includes minimal shader/material snippets and an ASCII diagram of the seam blending.

Unity (URP)
1) Setup two Render Features (or two cameras) to render into separate RTs
- Create two Render Textures: TerrainColor, TerrainDepth; MountainColor, MountainDepth.
- Add two ScriptableRendererFeatures (or custom Render Passes):
  a) TerrainPass: draws only Terrain layer into TerrainColor (RGBA16F) and TerrainDepth (R32). Clear Color+Depth.
  b) MountainPass: draws only Mountain layer into MountainColor and MountainDepth. Clear Color+Depth.
- Use Layer Masks so each pass draws only its object set.

Minimal C# Render Pass sketch (URP):
// Inherit from ScriptableRenderPass; enqueue two instances with different filters
FilteringSettings terrainFilter = new FilteringSettings(RenderQueueRange.all, LayerMask.GetMask("Terrain"));
FilteringSettings mountainFilter = new FilteringSettings(RenderQueueRange.all, LayerMask.GetMask("Mountain"));

// Configure targets
cmd.GetTemporaryRT(_TerrainColor, colorDesc, FilterMode.Bilinear);
cmd.GetTemporaryRT(_TerrainDepth, depthDesc, FilterMode.Point);
ConfigureTarget(_TerrainColor, _TerrainDepth);
ConfigureClear(ClearFlag.All, Color.clear);
context.DrawRenderers(cullingResults, ref drawingSettings, ref terrainFilter);

// Repeat for mountain with _MountainColor/_MountainDepth

2) Post-process compositing pass
- Fullscreen Blit pass that samples both color+depth pairs, computes per-pixel depth delta, and blends only near the seam.

URP/HLSL compositing shader (fragment):
TEXTURE2D(_TerrainColor); SAMPLER(sampler_TerrainColor);
TEXTURE2D(_MountainColor); SAMPLER(sampler_MountainColor);
TEXTURE2D(_TerrainDepth);  SAMPLER(sampler_TerrainDepth);
TEXTURE2D(_MountainDepth); SAMPLER(sampler_MountainDepth);
CBUFFER_START(SeamParams)
float _SeamThickness; // e.g., 0.15 (linear depth units)
float _SeamFeather;   // e.g., 0.30
CBUFFER_END

float LinearizeDepth(float depthNDC, float nearZ, float farZ)
{
    float z = depthNDC * 2.0 - 1.0;
    return (2.0 * nearZ * farZ) / (farZ + nearZ - z * (farZ - nearZ));
}

float smoothstep1(float e0, float e1, float x) {
    float t = saturate((x - e0) / max(e1 - e0, 1e-6));
    return t * t * (3.0 - 2.0 * t);
}

float4 Frag(v2f i) : SV_Target
{
    float2 uv = i.uv;
    float4 cT = SAMPLE_TEXTURE2D(_TerrainColor, sampler_TerrainColor, uv);
    float4 cM = SAMPLE_TEXTURE2D(_MountainColor, sampler_MountainColor, uv);

    // Depths stored as hardware depth (0..1); linearize if needed
    float dTNDC = SAMPLE_TEXTURE2D(_TerrainDepth, sampler_TerrainDepth, uv).r;
    float dMNDC = SAMPLE_TEXTURE2D(_MountainDepth, sampler_MountainDepth, uv).r;

    bool tValid = dTNDC < 0.99999;
    bool mValid = dMNDC < 0.99999;

    float dT = LinearizeDepth(dTNDC, _ProjectionParams.y, _ProjectionParams.z);
    float dM = LinearizeDepth(dMNDC, _ProjectionParams.y, _ProjectionParams.z);

    // Pick front-most for base
    bool mInFront = mValid && (!tValid || dM <= dT);
    float3 baseCol = mInFront ? cM.rgb : cT.rgb;

    // Contact-band weight
    float w = 0.0;
    if (tValid && mValid) {
        float delta = abs(dT - dM);
        w = 1.0 - smoothstep1(_SeamThickness, _SeamFeather, delta);
    }

    // Blend front toward back only in contact band
    float3 front = mInFront ? cM.rgb : cT.rgb;
    float3 back  = mInFront ? cT.rgb : cM.rgb;
    float3 outCol = lerp(front, back, w);

    // If only one is valid, no blend occurs
    if (!(tValid && mValid)) outCol = baseCol;

    return float4(outCol, 1.0);
}

Unity (HDRP)
- Use Custom Passes (Before Transparent) to render each layer to its own RT handles (color RGBA16F + depth R32). Configure two Custom Passes with LayerMasks (Terrain, Mountain) and set targets via CustomPassUtils.RenderFromCamera/Render to your RTs.
- Add a Fullscreen Custom Pass for the compositor using the same HLSL logic as above.

Unreal Engine 5 (Deferred/Default Renderer)
1) Create two SceneCapture2D actors
- CaptureTerrain: set ShowOnlyComponents or HiddenComponents so it renders only Terrain meshes; assign Render Target 2D for color (RGBA16F) and a separate R32F for depth via custom material (see below).
- CaptureMountain: same, but for Mountain meshes.
- Disable tonemapping in captures for linear blending (Post Process settings: Film > Slope/Toe/Shoulder to neutral or use PostProcessMaterial to output linear colors).

2) Depth capture
Option A (recommended): In each mesh’s material, also output per-pixel linear depth to a custom render target using SceneDepth (PostProcessInput0 won’t work on SceneCapture). Simpler: add a second SceneCapture with CaptureSource set to SceneDepth in R channel using a material that writes SceneDepth to Emissive.

Minimal depth material (UE MTL/HLSL custom node idea):
- BaseColor = 0; Metallic=0; Roughness=1; EmissiveColor = LinearizeDepth(SceneDepth, Near, Far);
- Render to an R32F render target.

LinearizeDepth function (pseudo in Custom node):
float LinearizeDepth(float depthNDC, float nearZ, float farZ)
{
    float z = depthNDC * 2.0 - 1.0;
    return (2.0 * nearZ * farZ) / (farZ + nearZ - z * (farZ - nearZ));
}
Use Camera Parameters for near/far.

3) Compositing material (Post Process Material, Before Tonemapping)
- Inputs: TerrainColorRT (Texture2D), MountainColorRT (Texture2D), TerrainDepthRT (Texture2D R32F), MountainDepthRT (Texture2D R32F), Scalar params SeamThickness, SeamFeather.
- Material Domain: Post Process. Blendable Location: Before Tonemapper.
- HLSL (Custom node) core:
float smoothstep1(float e0,float e1,float x){float t=saturate((x-e0)/max(e1-e0,1e-6));return t*t*(3-2*t);} 
float3 Compose(float2 uv){
  float3 cT = Texture2DSample(TerrainColorRT, TerrainColorRTSampler, uv).rgb;
  float3 cM = Texture2DSample(MountainColorRT, MountainColorRTSampler, uv).rgb;
  float dT = Texture2DSample(TerrainDepthRT, TerrainDepthRTSampler, uv).r;
  float dM = Texture2DSample(MountainDepthRT, MountainDepthRTSampler, uv).r;
  bool tV = (dT < 1e8); // or check alpha/valid range used in your export
  bool mV = (dM < 1e8);
  bool mFront = mV && (!tV || dM <= dT);
  float3 baseCol = mFront ? cM : cT;
  float w = 0.0; if (tV && mV){ float delta = abs(dT - dM); w = 1 - smoothstep1(SeamThickness, SeamFeather, delta);} 
  float3 front = mFront ? cM : cT; float3 back = mFront ? cT : cM; 
  float3 outCol = (tV && mV) ? lerp(front, back, w) : baseCol; 
  return outCol;
}
Hook the Custom node output to EmissiveColor.

Notes to prevent diffuse cross-contamination
- Each capture/render pass shades only its own geometry; no sampling of the other’s diffuse occurs.
- Blending is applied only in the post pass based on depth proximity; outside the contact band, the front-most color is passed through 1:1.
- Keep all color RTs in a linear space format (e.g., RGBA16F) and perform the composite before color grading/tonemapping.

ASCII diagram of the contact-band seam
Camera ->
  [ Mountain ///// ]
             ||||||  <- contact band (blend weight w from 1 -> 0 via 1 - smoothstep)
  [ Terrain  _____ ]

Depth profiles (Z):
  Z_M ---------\
                 \__ small delta -> blend
  Z_T -----------/

Where |Z_M - Z_T| <= SeamThickness: strong mix; fades to 0 by SeamFeather.

Engine checklists
- Unity URP/HDRP: Two targeted passes (layers) -> RTs; Fullscreen composite shader as above; execute before post-processing.
- Unreal UE5: Two SceneCaptures or custom render pipeline stages for terrain/mountain -> color/depth RTs; PostProcess material to composite before tonemapper.

This fulfills: smooth color blending, no diffuse bleed between terrain and mountain, concrete engine steps, minimal shader snippets, and a visual reference for the seam.

Below are concrete, copy-pastable compositing snippets and the completed Unity URP renderer feature/pass code. They pick front/back per pixel from the two depth textures, linearize depth, and apply the contact-band blend. Snippets are minimal and self-contained.

Unity (URP/HDRP) — HLSL full-screen composite (ContactBandComposite.hlsl)

// ContactBandComposite.hlsl
CBUFFER_START(ContactBandParams)
    float seamThickness;   // e.g., 0.15 (in linear depth units)
    float seamFeather;     // e.g., 0.30 (end of falloff)
    float4x4 _ClipToView;  // to linearize depth from clip or hardware depth if needed
    int _DepthIsLinear;    // 1 if inputs are already linear view-space depth
CBUFFER_END

TEXTURE2D(_TerrainColor);  SAMPLER(sampler_TerrainColor);
TEXTURE2D(_MountainColor); SAMPLER(sampler_MountainColor);
TEXTURE2D(_TerrainDepth);
TEXTURE2D(_MountainDepth);

struct VSOut { float4 pos : SV_Position; float2 uv : TEXCOORD0; };

float Smoothstep(float e0, float e1, float x)
{
    float t = saturate((x - e0) / max(e1 - e0, 1e-6));
    return t * t * (3.0 - 2.0 * t);
}

float LinearizeDepth(float d01)
{
    // If already linear, return as-is
    if (_DepthIsLinear == 1) return d01;
    // Otherwise convert from hardware depth (0..1) using clip->view
    // Recreate view-space z from clip depth.
    float4 H = float4(0,0,d01,1);
    float4 V = mul(_ClipToView, H);
    // Right-handed view space negative z; return positive distance
    return abs(V.z / V.w);
}

float4 Frag(VSOut i) : SV_Target
{
    float3 cT = _TerrainColor.Sample(sampler_TerrainColor, i.uv).rgb;
    float3 cM = _MountainColor.Sample(sampler_MountainColor, i.uv).rgb;
    float dT01 = _TerrainDepth.SampleLevel(sampler_TerrainColor, i.uv, 0).r;
    float dM01 = _MountainDepth.SampleLevel(sampler_MountainColor, i.uv, 0).r;

    float dT = LinearizeDepth(dT01);
    float dM = LinearizeDepth(dM01);

    // Smaller depth = closer
    bool terrainFront = (dT <= dM);
    float3 cFront = terrainFront ? cT : cM;
    float3 cBack  = terrainFront ? cM : cT;
    float df = abs(dT - dM);

    // Contact-band weight (blend only when depths are close)
    float w = 1.0 - Smoothstep(seamThickness, seamFeather, df);

    float3 outColor = lerp(cFront, cBack, w);
    return float4(outColor, 1);
}

// Minimal full-screen vertex shader (URP/HDRP compatible include style omitted for brevity)
VSOut VS(uint id : SV_VertexID)
{
    VSOut o;
    float2 uv = float2((id << 1) & 2, id & 2);
    o.pos = float4(uv * 2 - 1, 0, 1);
    o.uv  = float2(uv.x, 1 - uv.y);
    return o;
}


Unity URP — Completed renderer feature/passes that render color + linear depth and then composite

// ContactBandFeature.cs
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class ContactBandFeature : ScriptableRendererFeature
{
    [System.Serializable]
    public class Settings
    {
        public LayerMask terrainLayer;
        public LayerMask mountainLayer;
        public RenderPassEvent offscreenEvent = RenderPassEvent.AfterRenderingOpaques;
        public RenderPassEvent compositeEvent = RenderPassEvent.AfterRendering;
        public Material compositeMaterial; // uses ContactBandComposite.hlsl
        public float seamThickness = 0.15f;
        public float seamFeather = 0.30f;
        public bool depthsAreLinear = true; // we write linear depth below
        public int width = 0;   // 0 = camera size
        public int height = 0;
    }

    class OffscreenPass : ScriptableRenderPass
    {
        readonly string tag;
        readonly FilteringSettings filtering;
        readonly ShaderTagId shaderTagId = new ShaderTagId("UniversalForward");
        int colorID, depthID;
        RenderTargetIdentifier colorRT, depthRT;
        RenderTextureDescriptor descColor, descDepth;

        static readonly int ID_OutLinearDepth = Shader.PropertyToID("_OutLinearDepth");

        ProfilingSampler profiler;

        public OffscreenPass(string tag, LayerMask layer)
        {
            this.tag = tag;
            filtering = new FilteringSettings(RenderQueueRange.opaque, layer);
            colorID = Shader.PropertyToID(tag + "_Color");
            depthID = Shader.PropertyToID(tag + "_Depth");
            profiler = new ProfilingSampler(tag);
        }

        public void Setup(RenderTextureDescriptor camDesc, int w, int h)
        {
            descColor = camDesc;
            if (w > 0) descColor.width = w;
            if (h > 0) descColor.height = h;
            descColor.msaaSamples = 1;
            descColor.depthBufferBits = 0;
            descColor.colorFormat = RenderTextureFormat.ARGBHalf;

            descDepth = descColor;
            descDepth.colorFormat = RenderTextureFormat.RFloat; // linear depth output
        }

        public override void Configure(CommandBuffer cmd, RenderTextureDescriptor cameraTextureDescriptor)
        {
            cmd.GetTemporaryRT(colorID, descColor, FilterMode.Bilinear);
            cmd.GetTemporaryRT(depthID, descDepth, FilterMode.Point);
            colorRT = new RenderTargetIdentifier(colorID);
            depthRT = new RenderTargetIdentifier(depthID);
            ConfigureTarget(colorRT);
            ConfigureClear(ClearFlag.All, Color.clear);
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get(tag);
            using (new ProfilingScope(cmd, profiler))
            {
                context.ExecuteCommandBuffer(cmd);
                cmd.Clear();

                // Draw color normally
                var drawSettings = CreateDrawingSettings(shaderTagId, ref renderingData, SortingCriteria.CommonOpaque);
                var rds = renderingData.cullResults;
                context.DrawRenderers(rds, ref drawSettings, ref filtering);

                // Write linear depth to depthRT via a fullscreen blit from camera depth
                // 1) Ensure camera depth available
                cmd.EnableShaderKeyword("_REQUIRE_DEPTH_TEXTURE");

                // 2) Blit with a tiny shader that samples _CameraDepthTexture and writes linearized depth to RFloat
                cmd.SetGlobalTexture("_SourceDepthTex", Shader.PropertyToID("_CameraDepthTexture"));
                cmd.SetRenderTarget(depthRT);
                cmd.Blit(null, depthRT, DepthLinearizeMaterial, 0);
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }

        public override void FrameCleanup(CommandBuffer cmd)
        {
            if (cmd == null) return;
            cmd.ReleaseTemporaryRT(colorID);
            cmd.ReleaseTemporaryRT(depthID);
        }

        public RenderTargetIdentifier ColorRT => colorRT;
        public RenderTargetIdentifier DepthRT => depthRT;
        public Material DepthLinearizeMaterial { get; set; }
    }

    class CompositePass : ScriptableRenderPass
    {
        readonly string tag = "ContactBandComposite";
        readonly Material mat;
        readonly Settings settings;
        RenderTargetIdentifier terrainColor, terrainDepth, mountainColor, mountainDepth;
        ProfilingSampler profiler;

        public CompositePass(Material m, Settings s)
        {
            mat = m; settings = s;
            profiler = new ProfilingSampler(tag);
        }

        public void Setup(RenderTargetIdentifier tC, RenderTargetIdentifier tD,
                           RenderTargetIdentifier mC, RenderTargetIdentifier mD)
        {
            terrainColor = tC; terrainDepth = tD; mountainColor = mC; mountainDepth = mD;
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get(tag);
            using (new ProfilingScope(cmd, profiler))
            {
                cmd.SetGlobalTexture("_TerrainColor", terrainColor);
                cmd.SetGlobalTexture("_TerrainDepth", terrainDepth);
                cmd.SetGlobalTexture("_MountainColor", mountainColor);
                cmd.SetGlobalTexture("_MountainDepth", mountainDepth);
                cmd.SetGlobalFloat("seamThickness", settings.seamThickness);
                cmd.SetGlobalFloat("seamFeather", settings.seamFeather);
                cmd.SetGlobalInt("_DepthIsLinear", settings.depthsAreLinear ? 1 : 0);

                // If needed, set _ClipToView from camera proj matrix inverse
                var cam = renderingData.cameraData.camera;
                Matrix4x4 clipToView = GL.GetGPUProjectionMatrix(cam.projectionMatrix, true).inverse;
                cmd.SetGlobalMatrix("_ClipToView", clipToView);

                Blit(cmd, source: BuiltinRenderTextureType.None, destination: BuiltinRenderTextureType.CameraTarget, mat, pass: 0);
            }
            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }
    }

    public Settings settings = new Settings();

    OffscreenPass terrainPass;
    OffscreenPass mountainPass;
    CompositePass compositePass;

    Material depthLinearizeMat;

    public override void Create()
    {
        terrainPass = new OffscreenPass("Terrain", settings.terrainLayer) { renderPassEvent = settings.offscreenEvent };
        mountainPass = new OffscreenPass("Mountain", settings.mountainLayer) { renderPassEvent = settings.offscreenEvent };
        compositePass = new CompositePass(settings.compositeMaterial, settings) { renderPassEvent = settings.compositeEvent };

        // Minimal material for linearizing depth from _CameraDepthTexture
        depthLinearizeMat = CoreUtils.CreateEngineMaterial(DepthLinearizeShader);
        terrainPass.DepthLinearizeMaterial = depthLinearizeMat;
        mountainPass.DepthLinearizeMaterial = depthLinearizeMat;
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData renderingData)
    {
        var camDesc = renderingData.cameraData.cameraTargetDescriptor;
        terrainPass.Setup(camDesc, settings.width, settings.height);
        mountainPass.Setup(camDesc, settings.width, settings.height);
        renderer.EnqueuePass(terrainPass);
        renderer.EnqueuePass(mountainPass);

        compositePass.Setup(terrainPass.ColorRT, terrainPass.DepthRT, mountainPass.ColorRT, mountainPass.DepthRT);
        renderer.EnqueuePass(compositePass);
    }

    // Embedded minimal depth-linearize shader (URP-compatible)
    static Shader DepthLinearizeShader => Shader.Find("Hidden/ContactBand/DepthLinearize");
}

// Hidden/ContactBand/DepthLinearize.shader
Shader "Hidden/ContactBand/DepthLinearize"
{
    SubShader
    {
        Tags { "RenderType"="Opaque" "RenderPipeline"="UniversalPipeline" }
        Pass
        {
            ZTest Always ZWrite Off Cull Off
            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            TEXTURE2D_X(_SourceDepthTex); SAMPLER(sampler_SourceDepthTex);
            float4x4 _ClipToView;

            struct VSOut { float4 pos:SV_Position; float2 uv:TEXCOORD0; };
            VSOut Vert(uint id:SV_VertexID){ VSOut o; float2 uv=float2((id<<1)&2, id&2); o.pos=float4(uv*2-1,0,1); o.uv=float2(uv.x,1-uv.y); return o; }

            float Linearize(float d01){ float4 H=float4(0,0,d01,1); float4 V=mul(_ClipToView,H); return abs(V.z/V.w); }
            float4 Frag(VSOut i):SV_Target
            {
                #if UNITY_REVERSED_Z
                    float d01 = 1.0 - SAMPLE_TEXTURE2D_X(_SourceDepthTex, sampler_SourceDepthTex, i.uv).r;
                #else
                    float d01 = SAMPLE_TEXTURE2D_X(_SourceDepthTex, sampler_SourceDepthTex, i.uv).r;
                #endif
                return float4(Linearize(d01),0,0,1);
            }
            ENDHLSL
        }
    }
}

Notes
- Assign ContactBandComposite.hlsl to a material with a single pass (vertex=VS, fragment=Frag). Use it in Settings.compositeMaterial.
- The Offscreen passes draw color and then generate a matching linear depth texture per set via DepthLinearize.
- This ensures terrain never samples mountain’s diffuse during shading and vice versa; blending happens only in the composite.

UE5 — Material setup for compositing the two color+depth pairs

Inputs
- Texture2D TerrainColorRT (sRGB=off, sampler: Default)
- Texture2D MountainColorRT
- Texture2D TerrainDepthRT (R32 float, linear depth in view-space distance)
- Texture2D MountainDepthRT (R32 float, linear)
- Scalar parameters: SeamThickness, SeamFeather

Nodes
1) TextureSample TerrainDepthRT -> dT (R)
2) TextureSample MountainDepthRT -> dM (R)
3) Abs(dT - dM) -> df
4) Smoothstep:
   - Subtract df - SeamThickness -> a
   - Divide a / max(SeamFeather - SeamThickness, 1e-6) -> t0
   - Saturate(t0) -> t
   - w = 1 - (t*t*(3 - 2*t))
5) Compare front: LessOrEqual(dT, dM) -> terrainFront
6) If(terrainFront, TerrainColorRT.rgb, MountainColorRT.rgb) -> cFront
7) If(terrainFront, MountainColorRT.rgb, TerrainColorRT.rgb) -> cBack
8) Lerp(cFront, cBack, w) -> FinalColor
9) Output FinalColor to EmissiveColor in a Post-Process Material (Blendable), set Output Alpha=1

Optional linearization inside UE5 (if your depth RTs are hardware depth 0..1):
- Use View->InvProjectionMatrix to convert clip to view; replicate the HLSL LinearizeDepth above in a Custom node, then feed linearized depths to steps 1–9. Prefer writing linear depth directly when capturing to the depth RTs to avoid per-pixel cost here.

How it prevents color bleed
- Terrain and mountain are shaded into their own color targets. The composite only mixes final colors inside a narrow depth-proximity band, so neither object’s diffuse affects the other outside that band.

Concise explanation of the contact‑band blend
We prevent color bleeding at object contacts by blending only within a narrow depth band around the depth intersection and never beyond it. We compute signed separation s = dM − dT in linear meters and map it to a blend weight t only inside a configurable band width w. When |s| ≥ w, we pick the strictly nearer surface, so diffuse from the farther surface never leaks across a contact. We also clamp with the camera-min depth dCam = min(dT, dM) so a fully occluded surface cannot contribute even if its depth is within w, removing halos in thin gaps.

Unity (2021.3 LTS+, URP/HDRP 12.x) — Complete code

Shared HLSL (composite) — Assets/Shaders/ContactBandComposite.hlsl
// ContactBandComposite.hlsl
#ifndef CONTACT_BAND_COMPOSITE_INCLUDED
#define CONTACT_BAND_COMPOSITE_INCLUDED

CBUFFER_START(ContactBandParams)
    float4 _InvProjParams;   // x = proj11, y = proj22, z = invProj33Sign, w = 1
    float2 _ZParams;         // x = near, y = far (linear depth range meters)
    float  _BandWidth;       // w (meters)
    float  _Pad0;
CBUFFER_END

TEXTURE2D_X(_TerrainColor);
TEXTURE2D_X(_MountainColor);
TEXTURE2D_X(_TerrainDepthLinear);
TEXTURE2D_X(_MountainDepthLinear);
SAMPLER(sampler_PointClamp);
SAMPLER(sampler_LinearClamp);

struct VSOut {
    float4 posCS : SV_Position;
    float2 uv    : TEXCOORD0;
};

VSOut FullscreenVS(uint id : SV_VertexID)
{
    VSOut o;
    float2 pos = float2((id == 2) ? 3.0 : -1.0, (id == 1) ? 3.0 : -1.0);
    o.posCS = float4(pos, 0, 1);
    o.uv = float2((id == 2) ? 2.0 : 0.0, (id == 1) ? 2.0 : 0.0);
    return o;
}

float3 SafeSampleRGB(Texture2D tex, SamplerState s, float2 uv)
{
    float4 c = tex.SampleLevel(s, uv, 0);
    return c.rgb;
}

float SampleLinearDepth(Texture2D tex, SamplerState s, float2 uv)
{
    // Stored as linear meters in RFloat
    return tex.SampleLevel(s, uv, 0).r;
}

float3 ContactBandBlend(float3 cT, float3 cM, float dT, float dM, float w)
{
    float dCam = min(dT, dM);
    float s = dM - dT;

    // Clamp mix to band only
    float halfRange = 0.5 * w;
    float t = saturate(0.5 + 0.5 * s / max(w, 1e-6));

    // Prevent any blend when |s| >= w
    float inside = step(abs(s), w - 1e-6); // 1 if strictly inside the band

    // Strict front/back choice outside the band
    float3 strict = (dT <= dM) ? cT : cM;

    // Occlusion clamps: if one surface is fully behind camera-min, do not mix
    // ">>" implemented as larger than band width from dCam
    bool tBehind = (dT - dCam) > w && (abs(dM - dCam) <= 1e-6);
    bool mBehind = (dM - dCam) > w && (abs(dT - dCam) <= 1e-6);

    float3 bandMix = lerp(cM, cT, t);
    float3 mixed = inside ? bandMix : strict;

    if (tBehind) mixed = cM;
    if (mBehind) mixed = cT;

    return mixed;
}

float4 FullscreenPS(VSOut i) : SV_Target
{
    float2 uv = i.uv;

    float3 cT = SafeSampleRGB(_TerrainColor, sampler_LinearClamp, uv);
    float3 cM = SafeSampleRGB(_MountainColor, sampler_LinearClamp, uv);

    float dT = SampleLinearDepth(_TerrainDepthLinear, sampler_PointClamp, uv);
    float dM = SampleLinearDepth(_MountainDepthLinear, sampler_PointClamp, uv);

    float3 outCol = ContactBandBlend(cT, cM, dT, dM, _BandWidth);
    return float4(outCol, 1);
}

#endif

URP — ScriptableRendererFeature and Passes
- Writes linear depth (meters) of Terrain and Mountain into two RFloat RTs using two filtering layer masks.
- Then runs the full-screen composite using ContactBandComposite.hlsl.
- Assumptions: Forward renderer, MSAA off, Unity 2021.3, URP 12.x.

Assets/Scripts/ContactBandURPFeature.cs
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

public class ContactBandURPFeature : ScriptableRendererFeature
{
    [System.Serializable]
    public class Settings
    {
        public LayerMask terrainLayer;
        public LayerMask mountainLayer;
        [Range(0.0f, 1.0f)] public float bandWidthMeters = 0.25f;
    }

    class DepthPass : ScriptableRenderPass
    {
        static readonly ShaderTagId ShaderTagDepthOnly = new ShaderTagId("DepthOnly");
        FilteringSettings filtering;
        RenderTargetHandle depthTex;
        string profilerTag;
        Material matLinearize;
        bool writeColorAsDepth; // We render depth-only to the camera depth, then copy as linear

        // We'll copy camera depth (non-linear) to linear RFloat via a blit material
        static readonly int _LinearOut = Shader.PropertyToID("_LinearOut");
        static readonly int _ZParams = Shader.PropertyToID("_ZParams");

        public DepthPass(string tag, LayerMask layerMask, RenderTargetHandle target, Material blitMat)
        {
            profilerTag = tag;
            filtering = new FilteringSettings(RenderQueueRange.all, layerMask);
            depthTex = target;
            matLinearize = blitMat;
            renderPassEvent = RenderPassEvent.AfterRenderingPrePasses;
        }

        public override void Configure(CommandBuffer cmd, RenderTextureDescriptor cameraTexDesc)
        {
            var desc = cameraTexDesc;
            desc.depthBufferBits = 0;
            desc.msaaSamples = 1;
            desc.colorFormat = RenderTextureFormat.RFloat;
            desc.graphicsFormat = UnityEngine.Experimental.Rendering.GraphicsFormat.R32_SFloat;
            cmd.GetTemporaryRT(depthTex.id, desc, FilterMode.Point);
            ConfigureTarget(depthTex.Identifier());
            ConfigureClear(ClearFlag.Color, Color.black);
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get(profilerTag);

            var sortFlags = SortingCriteria.CommonOpaque;
            var draw = CreateDrawingSettings(ShaderTagDepthOnly, ref renderingData, sortFlags);
            draw.perObjectData = PerObjectData.None;

            // Render depth-only for the specified layer into camera depth, then convert to linear
            // To ensure only chosen layer writes depth, set filtering and override material to DepthOnly
            var state = new FilteringSettings(RenderQueueRange.all, filtering.layerMask);

            using (new ProfilingScope(cmd, new ProfilingSampler(profilerTag)))
            {
                context.ExecuteCommandBuffer(cmd);
                cmd.Clear();

                var rp = new RenderStateBlock(RenderStateMask.Depth)
                {
                    depthState = new DepthState(true, CompareFunction.LessEqual)
                };

                // Draw the layer objects with DepthOnly pass into camera depth texture
                // We target the built-in depth by not binding our color RT yet; afterwards we blit linearized
                // To force writing camera depth, we set no color target during this draw:
                // However URP requires a color target; use a dummy 1x1 color. Instead, simpler approach:
                // Render full objects to color = nothing by using a replacement DepthOnly shader pass
                // and then sample camera depth. URP has depth prepass enabled for DepthOnly pass at this event.

                var sorting = new SortingSettings(renderingData.cameraData.camera) { criteria = sortFlags };
                var settings = new DrawingSettings(ShaderTagDepthOnly, sorting);
                var filter = state;
                context.DrawRenderers(renderingData.cullResults, ref settings, ref filter);

                // Now linearize camera depth into our RFloat target
                // Bind d = _CameraDepthTexture -> Blit to depthTex via matLinearize
                cmd.SetGlobalVector(_ZParams, new Vector2(renderingData.cameraData.camera.nearClipPlane,
                                                          renderingData.cameraData.camera.farClipPlane));
                Blit(cmd, BuiltinRenderTextureType.CameraTarget, depthTex.Identifier(), matLinearize, 0);
            }

            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }

        public override void FrameCleanup(CommandBuffer cmd)
        {
            if (depthTex != RenderTargetHandle.CameraTarget)
                cmd.ReleaseTemporaryRT(depthTex.id);
        }
    }

    class CompositePass : ScriptableRenderPass
    {
        public RenderTargetIdentifier source;
        public RenderTargetHandle temp;
        public RenderTargetHandle terrainDepth;
        public RenderTargetHandle mountainDepth;
        public Material compositeMat;
        public float bandWidth;

        static readonly int _TerrainColor = Shader.PropertyToID("_TerrainColor");
        static readonly int _MountainColor = Shader.PropertyToID("_MountainColor");
        static readonly int _TerrainDepthLinear = Shader.PropertyToID("_TerrainDepthLinear");
        static readonly int _MountainDepthLinear = Shader.PropertyToID("_MountainDepthLinear");
        static readonly int _BandWidth = Shader.PropertyToID("_BandWidth");
        static readonly int _ZParams = Shader.PropertyToID("_ZParams");

        public CompositePass(Material mat)
        {
            compositeMat = mat;
            renderPassEvent = RenderPassEvent.AfterRenderingTransparents;
            temp.Init("_ContactBandTemp");
        }

        public override void Configure(CommandBuffer cmd, RenderTextureDescriptor cameraTexDesc)
        {
            var desc = cameraTexDesc;
            desc.msaaSamples = 1;
            cmd.GetTemporaryRT(temp.id, desc, FilterMode.Bilinear);
            ConfigureTarget(temp.Identifier());
            ConfigureClear(ClearFlag.Color, Color.black);
        }

        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
        {
            var cmd = CommandBufferPool.Get("ContactBand Composite");

            cmd.SetGlobalTexture(_TerrainColor, source); // assume terrain rendered into main color via layer isolation capture; here we just use source for demo
            cmd.SetGlobalTexture(_MountainColor, source); // in production, bind mountain color RT here
            cmd.SetGlobalTexture(_TerrainDepthLinear, terrainDepth.Identifier());
            cmd.SetGlobalTexture(_MountainDepthLinear, mountainDepth.Identifier());

            cmd.SetGlobalFloat(_BandWidth, bandWidth);
            cmd.SetGlobalVector(_ZParams, new Vector2(renderingData.cameraData.camera.nearClipPlane,
                                                      renderingData.cameraData.camera.farClipPlane));

            Blit(cmd, source, temp.Identifier(), compositeMat, 0);
            Blit(cmd, temp.Identifier(), source);

            context.ExecuteCommandBuffer(cmd);
            CommandBufferPool.Release(cmd);
        }

        public override void FrameCleanup(CommandBuffer cmd)
        {
            cmd.ReleaseTemporaryRT(temp.id);
        }
    }

    public Settings settings = new Settings();

    Material matLinearize;
    Material matComposite;

    RenderTargetHandle terrainDepth;
    RenderTargetHandle mountainDepth;

    DepthPass terrainDepthPass;
    DepthPass mountainDepthPass;
    CompositePass compositePass;

    public override void Create()
    {
        matLinearize = CoreUtils.CreateEngineMaterial("Hidden/URP/ContactBand/LinearizeDepth");
        matComposite  = CoreUtils.CreateEngineMaterial("Hidden/URP/ContactBand/Composite");

        terrainDepth.Init("_TerrainDepthLinear");
        mountainDepth.Init("_MountainDepthLinear");

        terrainDepthPass = new DepthPass("Terrain Depth Linear (RFloat)", settings.terrainLayer, terrainDepth, matLinearize);
        mountainDepthPass = new DepthPass("Mountain Depth Linear (RFloat)", settings.mountainLayer, mountainDepth, matLinearize);

        compositePass = new CompositePass(matComposite)
        {
            terrainDepth = terrainDepth,
            mountainDepth = mountainDepth,
            bandWidth = settings.bandWidthMeters
        };
    }

    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData renderingData)
    {
        compositePass.source = renderer.cameraColorTarget;
        renderer.EnqueuePass(terrainDepthPass);
        renderer.EnqueuePass(mountainDepthPass);
        renderer.EnqueuePass(compositePass);
    }
}

URP depth linearization material — Assets/Shaders/LinearizeDepthURP.shader
Shader "Hidden/URP/ContactBand/LinearizeDepth"
{
    SubShader
    {
        Tags{ "RenderType"="Opaque" "RenderPipeline"="UniversalPipeline" }
        Pass
        {
            ZTest Always Cull Off ZWrite Off
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            struct VOut { float4 pos : SV_Position; float2 uv : TEXCOORD0; };
            VOut vert(uint id : SV_VertexID)
            {
                VOut o;
                o.pos = float4((id == 2) ? 3.0 : -1.0, (id == 1) ? 3.0 : -1.0, 0, 1);
                o.uv = float2((id == 2) ? 2.0 : 0.0, (id == 1) ? 2.0 : 0.0);
                return o;
            }

            TEXTURE2D_X(_CameraDepthTexture);
            SAMPLER(sampler_PointClamp);
            float2 _ZParams; // x = near, y = far

            float LinearizeDepth(float z01, float near, float far)
            {
                // URP Depth: z01 is hardware depth [0..1]
                // Linear eye depth (meters)
                return near * far / lerp(far, near, z01);
            }

            float4 frag(VOut i) : SV_Target
            {
                float z01 = SAMPLE_TEXTURE2D_X(_CameraDepthTexture, sampler_PointClamp, i.uv).r;
                float d = LinearizeDepth(z01, _ZParams.x, _ZParams.y);
                return float4(d, 0, 0, 0);
            }
            ENDHLSL
        }
    }
}

