Assets/Scripts/ContactBandHDRPCustomPass.cs
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.HighDefinition;

class ContactBandHDRPCustomPass : CustomPass
{
    public LayerMask terrainLayer;
    public LayerMask mountainLayer;
    public float bandWidthMeters = 0.25f;

    RTHandle terrainDepthLinear;
    RTHandle mountainDepthLinear;

    Material matLinearize;
    Material matComposite;

    static readonly int _TerrainColor = Shader.PropertyToID("_TerrainColor");
    static readonly int _MountainColor = Shader.PropertyToID("_MountainColor");
    static readonly int _TerrainDepthLinear = Shader.PropertyToID("_TerrainDepthLinear");
    static readonly int _MountainDepthLinear = Shader.PropertyToID("_MountainDepthLinear");
    static readonly int _BandWidth = Shader.PropertyToID("_BandWidth");
    static readonly int _ZParams = Shader.PropertyToID("_ZParams");

    protected override void Setup(ScriptableRenderContext renderContext, CommandBuffer cmd)
    {
        matLinearize = CoreUtils.CreateEngineMaterial("Hidden/HDRP/ContactBand/CopyLinearDepth");
        matComposite = CoreUtils.CreateEngineMaterial("Hidden/HDRP/ContactBand/Composite");

        var desc = new TextureDesc(Vector2.one, true, true)
        {
            colorFormat = GraphicsFormat.R32_SFloat,
            depthBufferBits = DepthBits.None,
            msaaSamples = MSAASamples.None,
            enableRandomWrite = false,
            filterMode = FilterMode.Point,
            name = "TerrainDepthLinear"
        };
        terrainDepthLinear = RTHandles.Alloc(desc);
        desc.name = "MountainDepthLinear";
        mountainDepthLinear = RTHandles.Alloc(desc);
    }

    protected override void Execute(CustomPassContext ctx)
    {
        var cmd = ctx.cmd;
        var cam = ctx.hdCamera.camera;

        // Draw Terrain only into depth buffer, then copy to linear RFloat
        using (new ProfilingScope(cmd, new ProfilingSampler("ContactBand HDRP")))
        {
            var dr = new RendererListDesc(HDShaderPassNames.s_DepthOnlyName, ctx.cullingResults, cam)
            {
                sortingCriteria = SortingCriteria.CommonOpaque,
                renderQueueRange = RenderQueueRange.opaque,
                overrideMaterial = null,
                layerMask = terrainLayer
            };
            var rl = ctx.renderContext.CreateRendererList(ref dr);
            CoreUtils.DrawRendererList(ctx.renderContext, cmd, rl);

            // Copy camera depth (non-linear) to linear RT
            Vector2 zparams = new Vector2(cam.nearClipPlane, cam.farClipPlane);
            cmd.SetGlobalVector(_ZParams, zparams);
            HDUtils.BlitCameraTexture(ctx.cmd, ctx.cameraColorBuffer, terrainDepthLinear, matLinearize, 0);

            // Mountain
            dr.layerMask = mountainLayer;
            rl = ctx.renderContext.CreateRendererList(ref dr);
            CoreUtils.DrawRendererList(ctx.renderContext, cmd, rl);
            HDUtils.BlitCameraTexture(ctx.cmd, ctx.cameraColorBuffer, mountainDepthLinear, matLinearize, 0);

            // Composite: assumes terrain/mountain color already exist in ctx.cameraColorBuffer variants.
            // For a real setup, bind color textures rendered via separate cameras/layers.
            cmd.SetGlobalTexture(_TerrainColor, ctx.cameraColorBuffer);
            cmd.SetGlobalTexture(_MountainColor, ctx.cameraColorBuffer);
            cmd.SetGlobalTexture(_TerrainDepthLinear, terrainDepthLinear);
            cmd.SetGlobalTexture(_MountainDepthLinear, mountainDepthLinear);
            cmd.SetGlobalFloat(_BandWidth, bandWidthMeters);

            HDUtils.DrawFullScreen(cmd, matComposite, ctx.cameraColorBuffer);
        }
    }

    protected override void Cleanup()
    {
        CoreUtils.Destroy(matLinearize);
        CoreUtils.Destroy(matComposite);
        RTHandles.Release(terrainDepthLinear);
        RTHandles.Release(mountainDepthLinear);
    }
}

