//==================================================================
// Risk & Margin helpers
//==================================================================
// Compute stop distance in price terms using ATR
bool ComputeSLTP(const string sym, bool isBuy, double rr, double atr_mult, double &sl, double &tp)
{
  double bid,ask; if(!GetBidAsk(sym,bid,ask)) return false;
  double atr[1]; if(CopyBuffer(hATR,0,0,1,atr)<=0) return false;
  double atr_val = atr[0]; if(atr_val<=0) return false;

  double entry = isBuy ? ask : bid;
  double sl_dist = atr_val * atr_mult;
  double tp_dist = sl_dist * rr;

  if(isBuy){ sl = NormalizePrice(entry - sl_dist); tp = NormalizePrice(entry + tp_dist); }
  else     { sl = NormalizePrice(entry + sl_dist); tp = NormalizePrice(entry - tp_dist); }

  // respect stops level and freeze level
  int minPts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
  double minDist = minPts * gPoint;
  if(isBuy){
    if(entry - sl < minDist) sl = NormalizePrice(entry - minDist);
    if(tp - entry < minDist) tp = NormalizePrice(entry + minDist);
  }else{
    if(sl - entry < minDist) sl = NormalizePrice(entry + minDist);
    if(entry - tp < minDist) tp = NormalizePrice(entry - minDist);
  }
  return true;
}

// Calculate volume based on risk percent of equity and SL distance using tick value
double CalcRiskBasedVolume(const string sym, double riskPct, bool isBuy, double sl)
{
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  if(equity<=0) return 0.0;

  double bid,ask; if(!GetBidAsk(sym,bid,ask)) return 0.0;
  double entry = isBuy ? ask : bid;
  double sl_dist = MathAbs(entry - sl);
  if(sl_dist<=0) return 0.0;

  double risk_money = equity * (riskPct/100.0);
  // per point value for 1.0 lot
  double value_per_point_1lot = (gTickValue/gTickSize) * gPoint;
  if(value_per_point_1lot<=0) return 0.0;
  double points_to_sl = sl_dist / gPoint;
  double money_loss_per_lot = value_per_point_1lot * points_to_sl;
  if(money_loss_per_lot<=0) return 0.0;

  double vol = risk_money / money_loss_per_lot;
  return NormalizeVolume(vol);
}

// Ensure margin affordability and cap margin usage vs free margin
bool CheckAndCapByMargin(const string sym, ENUM_ORDER_TYPE type, double &volume)
{
  if(volume<=0) return false;
  double price=0.0; double bid,ask; if(!GetBidAsk(sym,bid,ask)) return false;
  price = (type==ORDER_TYPE_BUY ? ask : bid);

  double required_margin=0.0;
  if(!OrderCalcMargin(type, sym, volume, price, required_margin))
  {
    PrintFormat("[ERR] OrderCalcMargin failed (vol=%.2f): %d", volume, GetLastError());
    return false;
  }
  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(free_margin<=0){ Print("[ERR] Free margin unavailable or <=0"); return false; }

  // Cap: required margin <= InpMaxFreeMarginUsagePct% of free margin
  double cap = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(required_margin > cap)
  {
    // scale volume down proportionally
    double scale = cap / required_margin;
    double newVol = NormalizeVolume(volume * scale);
    if(newVol < gMinVolume){ Print("[WARN] Volume after margin cap < min volume"); return false; }

    // re-evaluate margin for new volume
    double req2=0.0;
    if(!OrderCalcMargin(type, sym, newVol, price, req2))
    { PrintFormat("[ERR] OrderCalcMargin retry failed: %d", GetLastError()); return false; }
    if(req2 > cap){ Print("[ERR] Required margin still above cap after scaling"); return false; }
    volume = newVol;
  }

  // Check broker minimal margin constraints via free margin direct check
  if(required_margin > free_margin)
  {
    // Try scale to fit free margin
    double scale2 = free_margin/required_margin;
    double vol2 = NormalizeVolume(volume*scale2);
    if(vol2<gMinVolume){ Print("[ERR] Not enough free margin for min volume"); return false; }
    double req3=0.0; if(!OrderCalcMargin(type,sym,vol2,price,req3)) return false;
    if(req3>free_margin){ Print("[ERR] Not enough free margin after scaling"); return false; }
    volume=vol2;
  }

  // Optional margin level gate
  if(InpMinMarginLevelPct>0)
  {
    double margin      = AccountInfoDouble(ACCOUNT_MARGIN);
    double equity      = AccountInfoDouble(ACCOUNT_EQUITY);
    double marginLevel = (margin>0 ? (equity/margin)*100.0 : 10000.0);
    if(marginLevel < InpMinMarginLevelPct)
    {
      PrintFormat("[INFO] Margin level %.1f%% below threshold %.1f%% — skip entry", marginLevel, InpMinMarginLevelPct);
      return false;
    }
  }
  return true;
}

//==================================================================
// Signals
//==================================================================
bool GetSignal(bool &buy, bool &sell)
{
  buy=false; sell=false;
  if(!IndicatorsReady()) return false;

  double emaFast[3], emaSlow[3], rsi[3], atr[1];
  if(CopyBuffer(hFastEMA,0,0,3,emaFast)<=0) return false;
  if(CopyBuffer(hSlowEMA,0,0,3,emaSlow)<=0) return false;
  if(CopyBuffer(hRSI,0,0,3,rsi)<=0) return false;
  if(CopyBuffer(hATR,0,0,1,atr)<=0) return false;

  if(atr[0] < InpATR_MinFilter) return false;

  // Use previous closed bar for cross
  double f_prev = emaFast[1];
  double s_prev = emaSlow[1];
  double f_prev2 = emaFast[2];
  double s_prev2 = emaSlow[2];

  bool crossUp   = (f_prev2 <= s_prev2) && (f_prev > s_prev);
  bool crossDown = (f_prev2 >= s_prev2) && (f_prev < s_prev);

  double rsi_prev = rsi[1];

  if(crossUp && rsi_prev >= InpRSI_Buy)  buy = true;
  if(crossDown && rsi_prev <= InpRSI_Sell) sell = true;

  return (buy || sell);
}

//==================================================================
// Trade placement & management
//==================================================================
bool PlaceOrder(bool isBuy)
{
  string sym = gSymbol;
  double bid,ask; if(!GetBidAsk(sym,bid,ask)) { Print("[ERR] No tick"); return false; }
  if(!SpreadOK(sym, InpMaxSpreadPoints)) { Print("[INFO] Spread filter blocks entry"); return false; }

  double sl=0, tp=0;
  if(!ComputeSLTP(sym, isBuy, InpRR, InpATR_SL_Mult, sl, tp)) { Print("[ERR] SL/TP compute failed"); return false; }

  // Risk-based volume
  double volume = CalcRiskBasedVolume(sym, InpRiskPerTradePct, isBuy, sl);
  if(volume < gMinVolume){ Print("[INFO] Volume from risk model < min volume"); return false; }

  // Margin checks and capping
  ENUM_ORDER_TYPE type = isBuy ? ORDER_TYPE_BUY : ORDER_TYPE_SELL;
  if(!CheckAndCapByMargin(sym, type, volume)) return false;

  trade.SetExpertMagicNumber(InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok=false;
  if(isBuy) ok = trade.Buy(volume, sym, 0.0, sl, tp);
  else      ok = trade.Sell(volume, sym, 0.0, sl, tp);

  if(!ok)
  {
    PrintFormat("[ERR] Order send failed: ret=%s err=%d", (string)ok, trade.ResultRetcode());
    return false;
  }

  PrintFormat("[OK] %s placed vol=%.2f SL=%.5f TP=%.5f", isBuy?"BUY":"SELL", volume, sl, tp);
  return true;
}

void ManagePosition()
{
  ulong ticket; long type; double open, sl, tp, vol;
  if(!GetOurPosition(gSymbol, ticket, type, open, sl, tp, vol)) return;

  if(!InpAllowTrailing && InpBreakevenRR<=0) return;

  double bid,ask; if(!GetBidAsk(gSymbol,bid,ask)) return;
  double price = (type==POSITION_TYPE_BUY?bid:ask);

  double atr[1]; if(CopyBuffer(hATR,0,0,1,atr)<=0) return; double atr_val=atr[0]; if(atr_val<=0) return;

  double sl_new = sl;
  // Breakeven logic
  if(InpBreakevenRR>0)
  {
    double sl_dist = MathAbs(open - sl);
    double be_target = open + ((type==POSITION_TYPE_BUY)?1:-1) * sl_dist * InpBreakevenRR;
    bool reached = (type==POSITION_TYPE_BUY ? price >= be_target : price <= be_target);
    if(reached)
    {
      double be = (type==POSITION_TYPE_BUY ? open + 1*gPoint : open - 1*gPoint);
      if(type==POSITION_TYPE_BUY) sl_new = MathMax(sl_new, be); else sl_new = MathMin(sl_new, be);
    }
  }

  // ATR trailing
  if(InpAllowTrailing)
  {
    double trail = atr_val * InpATR_TrailMult;
    if(type==POSITION_TYPE_BUY)
    {
      double cand = NormalizePrice(price - trail);
      if(cand > sl_new) sl_new = cand;
    }
    else
    {
      double cand = NormalizePrice(price + trail);
      if(cand < sl_new) sl_new = cand;
    }
  }

  // Respect stop/freeze levels
  int minPts = MathMax(gStopsLevelPoints, gFreezeLevelPoints);
  double minDist = minPts * gPoint;
  if(type==POSITION_TYPE_BUY)
  {
    if((price - sl_new) < minDist) sl_new = NormalizePrice(price - minDist);
  }
  else
  {
    if((sl_new - price) < minDist) sl_new = NormalizePrice(price + minDist);
  }

  if(MathAbs(sl_new - sl) >= (0.5*gPoint))
  {
    bool modOK = trade.PositionModify(ticket, sl_new, tp);
    if(!modOK)
      PrintFormat("[WARN] PositionModify failed ticket=%I64u err=%d", ticket, trade.ResultRetcode());
  }
}

//==================================================================
// EA lifecycle
//==================================================================
int OnInit()
{
  gSymbol = _Symbol;
  ParseSkipHours(InpSkipHoursUTC);
  if(!RefreshSymbolInfo(gSymbol)) return INIT_FAILED;

  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  hRSI     = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  hATR     = iATR(gSymbol, InpTimeframe, InpATRPeriod);

  if(hFastEMA==INVALID_HANDLE || hSlowEMA==INVALID_HANDLE || hRSI==INVALID_HANDLE || hATR==INVALID_HANDLE)
  {
    Print("[ERR] Indicator handle creation failed");
    return INIT_FAILED;
  }

  return INIT_SUCCEEDED;
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  if(!RefreshSymbolInfo(gSymbol)) return;

  // Session filter by UTC hour
  int h = CurrentUTCHour();
  if(h>=0 && h<24 && gSkipHour[h]) return;

  // Only one position per symbol (regardless of magic)
  if(HasAnyPositionOnSymbol(gSymbol))
  {
    ManagePosition();
    return;
  }

  // Work only on new closed bar for signals
  static datetime lastBar=0; MqlRates rates[]; int copied=CopyRates(gSymbol, InpTimeframe, 0, 3, rates);
  if(copied<3) return;
  datetime curBarTime = rates[0].time; // current forming bar
  if(gLastClosedBarTime==0) gLastClosedBarTime = rates[1].time;
  if(rates[1].time == gLastClosedBarTime)
  {
    // still same closed bar; nothing to do except trailing for existing positions (none here)
  }
  else
  {
    gLastClosedBarTime = rates[1].time;

    // Entry logic on new closed bar
    bool buy=false, sell=false;
    if(GetSignal(buy,sell))
    {
      if(buy)  PlaceOrder(true);
      else if(sell) PlaceOrder(false);
    }
  }
}

