void LogLastError(const string context)
{
  int err = GetLastError();
  PrintFormat("%s | Error %d: %s", context, err, ErrorDescription(err));
  ResetLastError();
}

void ParseSkipHours(const string hours_csv)
{
  ArrayInitialize(gSkipHour,false);
  string s = hours_csv;
  StringTrimLeft(s);
  StringTrimRight(s);
  if(s=="") return;
  string parts[];
  int n = StringSplit(s, ',', parts);
  for(int i=0;i<n;i++)
  {
    string p = parts[i];
    StringTrimLeft(p);
    StringTrimRight(p);
    if(p=="") continue;
    int h = (int)StringToInteger(p);
    if(h>=0 && h<24) gSkipHour[h]=true;
  }
}

bool RefreshSymbolInfo(const string sym)
{
  gSymbol = sym;
  if(!SymbolSelect(gSymbol, true))
  {
    LogLastError("SymbolSelect failed");
    return false;
  }

  gPoint  = SymbolInfoDouble(gSymbol, SYMBOL_POINT);
  gDigits = (int)SymbolInfoInteger(gSymbol, SYMBOL_DIGITS);
  gTickSize = SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_SIZE);
  gTickValue= SymbolInfoDouble(gSymbol, SYMBOL_TRADE_TICK_VALUE);
  gMinVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MIN);
  gMaxVolume= SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_MAX);
  gVolStep  = SymbolInfoDouble(gSymbol, SYMBOL_VOLUME_STEP);
  gStopsLevelPoints  = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_STOPS_LEVEL);
  gFreezeLevelPoints = (int)SymbolInfoInteger(gSymbol, SYMBOL_TRADE_FREEZE_LEVEL);

  long trade_mode = SymbolInfoInteger(gSymbol, SYMBOL_TRADE_MODE);
  if(trade_mode == SYMBOL_TRADE_MODE_DISABLED || trade_mode == SYMBOL_TRADE_MODE_CLOSEONLY)
  {
    PrintFormat("Trading not allowed for symbol %s (mode=%d)", gSymbol, trade_mode);
    return false;
  }

  return (gPoint>0 && gTickSize>0 && gTickValue>0 && gMinVolume>0 && gVolStep>0);
}

bool IsTradingHour()
{
  datetime now_utc = TimeCurrent();
  MqlDateTime t; TimeToStruct(now_utc, t);
  int h = t.hour;
  if(h<0 || h>23) return true; // safety default
  return !gSkipHour[h];
}

int PositionsCountThisSymbol()
{
  int total = PositionsTotal();
  int cnt = 0;
  for(int i=0;i<total;i++)
  {
    ulong ticket = PositionGetTicket(i);
    if(ticket==0) continue;
    if(PositionSelectByTicket(ticket))
    {
      if(PositionGetString(POSITION_SYMBOL)==gSymbol && PositionGetInteger(POSITION_MAGIC)==(long)InpMagicNumber)
        cnt++;
    }
  }
  return cnt;
}

bool HasOpenPosition()
{
  return PositionsCountThisSymbol() > 0;
}

bool GetBidAsk(double &bid, double &ask)
{
  MqlTick tick;
  if(!SymbolInfoTick(gSymbol, tick))
  {
    LogLastError("SymbolInfoTick failed");
    return false;
  }
  bid = tick.bid;
  ask = tick.ask;
  return true;
}

int GetSpreadPoints()
{
  double bid, ask;
  if(!GetBidAsk(bid,ask)) return INT_MAX;
  return (int)MathRound((ask - bid)/gPoint);
}

// Indicator value fetch with safety
bool GetEMA(const int handle, const int shift, double &value)
{
  value = 0.0;
  if(handle==INVALID_HANDLE) return false;
  double buf[];
  if(CopyBuffer(handle, 0, shift, 1, buf) != 1) return false;
  value = buf[0];
  return (value!=0.0 || GetLastError()==0);
}

bool GetRSI(const int handle, const int shift, double &value)
{
  value = 0.0;
  if(handle==INVALID_HANDLE) return false;
  double buf[];
  if(CopyBuffer(handle, 0, shift, 1, buf) != 1) return false;
  value = buf[0];
  return (value>=0.0 || GetLastError()==0);
}

bool GetATR(const int handle, const int shift, double &value)
{
  value = 0.0;
  if(handle==INVALID_HANDLE) return false;
  double buf[];
  if(CopyBuffer(handle, 0, shift, 1, buf) != 1) return false;
  value = buf[0];
  return (value>0.0 || GetLastError()==0);
}

//==================================================================
// Position sizing via equity risk and OrderCalcMargin checks
//==================================================================
// Computes volume based on: risk % of equity / SL distance value
// Applies: volume step/limits, OrderCalcMargin feasibility, per-trade margin cap,
//          free-margin and margin-level projections
bool ComputeSafeVolume(ENUM_ORDER_TYPE order_type, double entry_price, double sl_price,
                       double &volume_out, string &reason_out)
{
  volume_out = 0.0; reason_out = "";

  if(sl_price<=0 || entry_price<=0 || MathAbs(entry_price - sl_price) < gPoint)
  {
    reason_out = "Invalid SL or entry distance too small";
    return false;
  }

  // Risk capital in account currency
  double equity = AccountInfoDouble(ACCOUNT_EQUITY);
  double risk_amt = equity * (InpRiskPerTradePct/100.0);
  if(risk_amt <= 0.0)
  {
    reason_out = "Risk amount <= 0";
    return false;
  }

  // Pip/point value per lot approximation using tick value/size
  double sl_distance = MathAbs(entry_price - sl_price);
  double points_distance = sl_distance / gPoint;
  if(points_distance < 1.0) points_distance = 1.0;

  // Value per point per 1.0 lot
  double value_per_point_per_lot = (gTickValue / gTickSize) * gPoint; // normalize to point
  if(value_per_point_per_lot <= 0.0)
  {
    reason_out = "Invalid tick economics";
    return false;
  }

  double lots_by_risk = risk_amt / (points_distance * value_per_point_per_lot);

  // Constrain to broker limits
  double lots = MathMax(gMinVolume, MathMin(lots_by_risk, gMaxVolume));
  // Snap to step
  lots = MathFloor(lots / gVolStep) * gVolStep;
  if(lots < gMinVolume)
  {
    reason_out = "Computed volume below minimum after step";
    return false;
  }

  // Margin calculation for the order at computed lots
  double margin = 0.0;
  if(!OrderCalcMargin(order_type, gSymbol, lots, entry_price, margin))
  {
    LogLastError("OrderCalcMargin failed");
    reason_out = "OrderCalcMargin failed";
    return false;
  }

  double free_margin = AccountInfoDouble(ACCOUNT_FREEMARGIN);
  if(free_margin <= 0.0)
  {
    reason_out = "No free margin";
    return false;
  }

  // Per-trade margin usage cap
  double max_margin_allowed = free_margin * (InpMaxFreeMarginUsagePct/100.0);
  if(margin > max_margin_allowed)
  {
    // scale lots down to fit the cap
    double scale = max_margin_allowed / margin;
    lots = MathFloor((lots * scale) / gVolStep) * gVolStep;
    if(lots < gMinVolume)
    {
      reason_out = "Per-trade margin cap reduces volume below minimum";
      return false;
    }
    if(!OrderCalcMargin(order_type, gSymbol, lots, entry_price, margin))
    {
      LogLastError("OrderCalcMargin recheck failed");
      reason_out = "OrderCalcMargin recheck failed";
      return false;
    }
  }

  // Projected margin level after opening
  double used_margin_now = AccountInfoDouble(ACCOUNT_MARGIN);
  double equity_after = equity; // assume immediate, no P/L impact at open
  double used_margin_after = used_margin_now + margin;
  double margin_level_after = (used_margin_after>0.0) ? (equity_after/used_margin_after*100.0) : 999999.0;

  if(InpMinMarginLevelPct > 0.0 && margin_level_after < InpMinMarginLevelPct)
  {
    reason_out = StringFormat("Projected margin level %.2f%% < min %.2f%%", margin_level_after, InpMinMarginLevelPct);
    return false;
  }

  // Ensure free margin remains positive
  if(free_margin - margin <= 0.0)
  {
    reason_out = "Insufficient free margin after allocation";
    return false;
  }

  volume_out = lots;
  return true;
}

//==================================================================
// Order/position helpers
//==================================================================
bool PlaceOrder(ENUM_ORDER_TYPE type, double volume, double price, double sl, double tp, const string comment)
{
  trade.SetExpertMagicNumber((long)InpMagicNumber);
  trade.SetDeviationInPoints(InpSlippagePoints);

  bool ok = false;
  ResetLastError();
  if(type == ORDER_TYPE_BUY)
    ok = trade.Buy(volume, gSymbol, price, sl, tp, comment);
  else if(type == ORDER_TYPE_SELL)
    ok = trade.Sell(volume, gSymbol, price, sl, tp, comment);
  else
    return false;

  if(!ok)
  {
    LogLastError("Order send failed");
    return false;
  }
  return true;
}

void TrailOrBreakeven()
{
  if(!InpAllowTrailing) return;
  if(!PositionSelect(gSymbol)) return;
  if(PositionGetInteger(POSITION_MAGIC)!=(long)InpMagicNumber) return;

  double atr; if(!GetATR(hATR, 0, atr) || atr<=0) return;
  double trail_distance = MathMax(atr*InpATR_TrailMult, gStopsLevelPoints*gPoint);

  long   type      = PositionGetInteger(POSITION_TYPE);
  double price_open= PositionGetDouble(POSITION_PRICE_OPEN);
  double sl        = PositionGetDouble(POSITION_SL);
  double tp        = PositionGetDouble(POSITION_TP);
  double volume    = PositionGetDouble(POSITION_VOLUME);
  double bid, ask; if(!GetBidAsk(bid,ask)) return;

  // Breakeven logic based on RR
  if(InpBreakevenRR > 0.0)
  {
    if(type==POSITION_TYPE_BUY)
    {
      double risk = price_open - sl;
      if(risk>0 && (bid - price_open) >= risk*InpBreakevenRR)
      {
        double new_sl = MathMax(sl, price_open);
        if(new_sl > sl + gPoint)
        {
          trade.PositionModify(gSymbol, new_sl, tp);
        }
      }
    }
    else if(type==POSITION_TYPE_SELL)
    {
      double risk = sl - price_open;
      if(risk>0 && (price_open - ask) >= risk*InpBreakevenRR)
      {
        double new_sl = MathMin(sl, price_open);
        if(new_sl < sl - gPoint)
        {
          trade.PositionModify(gSymbol, new_sl, tp);
        }
      }
    }
  }

  // ATR trailing
  if(type==POSITION_TYPE_BUY)
  {
    double new_sl = MathMax(sl, bid - trail_distance);
    // Respect stops/freeze
    if((bid - new_sl) >= (gStopsLevelPoints*gPoint) && MathAbs(new_sl - sl) >= gPoint)
    {
      trade.PositionModify(gSymbol, new_sl, tp);
    }
  }
  else if(type==POSITION_TYPE_SELL)
  {
    double new_sl = MathMin(sl, ask + trail_distance);
    if((new_sl - ask) >= (gStopsLevelPoints*gPoint) && MathAbs(new_sl - sl) >= gPoint)
    {
      trade.PositionModify(gSymbol, new_sl, tp);
    }
  }
}

//==================================================================
// Signals
//==================================================================
int DetectSignal()
{
  // returns: 1 = buy, -1 = sell, 0 = none
  double ema_fast_1, ema_slow_1, ema_fast_2, ema_slow_2, rsi_1, atr_1;
  if(!GetEMA(hFastEMA, 1, ema_fast_1)) return 0;
  if(!GetEMA(hSlowEMA, 1, ema_slow_1)) return 0;
  if(!GetEMA(hFastEMA, 2, ema_fast_2)) return 0;
  if(!GetEMA(hSlowEMA, 2, ema_slow_2)) return 0;
  if(!GetRSI(hRSI, 1, rsi_1)) return 0;
  if(!GetATR(hATR, 1, atr_1)) return 0;

  if(InpATR_MinFilter>0 && atr_1 < InpATR_MinFilter) return 0;

  bool bull_cross = (ema_fast_2 < ema_slow_2) && (ema_fast_1 > ema_slow_1) && (rsi_1 >= InpRSI_Buy);
  bool bear_cross = (ema_fast_2 > ema_slow_2) && (ema_fast_1 < ema_slow_1) && (rsi_1 <= InpRSI_Sell);

  if(bull_cross) return 1;
  if(bear_cross) return -1;
  return 0;
}

//==================================================================
// Expert lifecycle
//==================================================================
int OnInit()
{
  if(!RefreshSymbolInfo(_Symbol))
  {
    Print("Initialization failed: symbol info");
    return(INIT_FAILED);
  }

  ParseSkipHours(InpSkipHoursUTC);

  // Create indicator handles on requested timeframe
  hFastEMA = iMA(gSymbol, InpTimeframe, InpFastEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hFastEMA==INVALID_HANDLE){ LogLastError("iMA fast failed"); return INIT_FAILED; }

  hSlowEMA = iMA(gSymbol, InpTimeframe, InpSlowEMA, 0, MODE_EMA, PRICE_CLOSE);
  if(hSlowEMA==INVALID_HANDLE){ LogLastError("iMA slow failed"); return INIT_FAILED; }

  hRSI = iRSI(gSymbol, InpTimeframe, InpRSIPeriod, PRICE_CLOSE);
  if(hRSI==INVALID_HANDLE){ LogLastError("iRSI failed"); return INIT_FAILED; }

  hATR = iATR(gSymbol, InpTimeframe, InpATRPeriod);
  if(hATR==INVALID_HANDLE){ LogLastError("iATR failed"); return INIT_FAILED; }

  // Prime buffers
  double tmp[];
  CopyBuffer(hFastEMA, 0, 0, 3, tmp);
  CopyBuffer(hSlowEMA, 0, 0, 3, tmp);
  CopyBuffer(hRSI,     0, 0, 3, tmp);
  CopyBuffer(hATR,     0, 0, 3, tmp);

  Print("EA initialized successfully.");
  return(INIT_SUCCEEDED);
}

void OnDeinit(const int reason)
{
  if(hFastEMA!=INVALID_HANDLE) IndicatorRelease(hFastEMA);
  if(hSlowEMA!=INVALID_HANDLE) IndicatorRelease(hSlowEMA);
  if(hRSI!=INVALID_HANDLE)     IndicatorRelease(hRSI);
  if(hATR!=INVALID_HANDLE)     IndicatorRelease(hATR);
}

void OnTick()
{
  if(gSymbol==NULL)
  {
    if(!RefreshSymbolInfo(_Symbol)) return;
  }

  // Filters: spread, session, one-position-per-symbol
  int spread_pts = GetSpreadPoints();
  if(spread_pts==INT_MAX) return;
  if(spread_pts > InpMaxSpreadPoints) return;
  if(!IsTradingHour()) return;

  // Work only once per bar for signals
  datetime bar_time = iTime(gSymbol, InpTimeframe, 0);
  if(bar_time==0) return;

  // Always manage trailing on every tick
  TrailOrBreakeven();

  if(bar_time == gLastProcessedBar) return; // already processed
  gLastProcessedBar = bar_time;

  if(HasOpenPosition()) return; // strictly one position per symbol

  int signal = DetectSignal();
  if(signal==0) return;

  double bid, ask; if(!GetBidAsk(bid,ask)) return;
  double atr; if(!GetATR(hATR, 1, atr) || atr<=0) return;

  // Define entry/SL/TP based on signal
  double entry=0.0, sl=0.0, tp=0.0;
  ENUM_ORDER_TYPE type;

  double stop_distance = MathMax(atr*InpATR_SL_Mult, gStopsLevelPoints*gPoint);

  if(signal>0) // BUY
  {
    type  = ORDER_TYPE_BUY;
    entry = ask;
    sl    = entry - stop_distance;
    tp    = entry + (stop_distance*InpRR);
  }
  else // SELL
  {
    type  = ORDER_TYPE_SELL;
    entry = bid;
    sl    = entry + stop_distance;
    tp    = entry - (stop_distance*InpRR);
  }

  // Respect freeze level: ensure SL/TP not within freeze and beyond stops level
  if(gFreezeLevelPoints>0)
  {
    if(type==ORDER_TYPE_BUY)
    {
      if((entry - sl) < (gStopsLevelPoints*gPoint)) sl = entry - (gStopsLevelPoints+1)*gPoint;
      if((tp - entry) < (gStopsLevelPoints*gPoint)) tp = entry + (gStopsLevelPoints+1)*gPoint;
    }
    else
    {
      if((sl - entry) < (gStopsLevelPoints*gPoint)) sl = entry + (gStopsLevelPoints+1)*gPoint;
      if((entry - tp) < (gStopsLevelPoints*gPoint)) tp = entry - (gStopsLevelPoints+1)*gPoint;
    }
  }

  // Compute safe volume with full margin/risk checks
  double lots; string reason;
  if(!ComputeSafeVolume(type, entry, sl, lots, reason))
  {
    Print("Skip entry: ", reason);
    return;
  }

  // Final safety re-check of spread
  if(GetSpreadPoints() > InpMaxSpreadPoints) return;

  string comment = (type==ORDER_TYPE_BUY?"EMA_RSI_ATR_BUY":"EMA_RSI_ATR_SELL");
  if(!PlaceOrder(type, lots, 0.0, sl, tp, comment))
  {
    LogLastError("PlaceOrder failed");
    return;
  }

  PrintFormat("Order placed: %s %.2f lots | SL: %.*f TP: %.*f", comment, lots, gDigits, sl, gDigits, tp);
}
